const articlesData = {"version":2,"generated":"2026-09-13 10:46","count":269,"articles":[{"id":1,"title":"初夏记事","category":"诗","date":"辛丑年立夏日","body":"塘边蛙鸣蒲花黄，\n披簑吆牛扶犁杖，\n耕读传家应笃本，\n挥汗弯腰插早秧。\n辛勤换来稻米香，\n一缕一食一壶浆。\n奢靡浪费最可耻，\n勤俭节约家国昌。"},{"id":2,"title":"富春江秋色外二首","category":"诗","date":"庚子初冬十六日","body":"（一）\n（富春江秋色）\n富春江上烟岚锁，\n山居遐尔景依旧。\n一叶孤舟钓情趣，\n一江碧水映深秋。\n（二）\n（白云原景区）\n云雾缭绕白云原，\n百丈飞瀑天际悬。\n空山无语鸟不惊，\n只闻小溪水流声。\n（三）\n（遍尝鲜美食）\n暮秋冬临胜春游，\n遍尝美食人不休。\n竹林才露小牛角，\n餐盆又添新珍馐。\n附记：前三日与友人随团休闲游浙江桐庐富春江，时光虽己入冬但仍有在深秋的感觉，沿途滿目璀璨、秀色可餐，并不亚于鲜花烂漫的春天。\n芦茨湾是桐庐富春江镇所辖的一个自然村，深藏于大山中、大概有百十户人家，家家户户都办农宿，销售一些土特农产品，三至四层的村舍几乎一式的白墙黛瓦，端庄古朴，很气派。芦溪绕村、溪水清澈鱼沉浅底、村容干净整洁，是消夏避暑胜地。这里与三年前去过的东阳横锦水库上游的白泉村相似。\n距芦茨湾车程不足半小时的白云原景区，海拔一千四百米，因是阴天山中云雾缭绕，树木依然蒼翠、深潭碧水溪流淙淙，海拔约千余米有瀑布一处，尤如一条百米长的白色绸带悬空而挂、倾泻而下，其声如雷。白云原的森林复盖率为百分之九十八，森林氧吧名不虚传。\n香榧”是一种坚果很好吃，油性很足有一股清香。夫人外婆家亲戚常有寄过来食得，但不知香榧树为何样，这次在白云原终于有幸目睹，开了眼界，其树型与树叶与红豆杉很相似。同时还认识了一种花卉“曼陀罗”，阔叶、叶型似无花果，花托像十公分长的嫩丝瓜、花型花色像南瓜花稍长些。\n狄浦花海的花己完全凋谢了，据说春天草木返青花开遍野美得很。但有几株难得一见的、干粗要四五个人相抱、树龄己有八百年可谓之“树王”的香樟树，它们可真正见证了人间世事变迁、过往烟云，岁月静好必在当下。\n富春江不仅景色优美人文荟萃，还因有元朝四大画（吴镇、王蒙、倪瓒）之一黄公望（江苏常熟人）的《富春山居图》而闻名遐尔。《富春山居图》是中国有序传存的十大名画之一。黄公望耗时三年、从七十九岁时（1347）至八十二岁（1350）为师弟郑樗（别号无用师）和尚、精心所作的一幅长卷纸本水墨画，画长639.9厘米、高33厘米。此画为富春江两岸初秋的山水景色，有百分之八十的景色在桐庐境内，其余的在富阳境内。\n明朝末年此画传到收藏家吴洪裕手中，他深爱此画，日观夜思爱不释手，到临终时要家人将此画焚烧殉葬，幸得其侄吴静庵从火中救出。但已焚为两段，前段剩51.4厘米。正好有一山一水一丘一壑名为《剩山图》，现收藏于浙江省博物馆。另一半名《无用师卷》现收藏于台湾故宫博物院。现在比照着看山水背景、几百年来变化并不太大。\n真是：“时光流逝六百年，山水依旧貌延绵。人生感慨输草木，悟得禅意修福田。”\n这次团餐真的不错，虽为农家土菜，但食材很新鲜，现摘现採现加工，各地口味不尽相同.，但香味仍留舌尖齿间，让人久久回味。通过这次旅游还结识了几位新朋友让人难以忘怀。\n就将这几百字的短文作为游记，留个纪念吧。"},{"id":3,"title":"给褚益民将军写照","category":"诗","date":"写于戊戌年春节修改于八一建军节","body":"戎装一身，一生戎装。\n立志军营，成长榜样。\n政治坚定，忠诚于党。\n报效国家，永志不忘。\n服务人民，勇于担当。\n律己修为，立德树望。\n爱兵如子，教导有方。\n精练严训，立足打仗。\n历经磨练，国之栋樑。\n人生颠峰，赫赫上将。\n卸职离任，解甲休养。\n关心国是，仍系心上。\n老骥伏枥，余热发光。\n赤子之心，昭日煌煌。\n牢记使命，永在路上。"},{"id":4,"title":"关城怀远","category":"诗","date":"二零二零年菊月","body":"雄关两翼安铁流， 雉堞连绵望肃州。\n风啸驼鸣戍边远， 孤客异乡守谯楼。\n城上相伴月如钩，遥盼家书解烦忧。\n一曲大风暮云起， 勇士归去鬓己秋。\n注释：雄关，是指明万里长城最西端的嘉峪关，自明洪武（1372）五年筑关始至今已有六百多年历史，这六百余载，历朝历代都将这里视为兵家必争之地，驻兵镇守永续不断。每每登上城楼听到与其相关的故事，总会联想到我的一位好朋友，他是原中国人民解放军二十一集团军装甲十二师王忠恩师长及其战友和麾下的李建印、陈登银、朱义国、梁超、朱耀民、孔令锷、李忠、李伟、王民立、王锁成，鲁怡然，郭建民、周建国、王生祺……等一大批优秀人才。王师长从入伍当战士开始直至升任到师长一职，在此奉献了大半辈子，当离开这里赴西安警备区就任司令员一职时己经两鬓斑白。  其它人或荣升或转业离开时也都尝尽了在戈壁沙漠守关戌边的甘苦。我曾经也是一名军人从部队转业到嘉峪关，这里是我的第二故乡，在这里工作生活了四十多年，也让我结识了很多军人朋友，我以我曾经当兵的经历及心灵的契合去穿越、去体验、去感受到了在此戍边卫国将士的艰辛和不易。所以我要将这首短诗献给我的好友王忠恩司令员以及自古至今在此戍边守关的所有军人，并向他们致敬。\n安铁流，泛指驻兵镇守戍边卫国。如今是指原二十一集团军装甲十二师坦克四十五团，四十七团，炮团。分别在关城的南北两翼安营扎寨，扼守雄关。\n肃州，指现在的酒泉市肃州区，原坦克十二师的驻地。\n大风歌：“大风起兮云飞扬，威加海内兮归故乡，安得猛士兮守四方。”汉高祖刘邦（公元前256—前195）在击败叛军英布后回长安时，途经故乡沛县邀请父老乡亲饮酒，酒酣，击筑（一种打击乐器）高歌这首《大风歌》以表达他带兵打仗、开土拓疆的雄心壮志和维护天下统一的决心豪情。\n二零二一年四月二十二日修改完稿"},{"id":5,"title":"管社山庄赏荷有感之一","category":"诗","date":"二零一七年——夏至","body":"一塘荷花万点红，蜻蜓戏水舞池中。\n翠盘银珠轻摇摆，涟漪荡起送凉风。\n赏荷旨趣各不同，任尔评说亦芙蓉。\n君子酷爱爱莲说，吾省清濁當追崇。\n附：宋周敦颐《爱莲说》，水陆草木之花，可爱者甚蕃。晋陶渊明独爱菊。自李唐来，世人甚爱牡丹。予独爱莲之出淤泥而不染，濯清涟而不妖，中通外直，不蔓不枝，香远益清亭亭净植，可远观而不可亵玩焉。予谓菊，花之隐逸者也：牡丹，花之富贵者也：莲，花之君之者也。噫！菊之爱，陶后鲜有闻，莲之爱，同予者何人？牡丹之爱，宜乎众矣！"},{"id":6,"title":"军人喜讯","category":"词","date":"二零一九年清明节后两天","body":"（扬州慢）\n世风转晴，阴霭澄清，退役官兵喜讯。\n荣誉不容玷，福利能搞定。\n急难险总在前线，军人本色，从未失信。\n受尊崇，理所当然，弹冠相庆。\n卸甲归田，尽本职圆梦复兴。\n今生无怨悔，时刻准备，听党号令。\n始终不忘初心，发余热再鼓干劲。\n使命担在肩，战士责无穷尽。"},{"id":7,"title":"中秋","category":"词","date":"二零一九年中秋节","body":"（卜算子）——《中秋》\n碧空蓝如洗，月儿挂树梢。\n亲人思念盼团圆，鸿雁把门敲。\n中秋故事多，民俗推新高。\n人寿年丰喜庆全，良缘谢月老。"},{"id":8,"title":"为民为官之本","category":"词","date":"癸卯年十月初三","body":"（西    江    月）\n尝遍苦难酸楚，\n历经人生无助，\n佛前祈愿卜前途，\n学海书山有路。\n深察民众疾苦，\n心系百姓实务，\n清廉勤行为公仆，\n治政重今鉴古。\n附注：近日观看央视播映的电视剧《丁宝桢》故事中的主人翁忧国忧民所作所为处处感人至深想到《为民为官之本》随用西江月词牌填词一首。\n1·为民之本就是吃苦，祈福不过是想风调雨顺多有收获，即是风调雨顺也不过是少吃些苦多些收获，想要多收获实际上就要多吃苦，吃得苦中苦方能人上人。老百姓的幸福感就是付出与获得是否成正比，老百姓还会以苦为乐、他们的满足感其实是不高的。苦中取乐，也是老百姓自我解压的最好方法，所以百姓之本就是“吃苦”二字。能吃苦就是好百姓。\n2·为官之本就是要深入民间、深入基层了解百姓之疾苦，深察百姓之所需、还要多学习历史、以史为鉴，多学习现代知识，只有想百姓之想才能制定出好制度，好政策，想出好方法，为百姓去愁解忧这就是“为官”之本，“先天下之忧而忧，后天下之乐而乐”这才是“为好官”之本。\n3·民，国之邦本。官，民之父母。官，国之栋梁。望天下之子民尽己之忠孝，望天下之官吏尽己之爱护。望天下之官吏尽己之所能，不负国托民望。\n西江月，词牌名，正体双调五十字，前后阙二、三句均押平韵，第四句押仄韵，变体较多，一般要求一二句对仗，也可不对仗。"},{"id":9,"title":"叙秋","category":"诗","date":"癸卯年重阳节前","body":"《叙        秋》\n（老气横秋）\n秋风扫叶肆意行，\n秋雨打湿游客情。\n秋岚刮起山换色，\n秋雾锁城欲蔽天。\n秋露凝珠似泪涟，\n秋霜萧瑟惊眼前。\n秋阳泛白暖无力，\n秋月清冷挂天边。\n秋情释放众眷恋，\n秋意解戾趋争先。\n秋思人生如四季，\n秋绪随缘话当今。\n秋来一岁将耗尽，\n秋去我亦别年轻。\n秋时皆说夕阳好，\n秋日酣醉梦方醒。"},{"id":10,"title":"太湖春景","category":"词","date":"甲辰三月十五日","body":"《太湖春景》·浪淘沙\n惠风送残冬。\n春意渐浓。\n岸边芦芽赛萌动。\n堤上柳绿衬桃红。\n人游画中。\n远朓醉双瞳。\n畅舒心胸。\n远山近水紧相逢。\n渔歌号子帆影重。\n美景无穷。\n附注：浪淘沙，词牌名，上下两片，各五句，二十七字，四平韵。"},{"id":11,"title":"小妹周年祭","category":"诗","date":"壬寅年三月十八日","body":"（其一）\n生年迈花甲，弃情离别家。\n骑鹤会先辈，深寐九泉下。\n英年早逝去，兄痛如刀剐。\n远望新市墓，衰草伴昏鸦。\n亲们欲祭奠，疫情断舟车。\n歉意默然生，哀思全寄托。\n（其二）\n岁月阴阳复，生命如朝露。\n人生单程路，圣贤亦无殊。\n别做长寿梦，寿无金石固。\n吃药求神仙，常把健康误。\n锻炼宽心境，难得真糊塗。\n极目西天舒，视死如归途。\n附：1、 吃药指吃保健品\n2 、西天舒指天堂美\n3、如归途好像回家的路上。"},{"id":12,"title":"无锡•思友人","category":"诗","date":"壬寅年清明节前","body":"好汉聚雄关，\n報国流血汗。\n岁月凝秋意，\n夕阳耀长安。\n相会终期盼，\n邀友下江南。\n深情铭心中，\n消息微信端。\n附注：\n1、4月1日晚接西安朱义国、孔令锷、鲁怡然诸好友电话十分高兴，遂想起王志宏、王忠恩、李建印、郭建民、梁超、朱耀民、王民立、 陈登银、徐学勤、张自忠、吴祥法等一大批故友相交的往事这批挚友原来都是兰州军区干部中的精英，退休后大都定居在西安，岁月真不饶人，昔英姿飒爽年轻有为的孔令锷政委如今也已退养休息，甚是感怀，他们都曾在雄关脚下热血报国且与我结下了深厚情谊。往事虽如烟，历历在目前。 至今己有多年不见想念日深随作短诗一首，以表思念更祈疫情过去早日相见。\n2、“岁月凝秋意”是指随时间推移，这批好友每个人都有一段讲不完的故事，他们在人生奋斗的道路上经过不懈努力，每个人都留下了一串串坚实的脚印，个个事业有 成，功成名就，结下了累累硕果。\n3、“夕阳耀长安”是指岁月不以人的意志而转移，年轻时他们听从党的召唤又分布到祖国各地为人民建功立业，年复一年随着年龄的增长他们也慢慢跨入老年行列，退休后聚集在西安颐养天年，人生就是这样没有永远的辉煌，但祖国和人民会记住他们的丰功伟绩。今日“夕阳无限好” 在西安在这片热土之上祝他们继续发挥余热照样闪光。我真诚的欢迎所有老朋友来无锡作客畅叙衷情。"},{"id":13,"title":"赞梅","category":"词","date":"二零二三三月三","body":"《赞        梅》\n（卜   算  子）\n花败草衰凋，\n欺雪凌霜傲。\n严寒料峭抖精神，\n独秀花枝俏，\n为冬默着彩，\n只催早春到。\n人间三月风光好，\n淡然香殒消。"},{"id":14,"title":"迎新春","category":"诗","date":"癸卯年除夕前夜","body":"《 迎新春》二首\n一·四海同庆\n梅花弄影小巷中，\n炮竹声喧大地红。\n千家万户庆佳节，\n四方亲友喜相逢。\n神州图腾中国龙\n华夏文化五州同。\n闹春锣鼓辞旧岁，\n踏歌起舞惊苍穹。\n二·新春祝福\n玉兔辞行龙腾飞，\n甲辰新年迎春归。\n吉祥如意送祝福，\n合家团圆和气聚。\n福寿安康常相随，\n幸福美满喜乐汇。\n一元复始呈瑞兆，\n祝您万事遂心扉。"},{"id":15,"title":"重阳感怀","category":"诗","date":"壬寅年重阳节日","body":"人生颠波多变化，\n客居他乡少离家。\n艰辛创业度春秋，\n心想事成数冬夏。\n故友千言话桑麻，\n同人九日惜春华。\n登高饮酒辞青去，\n感念盛世享闲暇。\n注：我在嘉峪关携全家借用\n拙诗《迎新春二首》给\n您和你全家人拜年衷心\n祝福你在新的一年里阖\n家安康、幸福美满、万\n事顺意。"},{"id":16,"title":"阅读新海南","category":"词","date":"二零二零年冬月","body":"天崖海角，名不虚传，心系旅游情牵。\n觅/极好风景，赏/悦思无边。\n望远方、椰林成片，鸥翔鱼跃，碧水连天。\n看近处，人在画中，快活神仙。\n海南崛起，立潮头、勇站浪尖。\n聚/举国力量，克难攻坚，创新抢先。\n中央决策英明，争朝夕、亲历变迁。\n筑/国贸新岛，园梦胜景再添。\n最近，有友人去海南旅游，发来几张风景照片，随让我浮想联翩，勾起好多美好回忆，海南我曾有幸去过两次，专属旅游确实不错。我还写过《冬游海南》游记一篇。\n中央决定将海南建成自由贸易区，更是推动了海南经济发展提速，有望不久的将来海南一定会成为市场开放，经济繁荣，风景美丽的新海南。\n借（扬州慢）词牌填一首《阅读新海南》作为阅赏风景照的回赠。"},{"id":17,"title":"冬日雄关迎客","category":"词","date":"癸卯年冬至日","body":"（浪淘沙令）\n山披白雪皑，\n景换新貌。\n檐下冰凌惹人爱，\n城中树灯添绿颜，\n大漠异彩。\n戈壁遍原野，\n塞外狼烟。\n雄关展臂敞胸怀，\n游客纷至迎春来，\n名扬四海。"},{"id":18,"title":"冬至有感","category":"诗","date":"甲辰龙年冬至日","body":"冬至已分日渐长，\n数九送寒阴升阳。\n园中梅花一夜开，\n天道有情赐吉祥。\n人间三月好春光，\n与君同乐播希望。\n四季轮回铁定律，\n人生旅途莫迷茫。"},{"id":19,"title":"报春梅","category":"诗","date":"二零二三三月三","body":"一夜东风温情吹，\n万紫千红百草回。\n莺歌燕鸣蜂蝶舞，\n送来消息报春梅。\n人间三月晴方好，\n爷孙兴致放纸鸢。\n诗和远方在这里，\n抛却牵挂无烦恼。\n注：\n昨日天气晴好感觉真是春天来了，好友相约去逰无锡梅园，虽不是休息日，但仍是游人如潮，梅园是经常打卡之地，每年春天至少一次，逰后似有写首打油诗的冲动，即写《报春梅》一首，并以（卜算子）填《赞梅》词一首，还照了几幅照片，释放大好心情，附后与你分享别见笑，请多多指教。"},{"id":20,"title":"拆字诗","category":"诗","date":"甲辰年十月初三","body":"人人此思量，\n不好种孽障。\n食欠酒作乐，\n言兑话带香。\n日日和吉祥，\n山山行怱忙。\n个个心空虚，\n木木藏宝藏。\n日月知自伤，\n月月友探望。\n口口味无穷，\n音匀律绕梁。\n注：1、“种”先读笫四声再读第三声，分别有动词“种”和名词“种”的意思。木木借用“默”的谐音和意义，有悄悄的意思。“朱门酒肉臭”“臭”是“香”的意思，这里香是臭和匪气的意思。“和”读“he”第四声，有“唱”的意思。\n2、是日无事闲坐家中觉得无聊，心有写诗之意的冲动，但又感到无情无景无意象无主题不好落笔，古今有拆字猜迷之举，是否可借此手法胡诌几句聊以自赏，随得以下，竖列以“人不食言日山个木、日月回音”为首字，横列皆将第一字一拆为二作为五字句，合并后的四字俗句，不能算作诗歌。\n3、这拼凑的几句五言诗意思是否连贯通顺，韵律是否自然通畅自感很徬徨，现仅分享给几位领导，几位老师和几位挚友以期得到大家忠恳的批评指正，以利今后用更好的创作报答大家。"},{"id":21,"title":"拜大年","category":"词","date":"乙巳年正月初一","body":"（临江仙）\n怱怱岁月似流水，\n烟花缀滿星空。\n辞旧迎新开门红。\n九州同欢庆，\n举国舞狮龙。\n顿首作揖拜大年，\n祝君阖家和融。\n福禄寿喜财运宏。\n紫气东来顺，\n万事遂心从。\n注：龙腾云霄辞旧岁金蛇狂舞迎新年在这举国欢庆的重大传统节日春节来临之际在嘉峪关借用（临江仙）填词一首给您和您全家拜年恭祝新春愉快，吉祥安康。"},{"id":22,"title":"春回","category":"词","date":"乙巳农历三月三","body":"（阮郎归）\n一夜东风唤春归。\n仟陌野菜肥。\n桃花含羞柳展眉。\n燕子成双飞。\n夫伴妻，踏青回。\n慵懒意相随。\n顺手拈来玲珑杯。\n对饮任自醉。"},{"id":23,"title":"春之梦","category":"词","date":"乙巳蛇年五一节","body":"（西江月）\n春梦一帘杏雨，\n落花满地随风。\n悚然惊醒影无踪。\n唯有暗香浮动。\n人生龙争虎斗，\n心静淡定从容。\n功名利禄皆抛空。\n坦然回味无穷。\n注：西江月词牌名，该词牌还有“白蘋香”“步虚词”“江月令”等别称。双调五十字，前后段各四句，两平韵一叶韵，另有五十一字、五十六字变体。"},{"id":24,"title":"春·和煦","category":"诗","date":"癸卯年清明节前","body":"坡上桃花灼灼开，\n溪下清泉淙淙来。\n好雨知时纷纷下，\n和风唤醒青青苔。\n蝴蝶双双追寻爱，\n蜜蜂对对赛勤快。\n杨柳依依伴燕舞，\n人生熠熠添芳彩。"},{"id":25,"title":"春天并不都是最美的季节","category":"散文","date":"乙巳年三月十五","body":"春节，像村前小河的水一样静静的流走了。粉红色的报春梅和金黄色的迎春花争先开放，一声震天雷唤醒了万物复苏、催生着花草发芽、随后在乡村的田间地头、村落的前前后后、菜地菓园、山川原野；在城市的阡陌街巷、林蔭大道和公园里到处都能看到桃红柳绿梨花白、看到樱花、杜鹃、茶花、玫瑰、月季、紫藤和更多不知名的花草树木，你方唱罢我登场，竞相次第绽放，到处都是花的世界、绿的海洋。还有在阳光蓝天白云映衬下伴着春风带着春天柔情的纸鸢、无声无息，任随风意飘逸在晴空中，不时还有无人机在鸢群中穿梭而过。人们三三两两成群结队地追逐着春天的脚步纷纷去郊外的农家乐、城市的公园里打卡拍照、观赏美景、释放愉悦的心情。\n人人都说人间三月天是一年四季中最美最好的季节，其实对春天或是世界上任何事物美不美的判断都是与个人的文化修养、心理素质乃至情绪价值和生活经历紧密相关的。\n我一九五零十月出生在苏北泰兴县的一个小镇上、算是生在新中国长在红旗下，在朦曈懂事开始有记忆后、总觉得春天并不都是最美的。尤其新中国成立后的五六十年代感触颇深，由于刚解放新中国接管的是国民党留下的一副百孔千疮百废待兴的烂摊子，由于刚解放就爆发了抗美援朝保家卫国的战争，在全国范围内还有很多敌对势力、旧社会的恶习需要肃清和改造、更主要的是急需建立新的社会制度和秩序这些政治活动不免会对经济的建设与发展会带来一定的影响解放后虽然解放了生产力调动了人民群众生产积极性，掀起了建设社会主义的新高潮但在一穷二白的基础上搞建设是多么的不容易，特别是新中国的人口从解放初期的四億五千万到五十年代末猛增到了八亿几乎翻了一番、到六十年代末期又增长到了十二億多，人口的迅猛增长，对社会物质的供给保障造成了巨大的压力，五十年代末“九评”苏共，苏联老大哥翻了脸丢下了所有援建项目撤走了全部专家、逼迫我国清偿抗美援朝所援助武器装备的债务。六十年代的前三年又遇到了百年不遇的自然灾害，国家实行“ 独立自主、自力更生”的战略方针后号召全国要树立一盘棋的思想，农村要支援城市，农业要支持工业化建设，由于这些天灾人祸及诸多原因的累积，当时社会的主要矛盾就是落后的生产力、满足不了人民群众日益增长的物质文化需要，这些年的春天每年都会遇到“春荒”，粮食不够吃国家虽然也给拨一些“返销粮”“借销粮”帮助人民度“春荒”，但那也是杯水车薪、哪种“瓜菜代”吃不饱肚子的日子还真是蛮苦的，尤其我家父母亲和我们六个兄弟姐妹全家八口人全靠父亲一人微薄的工资生活真的很艰难。与我同时代的人大概都有同感不会忘记这些苦难吧。\n在那个物质十分匮乏的年代，虽然每年春天同样会春暖花开，人们却无心去欣赏、因为度“春荒”过那紧巴的日子也就不觉得春天有多美，人们只期盼着春天早早过去、期盼着农谚所讲到的“ 四月十六蚕老麦熟 ”的日子快些到来。民以食为天、有了粮食才能有维持生存的基本保证。秋天是成熟的季节，秋天是收获的季节也许秋天才是最美好的季节。有首古诗说得好“春有百花秋有月，夏有凉风冬有雪，莫将闲事挂心头，便是人间好时节”心无烦忧牵挂之事，有轻松的好心情才能感受到美好真正的存在。\n解放后广大的劳苦大众挺直了腰成了国家的主人，虽然有这些无奈的回忆、但不会动摇人们对理想信念的追求、对党的忠诚和对祖国母亲的热爱。改革开放后的四十多年来全国人民就是在新中国创业初期留下的国家安宁和比较齐全的工业化基础设施的平台上韬光养晦、持续不断的努力奋斗才取得了今天辉煌的业绩。我们必须牢记前辈的艰辛，岁月静好必有人负重前行。"},{"id":26,"title":"春晚在无锡","category":"词","date":"辰巳交替除夕夜","body":"（苏幕遮）\n蠡湖清，梅园秀。\n清名桥旁，\n笙歌穿云透。\n瑶池陨落人间否。\n悦赏春晚，\n人约黄昏后。\n拈花湾，逢益友。\n惠山古镇，\n品鉴历史久。\n春风又绿江南柳。\n今夜无锡，\n与汝共相守。\n注：中央电视台将今年春睌分会场设在无锡，必然会吸引全世界的目光来关注无锡。无锡不仅是江南水乡的优秀代表，更具有悠久历史文化的积淀，用“山清水秀，人杰地灵”这一句话来形容毫不为过，今睌呈现在人们面前的有南长街运河水弄堂、清名桥，有太湖佳绝处的鼋头渚、有最古老的水利工程伯渎河、有世界第三之称的赏梅好去处梅园、有祠堂集群惠山古镇、有风景如画的拈花湾、还有最具江南特色的蠡园春早等诸多历史故事和美景，来到这里必然会得到“放松心情欣赏美景、追寻历史陶冶情操”的收获，因此我用“苏幕遮”词牌填词一首《春晚在无锡》献给你们，欢迎你们在春暖花开的季节来无锡旅游作客。"},{"id":27,"title":"春雨•春风","category":"诗","date":"乙巳年三月十五","body":"夜雨飘洒寂无声，\n缠绵多情润锡城。\n悄然无意播春色，\n碧柳清新去浮尘。\n晨风轻柔抚竹梢，\n拂晓天光闻啼鸟。\n百花盛放迎贵客，\n儿童快乐放纸鸢。"},{"id":28,"title":"春风化雨","category":"诗","date":"甲辰龙年三月三","body":"云遮晨曦浓雾起，\n风卷柳絮恰如期。\n细雨霏霏轻飘落，\n湖畔信步濡湿衣。\n洗净铅华透绿意，\n润物无声凝神怡。\n煮酒品茗读诗书，\n闲坐窗前听鸟啼。"},{"id":29,"title":"独酌自遣·二首","category":"诗","date":"癸卯年冬月十五","body":"一、人生苦短\n乌云舒卷起苍黄，\n雨声淅沥敲湿窗。\n酒后常思人生路，\n客前莫忆少年狂。\n光阴似箭时漫长，\n日月如梭鬓染霜。\n三盏焉能释襟怀，\n六杯微醺意飞扬。\n二、往事如烟\n半世飘零凡间人，\n浮生若梦亦如尘。\n经年往事名利累，\n孤寂聊赖伴余生。\n秦皇千古留长城，\n幡然醒悟急转身。\n唯有杜康终不弃，\n醉随清风全无痕。"},{"id":30,"title":"禅偈","category":"诗","date":"甲辰年冬月初一","body":"浮生如梦亦似尘，\n浪迹江湖寄游魂。\n也曾立下高远志，\n岂料命运不济人。\n如今活在最底层，\n半醉半醒且偷生。\n静待云散风归去，\n一缕青烟了无痕。"},{"id":31,"title":"辞旧有感","category":"词","date":"二零二五年元旦","body":"（苏幕遮）\n新年来，旧岁去。\n春风秋月，\n轮回遵时序。\n悄然华发添几缕。\n回眸人生，\n淡定应无语。\n登高处，理思绪。\n世间万象，\n权利值几许。\n为国为民唯正举。\n大地焕新，\n盼清明播绿。\n注： 今天是2025年元旦，在这辞旧迎新的日子里期望万象更新，随用苏幕遮填词一首分享给各位亲明好友以示祝贺。苏幕遮，词牌名，双调六十二字，上下片各四句，四仄韵。"},{"id":32,"title":"关于火车的记忆","category":"散文","date":"二零一二年六月","body":"6月23日端午节的这天，我和老伴，从女儿女婿居住的城市无锡返回第二故乡嘉峪关市，这次选择的交通工具是火车，是上海至乌鲁木齐的那趟53/54次直达快车。晚上10点发车到第三天的凌晨5点到家（火车晚点，正点到应该是3点40分）历时31个钟头。漫长的铁路旅行在车上只能看点儿书，累了就伫立在窗前向远处看看窗外的风景，除了可以看见彩云镶嵌的茫茫天际，沿途还可以看到迅速后移和不断变化的山川丘陵、阡陌稻田、庄稼果园及各式各样建筑风格的庭院村落等山水风物。\n不经意的观望和探求也就成为我这次旅行生活中别无选择的必修课。火车每经一地也就自然而然地联想到了南北方的差异，想到了各地不一样的人文风情、礼仪习俗、生活方式。\n古人说：行万里路、读万卷书，一路想来“行路”的目的并非完全是为了锻炼身体或纯粹的看看风景，而是有意让人们见识不同地域的风土人情、看到各个地方之间生活的特色，从而让有血有肉有情感的人、对于每一种生活方式给予足够的理解、尊重与认同，不要轻易的去否定。同时，也要相信命运给自己的安排，从内心服从命定的人生旅程，绝不能去进行不择手段和毫无准备的抗争，“这山望着那山高，到了那山没柴烧”，顺其自然，不乏是“天人合一”的灵丹妙药。\n车轮滚滚，天近黄昏，火车也越过平原来到高原，车轮将我们从富庶之地带进遥远的苍凉，祁连山头上覆盖着厚厚的雪，随着山势蠕动的河西走廊的戈壁滩上星星点点刚冒出一点绿。此时，江南春暖花开的季节已悄然退去，火辣辣的夏天即将来临。山坡上牧羊人挥动着鞭漫无目标地赶着牛羊觅食，太阳像捉迷藏一样躲进了山后，夜幕降临天渐渐的暗下来，窗外的景色也变得模糊不清，偶然看见远处有稀落的灯火亮了起来。除了车轮与铁轨摩擦的声音不停地在耳边响着、没有了白天的喧嚣，一切都静了下来，躺在卧铺上在进入甜蜜的梦乡前无由地勾起了我对坐火车的一些回忆。\n我第一次接触到火车是1967年的春天，文革期间参加全国大串联、目的地是上海。那也是第一次离开县辖范围出远门，当时我们苏中地区是没有铁路的，火车对于我来说是那么神往，因为过去只是从书本上读到、从图画上看到它既雄伟又修长的身躯，轩昂的车头拉着几十节车厢、一声呼啸就会随着铁轨铿锵有力的节奏狂奔而去，那种排山倒海让人慑服的气势是臆想出来的。\n第一次看到真的火车、而且坐上火车也是从无锡开始的，大串联基本处于无序状况、红卫兵串联无需购票凭介绍信即可登车、因此列车的通道、车厢接头处、厕所里到处都挤得水泄不通、严重超员，女同学上厕所没办法只好在车厢连接处围成人墙就地解决，真可谓人满为患，到上海后由锦江饭店红卫兵接待站负责食宿安排，到几所中学串联学习、五天后仍乘火车返回，车上依然拥挤不堪，从此就落下了乘坐火车的恐惧症。\n第二次坐火车是参军当兵、从泰兴的高港乘轮渡到镇江再从镇江转乘火车到安徽的当涂，从当涂步行到丹阳湖农场，丹阳湖农场是我们二十军的军垦农场，是围湖造田将滩涂造为肥沃的土地，种上稻谷，所产粮食是吃不完的。新兵要到那里锻炼，接兵的领导将新兵按部队的建制组成连排班，虽然组织有序但乘坐的是闷罐车，条件很差、也没有留下太好的印象。新兵连三个月的生活结束后，我被分配到五十九师一七六团特务连当了一名侦察兵。\n再后来坐火车的机会就多了起来，但每次都让人很揪心，一是车票难买、二是速度太慢、三是经常晚点。转业后到嘉峪关市工作，回老家探亲往返仅有一趟上海至乌鲁木齐的53/54次直达列车，要经兰新线、陇海线和京沪线，几十个站大小必停，如果能正点到达要历经59个小时，才能到达常州站，火车晚点10个小时之内都是正常现象、正点到达在记忆中好像从未有过。“晚点正常，正点例外”这种悖论当时就是现实。虽如此嘉峪关车站还是一个经过站，客票预留很少，一票难求，若不提前托人情走关系搞票、就很难按计划出行，返程购票更难，有时只能借助“黄牛党”。\n第一次坐高级软卧是在国外享受的，那是1992年嘉峪关市政府由常务付市长魏学鸿带队一行五人组成政府代表团到哈萨克斯坦进行经贸考察，从阿拉木图到江布尔市行程约700余公里，卧铺车厢内设两张床、有独立厕所，票价很便宜，卢布折合成人民币约5元钱。当时国内乘坐软卧车厢是分级别的，达到或相当地级以上的领导干部才能享受软卧待遇，仅有钱也是买不到软卧车票的。这一次是我第一次出国，也真正享受了一把高干的待遇。这次是从乌鲁木齐出境，10天后入境时乌鲁木齐机场大雪，飞机不能落地续飞哈什机场，第二天才得以返回。\n第一次坐地铁和高铁都是在日本，1995年省工商局由惠树仁局长带队组织部分市州局长考察学习，从东京到附近城市实地考察一般都是乘地铁，地铁的线路和班次很多、出行很方便、当时国内大城市还没有地铁更没有高速铁路，时速3、4百公里的高铁真让人开了眼界。\n第一次乘坐新型车厢是2006年8月15日跟省局张汉文副局长一行五人从兰州到拉萨参加国家工商总局组织的全国商标保护协作会议，乘坐7月1日刚开通的青藏铁路兰州至拉萨的718次列车，新型车厢有GPS卫星定位系统、垃圾收集系统、独立和集中供氧系统、声像转播系统、一改过去绿皮车厢内脏乱差的现象，设计很人性化、乘坐十分舒适。如现在乘坐高铁和动车那就更安全、更舒适了。\n世事更迭、沧桑巨变，改革开放三十余年，国内的交通和通讯都发生了翻天覆地的变化，“要致富、先修路”，铁路经过改造实行了六次大提速，蒸汽机车也进了博物馆，内燃机车和电力机车主宰着铁路，铁路网线近几年都以每年1000公里左右增加，全国营运里程已近九万三干公里。高速铁路建设也加快了步伐、广武和京沪高铁已投入运营，G、D、T、K、L字头的列车可以任意选择，去年底还实行了网上和实名制购票，“黄牛党”也逐渐销声匿迹了。城市建地铁和轨道交通的也多起来了。而且，现在出行选择的交通方式和工具也很多，高速公路在国土上已覆盖成网、民航支线机场也日渐完臻，出行是方便多了。火车和铁路的发展变化从一个侧面看到了中国社会经济发展的脉搏。\n期盼中华民族的伟大复兴指日可待。"},{"id":33,"title":"关于“年”的呓语","category":"散文","date":"壬寅年除夕前夜","body":"白驹过隙，很快今年的年又到了。\n“年”是什么？关于“年”的传说很多，说很久很久以前“年”是一只常栖海底或原始森林中的凶猛无比的魔兽，每年这个季节的这一天“年”就会出来到各原始部落中来掠食家畜和人类，它不仅会吞噬掉弱者的肉体，还包括弱者的灵魂。这时候原始部落的首领为保护部落的安全，不仅会组织部落里的强壮者还会联络其它氏族部落首领在这个时分同时点上火堆让火光和柴火的哗哩啪啦声响来驱赶这个魔兽，因为“年”惧怕火、惧怕红色后来还不断衍生出贴春联放鞭炮驱逐邪神恶鬼让所有魑魅魍魉再不敢祸乱人间。\n“年”是什么？年就是一个传说。就是家庭和睦、邻里友善、民族团结。就是敢于抗击一切邪恶势力的中华民族精神。就是久而久之形成的全家团圆、归宗祭祖、除夕守岁、红包压岁、燃放鞭炮、张贴春联、窗花剪纸、互闹社火、叩拜大年、探亲访友……等固定的“过年”习俗。\n今年的“年”是什么？是新冠疫情下的社会“冷漠”，是变幻莫测一波又一波攻击人们且不断变异的新冠毒株，是昧了良心的核酸检测企业和不法药商，一切都是那么冷酷无情，国家打造给我们的的潘多拉魔盒、就是要求我们每个人都不可以置身事外、都应该是抗疫第一责任人、都必须扛起“自我救赎”的责任。\n今年这个“年”到底什么时候能过去，无人知晓，“专家”们的判断也不可尽信，听多了反而会无所适从，所以一切一切都只能在迷茫中摸索着与未来较量。当然最后一定会走出闹心的阴霾，让世界重新得到和平，让人们都回到祥和的正常生活之中。\n“年”是什么？年就是以坚韧的信心静悄悄的等待黎明的到来准备迎接美好的明天。\n什么是“年”？我坚信“年”绝不是人们传说中的恶魔，“年”应该是一个时间的“界碑”，这个季节这一天被称为“除夕”，除夕的子夜时分是今年与明年的交替，过了“今年”就到了“明年”，过了这个时分今年就成了去年，明年就成了今年，人们又会期盼着新的明年。\n一年三百六十五天，会被均匀的分为七十三个等份、每份五天即前天、昨天、今天、明天、后天。前天是遥远、昨天是过去我们不应该计较过往得失，但必须记牢历史的经验与教训，这五天中最重要的是把控好今天，一定要铭记“蹉跎歌”的提醒，浪费今天就是浪费生命。明天和后天都是未来、明天是追求的目标、后天是奋斗的方向。\n人生中还有童年、少年、青年、壮年、老年各个不同阶段有了“年”这块界碑、我们收获的是随年龄增加的成长和成熟，失去的永远是时间！有了这块界碑就可以对人生中各阶段进行检验，就可以丈量你人生中前行的每一步。人们憧憬的诗和远方千里之行只有始于足下，走好人生中的每个阶段的每一步才是极其重要的。\n一年四季春夏秋冬，周而复始永恒不变，今年除夕的时间位于数九寒天、九九八十一天的四九第四天，冬天将要过去春天还会远么？\n什么是年？回过头来看一看，年就是时间的刻度，就是四季的总结，就是对人生分分秒秒的累积与考量，就是对生命的消耗和对人生的感悟。\n“关于年的呓语”这数百字的表达与寄托可否作为激励自己活到老学到老的一篇檄文？愿与大家共同分享，同时也是希望对自己名字“康年”和所有亲朋好友的祝福。康年、康年。"},{"id":34,"title":"关城感悟","category":"诗","date":"甲辰年五月端午","body":"落日隐河山，浮光托雄关。\n峻岭绕白云，低峦淹漠间。\n孤城狼烟闲，暗河流水潺 。\n岁月无痕去，青春不复还。\n附记：初夏的一个傍晚，站在嘉峪关城楼上，看着落日渐渐的掉落在九眼泉里，慢慢的隐藏到悬壁长城的山后，此时血红的晚霞将关城托举到嘉峪关山上渲染得无比灿烂，如果到天下雄关碑亭前顺光摄一张城楼的照片，那种美伦美奂一定会吸引人的眼球。在此再放眼远眺祁连山大大小小的山峰尽浮现在远际天边的白云之间，山上的白雪闪耀着钻石般的光，那种“大漠孤烟直长河落日圆”，的视觉效果定可一饱眼福，近处低矮的山峦连绵不断淹没在戈壁瀚海之中，长城第一墩下暗藏着千仞璧立的大峡谷，其腹中的疏勒河潺潺流水是千百年来祁连山给予居住在大漠绿洲人们的恩赐，像苍龙一般欲昂首腾飞的悬壁长城遗迹，至今仍彰显着中华民族的骄傲。“长城文化”与“丝路文化”在这里交融，古代文明与现代文明在这里碰撞，尤以改革开放后嘉峪关的建设给这座边陲小城更换了全新的面貌，人们给它冠以“戈壁明珠”的称号一点也不为过，我在此学习工作生活了近四十年，青春年华基本都奉献到了这里，留了些许痕迹不足为奇，一生无怨无悔退休后回到了日思夜想的故乡，定居在江苏无锡，嘉峪关始终是我魂牵梦萦的地方，因为这里是我为之奋斗过的第二故乡，这也是诌一首短诗歌颂它的原由。"},{"id":35,"title":"喝酒·三景","category":"诗","date":"甲辰年二月初二","body":"一、群 喝 \n雪降塞外隐关城，邀友相叙聚寒门。\n今宵豪饮酒千觞，清醒糊涂各几人。\n二、对 饮 \n对面相座友谊纯，花生盐豆伴醴神。\n凡俗不计贵与贱，推杯一醉定行程。\n三、独 酌 \n岁月不辞添新轮，熙攘尘世度余生。\n悲喜尽在微醺后，三碗入肚自销魂。"},{"id":36,"title":"感悟惠山菊展","category":"词","date":"癸卯重阳后三日","body":"（江 城 子）\n众香国里悠然来。色百种，姿千态。\n美聚惠山，妩媚添秋彩。\n不负园丁勤培栽。献祥瑞，国运开。\n岁寒四友名不衰。凌霜放，铁骨在。\n品高人爱，清风展新颜。\n陶公篱旁解疑猜。君相问，论成败。\n附记：10月26日至11月26日惠山公园举办第十四次菊展。菊花是我国十大名花之一有悠久的栽培史。日本的菊花从唐代起由我国传入，17世纪末荷兰商人将菊花带入欧洲，18世纪传入法国、19世纪传入北美、至今已遍及全世界菊花飘洋过海开枝散叶深得世界人民的喜爱，经历代园艺人不断的栽培选育繁殖出很多新品种。据说目前全世界有各类品种约3000多个，仅无锡惠山菊花基因库就有品种800余个，其中国内品种600多个引进品种近200个。这次菊花展是中国园林协会和无锡文旅集团有限责任公司共同举办。参展的大中城市及园林单位有50余家参展作品1300多个，布展面积12万平方米、用花80余万盆。单瓣型、复瓣型、球型、莲座型、龙爪型、舞环型各式各样应有尽有，盛况空前。参展的帅旗，墨菊、绿牡丹、七彩菊，赤线金珠、千丝万缕、金狮漫舞、金龙腾云、金缕流霞、叶公好龙、凤凰振羽、春水绿波……等品种尤为珍贵，形象生动招人喜爱。开展日赏花的人海如潮摩肩接踵，铺开的花海似浪目不睱接。重阳赏菊的盛举历来是国泰民安的象征。饮酒赏菊、吟诗填词，也是彰显文人雅士闲适生活方式之首选。否则就没有陶公的“采菊东篱下，悠然见南山。”元稹的“不是花中偏爱菊，此花开尽更无花。”孟浩然的“待到重阳日，还来就菊花。”及清初无锡词人顾贞观的（苏幕遮·泾皋菊）“早归来，三泾里，衣的风流。欲傲君王紫，标格不容轻位置。根叶生香，君与莲花并。”等哙炙人口的诗词。莲花与菊花同被君子所爱，一爱其清廉清正，二爱其刚性刚直。这也是被中华文化、价值观所熏陶的必然。当然那些违背了道德品格的人生一定会遭到唾弃，甚至会被永远钉在历史耻辱柱上。二零一二年也是这个季节在宝岛台湾参观的士林菊展当时感到很不错但与无锡这次菊展的规模品种布展方式相比，那就逊色很多。参观了这次菊展一定会留下久久的回味让人难以忘怀，写这些碎语和拍摄照片、录几个短视频的目的是留存纪念，并激励自己和教育好子孙后辈，做人一定要永远做一个品格高尚的人。"},{"id":37,"title":"管社春色（一）","category":"诗","date":"乙已年三月卅日","body":"几阵绵纤春雨，一溪清浅花香。\n惠风播绿到池塘。荡起微波细浪。\n叶间翠鸟私语，水底锦鲤徜徉。\n小荷初露着新装，管社绝佳风光。\n附记：管社山庄是无锡的一处湿地公园西起管社山东靠犊山大坝南临万顷堂，北至环湖路，它地处太湖、蠡湖梁溪河交汇之处占地四十三点多公顷，园内有万顷堂、驻美亭、思源亭，万顷古渡杨家祠堂，虞美人崖、镇湖庵等古韵悠长相互映照的建筑群，这里是除鼋头渚以外观赏太湖的另一绝佳处，尤以园内一条约两公里长的木栈桥将各景点串联到一起，让人留连忘返。夏日百亩荷花盛开更是壮观，管社山庄亲民亲水，对外免费开放是游客打卡的好地方，游完管社山庄兴致大发，随以《西江月》词牌填词一首分享给大家，且作纪念。"},{"id":38,"title":"管社春色（四）","category":"诗","date":"甲辰年荷月小暑","body":"管社山庄植好莲，亭亭多姿立水面。\n绿意盎然轻摇蓬，楚楚动人分外妍。\n花开似霞染满天，清香扑鼻沁心田。\n夏日绽放秋採藕，凝眸风景爱无边。\n江南梅雨常连阴，游客赏荷欲争先。\n写生拍照留倩影，笑语欢歌舞翩跹。"},{"id":39,"title":"管社春色（三）","category":"诗","date":"癸卯七月十五日","body":"管社荷放清风来，红黄粉白斗艳开。\n老友童心兴致发，摘片荷叶当帽戴。\n好景易逝时不待，秋风乍起荷塘衰。\n採莲挖藕虽有趣，人生莫恋名与财。\n附记：赏荷，是炎炎夏日休憩消闲最美之事。由此让我想起六十年代末在杭州中村当兵时曾游览过西湖十景之一的“曲院风荷”那是我有生以来第一次看到那么多那么美的荷花，随想起宋·杨万里《晓出净慈寺送林子方》诗中所描述的“毕竟西湖六月中，风光不与四时同，接天莲叶无穷碧，映日荷花别样红”的意境是多么的美妙、迷人，每次观赏过无锡管社山庄的荷总有不同的感受“曲院风荷”在西湖苏堤西北角面积不足一亩仅此就不可与管社山庄相比，管社山庄的荷塘有两公里长，木栈道穿行荷塘中间供游人更加亲近观赏到荷的色质姿态，看管社山庄的荷视野是那么的开阔真是一眼望不到边，观管社山庄的荷、红黄粉白竞相开放一抹托底的绿、让人的心境是那么的清亮透明赏管社山庄的荷不仅如入仙境还能让人有更深层次的哲学思考，让人品味“荷”你在一起的高尚人格昧力、“荷”气生财古老商业经营理念，家“荷”万事兴的治家格言，“荷荷”美美的人际关系，这些潜移默化的传统文化充满无限的正能量，可让人获得精神的升华。“风光不与四时同”秋天的残荷虽也有美妙之处，但客观的讲已失去了妩媚之美、留下的只是悲壮之美。管社山庄的“荷”是平凡的又是很伟大的，观赏管社山庄的荷并悟出一些道理的人也应该是聪明有灵慧的。在我的渲染下常州的老吴、王总赵总等几位以心相照、以情相投的好友不顾三伏天的闷热、下决心要来管社山庄看荷花，一群人边观赏边谈笑风生议论着赏荷的感悟、看到他们心情特别欢畅特别兴奋的样子很高兴，我自作主张将他们以“荷”相论以“荷”交人的各自所感所悟和我的一些灵感汇集在一起作小诗一首以记之。同时将前两次的感悟一起发给各位好友互勉希望得到更多的批评意见。"},{"id":40,"title":"管社春色（二）","category":"诗","date":"癸卯夏至后四日","body":"细雨纷飞起轻霭，滴嗒声柔催花开。\n千亩娇艳送清香，玉珠堆满翻翠盖。\n天上瑶池菡萏栽，人间赏荷数管社。\n自古颂莲清廉风，不妄君子当自爱。\n附记：管社山庄是无锡旅游打卡胜地，位于太湖、蠡湖、梁溪河三水交汇之处，山庄内有万顷堂、虞美人崖、驻美亭、泽惠亭、杨公祠堂……等，多个各具一格的景点，尤以万顷堂壮观、视野开阔，在此可左望鼋头渚、中看犊山、右眺大小箕山，将远山近水尽收眼底。山庄内两公里长的木栈道穿行于荷花绿植之间，梅雨时节雨随下随停、雨中赏荷人若入仙境自置于画中，悠闲自得可释放城市病带来的烦恼与压力，体验一把慢生活的乐趣。这次来管社山庄赏荷是应好友老施的邀约，不觉与二零一七的夏至日首访已相隔整整六年，其间我和老伴又得一个可爱的小外孙乳名珰珰即将上幼儿园大班，惊叹时间飞快怎能拖得住不老的脚步？午餐在梁青路老宅颐景花园对面的烧老鹅店、对酒当歌人生几何，感谢好友老施的邀约并附几张照相、同样写拙诗一首备记我们之间的友谊。"},{"id":41,"title":"读书随感","category":"散文","date":"二零一二年三月十日","body":"一个学富五车、知识渊博的人，必然是一个善于向实践、向书本学习的人。\n读书，是一个修身养性的高品味活动。\n说到读书可能就要思考这么几个问题，为什么要读书？读什么样的书？怎样去读书？\n“书”，是精神产品、是知识的宝库、是文字发明以后古人用来记载生产、生活过程中经过探索实践的经验积累。\n人们读书的终极目的是什么？是站在前人的肩膀上用己有的生产、生活经验、指导少走探索的弯路。有了知识、就可以让短暂的生命、获得更高的生存质量。\n读书是为了过好日子的功利性是不可否认的，但宋真宗皇帝的《劝学文》：“富家不用买良田，书中自有千钟粟；安居不用架高堂，书中自有黄金屋；出门莫恨无人随，书中车马多如簇；娶妻莫恨无良媒，书中自有颜如玉；男儿要遂平生志，六经勤向窗前读。”这种“万般皆下品、唯有读书高”，把读书作为入仕进阶敲门砖的观念、却不敢完全苛同，“知书达礼”、约束自己、管理社会，才应该是读书人的价值取向。\n书，是知识的海洋，是智慧的翅膀，在现代每年编著的无论是自然科学类还是社会科学类的书籍之多都是浩瀚无比的。当今正处于一个信息爆炸的时代、即使让一个人的生命期扩大十倍、每天二十四小时不休息，一生也不可能将所有的书读完。所以，读书要有选择的读，首先要读必读之书，必读之书是从幼儿园开始、小学、中学、大学各个层级及相关专业的教课书，它是人们接受教育、完成学业、为进入社会角色做好准备、从书本中汲取营养奠定基础的必由之路。读这些书、读好这些书不仅重要而且尤为必要。其它可以根据个人的兴趣爱好和需要选择一览而过略记概要，也可以选择一些进行精读和细读。\n读书，某种程度上是读者与作者一种心灵的沟通和情感的交流，今年春晚上的一个小品《穿越》仅是个娱乐人的笑话而已，实际上品读古今中外名著不就是穿越时空与先贤哲人对话吗？有时读到好书中的一些哲理、一些名言、真让人有茅塞顿开的喜悦。\n读书，要有一个不受干扰、比较安静的环境，一部书、一壶茗，细嚼慢咽、读到出神入化之时还可以做一些笔记，日后要用时可以随手拈来，只有这样才是上乘的读书品味。我读书很随意、对一些无关紧要的书我只是翻一翻、看看篇幅与《序》，对一些感兴趣的如中国古典《四大名著》、《唐诗宋词》、《四书五经》、《中国通史》等，才拿来认真的读，“认真”必须是看两遍以上，第一遍通读做个了解、第二遍带着问题到精品章节中去找答案。至今，精读细读的书目还没有，譬如《红楼梦》你要精读细读就要参加《红》学会，去认真的研究它。\n开卷有益、读书更重要的是要“解放思想”、多与其它兴趣相投的读者进行讨论和交流，不断的提高认识、增长见识，只有这样才能读出真才实学。中国古代的士大夫不是很重视立德、立功、立言吗？读书，大概也是其中一条捷径吧。\n读书的方法很重要，孔子曾说：“学而不思则罔，思而不学则殆。”明代人陈鎏也说：“读书须知出入法：始当求所以入，终当求所以出。见得亲切，此是入书法；用得透脱，此是出书法。”古圣的意思都是说读书要善于思考、更在于应用。决不能死读书、读死书、成为“书呆子”，重要的是能把所学的知识举一反三，触类旁通。\n读书必须有书，改革开放后人们的物质生活逐渐富起来了，有钱的人们有的忙于炫豪斗富，炫豪宅、炫香车宝马、甚至炫包了几个二奶，能炫的都炫；有的忙于搞收藏，藏金藏银、藏古董文物、能收藏的都收藏；有的忙于搞投机、炒房炒地、炒茶炒酒、炒股票炒期货、能炒的都炒。在书架上多添一些书的位数真不多。我也是一位“仇富者”，对这些没文化素养的富豪们只重物质享受、不重精神升华、庸俗不堪的行为是嗤之以鼻的。\n最近，小撒跑两会采访了很多官员、名人、百姓今年为自己制定的“幸福计划”，我感到官员的比较虚伪、名人的比较庸俗、百姓的比较实际。我也赶时髦为自己制定一个粗俗的“幸福计划”就是在书架上能多添一些我喜欢读的书，更多的是圆我少年时期读书的梦。"},{"id":42,"title":"乐游陆巷古村散记","category":"散文","date":"二零二五年十一月八日","body":"十一月八日周五，是立冬后的第一天，随都大明老师的餐旅文化班去苏州东山陆巷古村体验生活，四十九位学友八点准时在无锡人民大会堂门前集合乘大巴一路颠簸两小时十点钟到达。\n是日，虽已入冬最高气温仍有二十二摄氏度，天气晴朗、阳光明媚、温暖如春。“十月小阳春”并非虚言，这是天公给江南水乡的恩赐。\n陆巷是首批入选中国历史文化古村落的，素有“江南第一村”的美称。下车后首先映入眼帘的是近山叠翠，远山含黛、湖面浩淼、水天一色，漫山遍野的枇杷树被果农当作宝贝一样用钢管搭架照护了起来，枇杷树已经挂花、如果今冬无特殊的灾害性天气明年一定会大丰收。“白沙枇杷、小红蜜橘、乌紫杨梅、碧螺春茶”是东山响当当的名片，电影《桔子红了》就是在这里取的外景。\n陆巷古村三面环山，一面临水房舍依山而建，鳞次栉比、白墙黛瓦、古色古香。村后背靠莫厘峰，东有寒谷山、西有箭壶山，村前面临浩瀚的太湖，“万顷湖光碧连天，千只鸥群伴帆影”的秀美景观诠释了唐朝诗人王勃所作《滕王阁序》中经典名句“落霞与孤鹜齐飞，秋水共长天一色”的美妙之处。在这神仙居住的地方还让人获得精神上的享受，陆巷被称为“历史文化古村落”绝对不辱“上有天堂下有苏杭”的美誉。\n步行进村，村前有条直通太湖的小河、河水清澈见底，随着缓缓流动的河水小鱼追逐戏嬉、水草摇曳摆动、这种原生态的情景一定会勾起老年团大部分人对童年时代美好的回忆。\n陆巷古村始建于宋，“宝俭堂”是南宋户部尚书文学家词人叶梦得的故居、已有千年历史。村中至今仍有保存得较完好的三十多幢明清建筑。古村内的宝俭堂、惠和堂、怀德堂、怀古堂、粹和堂、遂高堂是参观的主要景点。“堂”应该与家庙宗祠相关，应是几大家族散枝开叶的繁衍之地，此猜想对错否？有待深入探讨。\n陆巷也是明正德年间宰相王鏊的故里，其相府“惠和堂”是一处明清所建的大型建筑群临街门面挂有“惠和堂”的匾额简约朴实，与其它民房相比并无特殊，进门后却别有洞天，整体占地面积约五千多平方米，建筑物面积约有两千多平方米，建有厅堂楼房一百零四间，其轩堂大都用楠木拱建而成很豪华，府内有私家花园亭榭长廊、曲水假山、柳荫修竹、各种花草树木布置得玲珑精巧，保存得十分完好。其它堂号各具特色、但与其相比总觉次之，大都有本姓后裔散居在内。\n陆巷的街道巷陌大都是条石和青砖铺就，目测主街道宽不超一丈、其它不过六尺，“六尺巷”的故事可能也是古时巷道建设的标准尺寸。主街道上立有纪念王鏊乡试、会试、殿试获得解元、会元、探花三考三捷的三座牌楼、蔚为壮观。\n古村中的所有景点对七十岁以上的老人和军警等特殊人群都是免费开放的，很贴心很友好。\n陆巷古村没有像其它古镇那样开发得商业气氛太浓，少有农户会卖一点自产的土特产，古村面貌基本保持了原汁原味，原住民仍在这里享受着静谧、整洁、古朴、悠闲舒适的日子，这里没有城市里那种喧闹和水泥森林般的压抑，不拥挤不俗气，这里却有烟火气浓厚的民宿，可供游客来此打卡慢慢品味这里的人文情怀。\n景点游览完毕后在一家叶姓民宿用午餐（应该也是叶梦得的后裔子孙）他家没有诱人的广告也没有光鲜的店名字号，无客人时纯粹是一户平常人家，夫妻二人和一个儿子有客时父亲掌厨母亲当服务员儿子当勤杂工、三人分工协同，全靠货真价实、物美价廉和优质的服务吸引游客、将民宿经营得风生水起。\n餐桌上十几个菜品的食材皆是土生土长，“太湖三白”是迎宾首选，干炸小鱼和红烧田鸡，这些妈妈的味道，在城里的宴席上基本上是看不到的，清蒸咸蹄和红烧鳗鱼本帮味十足，豆干炒水芹和清炒素三鲜（鸡头米、菱角、藕片）江南“水八鲜”有一半上了桌，清炖老鸭煲特别适合老年人，肉质酥烂汤汁鲜美，主人的厨艺可称一绝。\n餐费由都老师慷慨解囊一人承担。愧意多多。另可惜未将菜谱用文字或镜头一一记录下来。\n都老师的餐旅文化学识功底甚厚，他讲授的蔬菜瓜果栽培与营养健康知识丰富，因地理位置气候冷暖不同就有了“南橘北枳”的故事，蔬菜瓜果一年四季二十四个节气都有适应当时当地生长的品种。据专家研究人的长寿与“生存环境良好情绪、饮食习惯、充足睡眠、适当运动、基因遗传”六大因素密切相关。都老师建议多食与时令一致的瓜果蔬菜有益于健康长寿的理念和古人“一方水土养一方人”的精辟总结，值得推崇传承发扬。\n返程途径苏州木渎古镇，顺道游览了两小时，木渎位于苏州城西距城中心十五公里，一条河流穿镇而过将木渎古镇一分为二，秋色也很漂亮，主街道名称与姑苏区的山塘街同名也是条石铺就，两边商铺售卖的纪品在全国各地景点都能看到，有特色的不多，倒是街道条石的下面掩盖着雨水排泄的渠道这种设置体现了前人的智慧。镇上有几处景点“严家花园”和“虹饮山庄”值得看看，虹饮山庄与无锡的惠山古镇同是乾隆皇帝六次下江南必到的歇息之地。虹饮山庄内藏有乾隆十二年十月初一在此用晚膳的菜谱，每道菜的名称、食材制作厨师、使用的餐具都有翔实记录。看来所有菜品并非十分奢糜，现在一般的百姓也吃得起。因时间紧促只能走马观花。\n苏州地铁五号线已通此地灵岩山站一出口就是木渎镇的游客中心，苏州地铁十一号线与上海地铁十一号线已经互联互通，极大方便了人们出行旅游的交通选择，苏州地铁三号线和无锡地铁三号线已在建设，不久将汇集于硕放机场。\n为组织这次活动周班长、胡班长、方班长费尽了心机，将活动安排得井井有条、细致周到，他们热情为大家服务的精神可圈可点，可敬可佩。在此我代表大家谢谢他们。\n这次团队要求八十岁以上的学友要有家人陪伴，基本上都做到了，这充分体现了尊老爱老的“孝道”文化得到了有序传承，也让“老有所乐”的愿望得到了释放，江南不仅山水美，人的心灵更美。\n如将这次活动的环境、气候、氛围、情绪等林林总总的有点集合起来，大家是不是觉得用“快乐、惬意”四个字来表达最为合适。\n再一次感谢都老师，感谢各位班长，感谢各位老大姐老大哥、感谢各位团友，感谢陆巷。\n苏州有两个陆巷，另一个在昆山常熟之间、旅友们出门旅游时千万不要搞错哟。\n“奇文共欣赏，疑义相与析”文中有错误的地方期盼得到大家的批评指正。"},{"id":43,"title":"军魂","category":"词","date":"二零二三年八一节","body":"（江城子）\n八一庆典换盛装。豪情激，壮志刚。严阵以待，不负党希望。勤训苦练王师样，战必胜，我担当。\n战友情深难相忘。如兄弟，互相帮。祖国放心，好男志四方。军人本色迎难上，召必回，旌旗张。\n附记：1、凡当过兵的人都有一份军人情结，有过那段人生过往中当兵的历史觉得无怨无悔，还一直以此而自豪和骄傲，每年的八一建军节到来就会引发诸多思念。那些在解放军这座大学校、大熔炉里点点滴滴的往事虽然过去了几十年，但回想起来仍然是那样的甜蜜、那样的津津有味。我曾在陆军二十军五十九师一七六团特务连当侦察兵。因此上海青浦淀山湖，江苏宜兴团氿湖，安徽当涂丹阳湖的武装泅渡训练、当涂横山夜间孤胆及反侦察训练，江苏宜兴湖父镇岗下村野外驻训，浙江杭州中村反坦克训练，侦察排当涂至青浦小规模的长途拉练，特别是1973年11月全军冬训进行了以实战为背景的大规模军事演习，一天一百二十公里的急行军，边打边防，干中学、学中干，那种艰辛（虽比不上二十军在朝鲜战场上的艰苦）是常人想不到的，才真正锻炼了人的意志。捕俘格斗、投弹射击等冬练三九夏练三伏的日常训练虽苦犹乐，至今仍历历在目，尤其训练中受到首长的关怀、战友的帮助永远不会忘怀。在此建军九十六周年之际用《江城子》词牌填“军魂”这首词，此目的是让我的战友，我的军人朋友及所有的军人在当今时势并不太平的情况下仍要不忘初心砥砺前行。并祝诸位首长战友及所有军人建军节快乐！\n2、我将上片“战必胜，我担当”和下片“召必回，旌旗张”分别写成现役和退役军人的军魂所在，以示对所有军人召之即来、来之能战、战之必胜的信心和崇敬。\n3、江城子，词牌名双调七十字，上下片各八句，三十五字，五平韵。"},{"id":44,"title":"劳动节颂","category":"诗","date":"二零二四年五一节","body":"五一节临赞劳动，\n创造历史最光荣。\n世上真无救世主，\n革命生产靠群众。\n鄙视劳动寄生虫，\n资本收割已成风，\n人民当家作主人，\n重塑世界共大同。"},{"id":45,"title":"和《七绝•赞抗击新冠肺炎逆行英雄","category":"诗","date":"二零二四年","body":"瘴魔肆虐袭我家，\n天使誓行扫毒花。\n守望相助胜手足，\n万国齐赞大中华。\n附：朱文泉将军原作：\n《七绝•赞抗击新冠肺炎逆行英雄》\n荆楚瘴烟遮月华，\n他乡征战己为家。\n大军指处魔关破，\n热血浇开十万花。"},{"id":46,"title":"回家过年","category":"诗","date":"癸卯年除夕前夜","body":"疫情三年断行踪，\n隔绝亲情理难容。\n瘟神未达全然送，\n过年可期喜相逢。\n回家过年脚生风，\n思亲泪落拥怀中。\n人生自有来去处，\n谁能无家忘祖宗。\n阖家团圆乐无穷，\n国泰民安开门红。\n过年节俭少糜费，\n恭喜发财添福永。"},{"id":47,"title":"寄畅园一课","category":"散文","date":"甲辰年良月廿六","body":"无锡人去惠山古镇游寄畅园应是家常便饭的事。我作为一位退休后在无锡定居十余年的准无锡人游寄畅园，同样具有得天独厚的优越条件，七十岁以上免门票、交通也十分便利，乘坐小区门口的地铁四号线八站，即到惠山古镇站从六号口出便是。乾隆皇帝亲笔所题的“惟惠山幽雅闲静”石刻匾额镶嵌在临街左侧的墙面上。\n古镇直街与横街相交叉的地方、就是惠山寺山门，具有历史感的两座宋代石经幢矗立在山门两侧。\n惠山古镇去了很多次，大都是杜鹃盛开和有菊花展的季节、天气晴好的日子，游寄畅园仅是顺道而过，可算是名符其实的走马观花。因此对寄畅园的历史掌故、文化内涵也就没有太多深刻的认知。\n十一月二十五日，是金石声老师本学期“无锡文化”的最后一节课，安排游学寄畅园。是日，天下小雨，虽入冬但最高气温仍有十七度暖如秋日，惠山锡山被雨水清洗的树木红的更红，黄的娇黄，绿的苍翠龙光塔在雨幕中若隐若现，雨中游园别有一番情趣。\n在游学过程中金老师用他渊博的知识讲述了寄畅园的前世今生和许多至今人们尚未知晓的故事，让我们真的大开了眼界。\n寄畅园是一处建于明代的古典园林，园址原为惠山寺寓房的二僧舍，明嘉靖初年，（约公元1527年前后）曾任兵部尚书的邑人秦金所得，辟为私家花园，经其历代后人多次疏浚池塘，广植树木，改筑园居，构园造景二十处，全园分东西两部分，东部以小池小塘，曲径长廊为主，西部以假山树木房舍为主。寄畅园是取东晋书法家王羲之《答许椽》诗“取欢仁智乐，寄畅山月阴”句中的“寄畅”二字而得名。一九五二年秦家后人将此园献给国家成为人民公园，文革期间无锡工人书法家王季鹤的墨宝“郁盘”二字悬挂在“锦汇漪”（古称锦涟汇）旁“郁盘亭”的上方，其右边悬挂着战国时期《庄子•秋水》篇里、庄子与惠子一段具有哲学意义的对话《鱼乐》，沿锦汇漪周边还建有知鱼槛、涵碧亭、清响月洞曲径长廊等建筑，相互映衬，相得益彰。耸立的山、灵动的水、古朴的树、巧构的景、真假自然，经过不断的完善，凝练为最具江南特色的古典园林、是国家级5A景区，值得来此打卡游玩。\n清康熙、乾隆二帝每人都是六下江南，七次驻跸于此，犹乾隆皇帝对惠山寺寄畅园情有独钟，留有一百一十余首赞美的诗词，并将寄畅园复制到北京颐和园内，称之为“谐趣园”。清朝不仅是康熙乾隆二帝来过寄畅园，其实清雍正嘉庆皇帝也来过，他们不是称帝后来的，而都是在当皇子时随父皇南巡时来过寄畅园。\n明万历年间著名画家宋懋晋画有“寄畅园五十景”的册页现在将册页中的园景与现实版对照绝大部份还是原景原样，寄畅园保护建设得如此之好是历朝历代有识之士与园林人的功劳与骄傲。\n在寄畅园的“荷轩”旁，有两名六十岁左右的摄影师搭上长枪短炮，无声无息的不知在静等什么？时间好像定了格。面前荷塘内只有枯萎的残叶，折弯的荷梗，凑上前去搭讪方知是等小鸟栖息到枯萎荷梗上时抢拍照片，此情趣意境告诉我们，池中虽是衰败的残荷、但同样会有小鸟来爱。来年也一定会重发新芽，开出最美丽的花。就是这不经意的瞬间、不知会浸染多少人的心，让我们领悟人生不仅可以有诗和远方更应该珍惜现有的草木人间。\n我借用元代马致远（天净沙）词牌《秋思》词，学填一首《期盼》诠释眼前这一刻的情和景，“初冬风微雨小，残荷枯梗侯鸟，寒来暑往人老，期盼春风，树发芽原上草。”\n金老师还给大家详细讲解了“华孝子祠”家族的历史过往。“忠孝”二字是我们的国魂，是历代仁人志士“修身、齐家、治国、平天下”的最高境界，永远值得传承发扬。\n清名画家王石谷也给寄畅园画了《寄畅园十六景》的册页，据说并给每景都题诗一首，我查阅了不少资料终未查到。根据昨天主要场景的回忆写诗一首并附几张相关的照片记录寄畅园这一课的收获，同时珍藏为以后回忆时的可查资料。\n《锦涟汇》\n寄畅园中锦涟汇，\n冬时犹如秋日归。\n池中鱼戏自知乐，\n枫杨斜影亦成趣。\n雨打水面镜破碎，\n荡起涟漪烟霭飞。\n明月秋风寄郁盘，\n美景胜收谁不醉。\n附记：关于“郁盘”的说法有两种，1、“郁盘”出于唐朝诗人王维的《辋川园图》中“岩岫盘郁，云飞水动”之句，珍容郁郁葱葱的树木倒映在“锦汇漪”之中，倒影不仅随风而动而且还随水而动，趣意十足。2、传说乾隆皇帝在此召惠山寺僧人下棋，僧人棋艺非凡，在乾隆皇帝手足无措时，僧人虚晃一枪，让乾隆皇帝险胜，乾隆皇帝心知肚明是僧人有意让棋，遂心中不快为此郁闷，便下旨将此改为“郁盘亭”。3、马致远《秋思》老树枯籐昏鸦，小桥流水人家，古道西风瘦马，夕阳西下，断肠人在天涯。"},{"id":48,"title":"惊蛰","category":"诗","date":"癸卯年惊蛰节日","body":"（一）\n惊雷乍响天地开，\n蛰虫诞醒翻身来。\n一夜细雨润大地，\n万物复苏人释怀。\n惊蛰雷声送九尽，\n杜鹃啼血唤人勤。\n种豆种瓜好时节，\n邀友踏青宜早行。\n（二）\n惊雷乍响天地开，\n蛰虫诞醒翻身来。\n一夜细雨润大地，\n万物复苏人释怀。\n惊蛰雷声送九尽，\n杜鹃啼血唤人勤。\n种豆种瓜好时节，\n邀友踏青宜早行。"},{"id":49,"title":"抗疫对联","category":"对联","date":"二零二四年","body":"上联：一根棉签搅动天下诸喉，\n下联：三寸试管探明世间阴阳。\n横批：无疫而安"},{"id":50,"title":"江城子·端午感赋","category":"词","date":"癸卯年五月端午","body":"不事二主不折腰。投汩罗，浪涛滔。江水流淌，千秋唱离骚。华夏群英永不凋。屈子魂，传今朝。\n舟楫博击赛龙蛟。抢争先，听鼓号。民族兴旺，万代颂舜尧。时势变幻如我操。国运盛，成大道。\n附：江城子，词牌名。双调七十字，上下片各八句，均三十五字五平韵。\n端午节是中华民族优秀的传统节日，因为她饱含了最优秀的传统文化，也是中华文化自信的净土。格物致知，文以化成，她是传承培养中华民族优秀人才的摇篮，这样的节日值得纪念。还因两日前中美两国高层会谈成功，充分体现了我大国外交人才辈出有智慧有韧性，可喜可贺，因此，我用江城子词牌填词一首《端午感赋》献给祖国母亲和你并祝你全家端午节安康，幸福吉祥。欢迎你全家来无锡玩。"},{"id":51,"title":"祁连山赞","category":"诗","date":"甲辰龙年夏至节","body":"祁连群峰穿九霄，\n峻岭叠嶂云中飘。\n横亘千里隔南北，\n矗立万年挺直腰。\n青山不老雪为帽，\n冰川溶乳赐灌浇。\n绿洲草原农牧兴，\n森林峡谷藏国宝。\n国运昌盛好瑞兆，\n西部开发湧新潮。\n牵手秦岭阿尔金，\n振兴致富护环保。\n附记：祁连山是我国著名的高山之一，位于甘肃省和青海省内，山脉呈西北东南走向全长800余公里，山体宽窄在两百至四百公里之间，海拔在四千米至六千米之间，总面积两千零六十二平方公里。山脉东连秦岭西接阿尔金山，海拔四千米以上的山峰众多终年积雪，有冰川三千三百零六条，融化的雪水灌溉着绿洲农业，湿冷的气候更宜牧草生长，牦牛成群、羊肥马壮，是我国的五大牧场之一。茂密的森林中生物多样性蕴藏着众多的珍稀动植物，同时还蕴藏着石棉、黄铁矿、铬铁矿铅锌铜等诸多优良矿产，二零一七年国家已确定开发“祁连山国家森林公园”的试点工作。戈壁明珠嘉峪关市就座落在祁连山脚下，年轻时曾多次陪伴贵宾攀登过亚洲离城市最近的“七一冰川”，哪种半天穿越四季的感觉久久不能忘怀，对那些贵宾的美好印象也永远铭刻在心，这些深深的回忆激发了我对祁连山的赞颂。"},{"id":52,"title":"祁连春早","category":"诗","date":"甲辰正月惊蛰日","body":"祁连雪山卧玉龙，\n塞上尘清望碧空。\n艳阳高照三千里，\n暖意渐融二月中。\n春风吹开桃花红，\n柳丝轻拂燕语哝。\n人间美景复又来，\n惊蛰一雷天地动。"},{"id":53,"title":"离别情思","category":"诗","date":"二零二二年八一","body":"离情别绪思战友，\n翘盼重逢今聚首。\n少年曾怀报国梦，\n不负韶华初心守。\n瞬逝军旅五十秋，\n历历在目话不休。\n青春已过白了头，\n乐享天伦敬杯酒。"},{"id":54,"title":"芒种","category":"诗","date":"甲辰龙年芒种日","body":"蚕老麦熟枇杷黄，\n三夏丰收农家忙。\n日出而作日落息，\n低头弯腰抢插秧。\n指盼晴日晒谷场，\n不辞辛劳多打粮。\n杜鹃催人不觉累，\n相庆颗粒全归仓。"},{"id":55,"title":"蠡园冬景","category":"词","date":"癸卯年冬月初二","body":"（行香子）\n天降瑞兆，琼花舞飘。\n堆雪人，老少兴高。\n楼阁掛凌。树戴白帽。\n园/展玉颜、胜广寒、\n时癸卯。\n素装银袍，鹤鸣九皋。\n翠嶂峰，绿衰山腰。\n观鸭觅食，湖边独钓。\n闲/作诗画、留倩影，\n怡情调。\n附记：1、行香子，曲牌名。上下两片，各三十三字。上片八句四平韵。下片八句三平韵。亦有六十八字，上下片各为八句，四平韵。及六十四字，上下片各为八句，五平韵等变体。2、唐朝伟大诗人孟浩然（689—740）其代表作《春晓》春眠不觉晓，处处闻啼鸟。夜来风雨声，花落知多少。短短二十字、其意境情深意广，像水墨画卷呈现眼前铭刻心上，总会引发后人瞑思遐想。3、蠡园，位于无锡太湖之滨蠡湖景区，是国家四A级旅游胜地，占地132亩，蠡湖又名漆湖五里湖，据传春秋时越国大夫范蠡偕美人西施乘舟而来并隐居于湖中小岛西施庄，与蠡园隔水而望。由此湖因人而得名，园又以湖而得名。整个景区以水见长，堤岸帎水，碧波荡漾。园内假山池塘、修竹绿植、相互映照，亭榭廊桥、楼阁曲径、点缀其间，恰似江南女子的妩媚软柔之美，蠡园虽然不大，小巧玲珑，但其景观可集江南诸多园林之美于一身，只有过之，而无不及。远眺翠峰叠嶂、近闻白浪拍岸。登上“濯锦”阁凭栏望去雪浪绿烟、漆塘山岗、长广溪水等景观尽可收入眼底。清明节前几日与老伴踏青春游去了蠡园。观其景、牵其情并受《春晓》诗作的感染随填行香子词《蠡园春晓》一首，并附照片以记之。"},{"id":56,"title":"蠡园春晓","category":"词","date":"癸卯清明前三日","body":"（行香子）\n风和日照。亭阁栈道。\n桃花开，绿染柳梢。\n堤边浪轻。湖面霭飘。\n看/燕莺飞。蒲草长。\n春来早。\n夜听风雨。朝闻啼鸟。\n池中鱼，逐食戏闹。\n碑廊故事。各领风骚。\n望/远山青。近水秀。\n风光好。"},{"id":57,"title":"蠡园秋色","category":"词","date":"癸卯深秋于蠡园","body":"（行香子）\n卸去夏妆，荷败藕塘。\n望长空，归雁成行。\n水天一色，湖映斜阳。\n看/竹叶青，枫叶红，\n杏叶黄。\n芦荻花飞，和风轻飏。\n换季节，秋高气爽。\n景好依旧，色添沧茫。\n乍/寒风起、露凝霜、\n夜渐长。"},{"id":58,"title":"蠡湖踏青见闻","category":"诗","date":"甲辰季春廿九日","body":"陌上渐暖草色新，\n路边樱放柳如烟。\n浩淼湖水映天碧，\n成群燕鸥迴北迁。\n春光可惜贵如金，\n纸鸢扶摇和风轻。\n眼前人物皆着彩，\n放浪形意随我心。"},{"id":59,"title":"贺岁","category":"诗","date":"癸卯年正月初二","body":"千载传承年与岁，\n高雅平俗蕴情趣。\n虎兔交替呈祥瑞，\n除夕相守无人睡。\n春到人间红携翠，\n暗霭旧梦随鞭碎。\n新人新事新气象，\n添福添寿添富贵。\n万里河山阳光媚，\n岸边柳发燕子飞。\n人勤春早希望播，\n天道酬酢酩酊醉。\n注释：日月星辰，混沌开天。春夏秋冬，亘古不变。“过年”只是时间的交替，已传承了几千年。“过年”的习俗上至皇家贵族、下至黎民百姓，基本上约定俗成、都蕴藏着中华文明的情趣和密码，更离不开现实生活和对未来美好愿望的追求。今年的除夕夜嘉峪关遭寒潮来袭飘洒了些雪花，这也是天降祥瑞之兆。“守岁”习惯传承之今、依然保持岿然不动，这正好证明中华民族的强大和韧性。春节给人们带来了热烈，春天给人们带来了希望，一切陈旧的、戾气的、颓废的、暗淡的陋习和不切实际的梦想都会被除夕之夜的炮竹声击得粉碎，扔进历史的垃圾堆，一个崭新的充满生命力的世界会展现人间，“新人新事新气象”，“添福添寿添富贵”。这是我献给大家的贺岁词。春天是新一年的开始，她总给人们带来新的希望，春天是播种的季节，只有不误农时才会有收获，“幸福是奋斗出来的”，自古天道酬勤，当通过你的努力获得一些成功时，上天一定会赐给你美酒让你喝到酩酊大醉。这就是在新旧交替时许下的愿望，这也是对新年新岁的祝福！"},{"id":60,"title":"酒狂","category":"诗","date":"癸卯年正月十五","body":"陈酿桂花庆中秋，\n邀友赋诗举觥筹。\n老夫聊发不知醉，\n醒来巳是九月九。\n阅尽人生两杯酒，\n一杯欢乐一杯愁。\n既成黄泉相邀客，\n饮罢斗酒欲几何。"},{"id":61,"title":"酒徒画像","category":"词","date":"己巳蛇年清明节","body":"（行香子）\n深居陋室，简出独行。\n自沽酒，常邀“刘伶”。\n日刷视频，夜数流星。\n追/水中月，杯中影，\n梦中吟。\n不慕神仙，心无阴晴，\n且由我，涂抹生平。\n胡乱酣醉，要甚声名。\n随/单身来，只身去，\n一身轻。\n附记：现代社会有不少乱象之一据有关报道二零二四年我国新生儿九百五十二万，死亡人数一千一百多万人，人口自然增长率负千分之一点三，究其原因，年轻人认为现在为父母养老无能为力，抚育下一代更是压力山大，认为自身所负的两难抉择又为什么要传给下一代呢？于是中华传统的生儿育女传宗接代，养儿防老积谷防饥的生育观就被揉得粉碎，如何才能让中华民族生生不息兴旺发达不断繁洐下去呢？值得深思，需加于措施重新提振人口意识。乱象之二，有一些年轻人不求上进，心甘躺平网上有一则消息说有一对社会最底层的夫妻男的开出租车女的做环卫工，夫妻二人不辞辛劳节衣缩食培养独生子上大学，四年学有所成，毕业后找工作眼高手底总因岗位薪酬不如意，不愿上班，因此找不到工作责怪于父母没本事，于是回家躺平啃老度日，只要父母提及找工作之事就会发飙斗狠甚至用死相威胁，这种不知反哺报恩“我的地盘我做主”如同一句广告词的人生观，是不是值得反思难道家庭、社会、学校的教育能与此无关？为此将这些懒人、疯人、对社会一点都不负责任的渣人喻为醉生梦死、糊里糊涂的酒徒，填词一首以表讽刺并以此为社会提出警醒。"},{"id":62,"title":"酒逢知己","category":"诗","date":"乙巳年三月初十","body":"雨浇浮世醴洗心，\n自古樽中觅知音。\n酒逢知己千杯少，\n与君同行喝不尽。\n此生不才诚守信，\n无知狂言论古今。\n花马金裘换一醉，\n独揽清风入我襟。"},{"id":63,"title":"金匮公园赏樱","category":"诗","date":"庚子年—清明节","body":"金匮樱花堪可夸，\n灿烂绚丽如云霞。\n报春虽输梅林晚，\n装扮春天添一家。\n附记：金匮公园是无锡一座新造的人工公园，具体位置于苏锡路西、立德道东，高浪路南、观山路北，紧傍无锡市民服务中心。公园占地65万平方米，主题突出山水交融。园内广栽林木、遍种花草，引种多种水生植物。园内春日樱花布径道，夏日荷莲满池塘，秋日杏枫铺草地，冬日松梅遮青山。园内有樱花近5000株、染井吉野樱、紫日矮樱、福建山樱花、毛樱花，重瓣红、白樱花多个品种，犹以日本晚樱居多。所以，花期略晚于鼋头渚樱花谷的樱花。虽花的品种、种植面积皆不如樱花谷，但公园全面对外开放且不售门票，花期略晚这些正好有补遗拾缺之功能，不失为游人春日赏樱另一好去处。"},{"id":64,"title":"人生价值","category":"诗","date":"甲辰年腊月初五","body":"人生价值，心怀天下。\n耕读不缀，勤俭治家。\n农耕为本，种桑植麻。\n民食为天，决非虚夸。\n开门必备。柴米油盐。\n生活旨要，酱醋糖茶。\n闲情逸致，琴棋书画。\n人类进步，非遗文化。\n传宗接代，要多生娃。\n奉献社会，振兴中华。"},{"id":65,"title":"人生无悔","category":"诗","date":"甲辰龙年重阳日","body":"时光逝水流，\n风雨送春秋。\n少壮已努力，\n回报亦丰厚。\n窗外月如钩，\n静思常怀旧。\n往昔无憾悔，\n把酒谢垂暮。"},{"id":66,"title":"写给瘦风堂主八一节欣遇诸战友","category":"诗","date":"癸卯八一节后日","body":"奉献青春戍国防，\n战友情深难相忘。\n阔别离思数十载，\n欣然相逢喜若狂。\n把酒言欢叙短长，\n华发早生两鬓霜。\n仰叹竭力尽所为，\n不虚此生忆过往。\n附注：瘦风堂主宋金圣江苏姜堰人，生于一九五八年，曾在兰州军区第一测绘大队服役，从部队转业后到甘肃省工商行政管理局工作，任职至党组成员副局长，是我多年的同事又是江苏老乡和最好的朋友。拜读其作品《癸卯夏日适值八－建军节兰州欣逢阔别四十年兰州军区第一测绘大队黄增鹏诸战友》有感而发。"},{"id":67,"title":"听夫人弹古筝有感","category":"诗","date":"甲辰年正月初三","body":"学习弹古筝，意欲解闲闷。\n银弦随心动，发出音铮铮。\n慢弹意传神，快奏万马奔。\n轻挑听蕉雨，重拨山河吞。\n连勾风云涌，刮扫攝人魂。\n白雪巴人曲，各自蕴味深。\n一曲渔歌晚，余音绕半城。\n艺高无止境，全凭有心人。"},{"id":68,"title":"填一首词献给各位老领导和亲朋好友共度元宵佳节","category":"词","date":"甲辰龙年上元节","body":"（行香子）\n皓月当空。佳酿醇浓。\n庆元宵，天地人融。\n华灯齐放，焰火映穹。\n看/花千树。灯千盏。谜千重。\n人间蟾宫。团圆偕同。\n闹社火，百戏舞龙。\n流光岁月。一路追梦。\n愿/心上人。天上月。喜上逢。"},{"id":69,"title":"喜游龙寺玫瑰园","category":"诗","date":"癸卯三月二十日","body":"军嶂勝景龙寺在，\n十里玫香引客来。\n五彩缤纷婀娜姿，\n玫瑰花语情和爱。\n老伴留影相拥怀，\n花前月下情溢外。\n潇洒並非少年事，\n甜蜜生活好时代。\n附记：在俄罗斯欢庆反法西斯胜利七十八周年阅兵庆典的那天，天气温和不热不燥十分宜人、确是外出寻找闲情逸致的好日子，邻居老张夫妇邀约我和老伴去龙寺生态园赏月季。龙寺生态园与雪浪山（又名横山）生态园相邻座落在无锡市的西南角，被军嶂山相围、三面环山，山披绿翠景緻十分漂亮，军嶂胜迹莫过于军嶂古道，目前有五条线路，每条道都不是很远、那是热衷于登山探幽寻古，年轻人的绝好去处。龙寺生态园内月季、玫瑰、蔷薇品种有数十种统属蔷薇科，花型花色各异真是五彩缤纷婀娜多姿让人到有刘姥姥进了大观园的感觉。几百米的紫藤花架花开时十分壮观、可惜我们晚来一步都已开败了。园内月季的盛开期应是五一节、晚了几天也略显生机不足，但还未影响到观赏的程度因当天不是周末，游园的年轻人和孩子较少，很多老年人结伴同行其中不乏有夫妻双双比翼而飞的年满七十岁就可以享受免门票的待遇了。玫瑰的花语代表情和爱如今七十岁左右的人在那个艰苦奋斗的年代大多是没有尝试到这种甜美，现在拾遗补缺还为时不晚，眼前那种相亲相爱不离不弃的场景十分感人。同时，让人联想到现在物质条件那么好，年轻人的离婚率那么高这到底是为什么？真不可思议。老年人应当感谢这美好的时代。我们也十分感谢老张夫妇带给我们的这次机会"},{"id":70,"title":"太湖秋色之二","category":"诗","date":"甲辰龙年霜降日","body":"蓝天帆影映湖面\n群鸥撵舟舞蹁跹。\n渔歌号子伴桨声，\n泫沄泛波凝轻烟。\n沿岸芦花白无边，\n一袭残阳红半天。\n数声鹤唳乘风去，\n赏得此景亦成仙。\n附记：1太湖是我国五大淡水湖之一，面积2425平方公里。2南方泉是无锡市十大古村镇之一，位于无锡市的最南端，是伸入太湖的一个半岛，是观赏太湖美景的最佳打卡地，交通十分便利除通公交车之外地铁一号线可直达，且去年地铁S1线开通后地铁一号线可直达江阴外滩，真正能够做到通江达湖。"},{"id":71,"title":"新年感赋二首","category":"诗","date":"癸卯年腊月廿日","body":"一、辞旧癸卯\n岁月零二三，\n国运难与艰。\n负重伴同行，\n志坚移大山。\n逝水不复还，\n枯荣世事间。\n流年随暮去，\n恩威留人寰。\n二、迎新甲辰\n龙年开门红，\n福泽降万重。\n国泰定乾坤，\n民安多繁荣。\n神州舞东风，\n盛世赞英雄。\n炎黄衍四海，\n共园复兴梦。"},{"id":72,"title":"新春感怀两首","category":"诗","date":"甲辰年正月初五","body":"一、自遣\n春风送残冬，\n岁月行怱怱。\n闲遣烦恼去，\n乐生知足中。\n往事凝厚重，\n感慨忆曾逢。\n青春不复有，\n醉莫怪酒浓。\n二、自爱\n眨眼七十五，\n人生经历赌。\n世事皆有常，\n破茧难与苦。\n四空早彻悟\n名利如粪土。\n时日不可假，\n自尊自爱吾。"},{"id":73,"title":"无锡吟三首（临江仙）","category":"词","date":"甲辰龙年","body":"其一、（人文情怀）\n江南四百八十寺，\n不绝暮鼓晨钟。\n二泉映月情更浓。\n陶泥皆成趣，\n日月茶壶容。\n泰伯礼谦逊王位，\n吴越千古遗风。\n人文积淀凝厚重。\n德广共“三和”\n闲时“扯老客”\n其二、无锡美景\n江南美景谁不忆，\n锡惠两山葱茏。\n太湖帆影映日红，\n蠡锦春色滿，\n梅开方知冬。\n灵山佛刹播福祉，\n运河泛舟叙功。\n鼋头渚上闻涛动。\n古镇浸烟雨，\n客游在画中。\n其三、改革浪涌\n江南模式树榜样，\n改革浪急潮湧。\n中华复兴盛世逢。\n率先大发展，\n敢领创先风。\n四个无锡定目标，\n用武任凭英雄。\n改天换地缚苍龙。\n万民齐参与，\n共园复兴梦。"},{"id":74,"title":"五绝二首","category":"诗","date":"二零二一年霜降","body":"无 锡 秋 照\n滿城桂花香，\n遍地菊金黄。\n秋景美如画，\n人间胜天堂。\n太湖三白肥，\n江南八仙美。\n秋日品佳肴，\n幸福将心醉。\n附注：1、太湖三白指白鱼、白虾和太湖银鱼\n2、江南水八鲜指茭白、莲藕、水芹、茨菰、荸荠、莼菜、芡实、菱角"},{"id":75,"title":"无题","category":"诗","date":"甲辰年三月十五","body":"月下独徘徊，\n孤影伴高台。\n浅酌驱寒意，\n豪饮醉眼开。\n世风欺我才，\n运道断未来。\n杜康解烦忧，\n清风渐入怀。"},{"id":76,"title":"沁园春•建党大业","category":"词","date":"二零二四年七一","body":"大国泱泱，百孔千疮，历尽沧桑。\n悟/全新文化，大钊独秀，巴黎公社，马列榜样。\n五四运动，风起云湧，英雄辈出意志刚。\n求真理，曾/前赴后继，坚守信仰。\n征途初心不忘。\n看天翻地覆掀巨浪。\n忆/群英聚会，南湖啟航，中共一大，救国图强。\n平地惊雷，睡狮觉醒，日出东方迎曙光。\n看今朝，铸/千秋江山，大业辉煌。"},{"id":77,"title":"沙尘袭雄关","category":"诗","date":"甲辰年正月初八","body":"龙年第八天，\n沙尘袭陲边。\n日月皆失色，\n天地倒悬颠。\n山河真颜隐，\n流沙推丘迁。\n狂风伴暴雪，\n满城断人烟。"},{"id":78,"title":"深秋","category":"诗","date":"甲辰年九月初一","body":"风动纱帘难入眠，\n和衣邀月倚窗前。\n万家灯火隐朦胧，\n露凝成霜铺地面。\n山河失色噤无言。\n残荷败叶蔫一边。\n寒光照影人何处，\n方知深秋己来临。\n附记：\n1、农历初一的月相称朔月，只有微弱的光\n农历十五的月为满月月相称望，每月农历初七初八的月相称上弦月，二十四、二十五的月相称下弦月。\n2、诗中邀的月月相是朔月，只露微弱的光人过古稀之年激情岁月恍然不再，余光确似朔月月相，微弱难显，余热犹如深秋季节，一派萧瑟，无力抗寒，人老矣，槁枯之形更像风中残烛，痛哉，惜哉！"},{"id":79,"title":"清秋","category":"诗","date":"甲辰龙年出伏日","body":"细雨洗净万家楼，\n轻尘烟笼芦荻洲。\n清凉明月松间照，\n甘洌溪水石上流。\n天上云彩闲浮游，\n人间百姓忙丰收。\n极目远朓千峰翠，\n阅尽江山万里秋。\n附：唐朝诗人王维的写秋诗《山居秋暝》\n空山新雨后，\n天气晚来秋。\n明月松间照，\n清泉石上流。\n竹喧归浣女，\n莲动下渔舟。\n随意春芳歇，\n王孙自可留。"},{"id":80,"title":"献给母亲节","category":"诗","date":"甲辰龙年母亲节","body":"十月怀胎苦乐交，\n夜深婴啼碎心操。\n耗尽心血为娇儿，\n灯前影瘦白发飘。\n梦中思儿慈母老，\n榻前念子意难消。\n跪乳反哺绵绵情，\n灵犀相通千里遥。\n养育之恩比天高，\n谁言春晖报寸草。\n时光恍然亲不待，\n无悔只身未尽孝。"},{"id":81,"title":"送友打工行","category":"诗","date":"甲辰年正月十八","body":"年尽打工出门行，\n苦遇春寒泪湿襟。\n企望龙年好运转，\n不辞辛劳愿打拼。\n风雪冷雨寒生津，\n静盼斜阳向晚晴。\n阅尽人间冷暖事，\n任它流水有无情。\n题记：正月十八过去了，带来美好憧憬的年也就过去了。我的一名社会底层的忘年交朋友为维护生计，也就要告别家乡、告别亲人去远方的城市打工。天有不测风云，刚准备出门却遇到了倒春寒的困境，好多高速路也限行了，面对父母妻儿一家老小真是一步三回首，难分难舍，辛酸的眼泪早已悄悄打湿了他的衣襟，“一路顺风、互相保重”的嘱咐说了若干遍。带着龙年一定有好运的企盼，既情愿又不情愿的走了，在此送行的我感同身受，默默无语，可能这就是人生。李白的一首《赠汪伦》情感洋溢，今天我却怀着十分复杂的心情写一首拙诗《送友打工行》送给我的忘年交，前途是否光明？结局无可料定，好否总要面对。唯有祝福他龙年真的转好运，祝福他真的心想事成。"},{"id":82,"title":"关城英姿","category":"诗","date":"甲辰年十月初五","body":"万里长城铸雄关，\n威武雄壮担两山。\n明墙暗璧隐突兀，\n固若金汤拒敌犯。"},{"id":83,"title":"悬壁长城","category":"诗","date":"甲辰年十月初五","body":"蜿蜒曲折一苍龙，\n盘踞黑山称霸雄。\n扼守河西要塞地，\n江山永固大一统。"},{"id":84,"title":"朝宗柔远","category":"诗","date":"甲辰年十月初五","body":"严关险隘百尺楼，\n朝宗望远意怀柔。\n扫平漠北尘埃清，\n文治武功震匈奴。"},{"id":85,"title":"烽火狼烟","category":"诗","date":"甲辰年十月初五","body":"烽火台上狼烟起，\n番邦犯界消息抵。\n金戈铁马降贼寇，\n城上遍插大王旗。"},{"id":86,"title":"第一墩台","category":"诗","date":"甲辰年十月初五","body":"万里长城第一墩，\n壁立讨赖千仞深。\n历经风雨数百年，\n乳汁浇灌助农耕。"},{"id":87,"title":"雄关抗疫一幕","category":"诗","date":"二零二一年十月","body":"疫情无端呈猖狂，\n袭我家园摆战场。\n陇原人民齐奋起，\n雄关儿女挺脊梁。\n大军驰援迎八方，\n科学驱魔巧设防。\n千家万户曈曈日，\n人定胜天浩气扬。\n注记：二零二一年十月，在历史的记忆中必定是一个不平凡的岁月。在这国庆佳节余兴未尽，秋光流溢美景如画的季节，祖国西部明珠我的美好家园受到新冠疫情的突袭，在深重的疫情面前嘉峪关人按照省委省政府的统一部署和国家卫健委的科学指导，不分男女、不分老少不分你我团结一致齐上阵拉开了与疫情决战的序幕，雄关儿女不畏艰险不辞辛劳，服从指挥恪尽职守与支援大军协同作战充分展现了党的号召力和人民群众的执行力在这支强大的铁军面前没有克服不了的困难战胜不了的敌人我坚定地相信战胜疫情为期不远嘉关人创造的这种精神财富将会在民族复兴中发挥更强的战斗力贡献更大力量。"},{"id":88,"title":"颂秋","category":"词","date":"甲辰龍年中秋日","body":"枫红染枝头，\n柿黄挂高楼。\n白露凝，天蓝云悠。\n万里山河尽醉美。\n菊花放，画中游。\n归雁途中踌，\n蟹肥引涎流。\n月儿明，溪清景幽。\n百姓欣喜庆丰收。\n桂花香，思乡愁。"},{"id":89,"title":"中华神赞","category":"诗","date":"甲辰冬月初八日","body":"三皇五帝立汉疆，\n华夏文明序列张。\n秦皇汉武平六国，\n车轨同文统八荒。\n文治武功几沧桑，\n歌舞升平见霓裳。\n四大发明工开物，\n万国来朝贺大唐。\n江山岁月自传扬，\n钟鼎警醒艾未央。\n百年大局始裂变，\n世林惊殊中国黄。"},{"id":90,"title":"中秋偶遇意中人","category":"诗","date":"癸卯中秋节之夜","body":"中秋偶遇无锡时，\n相逢一笑无人知。\n无眠沉念无缘去，\n有心不忘有情思。\n自悔羞涩求爱迟，\n莫嗔花好月老事。\n对酌只叙挚友谊，\n经年不言少时痴。"},{"id":91,"title":"中秋叙怀两首","category":"诗","date":"壬寅中秋日完稿","body":"一、清秋\n鸟眠山静藏深幽，\n落叶顺溪流不休。\n向天问月今何夕，\n人间清凉又中秋。\n孤影自悯诸事丢，\n寂寥无语禅心修。\n遥思亲友寄祝福，\n天地同乐人无忧。\n二、拜月\n月洒银辉凉意来，\n院前桂香竹影斜。\n袅袅青烟随风散，\n祭天拜月望瑶台。\n长河落日月出彩，\n人生易老莫徘徊。\n天涯此时度良宵，\n人月两圆共情怀。\n注释：“清凉”指告别今年的暑热高温，同时也指远离喧嚣的城市来到郊外，抛弃诸事烦恼自寻悠闲，有机会总结思考人生过往，享受晚年生活的美好。“团圆”，是中国传统文化里最简单、最朴实的要素，人们总希望人与人、人与社会、人与自然之间都能和谐相处，共生共荣。“祭拜”，并不是相信迷信的活动，而是一种心理寄托，把心灵托付给最美好的精神境界，希望除去与个人意愿不相符的一切烦恼同时追求所有美好的愿望能够实现。"},{"id":92,"title":"元宵有感","category":"词","date":"乙巳蛇年上元节","body":"（行香子）\n烟花璀璨，盛世人间\n巳蛇舞，撩动旌幡。\n赏灯猜谜，快乐无限。\n逢/东风吹、政风和、\n民风闲。\n长空月圆，鼓乐喧阗。\n问流光，今夕何年。\n岁月依旧，唯我老残。\n叹/人无语、心无念、\n夜无眠。"},{"id":93,"title":"再游成都、重庆记","category":"散文","date":"乙巳年五月初一","body":"人生对“今天”以后所作的规划其实是具有很大不确定性的所以有句俗语“计划赶不上变化”。成都和重庆在二零一二年退休前均因公（会议）分别去过两次，那时的接待工作管理得不像现在这么严格，在公事中接待单位都会穿插着按排参观一些当地的主要景点，所以像峨眉山、青城山、都江堰杜甫草堂、乐山、大足石刻、磁器口和渣滓洞、白公馆、曾家岩八路军办事处等遗扯和景点都光顾过了，所以退休后就再没有去成都和重庆旅游的愿望和打算。\n情因好友原甘肃酒泉二十五医院邹院长段主任夫妻二人退休后不甘寂寞、与另一友人袁先生共同出资在四川成都所辖的崇州市白塔湖畔的仙侣山租赁了一片山地、开发出了“仙侣庭园”休假区、多次盛情邀请我和老伴去观光旅游，但总是下不了要去的决心。\n事常遇巧五一节假期间、朋友姜先生与亲家要在成都共同举办他们公子爱女的婚礼，凭感情我和老伴必须到场庆贺，所以决定顺便去拜望一下好友邹院长夫妇和友人袁先生夫妇这就打破了原有退休后不再去成都和重庆的计划，得以旧地重游。\n五月三日从无锡出发下午四点到达成都双流机场，姜先生亲自去接机。四日我和老伴逛了成都有名的宽窄巷子、春熙路、熊猫繁殖基地，这几个景点是我以前没有去过的。宽窄巷子是由宽巷子窄巷子井巷子三条巷子共同组成的历史文化街区，青石铺路，四十多套清朝遗留下来的古院落和沿街的古建筑修旧如旧，特别具有川文化的特点，景区售卖最多的是兔子头、板鸭、腊肉，很有烟火气，可以让人联想到上世纪前人们在这里是怎么生活的场景。现在作为成都的旅游名片，每天游客摩肩接踵络绎不绝。春熙路又完全是另一番景象，经多次改造已成为成都规模最大最成熟和最具现代化的商圈，在此衣食住行、游购娱无所不有、更是无所不能。熊猫是国家一级保护动物是我国的国宝，熊猫展览馆是世界上最大的人工繁殖研究基地，“熊猫外交”为我国外交方式作出过特殊贡献。与二十多年前所去的成都相比较，无论从什么地方看都感觉到变化很大发展很快其成果可以让人膛目。五月五日的婚礼仪式是在成都龙泉驿东安阁五星级大酒店的室外草坪上举行的，这里风景极美，主持人是新郎的同学婚礼仪式与老旧的西式婚礼和中式婚礼都截然不同，其特点是庄严、自由、开放、明朗、大气，因为参加婚礼的除亲朋好友之外，大都是新郎新娘的同学，这一批年青人都在外留过学有硕士博士学位，从不多的交谈中感觉到他们个个具有目光深远、睿智卓见、洞察未来的能力，少年有为未来一定属于他们。\n五日下午四时王生福王小红夫妇专程从重庆驱車赶来接我们去崇州邹院长的“仙侣庭院”王小红和老伴在嘉峪关中国银行是同事也是很要好的朋友，而且我们两家在嘉峪关还是同住一栋楼的邻居，王局长夫妇退休后随女儿来重庆定居，近距离的陪女儿生活，我们亦如此，这也成了大多数老人退休后选择居住地的标准。“儿行千里母担忧”，足可见，“可怜天下父母心”。\n六点半左右到达仙侣庭院山居，邹院长夫妇和友人袁先生夫妇早就准备了丰盛的接风晚宴，受到了热情款待、与邹院长近二十年没见面了，平时仅靠微信联系互相送去问候，见了面激动不已，席间回顾了很多往事和友谊。晚上将我和老伴按排在名为“佗歧”的湖景房内下榻，“佗歧”出自唐·韩愈诗《回首卿相位，通途无佗歧》意义非凡。王局长夫妇下榻在隔壁。\n邹院长夫妇都是在部队退休的享有高干之待遇，仅凭两人每月不菲的养老金，无论在国内哪个城市生活都会潇洒无比可他们偏偏选择了以苦为乐，修路盖房、规划设计、全是亲力亲为，养鸡种菜也全凭自已动手，将一座荒山初步建成了一座具有二十套木屋别墅规模的休闲山庄。\n晨起，倚窗而望白塔湖水面上飘起的薄雾如轻纱拂面，白塔寺的红墙掩映在青山绿水之间，白塔映衬在蓝天白云之下，一幅天然的山水画美得无可比拟，这里空气中含氧量十足，吸一口神清气爽可以静心养肺延年益寿。离开了烦燥喧嚣的城市环境，离开了森林堡垒的水泥楼房。在这里“桃花源里可耕田”，过上陶公式的田园生活，悠闲自然、自得其乐、悠哉！美哉！邹院长夫妇选择的这条幸福之路，这种深层次的精神境界，是很多人都不能理解的。\n《庄子/秋水》篇有这样一则故事，庄子与惠之游于濠梁之上，庄子曰：“鲦鱼出游从容，是鱼之乐也”惠子曰：“子非鱼，安之知鱼之乐？”庄子曰：“子非我，安知我不知鱼之乐？”惠子曰：“我非子，因不知子矣，子固非鱼也，子之不知鱼之乐，全矣”.。\n庄子观鱼，感受到自然无为状态的鱼是快乐的，在庄子看来修道的最高境界是浮游方外从而物我不分，逍遥无为以自适。每个人对幸福感的认知并不是一样的，只有自已感到怎样是幸福的才会得到真正的幸福，真心的支持邹院长夫妇的选择。\n在仙侣庭院休闲的两天里除了观山景和邹院长谈论山庄发展规划外，友人袁先生夫妇还精心策化陪同我们参观了附近的几个景点，这也是我未曾去过的，有大地主刘文彩的庄园罨画池、街子古镇、道明竹艺村，这些景点各具特色，刘文彩的庄园过去是阶级斗争教育基地所布展是地主阶级如何欺诈压迫农民的物件，现在也全部撤展了，只保留了刘文彩的庄园和其家人日常生活所需的一些物品。街子古镇与全国各地的古镇除建筑风格保留了当地的特色外商业氛围基本相似。罨画池是崇州市区里很美的一个景点，这个景点主要是讲宋朝诗人陆游在此为官做通判时所写诗集与罨花池相关的一些故事。录其中一首《偶过浣花感旧游戏作》“正月锦江春水生，花枝缺处小舟横。闲倚胡床吹玉笛，东风十里断肠声。”与大家分享，道明竹艺村充分体现了社会主义新农村的特色，一村一产业，竹编工艺致富了全村人。七日邹院长夫妇和袁先生夫妇又设告别晚宴欢送我们。\n八日早上辞别了“仙侣庭院”的好友后，随王局长夫妇的宝车返回重庆，途中去广汉市参观了“三星堆博物馆”，这里是我心心念念想去参观的地方，博物馆修建得很大气，一号馆内珍藏有玉石器、金器、陶器、骨器、犹以青铜器为多，一点三八米宽的人面像和三点九六米高的神树青铜器及金仗可为镇馆之宝。三星堆遗址的发现将人类文明推到了五千年前，出土的实物也证明了“巴蜀文化”与“中原文化”是有一些关联的，大凡出土的古遗址里都有祭祀用品，这种“祭祀文化”说明了古人对风雷水电火灾地震陨石等自然现象和自然灾害还没有认识到其真实原因时，只能求助“老天”来帮忙护祐。\n晚上六点半左右到重庆后王局长夫妇为我们接风，定要去品尝重庆火锅，重庆火锅的麻辣味一般人是享受不了的，在重庆寄居在王局长家，受到热情款待他们夫妻二人又陪我们玩了好几天，参观了抗日战争纪念馆、重庆花博园，下号里，磁器口、洪崖洞、李子坝等风景区，重庆又名山城，到洪崖洞感受上下翻越的街道，才能真正体验到“山城”的味道。在洪崖洞还遇到一起让人难忘的事情，洪崖洞上有一处观景台，可以观看长江嘉陵江两江交汇和对岸的美景，因不知具体地方，老伴就向一个约三十多岁的当地女子打问，她听出我们是外地口音，随认真的给我们指方向，此时天空下起了雨滴，她问我们带雨伞了没有，老伴回答说没带伞，此女子说下雨怎么去观景我给你们拿把伞吧、随急怱怱的返回拿来一把伞追到电梯口，老伴说怎么还你？她说不要还了送你们。重庆人对游客如此的热情友好是会让人永远记住的。李子坝的轻轨穿楼可谓是世界上独一无二的奇观也是“山城”的特色。\n十三日上午乘飞机返回无锡，这次无论在成都、祟州还是在重庆都受到了好友的热情接待心里很暖，也很过意不去，朋友们的情谊我们一定会深深的记在心里，在这里我和老伴打心眼里说声：“谢谢，谢谢你们”。"},{"id":94,"title":"咏叹岁暮夜雪","category":"诗","date":"甲辰冬月廿六日","body":"一、深冬念友\n朔风凌冽雪封楼，\n梅香清溢飘田丘。\n远眺群山成白首，\n地披银装蕴丰收。\n心念亲友抗寒流，\n莫忘早晚添衿裘。\n胸中常思春光好，\n何惧转逝又一秋。\n二、雪趣童真\n夜静雪洒寂无声，\n晨惊素绒盖边城。\n忽忆箩筛捉鸟事，\n霜染两鬓失童真。\n溜冰滑雪赋正能，\n科技助力练健身。\n冬奥捲起冰雪热，\n壮我山河后来人。\n附记：十二月十五日回到阔别已久的第二故乡嘉峪关探望岳父母双亲及故友，同是伟人毛主席诞辰一百三十一周年纪念日前夜、偶遇回嘉后的第一场雪，遂有所思，赋诗两首以作记念。"},{"id":95,"title":"咏无锡之雪二首","category":"诗","date":"癸卯年冬月初六","body":"（其一）\n寒流侵袭漫古道，\n江南璇花混沌飘。\n高楼隐遁天无影，\n山川素裹地媚娇。\n柔姿轻舞离喧闹。\n锡城披白添妩妖，\n好景应伴好友赏，\n煮酒烹茶度良宵。\n（其二）\n雪飘江南梅园醒，\n无锡又添新胜景。\n千树万树竞绽放，\n不畏严冬立山岭。\n云消雪融绿万顷，\n南国姿韵风度翩。\n三九寒天悄然去，\n春雷响时人不惊。\n附记：事情巧了下雪天会迎来送往，12月14日无锡的最高气温是摄氏23度，还像初秋，到嘉峪关时偶遇一场大雪寒冷无比今天好友老施发来视频说无锡也下雪了，南方下雪少见，最低气温零下一度其实也不太冷，雪时的南方和北方我都经历过，虽然都是下雪但雪的质量不同，南方的雪绵软温顺落地即化，北方的雪刚洌粗犷扑面生疼。回嘉峪关写了一首诗《雪中还乡》，今天也再写一首《咏无锡之雪》，以表对故乡的不偏不倚之情。"},{"id":96,"title":"咏梅","category":"词","date":"癸卯大寒后三日","body":"（江城子）\n庭前数株梅倚窗。傲然立，欺严霜。盘姿如虬，雪输一段香。\n岁寒三友高品望。敢争先，独担当。\n含苞欲放压群芳。送消息，迎春光。铁骨柔情，清气染故乡。\n千古绝唱兴未央，见书画，留文章。\n附记：江城子，词牌名。双调七十字，上下片各八句三十五字，五平韵。"},{"id":97,"title":"在党五十周年纪念","category":"诗","date":"二零二四年七一","body":"手捧纪念章，\n幸福热泪淌。\n举手曾宣誓，\n永远忠于党。\n报国着戎装，\n为民赴疆场。\n只要党号召，\n无需条件上。\n誓言终不忘，\n何惧苦与忙。\n年事虽已高，\n传统要发扬。\n人生有信仰，\n充满正能量。\n入党五十载，\n感恩党培养。\n附记：\n一九七三年十一月三日是一个平凡而有特殊，让我终身难忘的日子，因为这一天我正式加入了中国共产党成为一名光荣的共产党员了，也就是那天我举手宣誓：我志愿加入中国共产党，拥护党的纲领，遵守党的章程，履行党员义务，执行党的决定，守党的纪律，保守党的秘密，对党忠诚，积极工作，为共产主义奋斗终身，随时准备为党和人民牺牲一切，永不叛党。\n至今年七一差两天，我在党就满五十周年零八个月了，这半个世纪以来我始终坚持党的领导，听党的话，始终将为人民服务的宗旨作为自己言行的指南，将青春年华和人生价值交付给了党，时刻听从党的召唤、服从党的安排，恪尽职守、尽职尽责，为党的事业添砖加瓦发挥了一名卒子的应有作用，在本市和本系统范围内曾多次获得过优秀党员称号。一生虽无多大贡献党却培养我成为一名地厅级干部，如今虽早已退休但初心不忘，永在路上，一日在党终生无撼，誓将余热发光，为党的事业奋斗终身。\n我十分感谢我的入党介绍人老战友王道林和许绍周同志，感谢他们给我的帮助。同时也要感谢在人生道路上帮助我成长的师长亲友，感谢所有为我服务过的人们。请接受我深深的鞠躬，再一次的感谢你们，谢谢了！"},{"id":98,"title":"夜市见闻","category":"诗","date":"甲辰龙年夏至日","body":"消夏无事闲，\n夜市逛小摊。\n挚友三四个，\n佳肴五六盘。\n悠然侃大山，\n猜拳闹酒欢。\n忆旧皆情趣，\n回家醉步跚。"},{"id":99,"title":"学习，——开啟幸福大门的金钥匙","category":"散文","date":"二零二四年三月二十四日","body":"在世界民族之林中，中华民族是一个重视学习、善于学习、勤奋好学积极向上的最伟大的民族。\n“观以天文以察时变，观以人文以化成天下”中华文化的薪火赓续几千年，流传至今并让其发扬光大就是最有力的证明。\n人是社会的细胞，家庭是社会的最小单元，人与人要沟通，人与社会要交流，人与自然要融合。人要有信仰和追求，就离不开学习。\n学习，对普通人来说一方面是为了获取维持生命存续、提高生活质量所需的物质文明；另一方面是为了丰富思想、净化心灵、愉悦心情，规笵道德，提升精神和物质文明而采取的方式和手段。\n学习，对于社会管理者的精英阶层来说、其重要性更是不言而喻的，因为只有不断的学习才能加强提高治理社会的方略和能力，确保国家机器有序运行，才会创造出“国泰民安、天下太平”的盛世之举。\n学习，是获得知识的源泉，知识就是力量，是解决社会一切疑难杂症的金钥匙。人类一旦插上知识的翅膀，在知识的海洋里徜徉就会主动地去发现、认识、寻找、分析问题形成的原因，一旦用科学的方法找到了解决问题的答案，实现了自我价值、一定会幸福无比。\n学习，是穿越时空与古人对话的最好方法。“以铜为镜可以正衣冠，以人为镜可以知得失，以史为镜可以知兴替”中央电视台“典籍里的中国”这档栏目很受欢迎我也很喜欢。\n中国古代诸子百家的思想是治国理政的良方。通过学习可以把儒家、道家、法家、兵家的哲学思想如：“仁、义、礼、智、信，温、良、恭、谦、让。”“天人合一”“仁爱中庸”“三十六计”和先哲倡导的“修身、齐家、治国、平天下”这些博大精深的国学知识兼容并蓄融会贯通。\n学习，不仅要向书本向前人学习，社会才是最大的知识宝库，在这个信息爆炸的时代、读书学习要学会挑选和批判，才能做到取其精华去其糟粕，古为今用洋为中用。\n学习，并不是一种简单的复制而是在传承的基础上不断的加以创新提高。现代社会是一个信息化的社会，是一个科学技术迅猛发展的社会，科技成果改变了人们的生活方式、缩短了时空距离，扩大了视野、不仅为人们提供了更多的物质文明与幸福体验，而且会让生活变得更美好。\n少年时代读过一本书《科学家谈二十一世纪》那种“楼上楼下电灯电话，出门坐汽车”的美好憧憬早已成为过去“可上九天揽月，可下五洋捉鳖”的梦想已经变成现实，人工智能已经走进人们的生活一部智能手机就可以解决生活中的大部分问题，我们真是赶上了好时代。\n清楚地记得就是这本书激发了我的学习兴趣，可惜那个求知若渴的年代由于读书无用论的影响变得无书可读，读书学习的欲望受到了挫击，至今仍是一个很大的遗憾。\n后来我还是在工作之余抽时间蜻蜓点水般的阅读了四大名著，四书五经和《在人间》《母亲》《海燕》《钢铁是怎样炼成的》《铁流》《简爱》《红与黑》等中外文学名著，让我看到了外面的世界也很精彩。\n读书学习，虽说是苦差事但它确是站在前人肩膀上获得知识的捷径。不断的学习，不断的积累，不断的创新，才有不断的进步，才有今天的幸福生活。\n“书山有路勤为径，学海无涯苦作舟”古人“悬梁刺股”“凿壁偷光”等刻苦学习的故事至今还在激励着莘莘学子，激励着中华民族的每一代人。“天下无难事，只要肯登攀”只要我们树立了远大的理想和目标，持之以恒的去努力学习我们的前途就会更加光明。\n“活到老，学到老”是我一生的追求。无锡市老年大学是我人生中的又一个转折点，退休前大部分时间都用到工作中去了，还有很多年青时的梦想没有实现，退休后可以有大把的时间来关心所喜欢做的一切。乘着与时俱进的东风起航、在这里燃起新的希望。借屈原《离骚》“路漫漫兮其修远兮，吾将上下而求索”为座右铭，在求知求真求新的路上，永远把学习当作武装自己头脑的武器，相信有了这个武器就会开启更幸福的大门。"},{"id":100,"title":"忆军旅生活","category":"诗","date":"二零一二年八一","body":"一、紧急集合\n凌晨一声哨，\n紧急集合号。\n武器装备齐，\n摸黑打背包。\n穿衣和戴帽，\n快速是目标。\n悄然列队好，\n时间九十秒。\n二、站岗放哨\n紧握手中槍，\n军人当站岗。\n敌情常了解，\n宗旨记心上。\n半夜起身忙，\n放哨守安康。\n口令须牢记，\n警惕不能忘。\n三、射击打靶\n战士学打枪，\n瞄准第一桩。\n卧跪立姿全，\n负重练臂膀。\n森严射击场，\n有序不慌张。\n平静稳击发，\n弹落靶中央。\n四、投弹排雷\n当兵基本功，\n投弹算一宗。\n挥臂用猛力，\n迈腿手再松。\n埋雷考实用，\n排雷技术同。\n胆大心要细，\n人赞专又红。\n五、孤胆训练\n残月照松间，\n深秋霜意寒。\n山林寂无声，\n一鸣惊悚惨。\n戎装配指南，\n夜训练孤胆。\n峡谷独行客，\n终成英雄汉。\n六、擒拿格斗\n擒拿格斗中，\n行功快如风。\n跌打摸滚爬，\n勇猛赛大虫。\n站立挺似松，\n端坐稳如钟。\n灵活出奇招，\n不负有真功。\n七、勇拼刺刀\n刺杀要领多，\n挡别压挑抽。\n出手爆发力，\n快速把腿收。\n胸中燃怒火，\n杀声震天吼。\n面对假想敌，\n刺进它心窝。\n八、武装泅渡\n江河海与湖，\n武装能泅渡。\n万米畅游行，\n全凭真功夫。\n征程无坦途，\n思想不可疏。\n战时用得上，\n平时须吃苦。\n九、野营拉练\n千里徒步行，\n驻扎知社情，\n实战把兵练\n侦察总在先。\n宿营不扰民，\n埋灶避炊烟。\n昨夜人马在，\n何时无踪影。\n十、筑魂铸剑\n军魂非平凡，\n万锻铸一剑。\n当兵磨意志，\n何惧艰与难。\n翻过四十年，\n而今回首看。\n人生无悔意，\n当兵算一段。"},{"id":101,"title":"战友情怀（临江仙）","category":"词","date":"癸卯年七月廿五","body":"为五十九师一七六团特务连第六届战友联谊会而写\n从军退役五十载，\n往事历历常在。\n兄弟情深仍掛怀，\n今日喜相逢，\n热泪洒两腮。\n白发古稀聚上海，\n愿君健康自爱。\n一壶老酒话闸开，\n人生过往多，\n有缘可再来。\n附记：1、临江仙，词牌名，原为唐教坊曲名，又名“谢新恩”“玉连环”……等，双调小令平韵格，有五十二、五十四、五十八、五十九、六十、六十二字六种格式，常见上下两片各五句三十字，三平韵。《三国开篇词》是其典笵家喻户晓，尤为人人喜爱。\n2、中国人民解放军五十九师一七六团特务连是一个团结、紧张，严肃、活泼，特别能吃苦，特别能战斗的英雄集体，所有战友都为他骄傲、为他自豪，第六届战友联谊会将于九月二十日至二十三日在上海浦东新场古镇召开期盼战友们相聚一堂，追溯如烟往事、畅叙家国情怀，以切身经历，为国为民培养教育好下一代，让我们老有所乐、老有所为憧憬更美好的未来。为联谊会填词留作纪念。"},{"id":102,"title":"楹联两副","category":"对联","date":"癸卯年九月初二","body":"其一\n世事变迁越千年，仍闻风声雨声读书声声声入耳。\n莘莘学子，求知若渴，人才辈出，肩担道义，请命为民，探索治国方略。\n华夏精神传万代，不缺家事国事天下事事事关心。\n志士仁人，忧国忧民，前赴后继，赤胆忠心，献身国家，追求公平正义。\n其二\n贯华阁临窗眺远见新意\n惠山泉隐秘溯古藏深幽\n附记：10月16月无锡老年大学的金石声老师带学员们去惠山现场授“无锡文化”课，有幸欣赏到不对外开放的“忍草庵”景观同时聆听了不少关于忍草庵和许多历史名人来世今生的掌故，体会了人性与友谊的价值意义，尤其贯华阁内杨寿楣（1877—1954）写的一副楹联“风月无情侧帽填词人己去，烟霞不老卷帘读书我重来”含义深刻，耐人回味。这里记录了顾贞观（1637—1714）无锡人（东林党领袖顾宪成四世孙）清朝文学家，他与其友在此结社读书研究文学、品茗赏景填词作诗尽显文人风采并与陈维嵩、朱彝尊称明末清初“词家三绝”同时还与纳兰性德（1655—1685）曹贞吉被誉为“京华三绝”他还帮纳兰性德整理编撰了《侧帽词》纳兰性德30岁时因急病而亡。忍草庵从元代月川僧在此结庐开庵始已有几百年历史至今仍传承有序，值得珍惜点赞。忍草庵深隐于惠山头茅峰东南的章家坞，两侧地势险峻，古泉“聼松泉、松苓泉、蟹眼泉、南泉”几百年不干不涸，泉水充盈清澈透底，也算奇闻，隐匿惠山中的忍草庵如不到近处是无法识其真面目的，其上的“贯华阁”三间三层古雅朴实，此形势我感觉与蒋公中正浙江奉化故居妙高台极为相似。以为附雅撰楹联一副（其二）作为此次游学之收获，同时将9月18日惠山寄畅园内现场教学所了解的明代思想家、教育家、东林党领袖顾宪成（1550—1612）无锡人曾官任户部主事。“风声雨声读书声声声入耳，家事国事天下事事事关心。”他这一副几百年来家喻户晓、读书不忘救國的对联我将它扩展开来（其一）以示对古人的敬意同时也作为自己的学习心得一並记录于此，永为纪念，更应成为追崇古人鞭策自己的座右铭。无锡文化厚实凝重，英才荟萃永远也学不完。"},{"id":103,"title":"游嘉峪关长城","category":"诗","date":"乙巳年暮春三月","body":"祁连古道游，大漠峙关楼。\n墩台临碛立，峡下雪水流。\n狼烟连烽火，塞上长城陡。\n夕照悲壮影，魂销千古愁。\n附记：祁连古道即是指河西走廊嘉峪关城楼耸立在南边祁连山北边黑山两山中间的嘉峪关山上向西是一望无际的大漠嘉峪关素有“天下第一雄关”之称，长城第一墩矗立在北大河北岸的峡谷边上垂直九十度深有八九十米，是一道天然屏障，峡谷里奔流着祁连山上融化的雪水支撑着河西走廊上的绿州农业，悬壁长城像一条巨龙盘旋而上蜿蜒在黑山之上是另一条很难攻克的天险，关城两侧的长城上烽火台紧密相连，遇敌则点燃烽火相告，城墙影显明墙雄壮突兀、暗壁隐蔽幽深，明墙暗壁易守难攻自古就是一夫当关万夫莫开的兵家必争的军事要地，尤其在冷兵器时代在此建城立关很有超前的战略思想。下午五六点钟在关城外的西北角拍照，夕阳将三幢关楼映照得更为悲壮，具有六百多年的嘉峪关城楼已成为历史的见证向人们倾诉着艰辛沧桑，同时也成为供游人游览观光、凭吊的好地方。"},{"id":104,"title":"赠姜华夫妇","category":"诗","date":"己亥年阳春月","body":"世情人走茶就凉，\n何由苛求不寻常。\n姜华夫妇释大义，\n情融泪飞湿衣裳。\n附：李白《赠汪伦》\n李白乘舟将欲行，\n忽闻岸上踏歌声。\n桃花潭水深千尺，\n不及汪伦送我情。"},{"id":105,"title":"运河三步曲","category":"诗","date":"癸卯仲春廿五日","body":"一、帝王奢糜凿运河，\n悦赏琼花下扬州。\n百万民夫苦不迭，\n君与暴政俱焚休。\n二、漕运兴起富码头，\n官家运粮再无忧。\n便利商事进京去，\n康乾南巡总乘舟。\n三、南水北调大计筹，\n东线水路济京周。\n黄金水道多得益，\n惠泽子孙延千秋。\n附记：前几天好友老施约我和老伴去逛运河公园。春天，无锡的运河是那么的繁忙，公园里樱花初放美得实在不可言喻，大运河是世界非物质文化遗产，应该与万里长城、同属于中华民族坚韧不拔伟大精神的象征，至今已有二千四百多年的历史，她经北京天津、河北、山东、江苏、浙江六省市，联结海河、黄河、淮河长江、钱塘江五大水系，京杭运河长1794公里，加上杭甬段全长约两千公里。大运河经久不衰，在各个不同历史阶段承载着不同的任务，以此拙诗《运河三步曲》和几张打卡地的照片作为对大运河新的认识祝运河文化灿烂，愿运河精神永存。也感谢老施中午为我们准备家宴美食。大运河经修整疏浚已于2022年4月28日全线连通，发挥着它应有的作用。清康熙、乾隆皇帝都是六幸江浙俱尝驻跸惠山，康熙“朝游惠山寺，闲饮二泉茶”。乾隆“寄畅园中眺翠螺，入云抚树湿多罗”。康熙乾隆自1684至1784这百年间，共14次游惠山康熙第三次南巡返回时仍经惠山，乾隆第一次南巡返回时也经惠山，所以有各南巡六次却有七次游惠山的经历，康乾两帝游惠山留下了115首诗词，乾隆皇帝对惠山尤为推崇御笔写下了“惟惠山幽雅闲静”。如今惠山古镇已成为无锡重要的旅游打卡之地。"},{"id":106,"title":"祝各位亲朋好友重阳节快乐幸福安康","category":"词","date":"癸卯深秋重阳节于无锡","body":"（行香子）\n节临霜降，又见重阳。\n秋已深，天气渐凉。\n湖中蟹肥，院前柿黄。\n看/枫叶红、菊花放、\n农家忙。\n岁月沧桑，福添寿长。\n人生短，相伴善良。\n苍天亦老，何须惆怅。\n来/登高处、瞰俯仰、\n畅思想。\n附记：行香子词牌名，双调上下两片，各三十三字上片八句四平韵，下片八句三平韵。亦有六十四字上下片各八句五平韵及六十八字上下片各八句四平韵等变体。"},{"id":107,"title":"重阳（一）","category":"诗","date":"甲辰龙年重阳节","body":"时光飞逝又重阳，\n大江东去万年长。\n天涯尽头一过客，\n何必伤感断愁肠。\n邀友登高饮琼浆，\n笑对华发两鬓霜。\n人生哪能多如意，\n心愿亲友皆安康。"},{"id":108,"title":"重阳（二）","category":"诗","date":"甲辰龙年重阳节","body":"一番秋雨一番凉，\n万里寥廓千里黄。\n举目远望夕照晖，\n遇见归雁飞南方。\n山川失色四野荒，\n静待春风重梳妆。\n金菊玉桂花有时，\n喜忧参半题诗章。"},{"id":109,"title":"铸造无锡新人","category":"散文","date":"癸卯年十月初三","body":"无锡应该说是我的第三故乡，我出生在江苏省泰兴市曲霞镇，那是我度过青少年时代、是我成长的地方，十八岁参加中国人民解放军后转业到祖国的大西北、万里长城的最西端嘉峪关市工作，后又调任甘肃省工高商行政管理局（现称市场监督管理局）工作，直至二零一二年九月退休（在甘肃省生活了四十余年）后，才随独生女在无锡断断续续住了十年，除了带外孙少有的乐趣外，剩下的就是寂寞，随着外孙的长大看护时间少了剩余时间又增添了无聊。由于生活圈子小朋友少，与人交往的机会少，寂寞加无聊也就应时而来，搅扰得我差点患上抑郁症。我常想要做一个无锡人如果对无锡的历史沿革、人物故事，地理地标、风俗习惯、文化传承概然不知的话如何才能融入真实生活成为一个真正的无锡人？一日与邻居张南兴老大哥闲聊他说我的处境值得同情，并介绍了他参加无锡老年大学“无锡文化讲座”课程学习的心得体会，建议我到老年大学来试一试，在他的帮助下我成了2023“无锡文化”春季班的插班生。自从上了老年大学使我的生活发生了很大的变化，一是改变了过去在无锡生活圈子小、朋友少、与人交流少的状况，与班上不少同学都成为好友。二是无锡的方言吴侬软语讲起虽然很好听，但真是听不懂与人交流起来比较困难现在向同学学习慢慢的能听懂一些。三是通过学习和交往对无锡的风土人情、无锡的风俗习惯、衣食住行、有了更多的了解，生活起来方便了很多。四是听了金石声老师《无锡文化讲座》课后对无锡的历史文化、人物掌故有了更多的认识，五是班上的同学之中还有很多八十岁以上的老人如96岁的杨毓敏、92岁的顾静霞老太太，85岁的高泉宝等老大爷他们如此高龄仍积极向上勤学不辍真是我永远学习的榜样，同样会激励我活到老学到老。这些正能量就是我在老年大学得到的最好的收获。我觉得类似于我这种情况在无锡生活的人一定不是少数，建议大家来无锡老年大学学习体验生活一定会有很多很好的收获。同时用（临江仙）词牌填词无锡吟三首也作为我在老年大学学习后对各方面了解所获取的心得体会一并献给大家。\n其一《无锡吟·人文情怀》\n江南四百八十寺，\n不绝暮鼓晨钟。\n二泉映月情更浓。\n陶泥皆成趣，\n日月茶壶容。\n泰伯礼谦逊王位，\n吴越千古遗风。\n人文积淀凝厚重。\n德广共“三和”，\n闲时“扯老空”。\n其二《无锡吟·无锡美景》\n江南美景谁不忆，\n锡惠两山葱茏。\n太湖帆影映日红。\n蠡锦春色满，\n梅开方知冬。\n灵山佛刹布福祉，\n运河泛舟叙功。\n鼋头渚上闻涛动。\n古镇浸烟雨，\n客游在画中。\n其三《无锡吟·改革浪潮》\n江南模式树榜样，\n改革浪急潮涌。\n中华复兴盛世逢。\n率先大发展，\n敢领创新风。\n“四个无锡”定目标，\n用武任凭英雄。\n改天换地缚苍龙。\n万民齐参与，\n共圆中国梦。\n附注：陶泥，指宜兴紫砂壶和惠山泥人。“四个无锡”指市委市政府提出的发展方向及目标即魅力无锡、创业无锡、创新无锡、幸福无锡。“三和”指人与人之间关系和善，人与自然生态关系和谐，人与社会之间关系和睦。《铸造无锡新人》此文是应《我心目中的老年大学征文》所写。"},{"id":110,"title":"长安会诸友","category":"诗","date":"甲辰年桂月x日","body":"长安城里朋友聚，\n相见一拥洒热泪。\n感叹时光流水去，\n英姿已改鬓毛衰。\n钢铁长城戍边陲，\n雄师铁甲草上飞。\n千锤百炼酬壮志，\n精忠报国终无悔。\n人生虽如东逝水，\n足跡永驻情难毁。\n轶闻趣事常追忆，\n英雄人物数我辈。"},{"id":111,"title":"阳山赏桃花有感","category":"诗","date":"癸卯年清明节前","body":"明前踏青春已深，\n千亩桃园垒花魂。\n天公不解凡夫意，\n风雨难锁赏花人。\n人面桃花两形胜，\n笑伴东风入家门。\n燕子筑巢痴情醉，\n美景来自新农村。\n附记：杜牧笔下“清明时节雨纷纷”，正是这个季节的特点，前两天邻居老张邀约我和老伴去阳山踏青观赏桃花，可惜天公不作美几天时间都沉浸在潇潇春雨之中今天春风和煦艳阳高照方得成行驱车前行刚到阳山地界映入眼帘的是千亩桃林紧连一起、一片花海目不暇接，这里是无锡乃至长三角重要的旅游打卡地之一，游人如织若是周末更是人海如潮，阳山水蜜桃是无锡特产江南一绝已在全国闻名遐迩，个大汁多味鲜甜，与无锡的杨梅、醉李、枇杷共称初夏四鲜果。阳山的美比陶渊明笔下的桃花源更有胜之，被围在粉红色桃花和金黄色油菜花里的白墙黛瓦整齐划一的村庄和星星点点散落在花间的农舍和谐相衬，六畜兴旺、鸡犬相闻，真有天上瑶池落人间美不胜收的感觉。春天的美、春风的美、春雨的美、人间的美、人生的美、人性的美揉和契合在一起才能让人在心灵上感觉到“人间春光三月天”的无限之美和实实在在的乡村振兴之美。再一次感谢老张老俩口的邀约，谢谢你们！"},{"id":112,"title":"雪中还乡","category":"诗","date":"癸卯年冬月初三","body":"朔风玉龙鏖战残，\n天地无边彻骨寒。\n喧嚣城市寂无声，\n唯有路灯送温暖。\n素颜银装裹千山，\n怀旧凭吊回雄关。\n两耳充闻今昔事，\n一抹微光不值谈。\n附记：12月14日无锡最高气温23度，嘉峪关最低气温零下20度，两地空间距离约3000公里，温差天壤之别。一九七六年从部队转业到嘉峪关市，二零零八调甘肃省工商局工作，在嘉峪关工作生活了三十多年二零一二年退休后跟随独生女回老家无锡定居大半辈子所为皆留于此，所以说嘉峪关是我的第二故乡这次回来探望岳父母二老乘上海至乌鲁木齐的Z40列车正点到达是晚上10点多，偶遇大雪回家的路上几无行人。自到嘉峪关至今近半个世纪，城市的变化可为天翻地覆，引人不胜感概随有诗兴涂鸦一篇《雪中还乡》，以示纪念。"},{"id":113,"title":"春日访樱花谷","category":"诗","date":"庚子年三月初一","body":"四月芳菲樱花开，\n美似云霞惹人爱。\n春意满满晴方好，\n人间清明绿世界。\n惠风婆娑枝摇摆，\n落花缤纷吻人腮。\n祈福铛铛同样醉，\n赏花莫忘前人栽。\n附注：去年清明节踏青游春去了雪浪山，并赋诗一首。今年清明节前带外孙满满踏青去了鼋头渚的樱花谷，清明节前后十天左右是赏樱的最佳期。樱花谷是世界上三大赏樱胜地之一，较另外两个、一是日本北海道青森县弘道樱花园，二是美国华盛顿樱花园都各胜一筹。樱花谷占地五百三十九公顷，有樱花一百多个品种、基本上囊括世界上所有的品种，园内樱花三万多株。赏花季节花如云霞、满目烂漫，春风轻拂、落樱飞舞若是瑞雪飘洒落在人们的面颊上轻柔而甜美。目前疫情虽然还没有完全好转，但压不住人们向往大自然的热情，游人如织美不胜收。回来后吟拙诗一首以记之，诗中将两外孙的乳名“满满”“铛铛”嵌入其中，更富草根情趣。“铛铛”是祈福的风铃，挂在樱花树上经风一吹、随风摇摆会发出“铛铛”清脆悦耳的响声。"},{"id":114,"title":"清明扫墓有感","category":"诗","date":"二零一六年清明","body":"清明扫墓车碾尘，\n回眸旧地添新坟。\n行孝莫等人不在，\n祭祀切忌奢风盛。\n枝繁叶茂树有根，\n数典勿忘数家门。\n血浓于水无可非，\n哀思寄情传精神。"},{"id":115,"title":"清平乐·塞上四季·嘉峪关","category":"词","date":"甲午深冬腊八日","body":"《春回》\n翠抹群山，春回嘉峪关。桃红柳绿湖堤岸，蜂蝶燕子相伴。\n钢城崛起荒滩，创业精神可赞。而今翻阅历史，塞上已换人间。\n《夏来》\n大漠孤烟，夏阳悬中天。海市蜃楼奇景现，酷似汪洋无边。\n远眺雪蒙祁连，滋润绿洲成片。近看东湖落日，塞上江南眼前。\n《秋至》\n胡杨换装，秋到铺金黄。蓝天大雁排成行，回首北望故乡。\n羌笛啭悠扬，牧歌激昂豪放。农家喜获丰收，塞上无限风光。\n《冬临》\n青山不老，冬雪白头早。雄关盛装披白袍，气壮山河多娇。\n楼挺胸舒腰，长城英姿妖绕。阳光铺洒丝路，塞上风景独好。"},{"id":116,"title":"游西山缥缈峰","category":"诗","date":"二零一四年五一节","body":"晴登西山缥缈峰，\n纵览群峦形不同。\n大岛似鲸浮半水，\n小屿如画嵌屏中。\n远眺太湖帆影丛，\n近睹坡前榴花红。\n顿觉凉意拥满怀，\n道是山风也湖风。\n附注：五一小长假期间应女儿、女婿之邀约游苏州西山，有感而发随作拙诗记念。"},{"id":117,"title":"漁家傲·乡村四季·江南风","category":"词","date":"甲午深冬后立春日","body":"《春来》\n九尽冬去冰雪化，惠风艳阳暖意发，老树枯草吐新芽。风景佳，桃红柳绿遍地花。蜂飞蝶舞忙无暇，燕子衔泥筑新家，布谷催播秧苗插。早谋划，天道酬勤有报答。\n《夏到》\n池映青山托芙蓉，蜻蜓点水倩影弄，蝉聒枝上噪声冗。树不动，夕照晚霞满天红。人家炊烟暮色中，蛙鸣溪畔乱起哄，暗处飞出萤火虫。望星空，清风徐来睡意浓。\n《秋临》\n蝈蝈无力抗初霜，蟋蟀悄然低吟唱，黄金铺地稻米香。丰收忙，农事务毕闲休养。静观庭前菊花放，霏霏雨送天凉，早晚莫忘添衣裳。夜渐长，持盅独酌度时光。\n《冬至》\n四季不同风景异，朔风凛冽起寒意，瑞雪飘洒天压低。柴扉闭，耕读传家好门第。几蓬修竹倚藩篱，数枝梅花霜满地，百虫蛰伏匿踪迹。人无计，周而复始春有期。"},{"id":118,"title":"物产丰富夸无锡","category":"诗","date":"二零一五年中秋节","body":"三月烟花舞东风，\n明前茶园露峥嵘。\n春来阳山桃花海，\n夏临大浮杨梅红。\n秋至荷残摘莲蓬，\n冬到鱼肥供享用。\n桂香稻熟忙开镰，\n四季风物各不同。\n附记：世间万物乃天地灵气相共而生，无锡人杰地灵可谓神州富庶之地，素有江南“鱼米之乡”美称。鲜果时蔬四季不断，四时八节总有当令应市。阳山密桃、大浮杨梅、誉满天下，葡萄车厘、醉李枇杷、玉菇甜瓜、亦是名声显赫。水芹茭白、茨菇菱藕、“太湖三白”、虾鲜鱼肥、螺蛳河蚌、样样味美。特产茶叶、历史悠久，洞庭碧螺、阳羡雪芽、太湖翠竹、享誉全国。千年陶都、泥人文化、物产丰盈、万世皆夸。"},{"id":119,"title":"秋日三叠","category":"诗","date":"二零二零年重阳","body":"《秋意》\n菊放露寒秋意浓，\n岁月静好逝无踪。\n一年一度团圆节，\n人生如戏恍若梦。\n《秋雨》\n雨似烟岚天地蒙，\n楼隐山遁藏其中。\n江南美景皆不识，\n日出天晴赏红枫。\n《秋阳》\n稻熟柿黄送秋凉，\n鱼肥枫红迎重阳。\n千年美德敬老日，\n万叟福寿齐绵长。"},{"id":120,"title":"管社山庄赏荷有感","category":"诗","date":"二零一七年七月二日","body":"《赏荷》\n一塘荷花万点红，蜻蜓戏水舞池中。\n翠盘银珠轻摇摆，涟漪荡起送凉风。\n赏荷旨趣各不同，任尔评说亦芙蓉。\n君子酷爱爱莲说，吾省清浊当追崇。\n附注：七月二日、星期天，阴，偶有几丝小雨，稍闷热。余与女儿女婿及小外孙，一家五口去无锡管社山庄赏荷。山庄座落在无锡著名景点鼋头渚的对面，隔湖相望。进入游览区映入眼帘的是大片红色的荷花间夹杂着粉红、白色荷花及红色、黄色的睡莲，相互斗奇争艳。又见数种蜻蜓、盘旋低飞、不时落到荷花上、摇着头用前脚搓脸，十分灵动可爱。是日，正逢公休日游客如织，梅雨季虽略有小雨、却丝毫未影响到游客赏荷的兴趣。受此景此情触动，欣得几句跃在笔尖，趴到纸上，作《赏荷》备考。右录：宋理学家周敦颐（1017-1073）《爱莲说》“水陆草木之花，可爱者甚蕃。晋陶渊明独爱菊。自李唐来，世人盛爱牡丹。予独爱莲之出淤泥而不染，濯清涟而不妖，中通外直，不蔓不枝，香远溢清，亭亭净植，可远观而不可亵玩焉。予谓菊，花之隐逸者也；牡丹，花之富贵者也；莲，花之君子者也。噫！菊之爱，陶后鲜有闻；莲之爱，同予者何人？牡丹之爱，宜乎众矣。”"},{"id":121,"title":"绝妙对联","category":"对联","date":"二零一八年七月一日","body":"据说有一对联，乃世上绝对，皇上出上句让纪晓岚对下句，纪晓岚未对出，如今我来试试，请大家评价。\n出句：坐北朝南吃西瓜，瓜皮放东边。\n对句：皇上陛下阅左传，传臣迁右任。"},{"id":122,"title":"节日串烧诗","category":"诗","date":"二零一零年一月五日","body":"（一）、除夕\n千里返乡赶过年，围炉辞岁竟废眠。\n合家团圆话趣事，国泰民安史无前。\n子夜钟声种福田，辞旧炮竹响连天。\n除夕互敬屠苏酒，来年共盼好光景。\n（二）、新春\n守岁欢娱尽五更，彩门启处正月正。\n喜联纳福红大地，春风和煦暖小城。\n舞龙耍狮闹新春，欢声笑语祝福您。\n天增岁月人添寿，周而复始又一轮。\n（三）、元宵\n东风夜放花千树，月皎不逊中秋输。\n笙歌动处谁无衷，观灯人海塞车路。\n春到万物皆复苏，除却旧桃换新符。\n今夜难忘元宵乐，汤元吃罢谋前途。\n（四）、清明\n积蓝凝翠秀群峰，山村疏舍别样红。\n阳春三月好时节，蜂飞蝶舞伴惠风。\n郊游踏青友相逢，闲情野外把酒共。\n政通人和方清明，黎民百姓乐其中。\n（五）、端午\n屈原事楚命可抛，不为强秦去折腰。\n汨罗江上传佳话，自此端午世人晓。\n龙舟粽子插蒲蒿，千秋遗风祭英豪。\n古今贤愚同瞬息，竖子立志读离骚。\n（六）、七夕\n七月初七称七巧，广袤银河铺鹊桥。\n牛郎织女今夕会，天上人间诉烦恼。\n王母无情拆爱巢，棒打鸳鸯两相抛。\n千古有缘成眷属，自由婚姻幸福道。\n（七）、中秋\n阴晴圆缺方月亮，悲欢离合才正常。\n古今难全人长久，花好月圆梦工场。\n别把美满当奢望，人间真情岂能忘。\n一年一度又中秋，祈愿亲友皆安康。\n（八）、重阳\n九九邀友去辞青，胡杨秋色连碧天。\n笑对人生老将至，心志不衰自加鞭。\n十八离家独远行，孝举难奉严尊前。\n重阳自古感恩节，吾辈当为后人先。\n（九）、腊八\n寒冬腊月当进补，人参燕窝富人煮。\n从来维生靠五谷，常吃杂粮润肺腑。\n耕种收贮虽辛苦，粮满仓廩农家足。\n腊八熬粥早提醒，来年别把农事误。\n（十）、小年\n小年非节列风俗，礼仪隆重皆可数。\n灶糖供奉灶王爷，上天言事莫踌躇。\n掸尘洗涮打扫除，杀猪宰羊磨豆腐。\n打糕蒸馍早准备，喜购年货接阿福。\n（十一）、元旦\n一元复始又元旦，人生旅途殊艰难。\n跌宕坎坷应历练，快乐心情常陪伴。\n新年应把新事办，及早图谋莫等闲。\n拼博奋斗勤努力，天道自有公道还。\n（十二）、五一\n工人阶级真豪迈，力量征服全世界。\n团结砸碎铁枷锁，当家作主自安排。\n世界工运兴未艾，纵深研究从头写。\n高举五一大旗帜，劳动再创美好来。\n（十三）、国庆\n十月金秋风送爽，蟹肥花鲜果飘香。\n翻转甲子六十年，神州大地变了样。\n国庆佳节聚一堂，各族人民喜若狂。\n幸福生活要珍惜，党的恩情永不忘。\n一年中节假日如此之多，说明美好的生活常陪伴在我们身边，把一年的节日串联起来写成诗，抒发情感、意境独到，好不乐观开心。"},{"id":123,"title":"扬州慢","category":"词","date":"二零一八年七月一日","body":"（谙世）\n放飞理想，管控欲望，世事变化无常。\n奋斗无厚非，竞争莫痴狂。\n人生结局都一样，红尘看破，何必逞强。\n静观品、苍生万象，世态炎凉。\n立身修为，豁达大度秉善良。\n人间百般爱，情缘注定，聚散何妨？\n守残缺神思伤，大道无痕别徬徨。\n一笑泯恩仇，无旁鹜任飞翔。"},{"id":124,"title":"赏菊","category":"词","date":"二零一二年春节后","body":"（蝶恋花）\n姹紫嫣红墨白黄，平分秋色，清寒慰重阳。\n千姿百态欺严霜，万般风情飘冷香。\n黄昏虽近莫苍凉，玉骨刚姿，有志别番样。\n东篱菊君名士望，儒雅贤达圣人赏。\n注：魏紫、姚黄、墨菊都是菊花中的名贵品种。"},{"id":125,"title":"赞竹","category":"词","date":"二零一二年春节后","body":"（蝶恋花）\n坪峰满目叠翠竹，盘岩错缝，钻天立根足。\n春发嫩笋满山谷，秋伐玉竿富民福。\n天生我材非草木，坚挺有节，虚心脱凡俗。\n风雨摧残不倾伏，君子模范令人服。"},{"id":126,"title":"颂兰","category":"词","date":"二零一二年除夕前夜","body":"（蝶恋花）\n芝兰原是一株草，出于深山，无卑且无傲。\n婀娜纤姿自为巧，儒雅风韵独守抱。\n骨格清奇品位高，洁身无瑕，不争艳斗俏。\n淡然素馨随处飘，孤芳自赏无烦恼。"},{"id":127,"title":"临江仙·国庆阅兵有感","category":"词","date":"二零一九年清明节","body":"华诞庆典喜阅兵，\n雄鹰比翼长空。\n铁甲洪流数东风，\n将士振军威，\n神州东方红。\n雄狮觉醒待崛起，\n复兴奋斗其中。\n信念坚定不摆动，\n世上无难事，\n定圆中国梦。"},{"id":128,"title":"秋思","category":"诗","date":"二零一七年霜降日","body":"桂香月圆秋渐浓，\n岁月如梭行怱怱。\n阴晴圆缺秋思里，\n人生如戏戏如梦。\n秋雨如丝轻纱蒙，\n远眺群山醉朦朦。\n别怨高傲不识君，\n只缘身在烟霭中。\n蓦然霜降寒意重，\n山林尽染黄与红。\n此番胜景不日去，\n落叶无须怨秋风。\n天高云淡万里空，\n秋阳和暖似春风。\n抬头望见南飞雁，\n不觉时节快入冬。\n欲获秋收春下种，\n汗滴禾下勤劳动。\n天掉馅饼虚妄有，\n诚实付出酬苦功。\n金蟾玉兔广寒宫，\n吴刚嫦娥寻秋梦。\n望月思亲两牵挂，\n天上人间盼相逢。\n附记：二零一七年中秋节所想\n2017年10月4日是中国传统节日中秋节，也是中国人的团圆节。因今年农历闰六月，节时，己是秋意浓浓。俗语说：“年怕中秋，月怕半。”时光似流水，中秋节时一年就悄然过去了三分之二。\n且有诗云：“每逢佳节倍思亲”，确实如此，这是中华文化的根脉。年青时从数千里之外的江苏来到甘肃嘉峪关市工作，孑然一人，无依无靠，退休后随女儿生活又返回江苏无锡，可谓是叶落归根。\n但因岳父母仍在嘉峪关生活，他们视婿如子，余恩未报，如今他们已步入耄耋之年，体衰多病，我又无能力照料，分居两地常思常念。尤其余今年也已六十有八，虽不敢称风烛残年，但也到了人生之深秋，好多事已心有余而力不足，不能如愿以偿。因此，今年中秋赏月时勾起思绪连连......，随寄情于几首短诗将自己所思所虑相讬附之。\n经努力终于于节后一周的10月11日乘上海至伊宁的204次列车于12日21时到嘉圆相逢之梦，以免给今后留下憾事。"},{"id":129,"title":"二零一五大事楹联","category":"对联","date":"二零一五年","body":"三羊开泰，十八届五中全会，定改革开放好思路\n金猴奋起，十三五宏伟规划，启继往开来新征程\n一带一路建投资银行，谋双赢共发展\n全心全意为友邦着想，扬声誉振国威\n反腐肃贪，促风正气清，赢党心民心\n清廉从政，倡守规立矩，畅政通人和\n九三阅兵，勿忘国耻民难，关注国际安全\n十一国庆，铭记历史教训，维护世界和平\n乙未羊去，辞旧岁，满载而归\n丙申猴来，迎新春，再图大业"},{"id":130,"title":"人生如是","category":"诗","date":"二零二零年国庆","body":"人生跌宕多险难，\n退休淡然方清闲。\n长江逝水推前浪，\n黄河逐流挟泥丸。\n乐思青春激情暖，\n回眸往昔略心寒。\n岁月留痕鬓如雪，\n历程无愧余笑颜。\n附注：自释《人生如是》\n人来到这个世界上就必须学会适应周边环境，经过学习、工作、家庭、事业、社交等各方面的锻炼与考验，才能得到不断的成长与进步，学会人与人的交往，人与自然的交往才会日趋成熟。\n如果一生中无大的跌宕起伏就是命运最好的安排，就毫无理由期盼所有的事件都一马平川、一帆风顺。伴你左右的一定会有一些磕磕碰碰、遭遇一些坎坷和困难。\n古人云：天欲降大任于斯人，必先苦其心智，劳其筋骨，饿其体肤。如此人生才是多彩的、充实的。所以要做好充足的思想准备，坚韧不屈才能水到渠成，才能面对各种复杂情况做到得心应手运用自如，也才能成为一个完整的对社会有益的人。\n退休只是人生社会角色的转换，过去角色的光环会随着时间的延长慢慢的暗淡下去，隐逸到人山人海之中。\n“有我无我，无我有我”，一个正常的人一生不仅仅是为生存而活着，在推动社会发展进步上如果不能建功立业，至少也应该添砖加瓦，可以做一个平凡的人，但不能做一个碌碌无为的行尸走肉、这就是我对人生的理解与定位。\n感谢造物主送给一份极其珍贵的礼物─“时间”，让年青时未能实现的所有梦想，在退休后的第二春期，不断努力让其逐一实现，不让留下更多的遗憾，让“老有所依、老有所养、老有所为、老有所乐。”真正落到实处幸福就会扑面而来且可终身不缀。\n人生和社会的发展互相关联，都有其必然的规律，长江后浪推前浪，一代更比一代强这就是必然的趋势，只有懂得这个规律顺势而行，才能够行稳致远。\n黄河是母亲河并不是说说而已，我们每个人都象黄河中的一粒泥沙，必然会被滚滚洪流裹挟而行，与时俱进才能紧跟上历史的步伐。个人的力量是微渺的，当它汇成一股激流、就会以排山倒海之势，雷霆万钧之力，推动历史向前，这就是几千年来永不磨灭的中华民族之魂。\n“为人民服务”是中国共产党的根本宗旨，立党为公是党的出发点和落脚点。我作为一名共产党员始终不忘初心，乐于将一生交付于党的事业。满怀激情为园中华民族伟大复兴梦，实现两个一百年的宏伟目标、贡献自已力量而感到骄傲和自豪。\n回首反省已过去的日子，也还有不尽人意的地方，或者说还有很多事情做得不够好，留有一定遗憾。好在“人无完人、金无足赤”这句名言可以给一丝宽慰，让心情轻松一点。人生只要努力奋斗过，虽有不足也可以无怨无悔。\n激情的岁月随着时间的流逝渐渐远去，两鬓如雪这是人生过往留下的痕迹。\n“人过留名、雁过留声”，金杯银杯不如老百姓的口碑。人生的历程中如果老百姓对你有一个好的评价，组织上也给你一个好的肯定，一生无愧于天地良心，也就可以不枉此生了。\n那种“盖棺论定”的说法又有什么意义呢？"},{"id":131,"title":"元宵观灯","category":"词","date":"壬辰年元宵节","body":"（蝶恋花）\n琼楼玉宇广寒宫，群仙毕至，逍遥喜相逢。\n天上人间把酒共，闹元宵其乐无穷。\n月朗风清潮急湧，花灯斗彩，若狂舞金龙。\n大千世界沐春风，呈好兆人寿年丰。"},{"id":132,"title":"吟松","category":"词","date":"二零一二年春节前","body":"（蝶恋花）\n岁寒三友首为松，顶天立地，攀崖驻险峰。\n萧杀冷意凋蔽容，唯此披翠挺严冬。\n浩然正气凌碧空，不屈不挠，狂风撼不动。\n万木争发绿更浓，大智不语人称颂。"},{"id":133,"title":"咏梅","category":"词","date":"二零一二年除夕前夜","body":"（蝶恋花）\n雪梅傲霜花开盛，群芳无颜，冷艳秀天成。\n不攀富贵先宜人，料峭严冬报新春。\n生就铁骨铮是魂，蕊吐幽香，寒中抖精神。\n年复一年皆守恒，世间花魁独数您。\n注：《蝶恋花》，唐教坊曲名。本名《鹊踏板》。曼殊词改今名。调名取梁简文帝萧纲诗句“翻阶蛱蝶恋花情”中的三字。双调。六十字，十句。上下片各五句四仄韵。句式为：仄仄平平平仄仄，仄仄平平，仄仄平仄仄。仄仄平平平仄仄（或仄平仄），平平仄仄平平仄。下片句式同上片。凡以（蝶恋花）所填词皆以此为例。富贵，指牡丹花，暗喻人间的荣华富贵。"},{"id":134,"title":"嘉峪关城上怀古有感","category":"词","date":"二零一三年一月","body":"（沁园春）\n雄关高耸，扼喉锁钥，地势险要。\n眺烽火狼烟，战事又起。\n调兵遣将，鼓角螺号。\n金戈铁甲，土铳车炮。\n旌旗猎猎迎风飘。\n霎那间，观两军对垒，布阵出招。\n胜负未定分晓。\n伤民族情谁低谁高？\n还大千世界，睦邻友好。\n朗朗乾坤，韶光普照。\n柔远光化，羌笛胡笳。\n华夏根基永筑牢。\n数百年，看长城依在，沧桑正道。"},{"id":135,"title":"贪官铭","category":"对联","date":"二零一七年七月一日","body":"官高位重，恣意横行。吏污妄为，坑害百姓。\n弄权渎职，总为捞钱。饱暖思淫荡，贪欲忘初心。\n三餐八尺足，何许千万银？若欺民意轻，船翻盈。\n人作孽自找死，天不饶当获刑。家破人亡时，后\n悔亦无言。铭此诫：“官德要紧！！”\n附记：\n中学课本上有（唐）刘禹锡（772-842）所著《陋室铭》，读后直觉得古人真伟大。列朝列代有不少仁人志士、充满大智慧，把“修身、齐家、治国、平天下。”当为已任，千古留名。\n而今重读百感交集，盛爱有加。古人尚且懂得以道德自律，以清廉修为，不以物质利益为欲，崇尚精神高远为人。今天，人民公仆，为何贪腐百出？老虎苍蝇皆欲壑难填？千万上亿、屡见报端。细思量，道德、环境、制度、法律皆有问题。治国即治吏，治政必管党。十八大以来，打虎灭蝇、整饬官场，治标治本、并行共举，风清气正、不远有望。特以《陋室铭》为形韵，作《贪官铭》以示警诫。\n右录：《陋室铭》：\n山不在高，有仙则名。水不在深，有龙则灵。\n斯是陋室，惟吾德馨。苔痕上阶绿，草色入簾青。\n谈笑有鸿儒，往来无白丁。可以调素琴，阅金经。\n无丝竹之乱耳，无案牍之劳形。南阳诸葛庐，西蜀子云亭。孔子云：“何陋之有？”"},{"id":136,"title":"工商战士之歌","category":"词","date":"二零零六年八月初","body":"迎朝阳、整行装、脚踏坚定的步伐、头顶国徽、为民执法，监管市场、监管市场。啊！光荣的工商战士、光荣的工商战士，身负人民重托、肩挑民族期望、无比自豪、无尚荣光。\n战狂风、斗恶浪、高擎正义的大旗、履行职能、规范行为，意志如钢、意志如钢。啊！坚强的工商战士、坚强的工商战士，支持经济发展、保护消费安康、不畏艰险、斗志昂扬。\n创伟业、铸辉煌、谱写崭新的篇章、廉洁奉公、依法行政，贡献力量、贡献力量。啊！英勇的工商战士、英勇的工商战士，坚持文明管理、树立良好形象、红心向党、永向前方。\n永向前方。"},{"id":137,"title":"庚子抗疫记","category":"词","date":"庚子年正月望日","body":"（扬州慢）\n庚子朔望，病毒冠状，肆虐神州猖狂。\n全国总动员，武汉要坚强。\n运筹帷幄党中央，令如山倒，严密布防。\n关键时，党员挺身，知难而上。\n火神雷神，抗疫情急建方舱，\n调集人财物，八方驰援，有序不慌。\n战疫魔，定胜利，必张显中国力量。\n人间有大爱，相拥抱迎春光。"},{"id":138,"title":"思归","category":"诗","date":"二零零八年中秋夜","body":"月升中天彩云追，\n星聚银河鹊桥会。\n人间美景阅不尽，\n天上众仙思乡归。\n附记：\n中秋节是中华民族的团圆节，是世界华人思念故乡、托寄情怀的盛典之夜。是夜，举国欢庆、余于嘉峪关雄关文化广场观看中秋晚会。碧空如洗、凝练似海、秋高云淡、神清气爽、众星捧月、银辉普照。霎时、鼓乐喧天、笙箫和鸣、茑歌燕舞，喜降人间。\n观古往今来颂中秋明月的名诗藻词、虽枚不胜举，但触景生情夜不成寐、浑然不顾无名的冲动、遂将所思所念跃然涂鸦、仿作拙诗七绝《思归》一首，并备愚解以志记念。\n月升中天是指伟大祖国在当今世界民族之林中如日中天的国际地位，特别是成功举办了2008奥运会和残奥会后更是举世瞩目。因此，在外交政策和外交关系上也受到众多国家的拥护与支持。\n星和月是指宝岛台湾与祖国大陆的特殊关系，2008年4月台湾大选，马英九执政、两岸关系已有改善，重开“汪辜会谈”大有希望，台湾方面却亮出了不统、不独、不武的“三不”政策，给两岸关系蒙上了层层疑云，同胞兄弟、骨肉亲情、本应血浓于水、手足相牵，就此看来两岸人民的福祉、愿景还有盼于两岸领导人共图民族大业的胆识与创举，实现祖国统一仍然任重道远。\n去年10月24日中国发射嫦娥一号月球探测器，今年9月25日“神七”问天，宇航员太空行走，打破了月宫的千年沉寂，实现了人类的飞天梦想。天上众仙是指中华神话传说中的牛郎、织女、吴刚、嫦娥、他（她）们对地球上的人间重新审视、惊然发现、沧桑巨变、时代发展，伟大祖国科学进步、经济繁荣、民族团结、人民富裕、社会和谐、安居乐业，人间己胜过天堂。特别是改革开放以来、三十年的实践证明了中华民族伟大复兴之创举、所取得的辉煌成就是史无前例的。\n天上众仙思念人间之美好，企盼能早日回归故乡，骨肉团聚、夫妻相见。暗喻台湾同胞人心思归，完成祖国统一大业仅是迟早的事。\n2008中秋夜，\n三省轩主程康年"},{"id":139,"title":"寄情陇西","category":"词","date":"二零一零年七月三十日","body":"流火七月酷暑中，\n同仁陇西相逢。\n共谋发展正党风。\n谁也不示弱，\n个个争先锋。\n领导关爱意真切，\n胜似兄弟情浓。\n吾辈深知责任重。\n垂范先律己，\n清风扬系统。\n注：2010年7月27日至29日，全省工商局长座谈会暨党风廉政建设经验交流会在陇西县召开，为纪念会议的圆满成功填词《临江仙》一首以示祝贺。"},{"id":140,"title":"无锡吟","category":"词","date":"二零一二年端午节前","body":"其一、《无锡吟·人文情怀》\n江南四百八十寺，\n不绝暮鼓晨钟。\n二泉映月情更浓。\n陶泥皆成趣，\n日月茶壶容。\n泰伯礼谦逊王位，\n吴越千古遗风。\n人文积淀凝厚重。\n德广共“三和”，\n闲时“扯老空”。\n其二、《无锡吟·江南美景》\n江南美景谁不忆，\n锡惠两山葱茏。\n太湖帆影迎日红。\n蠡锦春色满，\n梅开方知冬。\n灵山佛刹布福祉，\n运河泛舟叙功。\n鼋头渚上闻涛动。\n古镇浸烟雨，\n客游在画中。\n其三、《无锡吟·改革浪潮》\n江南模式树榜样，\n改革浪急潮涌。\n中华复兴盛世逢。\n率先大发展，\n敢领创新风。\n“四个无锡”定目标，\n用武任凭英雄。\n改天换地缚苍龙。\n万民齐参与，\n共圆中国梦。\n注：1、人文：《周易·贲卦·彖辞》有云：“刚柔交错，天文也；文明以止，人文也。观乎天文，以察时变，观乎人文，以化成天下。”\n2、陶泥：宜兴陶器除生产的紫沙茶壶闻名中外，还能生产多种炊具和生活所需各种各样的实用器。惠山泥人，是无锡著名的旅游特产已有几百年历史其知名度也很高。\n3、日月茶壶容：不仅指无锡的宜兴在历史上出了很多制壶大师、传承至今、人才辈出，使制壶工艺发扬光大、经久不衰。而更多的是指自“茶圣”陆羽起、无锡人都颇讲“茶道”，酷爱啜茶品茗、过休闲悠得的生活。\n4、“四个无锡”是市委、市政府指出无锡今后发展的方向和目标，具体为要将无锡打造成：魅力无锡、创业无锡、创新无锡、幸福无锡。\n5、“三和”是指人与人之间关系和睦，人与自然之间关系和谐，人与社会之间关系和平。"},{"id":141,"title":"春恋","category":"词","date":"二零一二年春分日","body":"（四季欢）\n柳枝摇动春意闹，\n霞映桃花更俏，\n阳光正和暖，\n执情侣手。\n掩面笑。\n掩面笑，\n乐在其中，\n看蝴蝶双舞，\n热血涌心狂跳，\n翘首盼月圆花好。\n《四季欢》句式为：76543对34567，格律上片为：平平仄仄平平仄，仄仄平平仄仄，平平仄平平，仄仄平平，平平仄，下片与上片同。"},{"id":142,"title":"春之韵","category":"诗","date":"二零一三年春分日","body":"（一）\n檐下冰凌化素琴，\n岸边翠柳听鹂鸣。\n已是大雁归乡时，\n百花春雷谁为先？\n（二）\n丝丝细雨润田畴，\n九尽遍地走耕牛。\n夜来东风缱绻过，\n晓看红杏闹枝头。\n（三）\n三月踏青人如潮，\n艳阳惠风女儿姣。\n曲溪觞饮丹青伴，\n晴空碧洗风箏闹。\n（四）\n田园村落流暖香，\n蜂飞蝶舞采花忙。\n桃李不言自成蹊，\n山河怎能不换装？"},{"id":143,"title":"春游雪浪山记","category":"散文","date":"己亥年清明节前","body":"春山满坡花生香，\n牧笛余音绕山梁。\n杜鹃啼血催播种，\n农夫吆牛耕田忙。\n孙儿绕膝问短长，\n循导莫负好时光。\n不觉暮霭遮村舍，\n登上峰顶看夕阳。\n附记：清明节前一周，全家踏青春游雪浪山。雪浪山位于无锡江南大学南边，属近郊、是无锡可游览的一处胜景。山上满目青翠、满坡花香、尤以薰衣草居多。山下溪田点点，农耕缀忙。栈桥之上放眼远望，一片生机勃勃春意荡漾，柔柔的春风吹拂大地上的一切，送来温暖、送来滋养。满天的风筝争奇斗艳、随风飘扬。游春的人们络绎不绝，熙熙攘攘。\n这一美好时刻拉开了思绪的大幕，回想起自己大半辈子为生活所需、为家庭所牵、为事业所累、为工作所忙，虽无惊心动魄的坎坷跌宕，但也无值得骄傲的大成辉煌，平平实实无妄虚度，确属平常也算值当。\n退休已近十载，买菜饴孙当“厨娘”，乐此不疲幸福安康，无疑我这一生综而观之是遇到了好时光，时年古稀不知余生还有多长？树起“老有所依、老有所乐、老有所为”的情怀，活好当下别无奢望。\n将“一年之计在于春、一日之计在于晨”，“一寸光阴一寸金、寸金难买寸光阴”，“种豆得豆、种瓜得瓜”等古训精髓，谆谆教导孙儿要永记心上。\n展现在眼前的就是一幅美丽诱人的《牧春图》承载着人们美好的希望，无限的向往。恨无彩笔着墨更无画画才能使其跃然绢上，仅以此短文加相机辅录于此，也不枉今日春游之兴，获有所偿。"},{"id":144,"title":"“3.15”联想","category":"杂文","date":"二零一三年三月十六日","body":"3月15日是世界“消费者权益日”，在中国每年都会搞一台晚会，为消费者的权益伸张正义，搞一些权威发布，披露一些消费陷井，但总让人感到像网络热词所说的“正能量”不够，所谓的“天天3.15”只是一句说词。虚假广告、欺诈蒙骗；制假售假、昧着良心；服务幌子、全为捞钱；不法企业、无良商家、无知百姓，年年都在翻着花样坑蒙拐骗消费者，你在城里配制婴儿奶粉、我就在乡村培育红心鸭蛋，瘦肉精、苏丹红、吊白块、地沟油、甲醛泡、硫磺熏、三聚氰胺、激素饲料、电信诈骗、黑道传销；化肥滥施、农药残留……搅得“上帝”无所适从。公序良俗破坏怠尽，人们的“衣、食、住、行”都失去了安全感，人人自危、个个忧愁，谋财害命、触目惊心，并非危言耸听。大家都在问：这个社会到底怎么了？监管部门哪里去了？\n到底怎么了？静下心来仔细想一想，“金钱拜物、物欲横流、诚信缺失、人心浮躁”，这些消费领域里的毒瘤己浸染到了社会生活的各个层面。社会风气坏了，道德沦伤的表现无不存在：一死囚临刑时哭喊对不起家人，因他参与了一起灭门杀人案；一个人在医院里偷了别人的钱包是因为母亲病重急需钱；一个官员贪污收贿几百万是为了深爱的女儿锦衣玉食；一个父亲为了自已的孩子上大学，就可以随意改档案顶替别人的孩子；一老板久农民工的工资可称别人欠自己的钱也没还；一妇女从产房里偷婴儿的理由是太喜欢孩子却又没有生育能力；一老人大街上晕倒没人敢搀扶，因为怕引火烧身遭遇不白……诸如此类理由是理由吗？\n有钱必争、无钱不问，职责不清、监管乏力是行政监管的通病，新闻媒体曝光这些案件时也让人觉得在人性、伦理、规则、逻辑上有同情、默认、怂恿之嫌。经济发展物质丰富并不等于精神的文明，中国人历来有“不患寡、患不均”的传统思维，贫富不均、官场腐败、司法不公，政风失范、管理滞后是社会的瘟疫，如没有毛主席“送瘟神”的精神彻底铲除，后果是很难设想的。\n难道宠爱自己的孩子就可以漠视别人的孩子？难道孝敬自己的父母就可以欺侮别人的父母？难道善待自己的兄弟就可以盘剥别人的兄弟？难道爱护自己的姐妹就可以凌辱别人的姐妹？难道扩鼓自己的钱包就可以暗算别人的钱包？难道造福自己的家乡就可以掠夺别人的家乡？难道当官不是为民服务而是为自己捞钱？……\n二千五百多年前孔子的学生向孔子讨教支撑国家强盛不衰的法宝是什么？孔子回答说，法宝有三“兵、粮、信”，古人早就知道“诚信”是一个国家、一个民族兴旺发达的法宝，两千多年的华夏文明如今哪里去了？\n盼望社会风气好转、草根百姓在呐喊，一个好社会就应该有好风气，个人的幸福要不以别人的痛苦为前提，个人的满足要不以别人的遗憾为成本，个人的富有要不以别人的贫困为背景……，甚至，人类“以人为本”的时候、不再虐待别的物种，人类“壮大人间”的时候、不再掠夺大自然。盼望有好的社会风气，当权者就应该率先做起，连公开自己财产的勇气都没有，难道还有真心当“公仆”？要想有好的社会风气，全体公民也应该从我做起、从现在做起、从点滴小事做起，勿以善小而不为。“倡导文明、弘扬美德”全社会都应以只争朝夕的精神尽快变成共识和承诺，变成行动和效率。\n当然有了好的社会风气，天下孩子都会遇到呵护，所有老人都会得到孝敬。应当以公共的担当替代百姓的焦虑；应当以文明的信用激励民间的诚实；应当以完善的制度保障分配的合理；应当以严格的规范促进司法的公正；应当以透明的政务控制权力的运用……。\n更应当让富人失去骄横、学会仁爱；让弱者得到帮助、不失尊严；让美德与纯真不被嘲笑与辜负；让每个有梦的人都有光明与幸福感；让命运不会亏待那些劳苦大众，让耕耘和收获、汗水和果实一定成正比。这才是为民执政的天职使然。\n总之，当政者应当利用一切可以利用的方式方法推进政治民主、促进经济繁荣、引领生态文明、保障社会公平、弘扬传统美德，下大力气建设好社会诚信体系。更应当不会因遇到百姓的挑剔而恼怒，不会因遇到草民的责备而放弃自己的职责。只有这样中华文明的全面复兴才有希望。"},{"id":145,"title":"\"面子\"新说","category":"杂文","date":"二零零一年二月","body":"人总是要\"面子\"的，\"面子\"到底是什么，现代汉语词典上有两种解释一种是：1物体的表面。2体面，表面的虚荣。3情面。第二种解释是：粉末。\n对人来说\"面子\"即\"脸面\"，\"脸面\"从生理上解说无非是由额头、眉毛、眼睛、鼻子、嘴巴再加上腮帮拼凑起来的一个活部件，其作用极为奇妙、随时可以千变万化，既可以在上司面前媚态百生、也可在下属面前冷若冰霜；既可在毫无关系的人面前铁面无私，也可在有所求的人面前灿若桃花。川剧的变脸、是一种奇巧的艺术，更是一种深刻的文化内涵。\n\"脸面\"最要紧的是和\"面子\"牵扯在一起的、既有相同之处又有不同之点，可以说是难解难分。为此，我重给它下个定义，不知是否确切。\"面子\"就是一个人在社会上注册的商标、更多地表现为个人的信誉度和社会的认知度，是行为科学的一个方面。\n一、死要面子。为了在这个世界生活得更好些、人总是要表现自己的人性，因此就容易出现两种极端情况：一种是自认为\"拼博奋斗\"的，在学场上刻苦，在职场上奔命，在官场上争斗，在一切名利场上周旋。一生中遇到竞争对手是很多的，因为这种人很在乎金钱、权力、名声......，很在乎自已的\"面子\"，若在某一方面不顺畅，达不到自己的目的就怨天尤人，就会神经质地走向极端。初中学生为使自己学习成绩靠前、竞下毒毒死比自己强的好学生。官员为在官场得到一个光宗耀祖的好位置竞雇凶砍杀对手的事曾见于报端。\n死要\"面子\"的这种人，很在乎一切世俗的荣华和体面，古时候就有那么一个故事：有个秀才家境穷酸潦倒经常是吃了上顿无下顿、日子过得十分艰辛，但为了不在众人面前失\"面子\"饭点后无论是吃了还是没有吃、他总用一块肉皮把嘴角噌得油光珵亮显摆自已的殷实富有。这种酷爱虚荣的人、他们干什么不干什么、说什么不说什么，自己的一举一动总考虑别人怎么看、总在意别人怎么想，好像自己在为别人活着。这种人在自己的生活中好象只有得到他人的艳羡和仰慕才快乐，只有得到他人的奉承和恭维才幸福，只有得到他人的敬畏和膜拜才满足。郭冬临表演的幽默小品《有事您说话》生动的表现了这种虚荣的体面。虚荣心的膨胀、价值观的扭曲必然会导致理性自尊的灭失，想要\"面子\"其结果反尔是没有了\"面子\"。\n死要\"面子\"活受罪。\n二、不要面子。另一种人则是厚颜无耻真不要\"脸面\"的人，他们崇尚标准的实用主义，只要某种行为对自己有用处、有好处、有实惠，便会不顾自已的\"面子\"，就会不择手段，\"坑、蒙、拐、骗、偷、缠、磨、乞、赖、投\"，哪个能用就用哪个。就会放弃所有道德约束，甚至于法律而不顾，什么违法缺德的事都能干得出来。这种恬不知耻的人、根本不会考虑自己不要\"面子\"会给他人带来什么样的伤害和痛苦。这种不要\"面子\"的人，完全可以归类到社会痞子无赖里，列为人类的渣滓。\n人无廉耻国法难治。\n三、真爱面子。\n要真正学会做人处世很不容易。做人，死要\"面子\"和不要\"面子\"，两种极端行为皆不可取。处世，与有这两种极端行为的人皆不可交。要体现自己的人生价值、得到自己的信誉和社会的认知度，还得靠自己。有位哲人说过，\"家庭是社会的细胞\"。我们每个人又都是家庭的细胞。每个人在社会生活这个大舞台上都有自已的位置，要扮演好对家庭对社会负责的角色，\"面子\"还是要的。以法治国、以德治国、建设和谐社会的方略己经制定，要把自己的\"面子\"放到法律和道德允许的笵围内去考量，真爱\"面子\"就要加强道德修养，把儒家思想中的\"仁、义、礼、智、信\"体现到自己生活的各个层面。\n真爱\"面子\"也就一定会有面子。"},{"id":146,"title":"晨练与健康","category":"散文","date":"二零一二年荷月","body":"现在生活条件好了，人们都希望提高生活质量，希望健康长寿。因此，如何有一副好身体就成为人们日常生活中最值得的关注的事情了。由此也派生了电视、广播关于养生的节目多起来，关于如何养生的书籍发行多起来，走南闯北宣讲养生科学的专家多起来，当然像张悟本、萧宏慈那样的骗子和各式各样的骗局自然也就多了起来。\n退休以后，生活的方式变得单调纯粹起来。过去，总有许多不得不做的事情，时间不得由自己安排，忙碌起来真是\"白\"加\"黑\"、\"五\"加\"二\"，为按时交\"活\"争分夺秒，还经常是事半功倍，得到的是身心疲惫、情绪焦虑，无形中冲淡了关于生命意义的思考。现在则不同，所有的那些忙碌戛然而止，才慢慢悟到生命的意义，才真正理解\"身体是革命的本钱\"这句名言的意义，才懂得健康的重要性，时下\"健康第一\"已成为口头禅。身体健康要多了解一些养生常识未必不可，但决不能钻\"牛角尖\"，要得身体健康关键是两条：一是要管好自己的嘴，二是要迈开自己的腿。\n病从口入是有一定科学道理的，国人很多毛病都是吃出来的，记得十几年前广东人吃\"果子狸\"就吃出了问题。中国是一个饮食文化深厚的国度，粤菜、湘菜、川菜、徽菜、鲁菜、淮扬菜等各省或各种文化相似的地域都有自己的菜系。现在生活条件好了，老百姓吃饭也讲究了起来，只要有好吃的，不管是天上飞的、地上走的、水中游的都要尝尝鲜，只要有就行，就是不差钱。所以，现在一桌饭动辄就是几百上千，如果是\"三公\"消费上万元的也屡见不鲜。\n中国的高级厨师很多，他们研究的是满汉全席，制作的是调人胃口、色香味俱佳的菜肴。很少有大师把营养要素真正放在第一位去考虑如何选择搭配食材，高脂肪高热量的美味佳肴诱导人们暴饮暴食、海吃胡喝，让人吃成了易患糖尿病、心血管病的亚健康身体，还有我认为是垃圾食品的\"肯德基\"\"麦当劳\"让青少年吃出了肥胖症，这就是当前我国饮食文化的国情。偏食挑食不足取，均衡营养应该是值得提倡的。\n佛家有这么一种认为：人一生消耗的物质对每个人来说都是有定数的，不可多也不可少。如果过早地消耗掉，堆积在人的身体里，不仅会影响健康，而且有可能会缩短人的寿命。物极必反肯定是一条真理。\n生命在于运动也是有科学根据的，饭后百步走能活九十九。近几年无论是城市还是乡村都掀起了一股锻炼热，可谓是男女老少齐上阵，这也是生活质量提高的一种表现。锻炼的项目也很多，打太极、练武术、跑步、散步、喊街、吊嗓、唱歌、唱戏曲、跳广场舞、街舞、打球、游泳等诸如此类可各随所好。时间很灵活，迎朝阳晨练、邀晚霞散步，地点很随便，街头巷尾、广场公园都有比较适合人们锻炼的体育器械。\n刚结束的第三十届伦敦奥运会上，中国体育代表团又取得了像2008北京奥运会一样、金牌第一、奖牌总数第一的好成绩。所以，有人就说中国已实现体育大国、强国之梦。取得好成绩当然可喜可贺，说中国已成为体育大国我看未然。衡量一个国家是否是体育大国、强国，在竞技比赛中取得好成绩固然重要，但更重要的是看全民参与体育活动的积极性，最终看全民体质、平均寿命提高的程度。推动全民健身运动，彻底摘掉\"东亚病夫\"的帽子，才是成为体育大国、强国的真正标志。\n退休后我选择的晨练方式是快步走，每天早晨随太阳初升的时间从家中出发，用一到一个半小时沿迎宾湖走一圈返回，大约有五、六公里路程，坚持四肢运动。在走路的同时不仅调整好深呼吸，还要让双臂沿肩轴做双向绕行运动1000次左右，这种有氧运动对锻炼身体十分有好处。去年查体时发现的中度脂肪肝在今年查体时已成轻度，腰椎、颈椎疾病也有所好转，我的目标是坚持锻炼，彻底告别一切病魔，恢复第二青春。\n现在处于市场经济时代，人们的生活节奏不断加快，人心比较浮躁，人性也有所失落，身心健康都受到了一定影响。现在内在心理上需要的是内敛与修养，外在肢体上需要的是运动和锻炼。不参与锻炼就不利于身体健康，透支健康就是透支生命，慢节奏的生活才是时尚，这一点要提前认识，更要提前行动。\n清晨运动不仅活动驱体，更重要的是放飞心情。心情好身体才能好，身心才能都健康。早晨初升的太阳金灿灿的，向天上看蔚蓝的天空衬托着一朵朵轻柔的白云在慢慢地飘动，让人真有飞天的冲动；向前看阳光倒映在平静的湖面上像是铺了一条金色大道，前途一片光明；向地下看阳光把小草叶尖上的露珠照耀得像银色珍珠，让你遐想把它串成项链送给最心爱的人；向远处看阳光把祁连山主峰上的冰雪映照得更白、金光四射，让\"青山不老、为雪白头\"更有诗情画意；向近处看亲和的阳光照在人们脸上红朴朴的，显得人人都很健康，这都是大自然赐给人们的幸福。\n阳光更像一支彩笔，它照到哪里就会让那里的色彩增添十二分的光艳，使树更绿、草更嫩、花更红……无论照到哪一座建筑物上都会将柔和的光线反弹到你的眼眸中，触动你的视觉神经，那种缤纷炫目的色彩一定会让你兴奋不已。\n阳光是有生命的，它带来的也是一片盎然生机。晨练对人的身心健康是有好处的，一定坚持下去。"},{"id":147,"title":"八一絮语","category":"散文","date":"二零二零年八一节","body":"虽远离军营多年，但每逢八一心里总有一种莫名的冲动，有回忆、有激情、有思考、有思念……享受这种留念军营的情结，享受这种曾为军队中普通一兵的心境。细想也是，一个把最宝贵的青春年华奉献给国防事业的老兵，在今天应该有资格拥有这份属于军人的光荣与神圣……\n感谢浙江诸暨的许绍周、楼友光及刘景林、宋永高等战友发起了战友聚会，2016年在南京遗憾未能参加，2017年在商丘，2018年在泰州，2019年在诸暨，2020年预约好在江西的赣州因疫情取消，几次战友聚会一次比一次搞得好，主题突出内容丰富，尤其2019年的诸暨聚会，让我见到了四十多年未曾谋面又一直想念的指导员裘培松、老班长张德仁……诸多176团特务连的老战友。每届聚会我都以《扬州慢》词牌填一首\"战友情深\"以表记念。（作品另见其他拙作）\n有人曾问我，你人生最难忘的经历是什么？我会毫不犹豫地回答：当兵！军队这个大学校教会了我忠诚勇敢，吃苦耐劳，奉献牺牲；军队这个大学校教会了我守纪遵命，团结同志，拒耻争荣。\n青春的渐逝，伴随着的是精神的升华，体魄的磨炼，铸就了意志的坚定。面对批评的烦恼和表扬的喜悦，练就了宠辱不惊的成熟和冷静。虽远离了父母的舔犊之情，告别了兄弟姊妹的依依留恋，却收获了来自五湖四海、能同甘共苦的战友深情。\n至今，我不羡慕土豪，不追捧明星，只赞美勇士、只崇拜英雄。是千万烈士的血肉之躯，铺就了从南昌到北京的路程；是现代军人的赤胆忠心，时刻听从党召唤，处置急难险；是三军将士不辱使命，守护着祖国的太平和安宁……我曾经也作出了一丝丝贡献。\n我后悔过很多事，唯独不后悔当兵；也淡忘了很多事，唯独难忘战友深情；如果能重新选择，如果能重返年轻，我仍会投身军营，为国从戎，为民当兵。\n军人的品格伴随了我一生，忠于职守、严于律己，团结同志、服从命令，是我一生坚守的准则，如影随形至今挥之不去。军人的荣誉感激励我一生，保家卫国、男儿当先，争当先锋、无私奉献，不给军人脸上抹黑是我一辈子做人的原则。军人的价值观影响我一生，一不怕苦、二不怕死，吃苦耐劳、勇于牺牲的精神是支撑我一辈子克服任何困难的力量源泉。\n因为我曾经是一个兵，军人的本色在我心中烙下了深深的印记，任何时候都不会忘记。谨以此絮语献给老首长、老战友共度八一建军节。"},{"id":148,"title":"冬游三亚","category":"散文","date":"二零一三年元旦前夕","body":"海南三亚是每个人都向往的美丽地方，尤其是北方人在严寒料峭的冬天，能像候鸟一样从一个寒冷的世界飞到另一个温暖的世界去越冬，那是再惬意不过的事情了。\n第一次去三亚是2001年4月中旬，出席国家工商局主管的中国工商报社在三亚银苑度假村召开的《中国工商报全国记者通联工作会议》，会上，我既代表了单位也代表个人领了奖。十年后的2011年11月，嘉峪关市浙江商会张岳云会长邀约了五个家庭共十人去三亚旅游度假，我和老伴也在其列。28日晚乘火车29日早晨到兰州，省局霍民主任安排接站又安排了最丰盛的\"兰州牛肉拉面\"早餐后送机场，约十点半左右起飞，经停贵州的龙洞堡国际机场稍作休息，下午两点半左右到达三亚凤凰机场，落地后由预定的宾馆派车接机。机场离市区很近，只有11公里的路程，宾馆是家庭式的，家具也是按家庭生活方式配置的，这样的宾馆大都是由外地人购置的一室、一厨、一卫约40平方左右的小型住房，离海边也很近，不足一公里，委托给小区物业经营。大约四点左右各家入住完毕，也未作休息，旅友们就急不可耐、兴致勃勃到海边兜风看海。\n\"三亚\"，由三亚东西二河汇合成\"丫\"形而得名。古称\"崖州\"，早在西汉元封元年（公元前110年）就收入中国版图，秦始皇时置南方三郡，\"崖州\"就是其中之一，隋设\"临振郡\"，唐改为\"振州\"，明又改为\"崖州\"。\n三亚在海南岛的最南端，位于北纬18°09′34″至18°37′27″，东经108°56′30″至109°48′28″之间，属热带海洋性季风气候，年平均温度25.4°，七月平均最高温度28.3°、一月平均最低温度20.7°、平均年降水量1763毫米。\n三亚有大小港湾19个，陆地面积1929.58平方公里，海域面积6000平方公里，海岸线209公里。海洋资源丰富，有鱼类1064种、虾类350种、蟹类325种、软体动物700余种，鲨鱼翅、海参、石斑鱼过去被称为\"崖州三珍\"。\n三亚市有人口68.5万人，下辖两个管理区、六个镇和五个国营农场，城市建成区面积45平方公里，是一个黎、苗、回、汉多民族聚居地。2010年城镇居民可支配收入为17758元，农民人均纯收入为6520元。\n三亚市的物产以水果和水产为主，经济支柱是海南建省后发展起来的旅游业。三亚有\"三亚湾\"\"亚龙湾\"\"大小洞天\"\"西岛\"\"鹿回头\"\"槟榔谷\"等主要景点。两天多时间基本看完。\n三亚湾蜿蜒在城市的西侧，有\"东方夏威夷\"之美称，每日下午有渔民赶海\"拉网\"表演，若有兴趣也可搭一把手体验渔家生活，这是在其他景点看不到的。\n\"亚龙湾\"距市东南约25公里左右，是海南最南端的一个海湾，可谓是真正的\"天涯海角\"。湾如虹，呈半月型全长7.5至8公里，浅海区宽50至60米；水如玉，澄澈晶莹、蔚蓝无比，能见深度10米左右，水温常年保持在22°至25°之间，终年都可游泳；沙如肤，洁白无瑕、细腻温润，是进行日光浴和沙浴的极好场所。\n\"大小洞天\"古称鳌山，至今已有800多年的历史，位于市区以西40公里的海滨，总面积22.5平方公里。崖州湾弧弦百里，碧波万顷；鳌山峰云深林翠，岩奇洞幽；这里海景、山景、石景交辉相映，美不胜收，不愧为有\"崖州第一山水览胜\"之称。\n\"西岛\"是三亚的第二大岛，像飘浮在海面上的一只大玳瑁，与东岛遥相呼应，所以又名西瑁岛，距三亚湾以西8公里，全岛面积2.8平方公里，至今岛上仍生活着3000多世代以打鱼为生的居民。登西岛要搭乘快艇，单程需20分钟左右，上岛后主要游览项目有钓鱼、定点跳伞、潜泳等。潜泳必须经过简单的培训后，穿上潜水服由潜水员陪同下潜7至10米观看海底多彩多姿的珊瑚礁和色彩斑斓的多种鱼类，时间约10分钟左右，票价300元。我因2001年参与过此活动，已经体验过这次就免了，值得惋惜的是其他旅友受我的影响都未下水，好不容易来一次该体验的还得体验，再来的机会总是不多的。\n\"鹿回头\"位于市区南部3公里的海边小山上，这里三面临海、四季山青，主峰海拔275.1米，站在山上可俯瞰浩瀚的大海、远眺起伏的山峦、三亚市全景尽收眼底，景色颇为壮观。\n\"槟榔谷\"位于三亚甘什岭自然保护区内，两边森林茂密，中间是一条连绵数公里的槟榔谷地，\"槟榔谷\"也因此而得名。椰子代表海南、槟榔代表黎家，在黎家没有槟榔不成礼，没有槟榔不成婚，所以槟榔也就成了黎家的文化符号。本土民族的最大特征是\"雕题离耳\"，\"雕题\"就是纹脸，在脸上刻上图案。\"离耳\"就是在耳朵上佩带大耳环。这样打扮的人在槟榔谷虽然随处可见，但年轻人却很少有这样打扮的了。陪同我们的一位女导游是地道的黎族人，穿着打扮已经很现代化了。在槟榔谷我们参观了民俗博物馆，了解了黎家生产生活、民风民俗的简况，黎家织锦可称一绝，还观看了原汁原味民族风情的大型实景表演，感觉到槟榔谷才是最纯正的黎家活体博物馆。\n我在三亚玩了两天多时间，还没有完全尽兴，因侄儿程诚12月3日要在苏州完婚，必须赶回去庆贺，只好于12月1日提前离开三亚，先飞广州再转机飞无锡女儿处。\n在三亚的几天里给我的印象是与2001年相比各景点的基础设施建设有了发展，硬环境得到了改善。冬天是三亚的旅游旺季，各处景点都是游人如织，应该是顺应潮流抓时机，扬帆乘风而上时。遵照中央把海南打造成国际旅游岛的机遇加大宣传、加强管理、加快发展，但让人感到三亚旅游市场的管理确实比较混乱很不尽人意，同一景点的门票价格不规范不统一，无证导游到处都有、交通餐饮宰客现象十分严重，十分普遍，这次被游客举报、央视曝光后而取缔的\"富林海鲜村\"我们也曾深受其害，海南要成为真正意义上的\"国际旅游岛\"鄙人认为还任重道远。\n这次旅游时间虽短，但从内心感到还是比较温暖的，旅友们互相照顾、一切都平等相待，确实更有利于我体验适应退休后的生活。感谢安排这次活动的张会长，感谢参加这次活动的全体旅友。"},{"id":149,"title":"做人要厚道","category":"散文","date":"二零一零年元旦","body":"中国历史上，凡是显世扬名、彪炳史册的英雄豪杰、仁人志士无不能忍。人生在世，生与死较、权与利害，福与祸衡，喜与怒称，小之一身、大之天下国家，都离不开\"忍\"，成大业要忍、谋生活要忍、保平安要忍，解困境更要忍。正因为有了忍，才有了西伯拘而演《周易》；仲尼厄而作《春秋》；屈原放逐，乃赋《离骚》；左丘失明，厥有《国语》；孙子髌脚，《兵法》修列；不韦迁蜀，世传《吕览》。\n\"世事洞明皆学问、人情练达即文章。\"一个人一辈子要真正明白这个道理，并以此作为座右铭不断加强自身修养，尤其在\"慎独\"的处境下坚持修养自己的精神境界，更不是一件简单的事。虽说当今人人都处在市场经济条件下，处在一个物欲横流、人心浮躁的社会里，但被金钱物质撕破精神、充斥皮囊的人毕竟还是少数。受几千年中华传统美德的影响，\"众人重利、廉士重名、贤士尚志、圣人贵精。\"（庄子·刻意）注重道德修养的仁人君子不乏其人，\"君子和而不流\"（礼记·中庸）\"仁义之道、守之而不失，俭约之志、终始而不渝。\"（贞观政要·慎终）守正节操的社会贤达大有人在。\"芝兰生于森林，不以无人而不芳，君子修道立德，不为穷困而改节。\"吾自以为也是一位崇尚传统道德品行的\"人\"。\n俗话说：三十而立、四十不惑、五十知天命、六十知进退。庚寅年是我的本命年，一晃而过人生已走过六十个年头，卸任退休怡养天年可望在即。六十年的生涯中上过学、务过农、做过工、经过商、从过军、当过干，一生既无轰轰烈烈、也无大的跌宕，坎坷虽有平凡之致，但回首往事历历在目。六十年的平凡人生中有二十年担当过县处级领导、且有十五年时间是一个单位的\"一把手\"，前年组织上还将我提拔为副地级干部，这样的机遇为我创造了\"在上不骄、在下不谄。\"（宋·上龚舍人书）修炼实践的良好条件，也为我提供了接触他人并向他人学习和自我体悟待人处世之道的更多机会。\n\"待人处世\"，对于每个人来说都是一生中的必修课，它是一门既浅显易懂又深奥莫测的社会科学，更是各级领导干部必备的领导艺术。\"待人要厚道\"是待人处世的主要内容，我理解其内涵意境深重，至少要做到以下几点。\n一是待人要多一份宽容。宽容是一个人胸怀和度量的体现，宽容不仅是一种豁达与大度，更是一种待人处世的艺术与美德。日常生活中每个人都不免会遇到一些不顺心的人和事，但要有\"宰相肚里能撑船、将军额上能跑马。\"\"君子贤而能容罢（读Pi）、知（通智）而能容愚、博而能容浅、粹而能容杂\"（荀子·非相）的气度，凡事只要掌握原则、抓住重点即可，决不能把自己搞到\"小鸡肚肠\"\"斤斤计较\"一族中去。\n唐太宗说：\"人欲自照，必须明镜；主欲知过，必借忠臣。\"（贞观政要·求谏）要学唐太宗\"纳谏\"的气量。\"良药苦口、忠言逆耳。\"要容得下别人的各种意见，尤其是对与自己意见相左的同志，不要动辄求全责备、耿耿于怀，不要用简单粗暴的方法剥夺别人的话语权逼迫与你认同，更不要看不顺眼给\"小鞋\"穿。否则，只能是适得其反、口服心不服、甚至把事情越搞越糟。我们可以另换一个思路，从细微处入手以情感人，搭建一个让他尽情展现自我价值的平台，这样才能创造出更多和睦相处的氛围，才有利于团结共事。\n在现实生活中要切记\"君子和而不同、小人同而不和\"的古训，要防止巧言令色、阿谀奉承的小人，要注意悉心倾听别人的批评意见和建议呼声，更要认真分析筛选采纳。\"天时、地利、人和\"是助推事业成功的三大要素，把握\"人和\"就要学会待人处世之道。\n男子汉大丈夫还要有\"海纳百川\"的气概。毛泽东同志曾教导我们说：我们要善于学会团结同志，不但要学会团结和自己意见相同的同志，而且更要学会与自己意见不同且被实践证明犯了错误的同志。对这样的同志一定要不计前嫌、不揭伤疤、不算旧账，要容人之短、目光向前、用其所长。\n现实生活中如果我们每个人都能把禅学中弥勒佛\"开口便笑、笑天下可笑之人；大肚能容、容天下难容之事。\"的博大胸怀运用得当，你就会体悟到对别人多一份宽容，就会给自己多一份超脱的幸福感。\n二是待人要多一份理解。理解是沟通的桥梁，就是要充分理解相信他人。在遇到问题时要尽量站在对方的立场换位思考，要为别人设身处地的多着想，这样才能加深了解、加强互信，给别人多一份理解和信任，就是给自己增加一份自信和信心。作为一个单位的领导要学会关心爱护你的同志和下属（绝不是不讲原则的庇护和怂恿），要把自己和家人的利益看低一些、把单位和他人的利益看高一些，在工作和生活中要主动承担责任，决不能揽功诿过、有了成绩是自己的、有了过错是别人的，这样很容易失去与你共事奋斗的同志和朋友。\"一个篱笆三根桩、一个好汉三个帮\"，没有团队协作、孤军作战肯定是成不了什么大事业的。没有互相帮助和支持、没有互相关心和爱护、没有互相理解和信任，就会没有朋友和事业。\n三是待人要多一份忍让。忍让是一种美德和风范。古人所总结的\"温良恭谦让\"是一部富有积极意义、读不完的待人处世哲学。学会忍让也就是做人要学会淡泊一点、磊落一点，在纷繁复杂的社会中，不为灯红酒绿所迷、不为纸醉金迷所惑，更重要的是要把周围的人和事都要看得高于自己，对自己淡出一种不失君子风范的境界和升华。在现实生活中处理人际关系时，无论是社会交友、同事共处、家庭琐事等方面的一些非原则问题上都可以随一随、听一听、甚至低低头、让让步、睁一只眼闭一只眼的过去，根本没有必要针尖对麦芒的去较真、非分出谁对谁错、争过你高我低。古人说：退一步海阔天空。历史上\"六尺巷\"和廉颇蔺相如\"将相和\"的故事可谓是忍让的典范，是非曲直最好由他人去评说。\n\"吃亏是福\"，\"吃亏\"是忍让的行动，是它从另一个角度告诉我们忍让的道理。殊不知现实生活中如果多一份忍让，就会少去许多枝节、省却诸多麻烦。较真是愚蠢，冲动是魔鬼。只有忍让才能带来互相尊重、带来友谊与和谐。\n四是待人要多一份诚信。诚信历来被作为立国做人的基本准则。\"信，国之宝也、民之所凭也。\"（东周列国志）\"诚信者，天下之结也。\"（管子·枢言）都是先哲崇尚诚信的格言。中外历史上重\"诚\"守\"信\"的故事佳话也很多。《商鞅变法》故事中的主人翁商鞅就是一个一诺千金很讲诚信的人，有宋代改革家王安石追崇、称赞商鞅重守诚信的诗作为证：\"自古驱民在信诚、一言为重百金轻。今人未可非商鞅，商鞅能令政必行。\"\n外国有这样一段讲诚信的佳话，其故事梗概：有夫妻两人，自幼青梅竹马、后结为夫妻结婚生子功成名就、感情甚笃。二十年后一双子女相继成人且事业有成、一家四口幸福美满、其乐融融。一日丈夫发现妻子有一只密码箱从未打开，不经意间问妻子所藏何物？妻子说这是我与一位朋友的秘密不能告诉你，丈夫说我俩感情如此深厚你还有什么秘密对我所保呢？妻子再三解释决无个人感情隐私但箱子也决不能打开，丈夫更疑心妻子有外遇最后失去理智将妻子掐死，当他砸开箱子第一眼看到的是他妻子的一位女友写给妻子的一封信：\"亲爱的好友简：只有你答应我这些信件不给任何人看、包括你的丈夫、我才让你保管……\"丈夫看后后悔莫及，这虽然是杜撰的一个故事但后来却编成了一部小说书名《看不见的创伤》教育人们既要诚守诺言又要相互理解。\n讲\"诚信\"是人之所以为\"人\"的基本条件之一，对亲人朋友只有敞开胸怀、以诚相待，才能息息相通、心心相印、获得他人的信赖。古人崇尚\"仁、义、礼、智、信\"的道理即在于此。尔虞我诈只是阴谋家见不得阳光的雕虫小技，可能会一时奏效，终不能成大事、成大业。\n五是待人要多一份热心。热心助人、不图回报、以此为乐，是一种比较高的精神境界，也是体现一个人自身素养高低的分水岭。怜悯之心应该是人的本性。一个人能主动地\"舍得\"倾其所有、用其所能去帮助需要帮助的人，德莫大焉；一个人有从精神和物质方面去帮助别人的能力而不去帮助别人可谓之\"吝啬\"；如果一个人只图向社会向他人索取而不愿为社会为他人付出可谓之\"贪婪\"。在这方面我们决不能做一个\"吝啬\"和\"贪婪\"的人。\"我为人人、人人为我\"，是和谐社会的价值取向，虽然我们光明磊落，\"舍得\"付出、不图回报，（在其他文章中已对\"舍得\"的意义阐述了我的认识）但你不得不相信\"善有善报、恶有恶报，如若不报、时间未到\"的因果报应，肯于助人的热心肠人肯定会有好的报应。好人终会一生平安。\n我要将\"做人要厚道\"的这几点体会当作人生的座右铭，\"勿以善小而不为\"，而应该严格从自己身边的点滴小事做起。不积跬步无以行万里，只要我们坚持加强道德修养，就会成为一个品行高尚的人，你的朋友就会越来越多，事业就会愈来愈兴旺；你的心地就会越来越坦荡，人生就会愈来愈快乐。我愿坚守\"做人要厚道\"，从这一体现人格魅力的重要方面去修炼一生。"},{"id":150,"title":"待人处世要义之三（礼节和礼貌）","category":"散文","date":"二零一零年三月底完稿于兰州","body":"人是感情动物，说到、看到、听到、做到动情之处，本人或他人都必会为之感动。人情，实之人的感情，人的弱点就是具有感情，同时也是人的骄傲，因为人是具有睿智的，所以我们在待人处世时要以己之情察他人之情，用己之心度他人之心，则他人则体你之情、量你之心，达成共识、互谅互敬。注重礼节礼貌是最好的感情交流方式。\n中华民族是具有几千年历史文化的礼仪之邦，重视礼节和礼貌也是儒家\"修身、齐家、治国、平天下\"思想的精髓。\n两千多年前孔子在《论语·学而》篇中讲\"礼之用、和为贵。\"《荀子·大略》篇中讲\"礼以顺人心为本。\"《管子·形势解》篇中也说\"进退无仪，则政令不行。衣冠不正，则宾客不肃。\"古代思想家的言论都道破了礼节和礼貌的社会作用。\n礼节和礼貌对每个人来说同样具有十分重要的作用。《论语·季氏》篇中讲\"不学礼，无以立。\"《晏子春秋·内篇谏上二》篇中讲\"凡人之所以贵于禽兽者，以有礼也。\"同时《左传·襄公四年》篇中还告诫人们\"多行无礼，必自及也。\"至今，礼节和礼貌在指导人们社会生活中仍具有十分重要的现实意义。\n古人男子二十而冠，女子十五而笄，都是一种成人礼，也就是说举行成人礼后不仅表示身体已成人，更主要的是精神上已懂得做人的道理可以成家立业了。此时无论男女、无论识不识字都知道顺从天理人情，为人处世要讲三纲五常、注重礼义廉耻，所以男子二十女子十五就必须具有\"大人\"的风格和智慧，在这个时期基本形成了人一生的人生观、价值观、道德观，随着言传身教、身体力行、耳濡目染中国文明及其传统的道德观就这样单纯而广泛地传承下来，几千年来成为人们必须遵循的统一规范的生活方式。\n礼仪既是社会约定俗成的行为规范，也是每个人的行为准则。礼仪是礼节和礼貌一种外在形象具体形式的表达，是社会学系中关于人际关系的学问。现实生活中每个人都必须以\"礼\"规定的准则来处理个人与家庭、个人与个人、个人与社会之间的关系，这样社会才有可能和谐有序。\n\"礼\"的精神实质还在于每个人都务必遵循这种准则和形式并努力去践行。\n社会规范既包括法律规范也包括道德规范和礼节礼貌的规范。虽然它们都是调节人们之间行为关系的规范，但法律却是外在的强制性的约束。道德完全是内在的责任感的自律。礼节和礼貌正好处于两者之间，是通过感化人的灵魂、用人们的自尊心、羞耻感来克服自身的丑陋、欠缺、窘迫等等不足，从而达到约束自己言论行为目的的。\n礼节和礼貌是维系一个社会人与人之间协调和谐不可或缺的重要方面，它之所以被人们认同成为普遍的行为规范，是因为它源于人类的精神需求，反映着人们共同的审美情趣和欣赏习惯，是人们纯正心地、美好情感、坚定信念的自然表露和精神生活组成中不可缺少的部分。只有心灵美，才会有行为美。\n礼节和礼貌一旦被社会所尊崇、所认同，就会被人们所遵从、去实施。就会在构建和美的人际关系、和谐的社会关系中发挥无影无形、无比巨大的作用。\n讲究礼节和礼貌的重要原则一是\"尊重\"，二是\"自律\"。讲究礼节和礼貌就是要求每个人说话做事都要从对方的角度去考虑问题，都要以不损害他人利益为前提。俗话所说的\"入乡随俗\"大概就是这种意思。\n\"尊重\"就是既要尊重他人也包括尊重自己，\"礼\"的核心内容是尊卑确立、师长有序，下级对上级、晚辈对长辈、主人对客人、下位对上位都要有发自内心的恭而敬之。反之，上级对下级要礼贤下士、长辈对晚辈要关怀爱护、客人对主人要客随主便，上位对下位要主动把对方放在一个比自己更重要的位置。孔子说过\"己所不欲，勿施于人\"，只有首先尊重别人的同时才会获得别人的友好与尊重。因此，互相尊重是人际交往中的一个重要原则。\"来而不往非礼也\"，这可能就是对相互注重礼节礼貌最好的诠释。\n\"自律\"把注重礼节和礼貌这种外在美提升到了一个新的高度，它要求每个人在自己心中树立起一种内在的道德信念和行为准则来规范自己，并以\"一日三省\"这样的检讨机制来对照自己，无需外界和他人的监督。我欣然将笔名题为\"三省轩主\"就是表示加强自身道德修养的主观意图，并随时在努力付诸实践。\n礼节和礼貌是一种最直观的行为规范，它从一个人与人交往过程中的言行举止、仪态仪表、饮食起居、衣着打扮、待人接物等生活姿态，举手投足的各个细微之处的表现，就可以被对方捕捉到一个人的修养水平、气质风度、人格魅力大小的初始信息，体察到一个人的性格情操、思想品德、文化层次高低的综合印象，并可作为初步判断能否与之继续深入交往的依据。\n注重礼节礼貌是安身立命、待人处世、与人交往的必备的生活工具，无论是个人、家庭、单位、国家都很重要，有句俗语说得好：\"一句话可以暖人心，一句话也可以伤人心。\"个中就可以看到其重要性的所在。现实生活中不乏有诸多从注重礼节礼貌交往中获得别人帮助，得到家庭、事业成功的例子，也有因礼失当带来的深刻教训。所以，注重礼节和礼貌在人的一生中绝非是无关紧要的生活细节而是有关人生家庭、事业的大事。\n良好的礼节和礼貌是完美人格心理的表现，也是自古以来仁人君子修身养性之道，礼节和礼貌是可以通过教化、学习、模仿、示范等实践的过程不断提高的。历史上\"孟母三迁\"的故事是说\"近朱者赤、近墨者黑\"的道理。因此，我们要随时随地注意向懂得礼节礼貌、品德高尚的人学习，通过学习不断提高待人接物的技巧、培养客观成熟的心态、调适自我约束的能力，不断克服自身存在的缺点与不足，潜移默化地净化自己的心灵、陶冶自己的情操，更好地认知并检控个人与家庭、个人与他人、个人与社会相融洽的能力。\n中华民族历经历史上多次民族大融合和东西方文化大交流，形成了它特有的历史文化积淀，注重礼节和礼貌的优良传统至今仍在熠熠生光，但也存在一些封建礼教已不适应社会发展的需要，像《论语·颜渊》中所载孔子句：\"非礼勿视、非礼勿听、非礼勿言、非礼勿动。\"其中有积极意义的一面，同时也存在消极意义的一面，我们就要加以科学的批判吸收，取其精华、去其糟粕。尤其在如今开放的信息时代与国际交往甚多，我们也要学习熟悉他国的礼节礼貌，取人之长、补己之短。真正做到古为今用、洋为中用，将传承、发扬、光大优良传统作为自己的历史责任，从我做起正确处理好各方面的关系。为构建和美的人际关系、和谐的社会关系而努力。"},{"id":151,"title":"待人处世要义之二（中庸）","category":"散文","date":"二零一零年春节前夕","body":"人类要在二十一世纪生存下去必须要从两千五百年前孔夫子那里去寻找智慧。\n\"仁爱\"是孔子思想体系的核心，\"中庸\"之道是孔子治国安邦的基本方略，在博大精深的中国文化精髓里，\"中庸\"是一个很重要的组成部分，作为一种认识论和方法论它已经渗透到了与所有中国文化相关的基本元素之中，渗透到了中华民族的血脉里、骨子里，成为构成传统文化和社会普遍心理的要素之一。每个有着中国血统的社会成员，不管你置身于何时、何地，不管你愿意不愿意，你总摆脱不了那种与生俱来的\"中庸\"思维定势和历史印记。所以，在东西方文化广泛交融的今天，有意识地去探讨认识\"中庸\"之道的深刻内涵并加以运用，不仅是一种高尚情操和智慧之举，而且也是在默默履行传承中华民族优秀文化的责任。\n\"中庸\"思想起源很早，《尚书》中就已经记载了很多古代圣君执\"中\"、行\"中\"的例子。如《盘庚篇》中的\"各设'中'于乃心\"、《吕刑》\"罔非在'中'\"、《酒诰》中的\"作稽'中'德\"等。在《尚书·大禹谟》中，有被宋儒称作\"十六字心传\"的著名箴言：\"人心惟危、道心惟微、惟精惟一、允执厥中。\"《尚书·洪范》记载，周武王向殷朝的遗臣箕子请教国事，箕子提出九条大法，其中就有\"中\"道的思想：\"无偏无颇、无偏无党、王道荡荡。\"因此，我们完全可以把《尚书》中强调\"执中\"的政治智慧看作是中庸之道的源头之水。\n\"中庸\"一词，语出《论语·雍也》。孔子说：\"中庸之为德也，其至矣乎！民鲜久矣。\"意思是说，中庸乃至其最高尚的道德境界，已好长时间没有人去注意这方面的修养，现在更是很少有人能做得到了。孔子推崇的\"中庸\"其意义是什么？其境界到底有多高呢？\n孔子裔孙述圣孔伋（即子思）他把\"中庸\"看成万物本然之性，把\"和\"看成万物运动的基本法则。他曾说：\"中也者，天下之大本也；和也者，天下之达道也。致中和，天地位焉，万物育焉。\"提出：\"诚者不勉而中，不思而得、从容中道，圣人也。\"他把\"诚\"看成是维持世界和谐、平衡矛盾的本体。提出\"博学之、审问之、慎思之、明辨之、笃行之\"的学习过程和认识方法。他还把孔子\"内省\"的修身方法发展为\"慎独\"，这些都是对孔子\"中庸之为德也，其至矣乎！民鲜久矣。\"思想的继承与发展。\n宋朝理学家朱熹也用同时代的理学家程颐的话解释说：\"不偏谓之'中'、不倚谓之'庸'。\"\"中\"者天下之正道，\"庸\"者天下之定理。\"中庸者，不偏不倚，无过不及，而平常之理，乃天命所当然，精微之极致也。\"这样\"中庸\"一词的含义就是：\"中\"是一种凡事都追求\"不偏不倚、无过不及\"最恰当的一种状态。\"庸\"则是说这是一种不变的常理。朱熹认为《中庸》\"忧深言切，虑远说详。\"\"历先前圣之术，所以提挈纲维，开示缊奥，未有若是之明且尽者也。\"他在《中庸章句》开头引程颐语称《中庸》是\"孔门传授心法\"的著作。\"放之则弥六合、卷之则藏之密\"。\n汉代郑玄给\"中庸\"的另一种解释是：\"中庸者，以其记中和之为用也；'庸'，用也。\"意思是说：\"中庸\"就是\"中\"道之运用。对\"中庸\"的两种注释从其意义上说基本上是一致的，只是在\"庸\"的注释上略有偏差，一种认为是不变的道理、一种认为就是运用，许慎的《说文解字》\"'中'，内也，上下通也\"、\"'庸'用也\"。我认为这几种解释都不影响其根本的宗旨。生活实践告诉我们\"中庸\"之道确是有用之学，爱研读中国政治史和思想史的人读后一定会感到其韵味无穷，如果把握运用得当更会终身受益。否则，它也不会成为两千多年来封建社会钦定的教科书、成为封建士大夫的晋身之阶、成为社会倡导普及的行为准则和道德规范。凡崇尚\"古为今用、洋为中用\"者我认为都会同意我的这一观念。\n\"中庸\"之道应该说是一种标准极高且较难实现的理想目标，这也可通过孔子的言论来佐证，孔子在《论语·里仁》说\"无适（di）也，无莫也、义与之比。\"在《论语·先进》里说：\"过犹不及\"，其意思是说凡事都要尽可能追求最为恰当合理的解决，不能过头、也不能不及。比如我们日常生活中对\"勇敢\"的理解和把握、只有恰如其份的\"勇敢\"才符合它原本概念的意义，如果过之就成为\"鲁莽\"、如果不及就成为\"懦弱\"。清郑板桥有句名言\"由糊涂到聪明难、由聪明到糊涂更难。\"他就两难相比取其中\"难得糊涂\"。记得《红楼梦》中有这样一句话：\"机关算尽、反伤了卿卿性命。\"这就是没有用\"中庸之道\"去认识处理问题因而得到的结果必然是物极必反。俗言俚语中也总结了这样一句至理名言：\"聪明反被聪明误\"，现实生活中的笵例真是太多了。\"中庸之道\"本来是一种道德修养的境界，属于认识论的笵畴，但是儒家学说又把它普及化、当作一种方法论，要求人们面对现实社会的普遍矛盾、要用它来制定求最优解的方案。现实生活中一般来说如果对某一件事去追求最好的解决方案还有可能实现，对每一件事都要做到最好就比较难了。但是，心理上的期望值总是想用最优方案把事情做到最好。借用一句广告词\"没有最好、只有更好\"。我们一定要用心去领会这句话的含意，再通过不懈的努力实践，能达到这样的目标就是满意的结果。\n行\"中庸之道\"既然这样难，如何才能正确选取和运用呢？把握\"中庸\"之道既不可完全靠别人言传身教、也不可完全凭自己心领神会；既不可当作可望而不可即、纯粹渺芒无边的事，但也不可当作不加内心世界精心修养、就能垂手可得。孔子在《论语.子罕》里说道：\"吾有知乎哉？无知也。有鄙夫问于我，空空如也，我叩其两端而竭焉。\"在《中庸.第六章》里说：\"...执其两端，而用其\"中\"于民\"。就是说要从事情的两极端入手去把握。我们再以\"聪明\"一词作为一个例子去分析，聪明过分的\"聪明\"让人感到的就是\"狡猾\"，自作聪明的\"聪明\"让人感到的就是\"愚蠢\"，如何去把握\"真聪明\"和\"假聪明\"呢？我们可用\"中庸之道\"去认真推敲研究、仔细揣摸体会、不断感悟生活，最终才能心领神会得其要领将\"聪明\"应用自如。特别要提到的是我认为\"中庸\"之道的思维方式与哲学中的\"折衷主义\"完全是两码事、不可同日而语，它不是简单的折去两端而取其\"中\"。实际上\"中庸\"之道与现代科学中的模糊学和哲学中的\"度\"的概念及要求有好多相似之处，它也更接近于现代逻辑学中的试错法。\n把握和运用\"中庸之道\"在我们现实生活中的意义深远，大到国家与国家之间外交关系谈判、中到企业与企业之间经济合同签订、小到个人与个人之间社会交往处世，只要具有\"相互之间的关系\"、其利益得失均可运用\"中庸之道\"去权其轻重，取利避害。\n倡导\"中庸之道\"绝不是因国人掀起国学热的浪潮把我推成一名随波逐流者，也绝不是想把自己装扮成一名学者来夸夸其谈哗众取宠。其实，人就是人谁也不是神仙更区别于其它动物，要走\"中庸\"这条人之\"大道\"，斯大道宽兮。这仅是我在一生中悟出的一点浅见薄识，写出来想与大家共同分享待人处世的乐趣。在国人（尤其是年轻人）一味追崇西方文化的现实中不得不忋人忧天，我深感几千年中华文明史积淀的优秀文化不应该在我们这一代人面前灭失，将优秀的文化发扬、光大、传承下去这才是我们应承担的历史责任。"},{"id":152,"title":"感悟人生","category":"散文","date":"丙戌深冬","body":"人生，是一条难趟的河，人生，是一个难解的结，人生，更是一团理不清的麻。一个人的生命轨迹在历史长河中十分短暂又十分渺小，尤如浩瀚大海中的一朵浪花、苍茫宇宙中的一粒尘埃。\n因为生命短暂、世事纷繁，有人则认为要及时行乐，要么沉湎于醉生梦死之中、要么浑浑噩噩空度时日，这样的人蹉跎岁月、虚度年华，对家庭、对社会毫无责任感、一生如行尸肉，为世人所不齿、被社会所唾弃。\n有的人却让生命迸发出火花，为他人、为社会贡献出光和热，前苏联作家尼古拉.奥特洛夫斯基的名著《钢铁是怎样炼成的》书中的主人翁保尔.柯察金在回首人生时说：\"人最宝贵的是生命，生命每个人只有一次。人的一生应该这样度过，回首往事，他不会因为虚度年华而悔恨，也不因碌碌无为而羞愧，临终之际，他能够说：'我的整个生命和全部精力都献给了世界上最壮丽的事业------为解放全人类而斗争'\"。这样的人生才是轰轰烈烈、灿烂辉煌的、也只有这样的人生才最受人敬佩。当然，这样的英雄人生、在芸芸众生中也是不多的。\n世人的大部份生命轨迹都是在\"平平凡凡、平平淡淡、平平安安\"的日子里度过的，但是平凡决不等于庸俗糜烂、平淡决不等于碌碌无为、平安决不等于绝无风险。一生只要用心努力、奋力拼博、即使不成功，也会留下悲壮，不必要诚恐诚惶，逆境是磨练、也是财富、扶起自尊、挺直腰杆子就是一个大写的人。\n人的一生、一帆风顺仅是一个美好的愿望，一生都在顺境中度过的人肯定不多。人，来到这个充满矛盾的世界上、逢\"劫\"遇\"难\"，应该是很平常的事。所以，人的一生、命乖运舛、如果没有大起大落、跌宕起伏，总免不了会碰到一些坎坎坷坷，人生苦旅就是这个理儿。人的一生、从呱呱坠地的婴儿开始、要历经童年、少年、青年、壮年、中年直至饱经风霜的老年，就像度过自然界的春、夏、秋、冬，你会体会到春的生机盎然、夏的热情奔放、秋的丰收喜悦、冬的寒意凄零。人的生命轨迹中有高峰、有低潮、最终谁也逃不过\"生、老、病、死\"这个劫、这才是最平等的机遇、最公平的结局，永不变的规律。所以每个人都要正确的直面人生，享受生活、珍惜生命。\n春天是美好的季节、充满生机活力。人生的\"春季\"，就像早晨八九点钟的太阳、童趣横生、无忧无虑，春天又是播种的季节，俗语说：\"一日之计于晨、一年之计在于春\"，千万别错过播种\"希望\"、\"种豆得豆、种瓜得瓜\"，只要诚实、勤劳，一份耕耘就会有一份收获，所以要十分珍惜人生的春天。别让\"蹉跎歌\"与自己相伴，以致遗憾终身。\n夏天是火热的季节，散发奔放热情，人生的\"夏季\"，就像熔炉前的钢花飞溅、踌躇满志、追求进步、积累知识、勇于实践、阅历社会、丰富自己。\"宝剑锋自磨砺出、梅花香自苦寒来\"。历尽坎坷，有时甚至于至死地而后生，在错综复杂的人世间肯定会有你的一席之地，在社会大舞台的历史剧中肯定会有你的角色，让你尽情演绎你的人生。\n秋天是收获的季节，可以采金撷银，人生的\"秋季\"，经过春的萌发、夏的耕耘、春华秋实、如日中天、年入不惑，面对现实、心绪会更加平实稳重，打量自己、审枧四周、对自己巳拥有的一切应该明白来之不易、好自待之，更应该心地坦荡、倍加珍惜、知足常乐。不切实际、好高骛远、嫉贤妒能、万不可取。\n冬天是银色的季节，孕育春的萌动，没有冬季就没有周而复始、四季轮回，人生的\"冬季\"，老之将至，应该说悟透了人生真谛、深知为人之维艰。但无为者总叹\"昔阳无限好、只是近黄昏\"。常悲\"时光苦与短，黄泉路逼近\"。因此，暮气沉沉、伤神伤身，尚不知\"活到老、学到老\"的乐趣。有为者则不然、从容面对\"长江后浪推前浪\"，深知如果没有\"一代更比一代强\"。社会如何发展？历史怎能前进！虽知来日不多，决不坐以待毙，\"老骥伏枥、志在千里\"，情到与世无争、心想老有所为、有一份热、发一份光，经常寻找机会尽自己的绵薄之力帮助他人，报效国家、奉献社会。更有闲时悠然自得，心底吟诵\"满目青山夕照明，冬天过去是春天\"。\n\"春、夏、秋、冬\"让我们来感受四季、感受生活、感受生命，感悟人生。"},{"id":153,"title":"戈壁之光","category":"散文","date":"二零一五年元月","body":"-- 河  西  走  廊  段\n有人说，没有到过大西北就不知道中国有多么大。我可为这句话验证，确实如斯。有人说西部不如江南除了荒凉还是荒凉无景可观，我认为并不见得。因为我出生在南方，生活在大西北已有近四十年，南方和西部的风光应该各有千秋。\n出了兰州、一直往西翻过乌峭岭，就到了地理教科书上所讲的河西走廊。它介于南北两山中间，南山即祁连山和阿尔金山、海拔均在四千米以上，最高的团结峰高6305米，北山是合黎山、龙首山、马鬃山的合称、海拔比南山略低，呈西北--东南走向，东西长约一千二百公里左右，南北宽，窄处约十公里左右、宽处有近二百公里。它是古丝绸之路出入中亚、西亚、欧州的必经之路和唯一通道。\n进入河西走廊，放眼望去映入眼帘的是一望无际的茫茫戈壁和被戈壁滩裹挾的星星点点的绿洲。据传说几亿年前中国的西部也是一片汪洋泽国，随着地壳的运动、山脉的隆起、海底露出而成。经地质学家科学考证其真正的原因是经洪水冲击而成，呈现的地貌特征是由粗砂砾石复盖的硬土层。除河西走廊外在新疆、青海、宁夏、内蒙、西藏的东北部均有分布。\n江南风光中的小桥、流水、人家、青山绿水展现的是自然、精致、秀丽，尤如女人般的柔和之美。大戈壁滩上的原始、空旷、荒凉，一无遮拦袒露的是粗犷、率真、豪放，好像男人样的刚烈之美。不同的风光你可细细品味。\n河西走廊不仅仅是茫茫戈壁滩，自东向西还撒有武威、金昌、张掖、酒泉、嘉峪关五个地级市，及酒泉所辖世界闻名的敦煌市。河西走廊这片土地上向您展示的一定是：丝路长城文化交汇、古代现代文明相映、人文景观积淀厚重、自然生态美丽奇特。\n河西五市508万人口虽只占全省2557．5万人口的20％，但其27．75万平方公里的国土面积却占全省45．37万平方公里的60％以上，是江浙两省国土面积20．67万平方公里的1．35倍，人口是江浙两省人口总和13362．69万人的3．8％，仅酒泉市的国土面积19．2万平方公里基本就相当江浙两省国土面积之和，但人口只占0．82％。河西走廊孰大？孰小？\n这里的城市历史悠久、由于朝代的更替、时光的变迁、就有说不完的故事。公元前121年（元狩二年）汉武帝派霍去病进军河西当年秋天就打败了浑邪王、将匈奴残部赶出玉门关外，遂将河西走廊全部纳入西汉版图，设武威、张掖、酒泉、敦煌四郡，又从中原迁几万人来此定居、屯垦戍边。从此拉开了这里文明昌盛的大幕。\n武威曾称凉州，六朝时的后凉、南凉、北凉、唐初的大凉都建都于此。雷台汉墓出土的\"铜奔马\"是举国之珍已作\"全国优秀旅游城市\"之标志，\n在嘉峪关魏晋墓群中出土的墓砖画\"驿使图\"也是国之瑰宝，是我国当今的邮政标志。\n长城是中华民族的脊梁、是浩荡神州的象征。修筑长城可算是古人的智慧，圈地筑城可抵御外族侵袭，秦始皇灭六国统一中国后遂令将原各国之间的城墙拆掉，将边关之间的城墙修建相连，同时修驰道、便交通以御外敌。\"万里长城\"现己成为世界上最古老、体量最大的文化遗产。\n据国家文物局2012年向公众发布，通过科学测量我国历代修建的长城总长为21196．18公里。明长城再也不是教课书里所讲的\"东起山海关\"，而是辽宁\"丹东的虎山\"，明长城总长8851．8公里，其中人工筑成的墙体有6295．6公里，壕堑和天然形成有2592．2公里。长城除北京八达岭外、由于河西走廊段气候干燥保存得也相当完好、基本与高速公路平行，从高空望去由东而西像一条腾飞的苍龙曲折蜿蜒直奔嘉峪关，己有700多年历史的关城楼堞气势雄伟，\"天下第一雄关\"之称恰如其分。\n举世闻名的\"敦煌千佛洞\"从先秦开始至元等朝历时千余年开凿石窟700多个、其中有编号的495个、有壁画的400多个、壁画总量4．5万多平方米，有神话故事、佛像、经变、供养人等内容。有泥质彩塑2415尊。藏经洞中的5万多件文物在近代遭到英、法、日、俄、美等帝国主义的虏掠、大多散失在国外，目前仅存8757件藏于国家图书馆。敦煌的石窟、雕塑、壁画艺术、佛教文化均可堪称世界第一。元朝以后随着\"海上丝绸之路\"的兴起，陆上丝路才逐渐衰落。遗留至今的煌煌古代文明和今天复兴中华民族、重振丝路雄风的\"中国梦\"，应该值得每个中国人骄傲。\n茫茫戈壁还造就了一大批古代边塞诗人，从汉魏六朝至明清、唐朝是全盛时期，杰出代表有高适、岑参、王昌龄、王维、王之涣、王翰、李白、李颀、杜甫、卢纶、范仲淹、杨炯、杜审言......，他们的诗词很贴近生活，呕歌了边塞风光和戍边将士在极其艰苦条件下仍不忘杀敌报国、建功立业的抱负，表现人性之美的思乡情思。如：（唐）．王昌龄的《出塞》\"秦时明月汉时关，万里长征人未还。但使龙城飞将在，不教胡马度阴山\"。《从军行》\"青海长云暗雪山，孤城遥望玉门关。黄沙百战穿金甲，不破楼兰终不还\"。（唐）．高适《塞上听吹笛》\"雪尽胡天牧马还，月明羌笛戍楼闲。借问梅花何处落，风吹一夜满关山\"。（唐）．王之涣《出塞》\"黄河远上白云间，一片孤城万仞山。羌笛何须怨杨柳，春风不度玉门关\"。（唐）．王翰《凉州词》\"葡萄美酒夜光杯，欲饮琵琶马上催。醉卧沙场君莫笑，古来征战几人回\"。（唐）．王维《使至塞上》\"单车欲问边，属国过居延。征蓬出汉塞，归雁入胡天。大漠孤烟直，长河落日圆。萧关逢候骑，都护在燕然\"。（宋）．范仲淹《渔家傲．塞上秋来》\"塞上秋来风景异，衡阳雁去无留意。四面边声连角起。千嶂里，长烟落日孤城闭。浓酒一杯家万里，燕然未勒归家计。羌管悠悠霜满地。人不寐，将军白发征夫泪。\"这些耳熟能详的诗词至今仍在传唱。\n读古诗有感即兴作《塞上新貌》应和，\"今日塞外昔不同，华夏处处舞东风。平地矗起擎天柱，神舟升腾遨太空。风光发电绘新容，贫瘠荒凉一扫空。清洁能源世人誉，醒狮重振丝路梦\"。\n嘉峪关市和金昌市都是现代化的工业城市。西北五省最大的钢铁基地\"酒泉钢铁公司\"就在嘉峪关市内，其不锈钢产量列宝钢、太钢之后为全国第三位。2008年奥运主体育场\"鸟巢\"建设用钢总量11万多吨、其中就采用了酒钢生产的7万多吨、占总量的60％以上。金昌市是全国最大的镍钴生产基地和铂族金属的提炼中心，已探明的镍矿储量仅次于加拿大一矿区、占世界第二位，与铜镍伴生的其它稀有金属的储量与品位皆列全国之首。最具现代文明的酒泉卫星发射中心和中国核工业之母404厂都散落在嘉峪关市周边的戈壁滩上。\n绿洲农业，是先民勤劳朴实的见证。巍巍祁连东西绵延千余公里，它3600多条冰川的涓涓细流汇集到黑河、讨赖河、疏勒河、党河等水系滋润着河西走廊上的一片片绿洲，在这里有水的地方、就有人、就有村庄、就有农业，经先辈的辛勤开发、这里土地肥沃、水源充沛、日照时间长、昼夜温差大、很适宜农作物的生长，小麦、玉米、胡麻、棉花的产量很高、尤其瓜果聚集的糖份多很好吃。说了你可能不信，戈壁滩上的绿洲还确是全国重点建设的十二个商品粮基地之一。\"金张掖、银武威\"的美称就是最好的赞誉。\n站在戈壁滩上似乎无景可观，其实身临其境就是一景，极目远眺天地相接、那种博大难道不能释放你生活在水泥森林般城市中的压抑？这里少工业无污染天空蓝与深海蓝一样，可以洗涤你的心灵，让你的思绪清澈透明。每年七、八月间、天气晴好还经常能看到奇特的\"海市蜃楼\"景观。在这里才能真正体会到\"大漠孤烟直、长河落日圆\"的诗情画意。\n被美国《国家地理》杂志和中国《中国国家地理》杂志、分别评为世界十大神奇地理奇观和中国七大最美丹霞地貌景观的\"祁连山丹霞地貌群\"，\"色如渥丹，灿若明霞\"，东西长约40公里、南北宽的5-10公里，面积达300平方公里以上，尤其在夏天山顶白雪皑皑、山中绿树葱葱、山下丹霞融融、把祁连山脉打扮得五彩斑斓，真有\"不望祁连山顶雪，错把河西当江南\"的感觉。这里年平均气温5．8℃-9．3℃，昼夜温差15℃左右，是极好的避暑胜地。\n河西走廊里的故事是说不完的，这里的风景是看不完的，我所知道的也只是管规一窥，当你有一天深入到这里慢慢瞧吧！"},{"id":154,"title":"故乡情节","category":"散文","date":"二零零五年中秋节","body":"中秋节，是中国传统的团圆节，唐朝诗人李白的一首“窗前明月光、疑是地上霜，抬头望明月、低头思故乡”的千年绝唱又勾起了我的思乡之情。自十几岁离开生我养我的故土，一幌已将近四十年了，仍记得老家一句俗话：“金窝窝、银窝窝、比不上自己的穷窝窝”，有句歌词唱得更好：“谁不夸俺家乡好”，思念家乡、夸赞家乡、可能是所有远离家乡的游子倾情的心声，寻根的方式、血脉的繁延，更是一种难以割舍的故乡情结。\n我的家乡原是江苏省的扬州市，因公元一九九六年实施行政辖区分设，现隶属于江苏省的泰州市，有人戏谑我说，别人是追明星，你是追伟人，伟人到哪里你的家乡就搬到哪里。因为，前任总书记江泽民同志的故乡是扬州市，现任总书记胡锦涛同志的故乡是泰州市，其实这都是大地域概念，目的是方便别人记住我的家乡，我的家乡是泰兴市曲霞镇，一个县级市所辖的小城镇，我估计在中华人民共和国的地图上可能都未有明显的标注，我敢保证如果没有重大事件和重要人物的出现，人们完全可以忽略它，更没有理由去记住它，但它曾被扬州市所辖、现为泰州市管辖却是实情，追伟人实属不必，但与胡锦涛总书记还真正稍有亲缘关系。\n我的家乡虽不在江南，但与沪宁线上的苏州、无锡、常州仅一江之隔，从地球仪的纬度上来看其位置，还在有些“江南”之南，也有小桥流水、也是水乡泽国、也是鱼米之乡，是大概念“长江三角洲”上的一个点，“上有天堂、下有苏杭”，这是世人夸赞的，我的家乡就是苏杭的紧邻，相距都在二百公里以内，高速路上的车程都不需要两小时。离别故乡己将近四十年，我在第二故乡己经有了自己的家，但是我对我的故乡还是魂牵梦绕、还是十分眷恋。\n赞美我的故乡，不仅因为山青水秀、人杰地灵，有柔情似水的江南风光、有美不胜收的自然景观。而且 ，其美食也是独具一格的，令人叫绝的淮扬菜系、早就名扬中外。地方小吃更是品种繁多，随便点几道都可以让人垂涎欲滴，视为早点精品的有：三腚肉包、蟹黄汤包、鸭血粉汤、云饨须面、大煮干丝、黄桥烧饼......，每品都有讲究。\n传统的“三腚肉包”的馅、用料必须是猪里脊肉、一斤左右童子鸡的胸脯肉和大闸蟹的腿棒肉与香菇剁碎加各种调料拌制而成，蒸出来的包子入口鲜香无比、食后耐人回味。\n“蟹黄汤包”可谓一绝，还真有好多人对其汤馅是如何包进去的至今未解，其馅用料极其讲究、必须用入秋且刮过西北风后的肥蟹的黄与猪里脊外的肉皮一道熬成上等的肉冻，包子蒸熟后肉冻自然成一肚鲜汤，凡食之者，无不赞不绝口。曾传说，有一外地客商早闻蟹黄汤包如何好吃，一次有一宗生意要到我们老家去谈，心想正好有机会了其心愿、饱其口福，到后第二天大清早未等主人来请去用早茶，就到一著名饭店亲点蟹黄汤包两笼，汤包上桌他迫不及待张口就咬、鲜汤四溢、烫坏了舌头还烫伤了肩膀，随后有人问他蟹黄汤包什么味道，他说不知道。此传说仅是个笑话而己。吃蟹黄汤包还真得有点儿功夫，汤包上桌切忌心急，应轻轻咬一口、慢慢吮吸里面的汤汁，汤汁吮吸干了再细品包子皮，随着社会的发展、现在吃汤包也现代化了，吃汤包用吸管、慢吸包子里的汤汁，可解除被烫伤的后顾之忧。\n“鸭血粉汤”，以常见的鸭血和绿豆粉丝为原料，鸭血一般切成一公分见方、半公分厚的血豆腐块，清汤氽熟，出锅后可见血红、蒜绿、丝白、汤清，入口软糯、爽滑、清淡，让人一见就食欲大增，不像北方多用红汤或糊辣汤调制色重味浓、多伤食欲。\n“云饨须面”，也是适合大众消费的早点、其用料是将猪肉馅的小馄饨和龙须面同时煮熟，出锅后随意配汤料，汤料有：三鲜汤、鲫鱼汤、清红汤、清白汤......，口味各异、随意调制、但每款都是美仑美奂，让人食之难忘。\n“大煮干丝”、更是人见人爱的主打早点，大煮干丝的主料很普遍，是寻常人家厨房里的豆腐干，但其制作过程并不简单，用“精致”二字形容最为贴切。首先要将一公分厚的豆腐干片成二十四张均匀的薄片，然后再切成如火柴棍粗细的丝，用沸水烫两遍以除豆腥味，再配以鸡丝、鸡胗肝、腰花、笋片、香菇丝、加鸡汤等调料烧制，装盘后再浇盖熟河虾或虾仁、火腿丝、豌豆苗、食时即拌而成，这道菜由红、绿、粉、黄、褐、黑、白、多种色彩组成，色泽艳丽、味道极佳美。\n“黄桥烧饼”，其享名的原因主要是抗日战争时期陈毅元帅、粟裕将军领导新四军在苏中抗日根据地打日本鬼子，家乡的父老乡亲为慰问亲人而制作的既便于携带又便于保存的快餐食品，它的馅料主要是用上等猪油与炒面佐以葱花搓瓤，分甜、咸两种，烧饼坯擀好后撒上芝麻再放进用果木烧制成的木炭作燃料的炉中烘烤，烧饼出炉后香味扑鼻、入口酥脆。我每次回家探亲总要去品尝这几样小吃，回来时捎一点馈赠亲友，以此追忆自己童年的梦想、抒发思乡情怀。我虽不是美食家，但别具特色的扬州平三堂的豆腐素宴、泰兴国际大酒店的全鱼席等我也有幸品尝过，淮扬菜系的每道菜都是哙炙人口的美食精品，都能体现中国美食文化的博大精深。\n我赞美我的家乡还不仅因为它有自然美景、有精品美食，还在于它历史悠久，人文景观、风情习俗（风土人情另文再叙）与众不同、别具一格，除象征中华民族脊梁的万里长城历史遗迹外，具有中华民族第二的伟大工程------京杭大运河倚门而过，隋炀帝下扬州看琼花、鉴真大和尚东渡日本、以郑板桥为代表的扬州八怪，现代京剧艺术大师梅兰芳可以说是无人不知，现代史上中国人民解放军海军的诞生地在我们家乡、享誉中外的江阴长江大桥、号称世界第三亚洲第一的润扬大桥也都在我的家乡。尤其是站在改革开放第一线的长江三角洲、二十多年来在各方面所取得的发展成就举世瞩目，怎么会不让我这一位己不是泰兴人的泰兴人感到骄傲和自豪呢？\n感谢生我养我的父母亲、感谢疼我爱我的父老乡亲、感谢教我育我的一方水土。\n叶落终究要归根，我还是想要回到我魂牵梦萦、生我养我的故乡，仍然想做一个实实在在的泰兴人。"},{"id":155,"title":"故乡食事","category":"散文","date":"二零一四年冬至日","body":"常看中央电视台《远方的家》和《舌尖上的中国》这两个栏目，《远方的家》介绍的是当地的优美风景、风俗习惯和诱人美食，常常会勾起远离家乡、飘泊在外打工者对家乡的思念。《舌尖上的中国》是记录各地的\"名吃\"，看后会让味蕾回忆童年、让游子回忆家乡、让人魂牵梦萦平添几分淡淡的乡愁。\n\"食事\"其实就是相关吃的事，中国人已把它提升为\"饮食文化\"。从小在家乡就听到这么一句顺口溜：\"吃在杨州、玩在苏州、死在柳州\"。\n吃在杨州，是说杨州开埠很早，鼎盛时期却在清朝、商贾云集，尤以盐商为最，当时的杨州可称得上奢糜之乡、灯红酒绿、无所不有，盐商家中都有私厨、各有绝技，最后创造出了\"淮杨菜系\"，至今传承有序的名点名菜就有百种之多。\n玩在苏州，\"上有天堂、下有苏杭\"苏州是人人羡慕的江南水乡，当然有甚多可玩之处。\n死在柳州至今也未搞清为什么，大概是柳州的木材好、适宜制作上等的\"棺木\"吧。\n与\"食事\"相关的无非是什么时候\"吃\"？\"吃\"什么\"？怎么\"吃\"？\"吃物\"如何烹制之类的\"事\"。\n什么时候吃，一是逢年过节，二是遇有\"红事\"、\"白事\"、三是日常生活\"过日子\"，都离不开\"吃\"。逢年过节吃什么，故乡的\"年\"可分三个时段，第一时段是从农历腊月二十三\"过小年\"开始，到大年三十。过了小年就要买鱼买肉、杀鸡宰鹅、磨豆腐、做馒头，选用各种食材加工成半成品或成品食物，待春节期间享用。大年三十的晚餐应当是各家根据自身条件准备出全家最喜欢吃的、也是当年最好的一桌家宴，同时还含有表现当年人丁、经济及运道好坏的意义。除夕餐桌上\"鱼\"是不可缺的，而且上桌的鱼是不可吃的，要留到下一年吃，主要是讨个好口彩\"年年有余\"。北方人大年三十吃饺子，与\"交子\"同音，交子后就到了新的一年。\n第二时段是大年初一到初五，也是年的高潮，探亲访友拜年之事大都在此时段完成，初一和初五的早餐一般吃\"汤圆\"、也可以随便吃一些准备好的馒头糕点，南方的汤圆和北方的\"元宵\"还是有很大差别的，初五的午餐也是比较丰富的，初一到初五吃的都是年前准备好的成品半成品食物，这期间有不可动菜刀的风俗，初五又叫\"破五\"，以后就可随意了。\n第三时段正月十三到正月十八是\"元宵节\"也叫\"上元节\"家家都要挂灯笼，并有吃\"高灯汤圆落灯面\"的习俗，正月十五一定要吃汤圆的，\"高灯\"即\"高登\"的谐音，祈盼新的一年，事事如愿都有发展。正月十八吃完落灯面，这年就算过完了，可以各奔前程。\n年后就是各种节，\"清明节\"扫墓祭祖、吃\"扁食\"即大馄饨，与北方的饺子相似。其实更多的人是为了亲近自然、踏青游春，不辜负美丽春光。\"端阳节\"吃棕子为的是纪念屈原，喝雄黄酒为的是祛邪毒。\"七月十五鬼节\"要吃\"扁食\"不但要祭祖，更重要的是祭奠孤魂野鬼，让他们在阴间日子过得好一点。\"中秋节\"祭月神吃\"月饼\"和各家自做的\"涨烧饼\"，此时菱角也成熟上市，是上好的\"供品\"，菱角是水乡特有的一种水生植物，品种较多、外形有两只角和四只角，二只角最大的有十公分长叫\"大凤菱\"，四只角最小的只有一公分长名字也记不清了。常有农夫和小贩头带斗篷，将煮熟的菱角或炒好的五香螺蛳，用两只木桶装好挑在肩上沿街叫卖。儿时的这些情景，至今记忆犹新。\"重阳节\"吃\"蒸糕\"，\"冬至日\"是阴阳交错的时节，过了冬至黑夜变短，白昼日见渐长。这天也是吃\"扁食\"接下来就是又一个轮回\"过小年\"。\n大凡过年过节都是为了纪念什么人和事或祈盼神祐寄托人们的情思，当然\"祭\"和\"吃\"就分不开了。办\"喜事\"和办\"白事\"也是讲究\"吃\"的，吃的形式是\"八碗八碟\"，社会发展到今天、此风俗习惯在故乡依旧盛行。不过碗碟里装的内容是有所变化罢了。办\"喜事\"的\"八碗八碟\"与办\"白事\"的\"八碗八碟\"里的内容也有差别，办\"白事\"上的菜有些办\"喜事\"就不能上，如\"大烧棺子\"，就是将豆腐切成寸余长、半寸宽、半寸厚，形状象\"寿器\"放在油锅中炸至金黄捞出，再选当令时蔬加高汤烹制而成。\n我曾在《故乡情结》和《回忆年味》两篇文章中介绍了故乡的一些名点名菜。在此再介绍几样极其简单又与日常生活一日三餐必不可少的\"吃食和菜品\"。\n泰兴人特喜欢喝\"粯子粥\"，（'粯'方言'汗'音）自诩为\"泰兴咖啡\"，跟全国各地一样泰兴人把\"小麦\"磨成的粉叫\"面\"，泰兴人却把\"元麦\"磨成的粉叫\"粯子\"。\"粯子粥\"就是稀糊糊，在糊糊里加30％的大米、再加少许食用碱熬成，特别养胃。对酸性体质的人来说一定会喝出健康。现在泰兴豪华酒店的餐桌上随时可见。另一种比较奢侈的吃法是把\"粯子\"炒熟，加少许开水和白糖搅拌即成，故乡叫\"焦屑\"，学名应叫\"炒面\"，尤如藏族同胞所食的\"糌粑\"。全国各地超市里的杂粮应有尽有，但能找到\"粯子\"还真不容易。\n\"仄楞\"是一种很特别的吃食，三年困难时期粮食奇缺，每到春天青黄不接之时，有人将八至九成熟的元麦穗摘下，去壳后用锅炒熟再用石碾或石磨碾压成条形状食之，满口清香、韧性十足，此吃食为度命之计，即使在家乡也有很多人不知道，现在更是难得一见，若偶尔食得必是天赐珍馔。\n\"韮芽炒螺蛳肉\"，螺蛳是水乡最常见的食材，一年四季都有，最肥美的季节当令初春。将螺蛳肉去籽洗净下锅煸炒八成熟时倒入韮菜芽，翻炒少许即出锅，香糯酥软的大米饭以此佐餐，好吃无比。螺蛳另一种常见的吃法是\"炒五香螺蛳\"，将螺蛳尾部剪掉洗净用五香调料下锅炒制，出锅后用嘴啜其口轻轻吸出螺肉，清香、滑嫩、爽口。改革开放后少吃辣椒的江苏人也受川味的影响，现在炒制时也会加少许干辣椒，给舌尖味蕾留下另一种印象。\n\"茄夹饼\"是初夏时家庭当令小吃，选直经5-6公分的青茄或紫茄，切成0．7--0．8公分厚的茄块若干，再从中一剖为二，千万不要切断，中间塞上用虾肉和猪肉剁成并加调料拌好的馅，外面再裹上面糊糊放入油锅里煎炸至金黄色捞出，配上\"粯子粥\"，那才是真正的\"农家乐\"。\n\"河蚌烧青菜\"是秋天最好的家常菜，青菜要选用经初霜打过的塌青菜，入口微苦、回味甘甜，与河蚌配伍相得益彰，鲜美无比。退休前，每每回乡探亲三弟的餐桌上必有无疑。\n\"小鱼贴饼\"是初冬时的当令小吃，市场上选小杂鱼1公斤，去鳞、去腮、去内脏、洗净，用半斤黄豆或花生米炒熟，将洗净的小杂鱼用少许油煸一遍再用红烧鱼的方法加调料和水并倒入炒熟的黄豆用大铁锅去煮，同时在铁锅的上沿部贴上白面饼或玉米饼，盖上锅盖约二十分钟鱼熟饼熟，香味扑鼻，饭菜皆有，再配上\"粯子粥\"一家人围坐一起享用，必会其乐融融。\n以上所列这些\"吃食\"是家乡最常见、一年四季皆有的，所谓当令就是那个季节食之最好，而且在过去这些食物是登不了大雅之堂、上不了宴会餐桌的，如今人们返朴归真、追崇回归自然，反到成了城里人的稀世珍宝。\n改革开放三十多年来，随着市场经济的建立，交通，通讯工具的大发展，商品大流通，现在人己不分南北，物己不分东西，无论你身居何方，这些外地的食材即是\"山珍海味\"在当地市场上基本都可以买到。当然还是故乡的最新鲜，最好吃。"},{"id":156,"title":"春天礼赞","category":"散文","date":"二零一二年惊蛰","body":"太阳升起来了，照得大地金灿灿的，比冬日的阳光亮多了，暖和多了。\n小草绿起来了，像钢针一般地从板结的泥土里、石缝中，依托着旧年的枯根，挺着腰杆钻出来。一天，一点绿；二天，绿一点；三天，绿一片……\n柳树活起来了，鹅绒似的嫩黄挂在树梢上，经风一吹，轻轻摇曳，抚摸在脸上，似乎是在给人搔痒痒。洁白如雪的柳絮随风飘荡，静静地落在路边，落在行人的耳旁，呢喃好消息，把柔和的爱洒在人们的肩上。\n桃花开起来了，漫山遍野的粉红中夹着杏花的点点浅红，梨花也不甘示弱，一夜间绽放出一片素白，像一场雪覆盖在翠绿的大地上，那种桃红柳绿、美不胜收的景色，点缀着人间胜似天堂，怎不令人陶醉？\n燕子飞回来了，衔泥衔草，紧张地忙碌着，在梁柱上、房檐上垒窝，重整新家，为孵化雏燕、迎接新生命，一点点地、进行着不懈的努力。\n蜜蜂忙起来了，在馨香氤氲的清新空气中不停地舞动，高兴地去觅食，一会儿钻在这簇花下，一会儿又停在那簇蕊中，频繁地穿梭往来，急匆匆地向同伴们报告采蜜成功的喜悦，嗡嗡地哼着劳动最光荣的歌谣。\n蝴蝶舞起来了，挥动多彩多姿的粉翅，在绿草丛为底、油菜花为主色调的画布上，用盛开的百花画出绚丽的五线谱，上下翻飞，翩翩起舞，互相追逐着，挺吸引人的眼球，让人有按捺不住放歌的冲动。\n柔风吹过来了，扫去了一切寒意，亲和着人的面容，温乎乎的、暖融融的。惠风和畅，也给万物带来了盎然生机。\n春天悄悄来了，一声惊雷、一阵急雨，在远处的天边挂上一弯彩虹，赤、橙、黄、绿、青、蓝、紫，七色光环，美丽极了。\n春天真的来了。一年之际在于春，一日之际在于晨。从春天出发，把握好命运的脉搏。"},{"id":157,"title":"卜算子·赞梅园","category":"词","date":"二零一四年春节","body":"携眷赏梅游，精彩观不休。红粉黄绿撒满坡，犹如锦上绣。\n春风轻拂面，料峭寒意丢。品高自古人仰慕，愿将禅心修。\n附记：点赞无锡梅园\n2014年春节在江苏无锡过年，这也是我离家几十年第一次在老家过春节。夫人之侄女付晓玲从浙江东阳专程来无锡看望我们，正月初五携夫人及其侄女游无锡梅园。是日，阳光明媚，太阳照在身上暖融融的，虽处深冬，却适逢新春佳节，园内装饰一新，加之游人如织，早透春意。虽大多数梅花还没有完全盛开，但棵棵披红挂绿、株株含苞待放，更让人有先睹为快的感觉，丝毫不影响游园的情绪。好在有照片为证。\n无锡梅园原是无锡红色资本家荣德生先生的私家花园，至今已有近百年历史，1955年荣德生的后人荣毅仁先生将它捐献给了国家，现在已成为无锡一处比较著名的旅游景点。\n梅园地处无锡市西郊的东山、浒山和横山之上，面临碧波万顷、浩淼无垠的太湖，背靠龙山九峰，依山傍水、气势雄伟，因梅花而驰名。园内占地总面积812亩，其中有梅林56亩，栽培梅树已有70多年的历史，现园内广植梅树5000多株、梅桩盆景2000多盆，栽培品种多达40多个。犹以洁白素净的玉蝶梅、花如碧玉萼（e）如翡翠的绿萼梅、红妆淡抹的宫粉梅、胭脂欲滴的朱砂梅、浓艳如墨的墨梅、枝干盘曲娇若游龙的龙游梅最为珍贵。无锡梅园的梅花无论是品种或是数量均不比杭州孤山、苏州香雪海的梅花逊色，只有过之而无不及。\n雅士爱梅历来都是爱它不畏冽霜寒雪、敢与严冬抗争的品格，越是天寒地冻越是奋然怒放。你若看到一盆铁干拔地、铜枝盘空、雪飘风舞、古壮苍然的老梅，心中一定会肃然起敬，这就是心灵的相通。\n梅花古雅而不陈腐，正所谓：铁干铜皮碧玉枝，柯如青铜根如石。因此，才惹人喜爱。北宋诗人林逋（字和清）在杭州孤山一辈子植梅养鹤，终生未娶未仕，人称“梅妻鹤子”，可见其爱梅的执着。也只有他才能写出：“疏影横斜水清浅，暗香浮动月黄昏。”的诗句。后来的文人雅士更把“疏影”和“暗香”用作梅花的别称。\n南宋诗人陆游用《卜算子》词牌填“咏梅”一首，“驿外断桥边，寂寞开无主。已是黄昏独自愁，更著风和雨。无意苦争春，一任群芳妒。零落成泥碾作尘，只有香如故。”借物喻人，表达心情，惟妙惟肖。\n毛泽东主席也用《卜算子》词牌填“咏梅”一首，“风雨送春归，飞雪迎春到。已是悬崖百丈冰，犹有花枝俏。俏也不争春，只把春来报。待到山花烂漫时，她在丛中笑。”威武雄壮、大气凛然、令人仰慕。南宋诗人陆游和毛泽东主席的词中均未提到一个“梅”字，但他们确又把梅花的品格描写得栩栩如生。\n梅园内除了梅林外，还有可供游人赏玩的景点如：梅园刻石、香海、洗心泉、米襄阳拜石、天心台、揖蠡亭、清芬轩、诵豳（bin）堂、招鹤亭、小罗浮、念劬（qu）塔、豁然洞、松鹤阁、小金阁、吟风阁、开原寺等景点。每个景点都是一个典故，都有一段感人的故事，大都是教化人们，励志进取、尊老爱幼、积德扬善，很有教育意义。\n园内还辟有一处花溪景区，引种栽植100多种名花异草，并建有规模巨大的赏石景观，群山环抱、石洞石径、古树绿荫，淙淙流水中倒映着蓝天白云，相映成趣，赏心悦目，让人可以享受到回归大自然的欢畅与快乐。\n我也爱梅，爱“古梅如高士，坚贞骨不媚”的品格，一生曾以此为座右铭，修身养性，正像贤者所言：人不可有傲气，但不可无傲骨。回首往事，真有受用。随兴以《卜算子》词牌填“赞梅园”一首，以表达对无锡梅园的赞颂和对这次游园的纪念。"},{"id":158,"title":"父亲的丧礼","category":"散文","date":"二零零一年八月初六","body":"《父亲的丧礼》------为 了 永 不 忘 却 的 纪 念\n离开家乡已有四十多年，其间虽有探亲的机会近亲故乡，但每次的时间都很短，且有些大事是碰不到的，所以对家乡的一些婚丧嫁娶、喜庆习俗几乎忘得一干二净，丧礼就是其一。\n在家乡参加丧礼都是儿时的事，记得奶奶去世大概是一九五六年夏天，外婆是一九五九年的春天，爷爷是一九六零年的除夕夜，大姑是一九六一年的冬天，那时都由大人操持，我们只是按大人的意思跑跑龙套，甚至当成一次游戏来玩，没感到有什么悲伤之情，对具体的礼节也没有什么深刻印象。\n母亲去世是一九七五年的农历十一月十五日，我还在部队服役。当年夏初部队从浙江的杭州换防到河南商丘，为响应中央军委“严格训练、准备打仗”的号召，尽快熟悉驻地周边的情况，部队开展了冬季野营拉练。在驻训点接到母亲病重的电报，部队首长准假十天，让我回家探视。因当时交通十分不便，来回途中就得四天，十天时间很快就到，军纪难违，按期赶回部队。不到一周母亲病故，部队首长又特批假十天回家料理后事，我到家时母亲的丧事已办完毕。那个年代所有陋俗全部抛弃，一切从简，火化后开个追悼会就算完事，所以也就不讲究什么礼节了。\n父亲（4月28日农历3月26日14时45分）去世，丧礼是按家乡习俗办的，觉得比过去、比城市里都繁琐复杂得多，有些庸俗的程式可以简化掉，追思亡灵、激励后人的内容则可从文化的高度加以总结传承。\n写这篇文章只是在父亲生日那天，按家乡风俗补记了为父亲办丧事的过程和内容，没有去剖析，也不是祭文，另有一篇《怀念恩重如山的父亲》且作祭文、追思故人。\n家乡有人亡故（指正常亡故）出殡入葬的程序是：咽气后要即刻打开蚊帐，给亡人净身穿寿衣，将亡人的枕头抛到房顶上，好让亡人远处就看到自己的家（望乡）。穿好寿衣后要头南脚北放到停尸板上，脸上盖上黄纸，待尸寒后可放入冰棺（冰棺可租用）。随即要搭灵堂，灵堂内挂丧帐、奏哀乐，灵前上香并放上祭典用的饭菜、点心、水果。灵前还要放置一个烧化纸钱的大瓦盆，用来烧香化纸。灵堂搭好后，亲朋好友等客人就可以举行吊唁活动了。\n搭丧棚，丧棚的作用有两个：一是给来吊唁的客人休息的地方，主要放一些茶水、饮料、香烟等招待来客；还有一个作用是给帮忙的亲朋制作丧具、发放孝衣、孝帽、收受吊唁礼品等工作的地方。丧礼中送来的可有礼金、丧帐、花圈等，礼品轻重视与丧家亲密程度而定（必定有礼尚往来）。一般客人送黄纸一扎或锡铂一叠，父亲办丧事期间收到黄纸就有两三架子车之多，由此也可见我家的亲朋好友不少。\n搭饭棚，饭棚是招待来客用饭的。不像城里火化完到饭店吃一次饭丧事就算办结束，我们家乡办几天丧事就要吃几天的饭，而且还不完全是正餐时间，客人随来随吃。父亲的丧事办了三天，招待客人有五六百人次。搭饭棚请厨师、帮厨及厨具都是自带的，丧家只要有一人负责制定用餐标准和协助买菜就行了，酬金是按桌结算的。\n搭戏台，在我们家乡家境较好的人家还要搭戏台请演出队每晚演出，招待乡亲。演出的内容有追思亡人身世及身前故事、有讲述子女孝贤、有演绎当地风俗习惯、有宣传党和政府方针政策的，十分庞杂。形式有喜闻乐见的歌舞、快板、小品、戏曲清唱等。\n搭灵堂、搭丧棚、搭饭棚、搭戏台，请哭丧队、鼓乐队、演出队，和尚念经超度亡灵（父亲丧期未请和尚，商量纪念一周年时再补办）。在我们家乡，凡与婚丧、嫁娶、生老、病死、升学、乔迁等诸多风俗礼节相关的都有专业化服务队伍，操办时只要肯出钱就是了。\n在搭灵堂、丧棚的同时要及时送信给亲朋好友（发讣告），告知开丧期及入葬时间。开丧期有三至七天，但不得少于三天时间，所有丧礼要在开丧期完成。何时火化入殓、何时出殡入葬，所有葬礼都要请风水先生预先算好时辰，不得提前也不得拖后。墓地也是请风水先生看好的。我原意是买一公墓将父亲的骨灰与母亲的骨灰合葬一起，经与兄弟姊妹们商量，大家认为母亲落葬多年，我们全家从各个方面看都顺顺当当，动了风水可能给子孙后代带来不利。且父亲临终前还有要一口棺材的遗愿。当然，他老人家不是拒绝火葬，其真正的意义还是想让有家乡的黄土盖身。所以即顺从父亲的遗愿和大家的意见，在西港边找了一块墓地，东北西南向。后有靠山前有活水的地儿是风水宝地。我们家乡是大平原没有山，父亲的墓地方向背靠镇政府，前三十米面临一条通长江的大河，一往无前再无遮挡，风水还是很不错的。父亲说他百年之后会保佑我们全家，我想老天也一定会顺人意保佑积善之家、积善之人平安的。\n吊唁活动开始后，在亡人的头前要烧钱化纸，其意义是让亡人有足够的经济实力打发勾魂的牛头马面和赈济赴黄泉路、过奈何桥沿途所遇的孤魂野鬼，甚至可以收买通判和阎王爷到阴曹地府少受罪。\n儿子媳妇、女儿女婿从头到脚全部都要身着白色的孝服，腰扎稻草绳，披麻带孝，拖好（hao）竹棒（用青竹所做约一米左右长，头部要用麻丝扎上白布或黄纸）。孝子帽子上的麻丝要打七个结，其意义是要记住守孝不得少于四十九天（古时守长孝有三年的，守孝期间不得办任何喜事）。每七天要有一次祭典活动（烧七），第三十五天的五七和第四十九天的断七要有较重的祭典活动，直系晚辈应该都到场。断七过后丧期才告结束。孝子在守孝期间不得剃头，发之体肤受之父母，不理发是不对父母遗传的伤害，也是血脉传承的一种精神寄托。\n孝子媳妇在门前迎客时要行单腿屈膝跪拜礼（对长辈和同辈行的礼，对晚辈无须）。宾客在灵前吊唁时，儿子媳妇要行双膝跪拜礼，女儿们要行哭丧礼（嚎啕大哭）。女宾客的吊唁一般是哭丧，女儿们要陪哭（现在有请哭丧队代哭的，感情失真，不可效仿）。哭的内容都是追思亡人身前故事，孝子媳妇要跪到哭声停止才能站起来，每次哭丧的时间都在十分钟左右。\n守灵是丧礼中不可缺少的程序，开丧期间灵前必点长明灯（好让亡人“望乡”时看到其家人哀痛之情），晚上孝子不得睡觉要值更守灵，守灵时也可由他人陪伴。守灵三日疲惫不堪，守灵也是最后一次考验孝子的孝顺程度。为九十九岁的父亲守灵再苦再累也值得，我们家乡给年事高的人办丧事是当喜事（白喜）办的。“长寿碗”分送了一千五百个还没有够，乡亲们要“长寿碗”是说要沾一点老人的“长寿之光”。\n出殡前一天，儿子媳妇、女儿女婿所有的晚辈和亲友都要按辈份规定着孝服，在鼓乐队的伴奏下，孝子在前举上亡人遗像，其他人扛抬上彩纸扎的房屋、汽车、家电、马队、金银库等，步行到三公里外的土地庙烧化，给亡人报到，好让土地爷日后多关照，也指望日后亡人在九泉之下能过上好日子。出殡前还要将亡人生前所穿戴的衣物和扔在房顶的枕头一起去烧化（化铺草），一是让亡人在阴间有物所用，同时不要再想家。从土地庙和化铺草以及送葬返回家门时，门前都要烧一堆火，凡参加活动的人都要从火堆上跨过（跨火），其意义不太清楚，可能是与亡人的诀别仪式。死人的事终究是一种“晦气”的事，通过跨火与“晦气”诀别。\n父亲的火化时间是凌晨一点半，由大棚车拉上鼓乐队在前奏乐引路，殡葬车、拉花圈的车和其他客人所乘的车紧随其后，到距镇上约十八公里外的太兴火葬场火化的。入殓时间是清晨五点钟，入殓时在棺材的底部填石灰包，每一岁放一个，然后再把父亲的衣帽鞋袜按序放在棺材里，骨灰塞入人的心脏部位，棺材里的随葬品很少，是他生前所用和所喜欢把玩的一些小物品。入殓封棺前要（亮材）儿子儿媳、女儿女婿都要顺时针围着棺材看最后一眼，随后盖好棺板，由抬棺材的头目拿一把斧头，用几颗铁匠铺里打造的方头长钉把棺材钉起来（响钉），儿子儿媳、女儿女婿直系晚辈都要跪在灵前大哭，为亡人送行。这场面我永远难忘，一道黑沉沉的木门不是吱呀一声关上，而是朝着大地的方向死死地钉起来，永远不再开启，最后一斧头砸下去，棺材板严丝合缝，父亲就永远不见了。\n入殓后即要出殡（发丧），棺材在麻绳竹杠的捆绑下由十个抬棺人抬出家门，并要在太阳升出地平线前送到墓地。棺材是由十五公分厚的松木做成，漆上黑漆（也有漆红漆的），头前用金粉画上龙凤，写上父亲的讳号，质量还是不错的。棺材抬出家门后要摔碎灵前烧钱化纸的大瓦盆（摔瓦盆），棺材在鼓乐队的伴奏声中抬到墓地共休息三次（三至五次，视路途远近而定），每休息一次儿子媳妇、女儿女婿所有送葬的人都要面对棺材跪拜。棺材送到墓地后随即落葬，将棺材送入墓穴后其他人就可返回拆棚清理灵堂，留孝子一人帮抬棺材的人做坟标山（用彩色纸覆盖在坟尖上，也有用花圈覆盖的），并烧钱化纸，烧掉孝棒。\n入土为安后，还要集中一次，大宴宾客，开丧期才算结束，客人可以返回，子女在断七后才能脱孝。从此祭祀活动就融入清明节、农历七月十五日（鬼节）、冬至节、周年纪念日及春节祭祖等活动中去了。\n离父亲亡故时间仅八天（农历4月初四），客居海安八十五岁的叔叔也无疾而终，离我们而去。他的丧礼我也去参加了，海安离老家约四十公里，风俗习惯相差无几。\n“福寿康宁，固人所同欲。死亡疾病，亦人所不能无。”斯也。“生者为过客，死者为归人。”然也。“一脉相承，代代相传。”自然也。“祭而丰，不如养之薄也。”做到“礼”以顺人心即可矣。"},{"id":159,"title":"回忆年味","category":"散文","date":"二零一二年春节","body":"又过年了，是的，又过年了。\n“年”，每年都是这样过的，现在大多数人都说年味淡了，我似乎也有这样的感觉，是淡了。但细想起来又说不出哪些地方淡了。“年”过完了也就过去了，在大脑中没有留下多少印象，大概是人生在福中不知福吧。回忆儿时过年的味道，记忆犹新、感觉不错、印象也很深。\n小的时候上学特别期盼放寒假，因为放寒假也就预示着快过年了，只有到过年才有好吃的、好穿的、好玩的。在那个物质比较匮乏的年代，盼过年应该是小孩子普遍的愿望吧。\n“腊八”是“年”的入场券，喝了腊八粥就逐渐有年味了。腊八粥的熬制是很有讲究的，其主要食材是各种米、各类豆、各式坚果，口味可因人而宜，分甜咸两种。如果是甜味的可任意加一些蜜饯，咸味的可加一点肉沫。\n过年是要穿新衣新鞋的，那时候到商店去买做好的衣服简直是奢望，村镇的商店里是找不到成衣的。因为每人每年只能发到一丈左右的布票，几两棉花，全家人的新衣服是在年前把裁缝请到家中量体做的，基本上保证过年能穿上一套兰或灰色卡其布的衣服，一套衣服是新一年、旧一年。缝缝补补又一年，小孩是长身体的时期，有的衣服也只能穿一年，下年再穿就嫌小了。好在当时未实施计划生育政策，每家大概都有四、五个小孩，这样就可以老大穿了老二穿、老二穿了老三继续穿。大人们不一定每年都做新衣，今年做了过年穿几天，年过后洗净收起来来年再穿仍是新的，因为家中要添置一点被褥也要靠那一点儿布票，做了衣服就添置不了被褥，添置了被褥就做不了衣服。腊月到，裁缝俏。裁缝的活儿多了，不提前预约，临时是找不到裁缝的。新鞋是由母亲平时抽空衲底做帮最后送到鞋匠店绱的，一般是每人两年三双黑卡其布面料的单鞋、一双灯芯绒面料的棉鞋。\n腊月二十三过小年，过小年要在灶头上贴上“上天言好事、下界保平安”的对联，供奉上灶糖也就是“麦芽糖”祭拜灶王爷。小年以后就忙了，每天都要有一件大事要做，首先是掸尘，家中里里外外彻底搞一次卫生。磨豆腐，是每家都有的，把黄豆泡发好拿到做豆腐的人家去加工，磨浆、扯浆、煮浆、点卤、上箱，豆腐做好拿回家用一小陶缸把豆腐顺缸壁码放上，再加冷水养着不坏，可吃到正月底、二月初。做馍头，西北这地方把没馅的叫馍馍，有馅的叫包子，我们家乡有时把馍头和包子就不那么分得很清了，做馍头也是拿到别人家去加工，先要发面和做馅，馅有甜咸两种，甜的以豆沙居多，洗豆沙也是比较忙烦的，要将赤豆泡发、煮熟、揑碎、过渣、沉淀后，再用适量的油和糖炒制。咸馅制作起来就比较容易些，一般是将腌制的干咸菜或晒干的萝卜丝与肥瘦相间的肉丁炒熟拌匀就行了，有的也可加一些虾米，做馍头面的发酵很重要，发得好不好，说能预示这一家来年的运道。磨豆腐、做馍头这两样一般人家是必不可少的。家境殷实些的人家还要贴烧饼、磨米粉蒸糕、汤圆是随吃随做的，其做法也不同于北方的元宵，分甜、咸馅，咸馅一般是荠菜、青菜加细肉丁做的。甜馅有豆沙、芝麻、桂花、猪油等，猪油馅是将猪板油切成3至4毫米的方丁用白糖提前十天左右腌制好的，用它包的汤圆咬破看馅晶莹剔透、一吃满嘴流油、香甜无比。至今提起荠菜馅和猪油馅的汤圆，还会调动味蕾让我嘴角流涎。炒花生、蚕豆、瓜子等干货，红枣、柿饼之类的密饯有条件的人家也要备一些。家里大凡有点好吃的东西，平时不动都是要留作过年的。\n从过小年起，我家所在的镇虽不像宋丹丹小品里所说的“那个人山人海”，但确实会比平时热闹许多，周边农民会把自种自养的农付产品拿来买卖，城里的小商贩也会赶来出售年画、对联、喜钱（剪纸）和一些日用杂品，直至大年三十上午。\n三十下午要贴春联贴“福”字、打“元宝墩”，打元宝墩就是将石灰粉放在细密的竹篓里在门前屋后打成几何形状的墩，以示来年风调雨顺、五谷丰登。去年我父亲九十九岁高龄离世，只有前两年的春联和“福”字是买的，其它都是父亲亲笔所书。小时候，凡是办过年的事，我都愿意高高兴兴去做。\n准备过年的这些习俗在我老家曲霞镇流传至今也没有变。“年”文化的魅力根深蒂固不得不令人刮目相看。自离家后，四十几年再没和家人一起过年、品味年味，这是我人生中最大的遗憾。\n大年三十的年夜饭前，先要挂上列祖列宗的画像举行祭祖仪式，祭典先人是为了不忘自己的根基，同时也求列祖列宗来年继续保佑全家人丁兴旺、财运亨通。年夜饭是比较丰富的荤素搭配，炖、焖、烧、炒、煎、炸……，各种烹调方式全可用上，最少也要有8个菜，俗称“八大碗”，富裕人家可备十二至十六个菜。备一份“什锦火锅”那更是一般人家的奢望。现在的情况不同了，随着市场的大流通，无论在何地物质都是很丰富的，前几年还兴了一阵吃年夜饭到饭店，大家渐渐感到“家”味不足，“年夜饭”还是在家中自己动手准备才有“团圆”味。年夜饭中“芋头红烧肉”“粉丝汆丸子”“大葱煎豆腐”“八宝饭”“红烧鱼”这几个菜是每年必备的，“芋头红烧肉”有新年开门就能遇头彩的意思，“粉丝汆丸子”有团团圆圆连绵不断的意思，“大葱煎豆腐”有新年吃豆腐越吃越富的意思，“八宝饭”有广聚财源、招财进宝的意思，其实每道菜品都有庆祝当年丰收、预示来年富裕、期盼全家幸福的意思。除了鱼不能吃以外，其它上桌的菜可以一扫而光。因为“鱼”与“余”谐音，要年年有余。大年三十的菜肴每个都要备两份以上，因为大年初一有禁动刀剪的习俗，饭菜只能回锅热了吃，也有祝愿富裕有余的意思。\n晚上睡觉前父母会把不多的“压岁钱”放在孩子的枕头下，压岁钱绝对是均等的。正月初一，起床后首先给家中长辈拜年，吃完早餐后按辈份给族中长辈和邻居家拜年，或是看社火表演，初一到初五社火不断，舞龙耍狮、跑旱船。文革期间破“四旧”没有了，换了新的形式，由文艺宣传队演一些歌舞节目。凡结婚成了家的初二去岳家给长辈拜年，初三直至正月十五都可以给亲戚拜年，到岳家和亲戚家拜年不得空手，都必须提一点“茶食”作为礼物，“茶食”就是一些糕点。亲戚到我家拜年或到亲戚家拜年无非是陪着吃和玩。这样的好事哪有小孩不高兴的呢？\n正月十五元宵节，也称上元节，从正月十三起一般都举办灯会，称作“高灯”，正月十八称“落灯”，自此年也就算过完了，工、农、兵、学、商，你干什么行当就该干什么去了。不过，元宵节还可以疯玩一天，一般到了正月十五天气也暖和好多了，如无大风气流平稳，白天在麦地里比放风筝是最大的乐事了，未拔节的麦地是可以踩踏的，踩踏后有利于麦棵的分蘖，可以增加产量。风筝的种类很多，大多是野禽和昆虫形状的，有老鹰、仙鹤、鸽子、蝴蝶、蜜蜂、蜻蜓……，还有些几何形状的如菱形、正方形的，我放的风筝是由邻家叔叔和我一起用竹篾糊扎的圆形月亮风筝，两边用芦苇花平衡，后边拖上一个长长的纸尾巴，可放几十米的线绳，高达一、二十米，有时要两人才能拖曳得住。若是一年中第一个月圆之夜，天气好，月光如昼，伙伴们会在旷野中放自扎、用废自行车胎作燃料的“洋灯”，北方人叫“天灯”，学名叫“孔明灯”，且一伙一伙比谁的飞得高、飞得远。\n北方与南方的年俗也不完全一样，但在这团圆的日子里期望家人在新的一年中事事顺心如意、人人幸福安康的心情那都是一样的。\n现在的物质条件好了，过日子就像天天过年，想吃什么、喝什么、穿什么、玩什么就有什么，家常便饭赛过年，天天过年当然会让人索然无味。真不知道现在的小孩最盼望的是什么？\n以后过年的“味”可以不要放在吃喝玩乐上，要挖掘“年俗”深层次的文化，利用“过年”这样的机会，把尊老、爱幼、和亲、睦邻、亲友、融人等方面引导到节日的氛围中，为构建和谐社会提供一个古为今用的好载体。\n相信年会过得越来越好，年味也会越来越浓。这是我对“年”的祝福。"},{"id":160,"title":"官场一瞥之一：真话与假话","category":"散文","date":"二零一一年春节后","body":"“不唯上、不唯书、只唯实。”应是为人为官之道的根本，现在可不是了。官场上呆的时间不算长但也不算短，所以也就看出了一些通病。\n说真话、说实话平民百姓往往敢于做到，官场上的官员就不成了，不管是大官还是小官，道理是一样的，要想把官当稳当、越当越大，就要学会说话。一是要学会专挑好的说，真是专挑好的说还算不错，因为不管怎样你还是干出了一番事业、做出了一些成绩，才有可挑性。二是要学会看什么人说什么话，话语出口前要上下左右看一看，看什么？一看上司有什么嗜好、有什么意图、自己在上司面前是否能得宠，常以阿谀逢迎、百般媚态、诸多软话说给上司听，为讨得上司的高兴。二看左右同僚与自己意气相投的，多以互相吹捧的热话说给同伙听，以便结党营私；三看官场死敌，多以似乎漫不经心、毫不在乎的冷话说给与自己争风吃醋或是官场不和的对头听，多为气人。四看哪些是自己的下属，会以居高临下、盛气凌人的硬话说给下属听，意在逞威。三是专会说假话，好大喜功、报喜不报忧、弄虚作假、胡编乱造、说谎不脸红。四是尽讲废话，现在各级领导的工作方法是热衷于开会，一开会台上的主要领导就要“致辞”或者“报告”，报告者往往将台下的听众当小学生，长篇大论还害怕别人不理解，也不管听者是否昏昏欲睡哈欠连连，其他领导还要反复强调会议的重要性。诸如此类官场上的话还能听吗？听了还能信吗？规劝善良的人们一定要学会反着听、倒着看的功夫。\n敢讲真话是一个人的品德问题，更是一个道德底线。官员不讲真话既有个人的人品问题又是时下官场的潜规则，在当下社会转型过程中，许多事情前景不明、祸福难测，怎样才能使个人利益最大化这是官员们首先考虑的问题，尤其今天的现实生活中许多事情的真相并不美好，谁说了真话就有可能成了那个大喊“他什么也没有穿”的孩子，导致官员讲假话不仅是官员的个人品德问题，制度缺陷、法律漏洞、政治生态都是这无良行为的推手。急需改良官员考绩办法。\n官场上正直的不缺良知的无论大、小官员首先应该带头讲真话，说话绝不能昧良心。同时一定要保持清醒头脑争取多听真话，听话决不能偏听偏信，一定要多加了解、多加分析与思考，三思而后行。更重要的是识破那些有所企图、专编假话、溜须拍马的人，要让他们的目的不能得逞。人在官场身不由己，有时也很无奈，违心的话可能也说过，违心的事可能也做过，但一定要把握原则、守住做人的根本。要想当个好官就从说真话做起。\n官“场”风气是吏治的一种综合作用力，是官员们彼此相连共同的精神支撑，一个官员不讲真话、不讲诚信无所谓、成不了大气，怕就怕官员之间上下左右互相影响、陋习成风，形成通病，就有可能危害一个地区、带坏一片风气，（媒体曾经报道贵州省六盘水市用“集体决策”发文件的方式，编造一套假话蒙骗中央环境治理督察组）诚信缺失、不讲信用，不仅会破坏市场经济秩序，损坏社会公正和群众利益，妨碍精神文明和民族进步，危害社会经济发展，更可怕的是官场之风影响到纯朴的民风，如果整个社会不讲诚信，必然会遗患无穷。孔子的学生曾向孔子讨教支撑国家强盛不衰的三件法宝是什么？孔子回答说是“兵、粮、信”，一旦社会缺失诚信，国必将不国，所以说假话、不诚信之风不可长、不可长！要彻底改造说假话、不诚信之风，必须强化知耻意识，要将说假话、不诚信视为缺德之行，全社会共诛之。"},{"id":161,"title":"官场一瞥之二：变味的调研","category":"散文","date":"二零一零年五月十日","body":"毛泽东同志曾说过：“没有调查研究，就没有发言权。”我参加的各种调研活动算起来也不少，2009年配合中央34部委在甘肃的调研（改革开放、市场流通组）、参加过省人大、省政府组织的专项调研，今年3月用了近一个月的时间参加了省局组织的千人基层大调研活动，各种小型调研活动就更多了。调研本身是一种极好、极有效的工作方式方法，因为真正沉下去深入基层的调研，可以实实在在地了解人民群众的需要，可以了解基层急需解决的实际问题，可以把我们党的三大法宝之一的依靠人民群众落到实处，但是现在的调研已经 有变味的感觉。\n现在的“调研”一是调研者再不是那么轻车简从，“兵马未动、粮草先行”，调研前就将要调研的课题和要去的地方通知到了下一级地方政府，下去时由相关部门参加、仪仗隆重、前呼后拥。地方政府也是兴师动众，一般是根据调研者的身份、职级和调研的内容，采取对等接待，（内容重要或关乎地方经济发展的项目经费，接待规格就会提高）地方政府会根据调研的单位与人员通知本级和层层通知下级的相关单位人员参加，会到自己辖地的边境上警车开道、迎来送往，因此调研队伍就会迅速膨胀起来，车辆人员会达到调研组的三、四倍，搞得调研队伍浩浩荡荡、将调研者裹挟其中，沿途群众驻足观望、好不威风、有的调研者也就乐在其中。实际上这种接待是给调研者和调研对象之间构筑了一道藩篱。\n由于调研内容是预先通知的，被调研对象必然有所准备，到现场给看什么、该说什么、有什么样的人说，一一都组织好了、有备而来，拣好的看、挑好的说、报喜不报忧，理所当然。调研者也只能在被调研的安排导演下顺乎自然、走马观花地看了一场“恶作剧”。这种现象你能了解真实情况吗？\n调研中召开汇报座谈会是必不可少的程序，汇报者的材料也不过是一场文字、数字游戏，其中有多少真实情况可想而知了，何况又有哪位操刀捉笔的秘书敢写真实情况？调研者听了汇报、看了现场必然要反馈信息、谈调研的印象、谈优点一、二、三、四、五……，说问题避重就轻、蜻蜓点水、轻描淡写、不疼不痒。似乎才对得起“被调研者”的有所准备。\n调研组回去后不管调研情况如何，其成果是要交上一份调研报告、应付差事，调研工作就算完成，对调研需要解决的实际问题、上级或本级如何决定、最终落实得如何就可以束之高阁、无须再过问。不管什么样的调研，绝大多数都是一样草草收兵、什么问题也解决不了的结果。\n一个单位的新任领导下基层调研绝大数也不是想解决什么问题的，认认门、识识人，套套近乎、树立威信是根本所在，体恤下情的能有几位？解决了多少历史遗留的重大问题和共性普遍问题，是检验是否是好领导、真调研的试金石。\n“吃好、喝好、玩好、送好、汇报好、接待好。”这是各级政府部门应付上级调研、检查、评比、考核的潜规则。“多栽花、少栽刺。”“上天言好事、下界保平安”“事不关己、高高挂起。”这几种也是官场上“调研者”的通病。"},{"id":162,"title":"官场一瞥之三：庸官之道术","category":"散文","date":"二零一零年六月八日","body":"由于几千年官本位传统文化的影响，出仕当官至今仍是大部分人追求的职业。“千里当官为了吃穿。”的意识已将“人民公仆”涮得苍白无力。尤其官场上的庸官为了保住自己的饭碗，可以不择手段，下面列举几例庸官之道术，以告各位看官。\n一是不学无术，就靠一个“混”字。有俗语调侃，“世上当官最省心，只要坐车头不晕，不通文墨也无碍，照本宣科顺着念。”因此，即有“西哈努克亲，王八日到京”的笑话。庸官不看书、不读报，口出：“小报抄大报、大报抄梁效”这样才会永远不犯错误。这种人没有专业特长，业务生疏不通，缺乏领导艺术，做报告有秘书准备稿子，开会发言或是顺着领导的竿子往上爬，或是海阔天空胡吹一气。他们张口闭口拿红头文件、上级指示压人，全然不顾此时此地的实际情况，做工作不知道工作抓手在哪里，联系实际不知道实际是什么，只知道跟风造势。遇事打官腔研究研究。对群众冷眼相看、冷言相待，对领导媚眼相献，肉麻追捧，竭尽阿谀逢迎、溜须拍马之能事。这种人酒场、舞场、浴场、麻将场上随时可遇，单位基层不见人影。这种人养尊处优、鞍前马后有人伺候，凭一个“混”字，却混得潇洒自如，甚至春风得意，青云直上，真叫人不可思议。\n二是左右逢源，单求一个“稳”字。有杂诗为证，“庸官庸不庸，置其风云中。遇事无主见，就像不倒翁。”这种人上传下达，就像复印机、传声筒，唯领导马首是瞻、跟在领导屁股后面转、看领导眼色行事，按上面意思办，不敢越雷池一步。工作不思进取、随大流缺乏创新精神，遇到问题绕道走，这种人是“墙头草”顺风倒，根本没有什么原则，东风西倒，西风东倒，看问题自己没有主见、人云亦云、见风使舵，处理事情没有自己的个性。对下级不敢管、对不正之风不敢抓，端着茶杯打哈哈、争取人气保“乌纱”。“不出乱子、守住摊子、保住位子。”是他们做人做事的唯一准则。\n骑马快、骑驴慢、骑匹骡子夹中间。庸官都是这嘴脸。\n三是工于心计，善于一个“装”字。送小诗一首。“恬不知耻混官场，瞒天过海巧于装。不识卢山真面目，道貌岸然尽假相。”现在市场上琳琅满目的商品，要想好卖，除了大量做广告外就是深度包装，官场上庸官们想要风有风、要雨有雨，就得想方设法包装自己。做官要有相对等级的文凭吗？他们有的大学的书一本也没翻过、课程一天也没学过，有的报上函授、由秘书完成作业并代考，也有的干脆拿钱买一个“大学本科”或“研究生”文凭，履历表上赫然填上“大学本科”或“研究生”学历，真才实学一点也没有。当官不是要政绩吗？他们报喜不报忧，鲁迅先生赞扬老黄牛精神，“吃的是草、挤的是奶”，庸官的汇报材料不喝饮料、数字也能挤得下水来，“路边工程”表面文章是他们巧于装潢的拿手好戏，一个个鲜艳夺目的“盆景”政绩，哪能不讨上级领导喜欢、升官自然。（当然遇上的也是糊涂官、大昏官、大庸官。）提拔不是要知名度吗？他们专门有一套写作班子为其捧场，开会报告、招商引资、开业剪彩，电视里天天有影、广播里经常有声、报刊上宣传有字，各种媒体轮番轰炸让当地群众家喻户晓、妇孺皆知，整天都是浮华的忙碌，老百姓真正关心的热点问题从不放在心上。\n四是不顾脸皮，放肆一个“闹”字。有打油诗为证：“闹是庸官一绝招，无是生非乱造谣。会哭孩子有奶吃，投机常把好处捞。”这些人成事不足、败事有余，在“班子”里常常搅局，自己不干事、让你干不成，或是自己不干事、专挑干事人的毛病，混水摸鱼、乘乱捞利，这种行为是可忍、孰不可忍，但我们的官场体制却偏偏不管此事，“乱中求稳、息事宁人。”好像就是处理这些人的办法。说得更夸张一点，这样的处理原则大有包容、纵容庸官胡闹之嫌。既有滋生庸官的土壤，必有庸官的产生。\n庸官的道术其实很多，在此略举一二，为的是让为官者举一反三，更多的反省自己。\n“当官不为民作主，只能回家卖红薯。”"},{"id":163,"title":"官场一瞥之四：涌动的暗流","category":"散文","date":"二零一零年十月三十日","body":"在目前市场经济条件下，潜规则普遍存在于各行各业，政治生活中的潜规则肯定是腐蚀剂，它会破坏社会的公平与正义、干扰社会的和谐与稳定、影响社会的管理与发展，政治生活中的潜规则是有序社会管理中的暗流，更是一个毒瘤。\n日前，饭后茶余偶从一份小报《报刊文摘》中看到北京大学社会学专业在读博士生冯军旗到中原腹地某农业县挂职副县长两年，经过深入调研后写出的一篇博士论文《官场生态》深刻地披露了他挂职所在县官场的内幕，道出了中国县乡政治实情。冯博士去的这个县是我国2000多个县级行政区中最为普通的一个，人口80余万，GDP在省里排40多位，主要经济以农业为主，他直接访谈了160多名副科级以上干部，对全县1013名副科级以上干部的简历、升迁奥秘，做过认真的探讨。在干部提拔晋升问题上直接与县委书记交流过，县委书记的答复是：“有些事情能说不能做、有些事情能做不能说，不可言传、只可意会。”\n干部提拔晋升靠什么？一要靠政绩，于是乎作假造势、大部分官员的政绩、真真假假、分不清楚，甚至不惜伤害了人民群众的根本利益为自己脸上贴金。二要靠送礼，每逢年节、领导家中有红白喜事，乡镇干部给县领导送、县领导给市领导送。有人调侃说：“一顶草帽都要好几元钱，何况一顶官帽呢？”三要靠拉票，民主推荐其实是幌子，被推荐对象获票多少却不可漠视，票多者当官是必然结果。因此，明规则禁止拉票、潜规则却默许拉票，拉票甚至被视为追求进步的信号，如果干部不拉票会被认为没有想法。四是一人当官鸡犬升天。干部要晋升并非完全靠金钱构筑的关系网，而是一张血缘与姻缘构成的政治家族网，在这个县里官位在家族内可以有世袭，凡是副处级及以上领导干部的子女、至少拥有一个副科级以上的职务、担任正科级职务的也不鲜见。有一位曾任县委副书记的家族，妹妹任副县长、妹夫任卫生局长、姑老表任畜牧局长，而他们的子女、女婿更是个个身居要位、大权在握，他（她）们有任海关关长、旅游局长、副区长、医院院长、工商局副局长、急救中心主任、新华书店党委书记。这个只有1000多科级职数的农业县里像这样的政治“大家族”就有21户、政治“小家族”140户。干部提拔晋升的潜规则由此可见。因此，联姻、认干亲的方式在这个县里有不断扩大化的倾向。这是一个县的官场概况，全国2000多个县基层官场生态又会怎样？照此类推全国600多个地级市的情况又会怎样？作者工作的地方“书记专业户”的故事早在20年前就演绎过。“太子党、秘书党”的传说其实早已不是传说。\n我们党内的潜规则更是潜伏在党组织运行的全过程中，如：意识形态方面的有：“不认主义认实惠”“不认组织认个人”等。决策执行方面的有：“只唯上不唯下”“走过场玩程序”“上有政策下有对策”等。选人用人方面的有：“少数人说了算”“平衡关系”“任人唯亲带病提拔”“民主选举、暗箱操作”等。干部考评中的有：“只注重GDP唯政绩论”等。党内政治生活中的有：“多栽花少栽刺”“家长制一言堂”“关系是第一生产力”等。腐败与反腐败方面的有：“公家的钱不花白不花”“抓小放大”“放水养鱼”等。林林总总党内这些潜规则无一不是执政党的害群之马！截断这些暗流必须真正树立起“立党为公”的观念，同时要靠公开透明的监督，切实有效的制度来解决。"},{"id":164,"title":"官场一瞥之五：生长的贪腐","category":"散文","date":"二零一二年二月春日","body":"历朝历代老百姓都希望自己所处的时代官场清正廉明，社会公平正义。官场清正廉明、社会公平正义、百姓才能安居乐业。 \n中国古代圣人君子不仅倡导官场清廉而且都是以廉为律、加强自身修养。《左传.襄公十五年》：&#39;宋人或得玉，献诸子罕。子罕弗受。献玉者曰&#39;以示玉人，玉人以为宝也。故敢献之。&#39;子罕曰：&#39;我以不贪为宝，尔以玉为宝。若以与我，皆丧宝也，不若人有其宝。&#39;\n汉.韩婴《韩诗外传》卷一：&#39;智者不为非其事，廉者不求非其有。&#39;宋.欧阳修《廉耻说》：&#39;廉耻，士君子之大节。&#39;《后汉书.杨震传》：&#39;荆州茂才王密为昌邑令，谒见，至夜怀金十斤以遗震。震曰：&#39;故人知君，君不知故人，何也？&#39;密曰：&#39;暮夜无知者。&#39;震曰：&#39;天知、神知、我知、子知！&#39;密愧而出。\n宋.包拯《乞不用赃吏》：&#39;臣闻廉者，民之表也；贪者，民之贼也。今天下郡县之广，官吏至众，而赃污擿发，无日无之。&#39;\n纵观历史凡皇上开明节俭、官场风正气清、必然惶惶盛世。凡改朝换代、江山更迭必然是贪腐奢糜成风、天灾人祸成气。民不聊生必然会揭竿而起。蒋家王朝的最后复灭是失去了人心，大小官吏置百姓于水深火热不顾而各自无不为&#39;五子登科&#39;不择手段而奔忙。&#39;得人心者得天下、失人心者失天下。&#39;&#39;水能载舟，水能覆舟。&#39;这是任何一个统治阶级都懂得的道理。\n党的七届二中全会上毛泽东同志就谆谆告诫全党：&#39;夺取全国胜利，这只是万里长征走完了第一步。......因为胜利，党内骄傲的情绪，以功臣自居的情绪，停顿起来不求进步的情绪，贪图享乐不愿再过艰苦生活的情绪，可能生长。因为胜利，人民感谢我们，资产阶级也会出来捧场。敌人的武力是不能征服我们的，这点己经得到证明了，资产阶级的捧场则可能征服我们队伍中的意志薄弱者。可能有这样一些共产党人，他们是不曾被拿枪的敌人征服过的，他们在这些敌人面前不愧为英雄的称号；但是经不起人们用糖衣裹着的炮弹的攻击，他们要在糖弹面前打败仗。我们必须预防这种情况。......中国的革命是伟大的，但革命以后的路更长，工作更伟大，更艰苦。这一点现在就必须向党内讲明白，务必使同志们继续地保持谦虚、谨慎、不骄、不躁的作风，务必使同志们保持艰苦奋斗的作风。......\n党中央从西柏坡移师北平时毛泽东同志形象地比喻&#39;这是进京赶考。&#39;因此，新中国第一大贪案的主角刘青山、张子善逆历史而动，他们的贪腐是以生命为代价的。毛泽东时代虽然物质比较贫乏、但官场的清廉让一些老同志回忆起来、至今还是津津乐道的。\n中国的改革开放给摆脱穷困、发展经济带来了机遇，也给贪腐滋生提供了土壤。殊不知市场经济法则中的&#39;经济利益最大化&#39;，只是经济管理活动中的规律，守不住清贫的官员们错误地认为这一规律、在任何场合都能适用，他们将人民赋予手中的权力作为权钱交易的法码，忘记了共产党人&#39;为人民服务&#39;的根本宗旨，或者只把它当作形式主义的口头禅，根本没有把胡锦涛总书记&#39;心为民所系、权为民所用、利为民所谋&#39;记在心上，却把&#39;有权不用、过期作废。&#39;视为谋一己私利的经典。\n2012年1月6日中央纪委监察部在京召开通气会，通报2011年全国纪检监察机关查办案件情况：据统计去年纪检监察机关共接受信访举报1345841件（次）其中检举控告类960461件（次）初步核实违纪线索155008件，立案137859件，结案136679件，处分142893人，其中给予党纪处分118006人，给予政纪处分35934人，被处分的县（处）级以上干部4843人，被移送司法机关县（处）级以上干部777人。\n最高检统计资料显示：全国依法严肃查办贪污贿赂等职务犯罪案32909件44085人，同比增加1.4％和6.1％，其中立案侦查贪污贿赂大案18224件，同比增加0.2％，涉嫌犯罪的县（处）级以上工作人员2723人（含厅局级188人、省部级6人）同比增加2％，立案侦查行贿犯罪嫌疑人3969人同比增加24.3％，追缴赃款赃物计74亿元。\n2009年我国可统计落马的企业家有95位、2010年这个数字上升到155位、2011年实破200位，202位企业家犯罪案除3例被通缉在逃外，199位分别处于&#39;双规&#39;或司法程序阶段。199例案件中、国企领导88例占总数的44.2％，犯罪金额成几何级上涨，2009年人均贪腐500多万元，2010年上升到人均957万元，2011年上升到3380.82万元，仅光明集团创始人董事长冯永明一人就贪污7.9亿元，如去掉这一特殊案例、人均贪腐金额也达到2077万元。\n河南省四任交通厅长&#39;前腐后继&#39;的故事决不是笑话，第一任曾锦城、第二任张昆桐、第三任石发亮、第四任董永安哪个不是信誓旦旦的说要接受前人的教训决不搞腐败。2006年湖南郴州市官场地震、市委书记李大伦、原市长周政坤、付市长雷渊利、市委付书记纪委书记曾锦春、组织部长刘清江、宣传部长樊甲生皆因贪腐落马、几乎是整个领导班子一锅端，这样的现象并不少见。据不完全统计改革开放以来落马的付部级以上的政府高官己有一百几十位，仅2011年就有6位，贪腐现象大有与经济发展同步增长的势头。看看以上既说明什么又说明不了什么的数据，是不是有触目惊心的感觉。\n腐败不断发生，迅速滋长的现象令人深思。总体分析大概有四条原因：一是教育的失败、二是制度的失灵、三是监督的悲哀、四是法律的软弱。\n这几年教育工作不断在搞如：&#39;三讲活动&#39;、&#39;党的先进性教育&#39;、&#39;科学发展观教育&#39;形式上轰轰烈烈，实际上受教育的人没有真正入脑入心。金钱拜物教使人心浮躁、贪欲膨胀，正面教育的效果往往敌不过社会上反面教育的冲击，有些主流媒体应当是对社会、对党员、对群众进行理想信念、传统道德、人生观、价值观教育的主阵地，但有的却成了无聊的娱乐工具。有不少的人并没有把理想信念、道德自律当一回事，实际上是教育的失败。\n人性如水，制度如渠。邓小平说过，还是制度可靠些，当一些官员像飞蛾扑火一样重蹈腐败之覆辙，那就不仅仅是一个道德自律问题，肯定要从制度上找原因，建立良好的监管制度，推进民主决策化，实行权力透明运行，才有可能从根本上扼制前腐后继现象的发生。\n这几年党内制定了不少制度如《中国共产党党员领导干部廉洁从政若干准则》、《中国共产党纪律处分条例》、《中国共产党党内监督条例》（试行）《关于领导干部报告个人重大事项的规定》等等，制度本身的内容很多也很好，但贯彻执行的力度不够，落实不到位，效果到底如何？有目共睹。\n现在党内监督、社会监督、上级监督、群众监督、與论监督好像监督无处不在，事实上对&#39;一把手&#39;的监督几乎是失控的，有人总结&#39;一把手&#39;是：财务审批上一支笔，选人用人上一人定，民主集中制上一霸主，权力运行上一把抓，监督制约上一空文，腐败主体上一家人，公开形象上一假象。监督仅是聋子的耳朵，在&#39;一把手&#39;的独立王国里所有公共资源他都可以任意支配。&#39;不怕权力大、就怕权力不怕啥。&#39;这实际上是监督的悲哀。\n说官场上贪腐成风是否有些夸张，但事实是贪腐的官员越来越多、官位越来越高、金额越来越大。虽然成克杰、胡长清、郑筱萸......也判了死刑，但判严刑的相对较少，寥寥无几。绝大多数腐败分子总是心存侥幸心理，甚至更加疯狂敛财、动辄几百万上千万，即使被查办成本也很低，判死刑可缓，判无期可减，体现的是法律的软弱。我不是一个迫害狂，我认为官员既然是社会的管理者，那么就应该是社会文明的倡导传播者，更应该是社会文明的典笵与偶象，是百姓学习的榜样。凡愿到公务员这个领域的就应该耐得住寂寞、守得住清贫，一言一行要为百姓着想，一举一动要对社会负责。凡敢触碰贪腐这根高压线的、十万元以下让他获牢狱之灾，身败名裂。十万元以上就让他上断头台，家破人亡。否则贪腐之风何日能除？\n反腐倡廉、任重道远。所述的四条原因仅是管窥之见。真正的是教育、制度、监督、法律落实得都不到位。同时我国是一个人治社会、人情社会、有几千年的历史沉淀、有滋生贪腐的土壤，如果不从根本上去触动去改革、政风清廉就可能遥遥无期，所好的是依法治国的进程在痛苦中依然得到不断的推进，这是希望所在。\n改革开放国外的经验不能学习吗？尊重历史、古人的经验不能借鉴吗？古人都知道&#39;修身、齐家、治国、平天下。&#39;是官员的基本功，在物欲横溢的今天、修炼君子之风、用良心和道德的约束、首先管好自己，才算一名基本合格的清官好官。\n郭沫若先生1944年3月发表的《甲申三百年祭》当时就受到中共中央的重视，毛主席亲自批示将此文作为延安整风重要文件之一，组织大家学习。现在重温这篇文章有没有必要、有没有意义呢？"},{"id":165,"title":"官场一瞥之六：奢糜的接待","category":"散文","date":"二零一三年七月一日","body":"中国是文明礼仪之邦，凡有客人来都要摆酒接风，以彰显主人的礼节礼貌。因此，历史上就有&#39;有朋自远方来不亦乐乎&#39;的古训，&#39;公务接待&#39;古就有之、据考证秦始皇建郡县制以后官场就逐渐出现了接风饯别等宴会，魏晋南北朝时期、各州郡都设置了&#39;送故主簿&#39;的官职（相当于现在的接待办主任）专司接待工作，宋朝时甚至明文规定：&#39;凡点检或商议公事、出郊劝农等，皆准公筵。&#39;明、清官场的接待之风达到了顶峰，不仅是吃喝无度而且还要有&#39;程仪&#39;&#39;折席&#39;&#39;跟随&#39;等众多名目的财礼相送。搞接待本来是无可厚非的事，主要是不按标准、奢侈浪费、互相攀比、场面宏大，才搞得怨声载道，现如今的接待较之古代只有过之而无不及。搞好接待本应体现在：气氛上要热情大方、态度上要不卑不亢、举止上要有礼有节、招待上要适当节俭。\n在上世纪物质匮乏的六、七十年代，主人总是倾其所有招待客人以表现自已的不吝啬，不失体面。&#39;穷大方&#39;可能就是中国人的&#39;待客文化&#39;。至今，酒宴上主人向客人敬酒自己不喝的习俗可能就此沿袭而来。\n改革开放以来我们的物质生活得到了极大的改善，物质丰富了但接待的理念仍然没有变，吃喝之风、公款送礼屡禁不止，大有愈演愈烈之势，据主流新闻媒体报道&#39;中国铁建&#39;这一企业经审计2012年至2013年上半年的接待费就达到了8.6亿元之多。看起来花的不是纳税人的钱，但大型国有企业的钱也应该是老百姓的钱吧？中国人在餐桌上的浪费一年就达2000多亿元，其中绝大部分是公款。综观现在的公务接待是太奢糜了，餐桌上名酒名烟、山珍海味，一桌饭轻则几千重则上万元，饭后要小姐陪唱卡拉0k，泡脚洗澡，会议考察还要准备礼品。据说有一个省到香港招商引资，安排参会人员的早餐人均一千多元，使香港的老板也为之咋舌。&#39;主人&#39;化的都是纳税人的钱，当然不心疼、不可惜。社会上曾流行这样的说法&#39;公务员真逍遥，吃、喝、嫖、赌都报销。&#39;改革开放以来党中央也几次发文要求对接待工作进行整改、希望刹住奢糜之风，可总是上有政策、下有对策，中央曾规定接待用餐&#39;四菜一汤&#39;，有的地方就换个形式用&#39;四大盆&#39;每盆四个菜。2006年财政部开始推行党政机关出差和会议定点饭店制度，被视为遏制公务浪费和腐败的&#39;利器&#39;，在&#39;档次适中、价格合理&#39;的原则下，全国31个省（市、区）的4740家定点饭店仍近一半是四星五星级，会议费更是一个&#39;大筐&#39;，饭店的态度是多多益善，主动提供奢侈品、娱乐甚至色情消费都能装进去，钱花超了可以多报人数、天数来找补，开发票让你回去报销做账，饭店不说、真实性就很难查，\n整治接待奢糜之源总不理想，究其原因还是接待理念问题、体制机制问题和管理制度问题，既规定了接待标准，下级为何不愿去执行呢？道理很简单其一、按照官场权力规则、上级对下级永远掌握着考核监督、升降去留权，下级主动逢迎就成了本份。其二、所花款项皆属公款，个人不失皮毛，不负任何责任，何乐而不为呢？其三、现在的领导喜欢讲排场、出风头的人不少，接待不好、满腹牢骚，下级不得不去逢迎。我曾到日本、澳大利亚学习考察，对方接待很简单、全在员工食堂吃快餐，省却了许多无聊的应酬，既自由又不浪费，很值得国人在接待方面学习借鉴。党的十八大中央制定了&#39;八项规定&#39;，奢糜之风有所收敛，真希望能巩固扩大效果，使毛泽东同志&#39;贪污和浪费是极大的犯罪&#39;的论断深入人心，党风进一步得到好转，这是一个有40多年党龄老党员的期盼。"},{"id":166,"title":"官场一瞥之七：赃官的买卖","category":"散文","date":"二零一四年十一月","body":"如今的官场真让人有所看不懂，会干的不如会说的，不钻圈的不如会划圈的，眼睛朝下的不如眼睛向上的，亲民的不如霸道的，清廉的不如腐败的。仔细看看，认真想想这些人的&#39;官&#39;都是花钱买来的。\n过去传言部队团级到师级要花60万，师级到军级要百万以上，似乎各级都有明码标价，让人不可思议。今年曾任解放军总政治部主任、中央军委纪检委书记、中央军委副主席的徐才厚事发，让不可思议变成了无可非疑。地方上买官卖官的丑恶现象、同样也不少，最近落马的河北省委组织部长梁滨可能就与卖官买官相关。\n据说买官卖官也有规律可循。一般买官的分为三类人，一类是&#39;升职型&#39;，即副职想转为正职或向上提一级。第二类是&#39;平调型&#39;，即从穷单位调到富单位，从权力小的部门调到权力大的部门，从经济欠发达地区调到经济发达地区。第三类是&#39;入仕型&#39;即企事业单位非政府行政部门想到行政部门当官的人，或是党政部门一般工作人员想进领导层的人。\n卖官的一般为两类人，一类是在干部人选上大权在握的党政一把手，第二类是分管组织人事的领导、组织部长，或能为买官者提供帮助的党政领导干部。\n发生买官卖官的时间主要集中在两个时期，一是&#39;换届期&#39;，换届选举、干部交流提拔得较多、一些买官者可混水摸鱼，二是领导&#39;上任离任&#39;时，领导干部上任后会对干部进行一些调整，买官者即会投石问路伺机买官，领导干部离任时着急处理一些遗留的问题，以免留下后患会主动卖官，也给买官者提供了机会。\n中国是一个人情社会，买官卖官的人很会运用逢年过节这个时段，此时买官者会带着厚礼登门拜访，以求一官半职，卖官者坦然接受，以官相许。另一个易发时段是遇到特殊情况、如领导及其家人有生病住院，婚丧嫁娶、添丁增口、子女考学，领导出国等时机，买官者会不惜钱财大加表现，以求得到提拔调动。\n买官行为主要分为三种，一是温柔型，放长线钓大鱼，隔一段时间买官者会主动表示一次，不达目的决不罢休。二是体贴型，当领导家中&#39;有事&#39;，买官者都会主动登门、鞍前马后、慷慨解囊、雪中送炭。三是急切型，买官者必投其所好、以表&#39;亲切&#39;，在短时期内会投巨资激烈猛攻，很快如愿。\n卖官者行为也分三种，一是暗示卖官、即在干部调整前先放风，或干部调整后不急于任命，让许多人赶紧送礼。二是半推半就，嘴上说不要，手上照接受。三是直接索取，对职位明码标价，钱不到位就不提拔。\n买官之人&#39;官&#39;是花钱买的，怎能真心去为民服务？花钱买官怎能光赔不赚？必然会大肆搜刮，敛财于民。卖官的、此钱来得容易，花得潇洒自如养情人、包二奶、下赌场。殊不知这都是民脂民膏。\n买官卖官既有规律可循，就应该有法可治，放而任之，养痈遗患，必損党信国威。\n买官卖官的丑恶现象，不铲除必丧党心、民心、人心。党的十八大后、中央决心从严治党，严惩贪腐，自开展&#39;打虎拍蝇&#39;活动后、贪腐分子纷纷落马，对买官卖官者虽可以儆效尤，赢得人心，但如何才能做到表里兼治、斩草除根？让买者不敢买，让卖者不敢卖，除了让为官者加强道德修养，严于律己之外，更重要的还是得靠严明的党纪国法和严格的制度管控。\n官场上无论是卖官者还是买官者都要时刻牢记：&#39;莫伸手，伸手必被捉&#39;。\n官场廉洁风清气正，百姓如愿方见青天。"},{"id":167,"title":"怀念恩重如山的父亲","category":"散文","date":"二零零一年六月十五日","body":"他走了，他静静的走了，他饱经沧桑载着一个世纪的坎坷与平凡、勤劳与俭仆、慈爱与善良，心地坦然的离开了他所爱和爱他的六个子女到另一个世界孤独远行。他就是我们的父亲、恩重如山的父亲，这天是公元二零一一年的四月二十八日下午二时四十五分。（农历三月二十六日）\n今年八月，父亲就一百岁了，我们子女都盼望热热闹闹的给他过百岁大寿，但事实又是这样的无情。\n回忆父亲的一生、虽无可以树碑立传的事，但在我们那个只有几万人的小镇及周边村庄，父亲的德高望重，是乡亲们有口皆碑的。在儿女心目中父亲更是一位慈祥可亲的老人。写下他一生中为人处世的点滴印象，是为了永远的怀念他。\n大爱是无言的，只有用心才能体会得到。朱自清先生的一篇《背影》真情实感的把天下父爱写得淋漓尽致。朱自清先生在文章中写道：......&quot;我看那边月台的栅栏外有几个卖东西的等着顾客。走到月台那边，须穿过铁道，须跳下去又爬上去。父亲是个胖子，走过去自然要费事些。我本来要去的，他不肯，只好让他去。我看见他戴着黑布小帽，穿着黑布大马褂，深青布棉袍，蹒跚地走到铁道边，慢慢地探身下去，尚不太（大）难。可是他穿过铁道，要爬上那边月台，就不容易了。他用两手攀着上面，两脚向上缩，他肥胖的身子向左微倾，显出努力的样子。这时我看见他的背影，我的眼泪很快地流下来了。&quot;......\n在登火车前为远行的儿子买几个桔子、常人看起来是最不起眼的事了，父亲这种最普通的行为却是人类最伟大的无私与真爱。当你从内心体会到这种爱才是最感人的。\n我们的父亲留给我们的爱也是无言的。我每次探亲回转时他总要送我们，看到我们的车走了很远才肯回家。记得去年五月我和夫人一起回乡看望他，临走时执意要送，我们拗不过，只好让九十八岁的老父亲用一辆平时他乘坐的残疾人专用手推车，把我们的行李推送到一公里外的汽车站，汽车开动时他用很伤感的语调和手势与我们挥别，我们只得将泪珠含在眸中、假作高兴的样子承诺再回来看他，回想起当时的情景至今历历在目，心情一直凝重得很。今后除了梦里相见，再不可能看到他送别我们的身影了。\n天下父母只要是为了儿女一切都可以献出。可是儿女给父母的回报又有多少呢？有句俗语：&quot;父母的心在儿女身上，儿女的心在石头上。&quot;可怜天下父母心。\n我自认为是一个孝子，有孝心尽孝道，但回顾对父亲的赡养还是有愧的，物质生活基本可以满足，但精神慰籍特别是晚年侍奉在他身旁还是很不够的，我只能用&quot;忠孝难两全&quot;这句话来为自己开脱。但在我心中，父亲留给我们的爱确实是永恒的精神财富。\n父亲坎坷平凡的一生，是踏着时间走过来的。他出生在一个从他曾祖父起由安徽休宁县山斗村远迁江苏的儒商之家，是时、家底还颇为殷实。因社会动荡、生意萧条、几代人下来、到我祖父时家道早己衰落、家境也就十分贫寒，父亲兄弟姊妹五人，三个男孩中他是老大，十三岁时就外出谋生、为我爷爷分担生活重担。解放前是在飘泊不定的日子中度过的。前半生辗转于上海、浙江、江苏、安徽多个城市，所干的职业不少、当过洗染厂的工人、轮船上的庶务、专卖公司的文员、多家绸缎店、杂货店、酱园店、书店的店员、也为勉强度日摆过小摊经营。那个年代一年半载，失业换行当是常有的事。解放后公私合营加入供销合作社后，工作才趋稳定，一生以经商为主直至六十五岁退休。父亲无论是旧社会为老板打工、还是新社会为人民工作都是勤勤垦垦、競競业业、任劳任怨、一丝不苟的。旧社会找一份工作不容易，想保住工作更不容易，没有勤奋与努力就没有饭碗，我想这就是他一辈子对工作为什么特别认真负责的缘由吧。\n父亲虽不是党员、但他是一个有感恩之心的人，懂得知恩必报。他深知今天的好日子来之不易，是党领导得好。去年九月底组织上让我带队参观世博会，结束后正好是国庆长假、顺便回了趟家，离家时他还是跟以往一样再三叮嘱我说，组织和领导培养你、重用你，你一定要听党的话、听领导的话，遵守党纪国法、不要犯错误，一定要把老百姓的事放在心上，尽职尽责、努力工作，用实际行动来报答党组织和领导的关心。这就是几十年来父亲对我最朴素的要求和殷切的希望。参加工作四十余年、入党也近四十年，今年即将退休。他的叮嘱从未间断过，我也从未忘记过。我从一名一般干部成长为一位副厅级领导干部，无论任何情况即是在市场经济、人心为金钱物质所浮躁的情况下，我始终牢记父亲的忠告，把听党的话当作座右铭和人生奋斗目标，在不断的努力和实践着，一步一步走到了今天。父亲的话一句一定顶一句，我会永远铭记于心、让它伴着我走完一生。\n父亲勤劳俭仆的一生，是背着责任走过来的。在我们兄弟姊妹年幼的时候、正逢三年自然灾害，家庭生活是很困难的，我姐考取高中时差点缀学，在亲友的资助下且未荒废学业。大弟小学毕业即到社办厂工作，我是读到初中毕业，因为文化大革命和家庭的实际困难，无学可上、有学也难上、就此缀学，参加工作后又入伍参军。我是一个比较爱学习的人，因缀学一度对父母还耿耿于怀，后来自已支撑生活时，才理解当时靠父亲一人大概三、四十元的月工资养活一家何等容易啊。在那个有什么想法都白搭、有劲也是使不上的年代、父亲竟敢冒着被割资本主义尾巴的风险、养了几只剪毛兔，用兔毛换一点日常需要的油盐火柴，把唯一的抽烟嗜好也彻底的戒了，处处想法开源节流，维持着一家最简单的生活。现在生活条件好了父亲仍然十分节俭、衣着虽然朴素却收拾得很干净。他从不乱花钱，经常教育我们，有时要当无时过。我们兄弟姊妹六人早已成家立业，生活条件都还算不错，血脉连绵他已五世同堂，晚辈有四十几人。哪个子女临时有困难总是悄悄的给些补贴，他也不吝惜。我们兄弟姊妹也互不计较。他说十个指头咬咬个个疼，看不得儿孙有苦有难。临终前还将所存不多的积蓄均分成六等份、人人一份。父亲这些好品德早就印在我们心灵上，永远不会被抹掉。我们要做一个负责任的人，无论是对家庭、对单位、对社会都应承担起应尽之责。\n父亲慈爱善良的一生，是伴着智慧走过来的。他年轻时只读过几年私塾、文化程度不高，但他却坚持自学，特别是退休后一直坚持记日记、把家中的零碎小事记得一清二楚，无事时爱拉京胡哼几句京剧，还坚持研究书法楹联、诗词格律、栽花种草、养生益寿、终生不缀。八十六岁时为我楷书一幅《朱子家训》收藏至今。世界观受到了儒家思想潜移默化，优秀的传统美德当然也成了我的安身立命之本。父亲给我写《朱子家训》的良苦用心，我是随着时间推移才慢慢体会到的。前年，国庆六十周年之际他亲书自已诗作一首、参加文化馆的比赛、还分别获得了书法奖和诗作奖。\n实际上在我们很小的时候父亲就用儒家思想熏陶我们，他将&quot;勤有功，嬉无益。&quot;写成对联贴在门上，勉励我们好好学习，改革开放后、在党组织的培养下我才有机会读了中央党校在职党政干部管理大专和经济管理本科两个专业，才有今天的这点文化功底。无论从哪个方面看、父亲的教诲我都是获益匪浅的。\n从我儿时记事起，我就不记得父亲对我有过严励的责罚，犯了错基本上是给我们说理，让你懂得错在什么地方、应该怎么做。严父慈母，在我们家似乎颠倒过来了。对我们的教育上相对来讲母亲还是比较严励的，母亲说，上等之人自成人，中等之人教成人，下等之人打成人。小时候在母亲面前不听话是要挨板子的。自小至今学会做人、做事，皆无大错，应该是父母养我育我之功，父母于我们确是恩重如山。\n父亲一生为人处世，从不与人争高低，宁可自已吃一点亏，得理也可让人，这并不是父亲的却懦或无能，而是父亲的智慧。&quot;六尺巷&quot;的故事最早就是父亲讲给我听的。左邻右舍、乡里乡亲凡有困难他一定都会尽力帮助的，从不因&quot;善小而不为&quot;。慈爱善良、遇事放得下，这可能是他受人尊重、也是他长寿的秘决。\n父亲的晚年还是比较幸福的、不仅享受到了改革开放的成果，退休工资还不断见涨、衣食可谓无忧，而且我们当子女的也比较孝顺、想方设法安排好他的生活，从去年起共同出资、找了护工专门照顾他的饮食起居，他自已也很努力、尽量不给儿女和别人添麻烦、生活基本自理。头脑一直清楚，今年春节后体力才有所不支，父亲一辈子是一个明白人。\n小弟电告父亲弥留之际想见一面、四月二十二日先夫人急驰回家。无论是儿女的情感、还是现代先进的医疗技术终未能留住他。生老病死之规律是谁也打不破的。治丧期间省局和嘉峪关市工商局的领导十分重视、分别派员远赴江苏参加吊唁活动，诸多同仁好友也纷纷表示悼念，令我全家不甚感激之至。"},{"id":168,"title":"管与不管：一个管理者的心语","category":"散文","date":"二零一六年清明节","body":"前些日子的一个早晨，到太康市场买菜，偶然看到这样一个场景，菜市场外面的一些小摊贩主和城管关于收摊的要求进行讨价还价，小贩们说：&quot;再等会儿、再等会儿。&quot;城管执法队员说：&quot;不能再等了，再等我的饭碗可能就要丢了。&quot;我饶有兴趣的驻足倾听，观看小贩摊主急怱怱的收拾货物，准备离场。心中由然而生感到这是社会进步了，执法人员和小摊贩业主的法制意识都加强了，人们素养的提高，必然会引起执法方式方法的变化。任何事件都要相互理解就对了。\n这场景不由我想起十几年前，我生活的那个小城市，市场外的摊贩是由工商部门管理的，当了二十多年的工商局长，看市场监管执法人员管理摊贩是最常见不过的事儿了。在我的印象中市场管理执法人员与这些临时摊贩业主的关系，好像是老鼠见猫，他们看到管理执法人员卷起货物撒腿就跑，跑得慢的货物就有可能被踢得乱滚，称杆子被折断、货物被没收。每次这样的执法都会引来很多群众围观，甚至引起矛盾激化，管理与被管理者的矛盾，非要这么尖铭锐吗？这情景是我这个当领导的最不愿意看到的。\n当时社会上普遍认为个体都是万元户，其实不然，每年我都随个私协会家访个体户，有的真贫穷得狠，做小买卖只是为生存、图一个简单生活。当时的个体工商户真是一个弱势群体，需要社会各方面的关注、理解与帮助。\n管理执法是公务员的神圣职责，但绝对的&quot;神圣&quot;很多很多都会化成后来的&quot;荒诞&quot;，只有时间、历史经验、社会常识才是最强大的武器。只有经过时间、历史经验、社会常识检验后认为是正确的才是最可靠的。&quot;实践是检验真理的唯一标准&quot;千真才确。\n想起有一年酒泉附近驻军的一名基层干部、利用星期天着便装到嘉峪关来练摊，与管理执法人员发生争执，在肢体接触中碰坏了人家下身，引起了纠纷，惹下了麻烦，为处理好这起军民关系的大事，真还费了不少周折。\n处理此事时，我站在双方的立场上来考虑，似乎任何一方都没有大错，小贩卖点货物赚点钱补贴生活、还方便群众算什么过失？执法人员为规范市场管理，疏通城市交通秩序有什么不对？细想起来只是管理方法不得当。后来常用此例教育下属，执法一定要人性化。生硬执法一定会受到批评。经过一段时间的努力在我们单位、还确实收到了良好效果，受到群众的好评。\n法律和法规是刚性的是硬东西，如果不坚硬、人们可以随意触碰，久而久之法律法规就会如同一堆烂泥形同虚设。法律法规的刚性是原则，但除此之外，人们生活当中也还需要刚性之外的柔软，这就是良知和情理。其实法律法规也不是同等的。如果将法律硬度用摩氏来计量的话，法律为摩氏七度、法规则是摩氏六度、政策则可能是五度了。这种硬和软之间一定会有一个缓冲地带。\n&quot;一管就死、一放就乱&quot;好像是宏观和微观管理中永远都很难解的两难题，其实不然，只要管理执法人员顺势而行、视情而定，把握适度，就会游刃有余，就会使执法工作处于合法、合理、合情之中。会将管与不管拿捏准确、才是一个好的执法者，才是一个合格的领导。\n生活中对每个人每件事都应该如此。因此，在是与非之间，在权力与欲望之间，需要建立一个缓冲地带，这个地带就能够给后来的进与退留一点余地，给后来的调整与纠偏留一点空间，这也是我几十年工作中举一反三总结出的&quot;冷处理法&quot;。仁者见仁、智者见智，如有点滴可用，也算是有经验传人。"},{"id":169,"title":"胡杨精神","category":"散文","date":"二零一四年植树节","body":"南桔北枳，是说植物自已不能择地而生，随着环境的变化其本质也会逐步变异。具体以纬度多少为界分为南方北方？实在没有认真考察。生长在南方的桔子果实扁圆、果皮红黄、果肉酸甜以甜为主；生长在北方的枳子果实稍圆、果皮黄绿、果肉酸甜酸涩为重。我们家乡有一种木本植物叫香橼其外形和果实都与枳的描述相似，亦或香橼即枳未可而知，起码桔、枳、香橼都是&quot;堂兄弟&quot;。\n植物既不能自已择地而生、只好安于自然、随环境改变自己，有符合生存条件时才有可能生长得根深叶茂。我曾在桂林的阳朔景区看到一棵有1400多年的大榕树、传说是广西壮族歌仙刘三姐与其情郎牛哥的定情之处，此树生长盘根错节、占地有好几亩己成一片树林。气候温暖、阳光充足、雨水充沛是它能生长茂密的先决条件。\n更有值得惊奇的是我在宝岛台湾的阿里山看到的桧木有的三代叠生在一起、有的粗壮得像象鼻、形状各异，最大的一棵桧树树龄己有千余年、树高40米、树围要有15人手拉手围一圈才能相抱，生长在潮湿地带的桧木与生长在戈壁沙漠中的胡杨同样有生而千年不死、死而千年不倒、倒而千年不朽的奇迹。\n由于南方气候温和、雨水充沛、植物的多样性及其能蓬勃发展、细想起来应该无所奇怪。\n生长在北方的树也有值得夸赞的，记得上中学时就读到茅盾先生1941年3月发表的一篇著名散文《白杨礼赞》，白杨生长在北方贫瘠的土地上、主干3-4米以下浑圆通直没有任何枝杈、主干以上的枝杈也是挺拔向上生长着、决无横七竖八，旁逸斜出，茅盾先生通过对白杨的赞美讴歌了正在坚持抗日战争的北方农民及其所代表的中华民族正直、质朴、坚强、力求上进的精神。\n我出生在南方、但工作几十年都在大西北，因此对生长在大西北的胡杨树更加熟悉、因为它比松柏有更多值得歌颂的地方，我对它有发自内心的倍加赞赏。胡杨是一种古老的植物，生存在地球上己有一亿三千万年的历史，可能比植物学家们认为，活着的古植物标本银杏树还要长，世界上绝大部份的胡杨生长在中国、而中国90％以上的胡杨生长在中国西部，塔里木盆地有3800多平方公里生长着胡杨，目前新疆沙雅县拥有世界第一大面积达366．22万亩的天然胡杨林，占全国胡杨林总面积的四分之三。从甘肃酒泉金塔县的天仓乡经酒泉卫星发射基地、延伸到内蒙古西北部的额济纳旗居延海、长约200公里、宽约15公里的大漠上，也是胡杨树的生长带，面积约有85万亩。&quot;胡杨红柳护大漠，芨芨芦苇不示弱。&quot;、&quot;古今文明汇東风，艰难困苦育英雄。&quot;（酒泉卫星发射基地又称东风场区）这是我对胡杨精神的赞美。额济纳旗同样是世界著名的胡杨林景区，因为工作关系我有幸多次去参观过。\n胡杨树属杨柳科，别称胡桐、异叶杨，落叶乔木、树高15-30米，幼树和嫩枝上密生柔毛，值得奇怪的是胡杨树的叶片一生变异很大，在幼树或嫩枝上的叶片呈线状披针形、短枝上的叶片呈菱形、成熟的树叶成卵形或肾形，（所以胡杨又称异叶杨）叶片上有蜡质能锁住水份，为其能在干涸的荒漠中生长提供了保护，胡杨开紫红色披针形花、结长橢圆形葫果。\n看着一片片置身于大漠与命运抗争的胡杨林，令人由衷感叹生命的坚强，从合抱粗的老树到不及盈握的细枝、横逸竖斜、杂芜而立、然而无论柔弱、无论苍老，总有一抹生命的绿色点染着枝梢，彰显着不屈的生命力。无论生存环境多么恶劣、生长条件多么艰辛，每到金秋十月、株株胡杨都会披红挂金。金黄色的胡杨林会与蓝天白云夕阳彩虹相映成趣奉献给天空；金黄色的胡杨林会给林间幽径铺设一条金光大道奉献给大地；金黄色的胡杨林会将喜获丰收展现成熟满足意境奉献给人们。胡杨扎根在盐碱沙地戈壁荒漠上、并从中汲取很少的养分不断的壮大自己。胡杨以极其恶劣的生存条件、不倔的生命抗争回馈给大地的却是一片美丽。胡杨的伟大还在于、它承载着人们的万般思绪，让人们领悟到了人生的真缔。\n胡杨是长寿的植物、生而千年不死、死而千年不倒、倒而千年不朽。无论是虬结苍劲、枯干张扬的，无论是活着、还是死了的，形形式式的胡杨都是挺直着脊梁的。\n当然，人们看树是看风景，无论从时间和空间的角度都应该以仰视的心情抬着头看。金秋的胡杨林是大自然贡献给人们的一幅美仑美涣的画作，它是缓释人们浮躁、净化人们心灵的广而告之。喜好攝影的人们都涌向这里用手中相机记录着美好回忆、憧憬着未来。\n中国摄影家协会理事王金先生是我的好友,曾送我一幅放大的杰作《胡杨秋色》,那种自然、那种質朴、那种色彩、那种坚忍不拔，至今仍让我爱不释手。\n树看人是看人间万象，无论从时间和空间的角度都应该是俯视，看到的是沧海桑田的过眼烟云；看到的是怱怱过客的喜怒哀乐；看到的是盛衰沉浮的人生轮回。用树的视角看人生也是一幅风景，可以帮助调整人生轨迹。\n人类与胡杨本是两种不同的生命、却共生与天地之间，人与胡杨命运应无互相交错的理由，但又逃不脱共同的自然法则。人类具有智慧、创造了工具成为万灵之首，掌控了生杀予夺任何生命甚至同类的大权、寿命却不过短暂百年，人性中的贪得无厌是彻底毁灭自己的腐蚀剂。胡杨无灵智、选择不了生存之地，只好物竞天择，听任苍天的摆布在最严酷的沙漠戈壁中悄悄生长、无怨无悔，更无奢望、甚至可以逆来顺收，不争世间主宰却可轻易活过千年。人若如斯该多好呀！\n人与胡杨谁为高贵？自有评说，当人返本归原化为一抔黄土时、也许就成为胡杨的养分，今世的索取就可能成为来世的付出、，任你是平民百姓、显赫权贵还是盖世豪强终不能例外--。\n这世上总有公道，总存在着公平！"},{"id":170,"title":"观菊遐思","category":"散文","date":"二零一九年重阳节前两日","body":"&quot;人之初、性本善&quot;后来随着环境的变化就有可能慢慢的发生了改变&quot;近硃者赤、近墨者黑&quot;就是这个道理。当然追求一生做一个善良的好人还是不乏其人的。因此，就有了以物喻人品格的方式，花中四君子即是这样。&quot;梅&quot;剪雪裁冰、顶寒绽放象征着傲然不屈；&quot;兰&quot;空谷幽香、孤芳自赏象征着与世无争；&quot;竹&quot;筛风弄月、潇洒一生，象征着正直坚毅；&quot;菊&quot;凌霜自行、不趋炎势象征着刚烈无媚。综观之共同点都有清华其外、澹泊其中的仙风道骨。我曾用《蝶恋花》词牌各填词一首赞美过&quot;岁寒三友&quot;和&quot;花中四君子&quot;。\n我除了爱莲也爱菊，退休后常莳花弄草打发时光，学习菊花的栽培知识几乎着迷，在无锡定居将近十年，每年重阳节前后、锡惠公园的菊展必不会放过的。\n菊花的品种很多，按花期可划分为夏菊每年5月、9月各开一次，秋菊的花期每年10至11月盛开，冬菊每年12月至次年1、2月开放。尤有秋菊的品种多。按花径长短可划分为小型6公分以下，中型6公分至10公分，大型10公分以上。按花的颜色可划为单色复色两种、单色又有若干种，复色也有若干种。如按种植方式、花的作用等等还可以有多种分类法。这里介绍几种常见的品种&quot;墨牡丹&quot;型似牡丹色如丹渥大气典雅，&quot;白牡丹&quot;型似牡丹色如白雪洁白无暇，&quot;瑶台玉凤&quot;白色花瓣包裹着黄色花蕊有一种雍容华贵的美感，&quot;仙灵芝&quot;花瓣纤细、尾部呈橙黄色亭亭玉立俊秀大气，&quot;天鹅舞&quot;花瓣一部分向外一部分向内如同一只起舞的仙鹤，还有小雏菊、天葵、绿云、墨荷、帅旗、型与色可各领风骚一片 。\n说起菊花自然会想起东晋靖节先生（陶渊明）采菊东篱下，悠悠见南山的名句，也必然会联想到历史上众多的仁人志士，隐喻菊的操行。\n今年的重阳节正好在国庆长假间，重阳节前两天去锡惠公园看菊展，从惠山古镇的老街进园，园内通往惠山寺的甬道上游人如织熙熙攘攘，两边设有长长的花架，盆花列阵分品种摆放，园内其它地方也随处可见菊花依于竹，偎于松、彩于池、垂于墀，真可谓霜染菊花肥......胖瘦齐聚、形色齐备，浮丹流翠、五色杂阵，小雏菊也叠堆成锦，大概有二、三十个品种。这又让我想起2012年11月底去宝岛台湾观光旅游时，在&quot;士林官邸&quot;（原先是蒋介石夫妇居住和办公的地方后僻为公园），所参观的菊展无论是规模之大、品种之繁还布展的精巧都远胜眼前一筹。特别有一品种&quot;大丽菊&quot;是他们自己培育出来的很稀贵。\n菊展是一种集大成，可在最短的时间、最小的空间，有最多菊花让人一睹为快，但缺乏幽然灵动。坦率地说菊展能让我所爱但又存遗憾。让本属于乡野田园、溪流岩边、点缀于舍前篱旁，一簇一丛萧疏随意而生、随风潜送暗香的野菊花回归于自然欣赏起来是不是才更有情趣。"},{"id":171,"title":"观尼亚加拉大瀑布有感","category":"散文","date":"二零一二年五一节前","body":"今年四月出访美国、加拿大期间，有幸参观了尼亚加拉大瀑布，尼亚加拉大瀑布号称世界七大奇景之一，有时又直译为：&quot;尼加拉瓜大瀑布&quot;，&quot;尼亚加拉&quot;在印第安语中意为：&quot;雷神之水&quot;。尼亚加拉大瀑布也是世界三大瀑布之一。\n尼亚加拉大瀑布，源自流经南起美国纽约州布法多的伊利湖，北到加拿大安大略省杨格镇的安大略湖的尼亚加拉河，全长５４公里，大瀑布正好位于尼亚加拉河的中段，河流上游水面有2－3公里宽，落差15米、水流较舒缓，从伊利湖北岸32公里起河道变窄，水流加速，在一个90度急弯处，河道上横亘了一道石灰岩构成的断崖，落差从174米突降至75米，形成瀑布。瀑布的流水面宽约1160米，如果加上两个岛屿宽约1240米，气势非常磅磚，场面相当壮观。\n尼亚加拉大瀑布有三部分组成，河水经过河床绝璧上350米宽的公羊岛分別流入美国和加拿大，－部分是美国大瀑布，另一部分是加拿大马蹄形瀑布。美国瀑布旁有－个鲁纳岛．水流又将其一分为二，分出了－条高50米，宽80米的小瀑布称其为&quot;新娘面纱瀑布&quot;。\n尼亚加拉河的径流量为6000立方米/秒，美国和加拿大在各自领土上都建了一个水力发电站，同时两国对发电的蓄水量有严格约定，瀑布的流量不得少于3000立方米/秒，不得有碍于瀑布的观赏。\n观赏尼亚加拉大瀑布可乘坐&quot;雾中少女&quot;号游轮，最好是乘直升飞机从空中观赏，但费用较高，每人需200加元，每加元约折合人民币6.35元，团友们还是慷慨解囊了，从空中俯瞰尼亚加拉大瀑布感觉和地面就是不－样，可以清楚地看到一条大河把伊利湖与安大略湖联结起来，水流从较高地势的湖中奔涌而出化成瀑布、波澜壮阔，真有&quot;飞流直下三千尺&quot;的感受，晚上用彩灯射上去更是灿然入目、多姿多彩、晶莹剔透、熠熠生辉。\n世界上另外两大瀑布一是，&quot;维多利亚瀑布&quot;它位于非州赞比西河中游，赞比亚和津巴布韦的接壤处，瀑布水面宽1700余米，落差60米到108米不等，维多利亚瀑布分五段：有东瀑布、虹瀑布、魔鬼瀑布 、马蹄瀑布和主瀑布组成，径流量为934立方米/秒，其宽度和高度比尼亚加拉瀑布都大一倍。另一大瀑布是，&quot;伊瓜苏瀑布&quot;它位于阿根廷和巴西边界上的&quot;伊瓜苏河&quot;，是一个马蹄形的瀑布，宽4000米、落差60米到80米不等，径流量为1756立方米/秒，宽度约是尼亚加拉大瀑布的4倍。这两个大瀑布都未有机会身临其境，相关情况是查阅的资料，但从&quot;尼亚加拉大瀑布&quot;的壮观、想象其容貌一定也很了不起。国内&quot;九寨沟的水景&quot;、&quot;黄果树瀑布&quot;加上各种地形地貌及植物的匹配、景观很有特色，确实也是很迷人的。&quot;黄果树瀑布&quot;位于贵州省安顺市镇宁布依族苗自治县境内，在珠江水系打邦河支流的白水河上。瀑布高度为77.8米，主瀑高67米。瀑布宽101米，主瀑布宽83.3米。\n观看尼亚加拉大瀑布后感到大自然的力量是无法比拟的，其杰作真可谓是天造地设，随填《蝶恋花》词一首题作：\n《观尼亚加拉大瀑布有感》。\n浩淼急流奔略湖，百折不回，轰鸣声如鼓。\n天设地造悬瀑布，胜景奇观腾云雾。\n观瀑人流难计数，万头攒动，攝影堵行路。\n鬼斧神工非－处，有我神州黄果树。"},{"id":172,"title":"关注世博会","category":"散文","date":"二零一零年十月末","body":"2010年的5月1日至10月31日，中国上海受到了全世界人民的瞩目，因为在这里将举办历时半年的世博会。九月底接上级指示省局机关组织第二批干部职工赴上海参观世博会，局领导委派我带团参加，往返一周圆满完成了任务。结束时正好是国庆长假、还顺路回老家看望了我九十八岁的老父亲。参观世博园期间、首先游览了中国馆，并对美国，加拿大、英国、法国、德国、俄罗斯、澳大利亚、日本国、韩国、东南亚各国以及非洲、欧洲联合馆分别进行了参观，感受了异域他国的风土人情、风俗习惯和生活缩影。遗憾的是参观世博园的游客、每天都是络绎不绝、真可用人满为患来形容，特别是被热捧的沙特馆、因要求进馆参观的人数太多、我没有耐心排队等待、自愿放弃了机会，无从了解馆内的内容。用两天时间参观了其它所有展馆，虽然是走马观花但感触还是颇深，&quot;科技改变生活&quot;的主题决不是神话，而成为现实，随有感而发，用《水调歌头》曲牌填词一首题称《愿世博精神源远流长》，以誌留念。\n金秋皆流光，溢彩世博园。异国风情奇玄，齐聚上海滩。展示科技成果，诠释文化多元，实力尽彰显。一日游环球，世界在身边。\n忆过去、观当前、思发展。岁月沧桑维艰，历史不重演。曾经农业文明，更有辉煌今天，愿生活美满。和谐携和平，人类开新篇。"},{"id":173,"title":"人生境界","category":"散文","date":"二零一四年初冬","body":"人生如梦，细算起来己消耗了22360天，还有多少天耗尽整个生命不得而知，其实人生是很短暂的，仅是一场梦而已。在这己消耗的两万多天里、人生的成长过程中是不是有进步、是不是有感悟、是不是有积累，自己认为总是有一点的、否则怎么对得起在人世间的这两万多天，当然对人生的评价最好是由人评说、盖棺才能论定。\n人生如戏，在人生这个舞台上生旦净末丑、每个人都有自己的角色，无论是愿意还是留有遗憾、都会像一颗流星在历史的天空留下自已的痕迹，这一点是无可非议的。像每天日出东方日落西方一样、在人生这个舞台上、你方唱罢我登场，也是一条突不破的规律。\n由于每个人在不同階段看待世界的立场观念方法角度不同、所得出的结论就会有所不同。回顾几十年的职业生涯、最好的年华里、有不少时间是在聆听和编织谎言中度过的，思想起来甚为自己感到悲哀。向&quot;古来稀&quot;快奔的这个年龄、己历经人生大半的历程，虽有些感悟但毕竞是&quot;夕阳无限好、只是近黄昏&quot;。\n肚知心明己经没有人愿听我的絮叨，但我也要将我所悟的人生之境界作为泣血忠告录之于下、见者可慎思其对否？\n&quot;人之初、性本善&quot;人生之初纯洁无瑕，看事物比较纯真、做事情比较率真。在师长&quot;老实做人&quot;谆淳教导下，大概一般的人都一样，看到什么即是什么、人家告诉他说那是&quot;日月星辰&quot;、&quot;阳光空气&quot;、他就直观认识了日月星辰、阳光空气。别人说那是&quot;高山大川&quot;、&quot;江河湖海&quot;他就直观记住了高山大川、江河湖海的形象。到底什么是日月星辰、阳光空气、什么是高山大川、江河湖海，只知其然、不知其所以然，不会认真去探索为什么是日月星辰、阳光空气，怎样才能成为高山大川、江河湖海。或者反其道用钻牛角尖的方式去求证都不可取。\n看什么就是什么或者将任何事情都追求完美、这是人生的第一境界&quot;天真无邪&quot;。&quot;天真无邪&quot;的优点是初生牛犊不怕虎，做事敢闯敢干、敢标新立异，真有舍得一生剐、敢把皇帝拉下马的精神。其缺点是容易采取莽闯行动、且不计后果得失，一杆子可捅破天。按&quot;天真无邪&quot;行事可能会影响自己的一辈子的功利进取。&quot;天真无邪&quot;一定要不断地加以修为、最后才能达到人格的成熟。\n一幌人已到中年、在人生这个大舞台上获得的无非是两种结果，成功和失败。随着年龄的增长，经历的事情渐多，就会发现这个世界的问题越来越多、越来越复杂，这个时候再看那日月星辰、阳光空气、高山大川、江河湖海跟原来认识的就完全不一样了。由于社会生活的真实与复杂，便经常会出现是非混淆、颠倒黑白的事情，人们经常会被激愤的、不平的、忧虑的、疑问的、警惕的、复杂的情绪干扰着，甚至会被&quot;好人无好报&quot;的心结缠绕着、长期得不到解脱。人们不再轻易地相信直观看到的一切。这个时候再看看日月星辰、阳光空气、高山大川、江河湖海，更多的是感慨和叹息，正像《篱笆墙的影子》这首歌里一句歌词：&quot;山也不是那座山，河也不是那条河&quot;了。于是人们的情感也就发生了变化，愤世嫉俗、借古讽今、指桑骂槐的情绪发泄也就多了起来。\n有时还会忘记自己的缺陷和不足，过高的估计自已、盲目的站在这山望着那山高、争强好胜，绞尽脑汁、与人较量，计较得失、永无满足，心高气傲、勉强不来的事硬要去追逐。\n原本人世间的一切一切都是人的主观意志的载体，你直观看到的不一定就是&quot;那个样&quot;，你还可以去想像、去发挥，不一定去认&quot;死理&quot;。此时此刻大概就达到了人生第二境界&quot;成熟老练&quot;。人生到第二境界后就少了朝气、多了暮气、疑虑增多，做事放不开手脚、前怕狼后怕虎、畏首畏尾。到头来，只能是追求了一生、忙碌了一生、奋斗了一生，也没有达到自已的理想，于是遗恨终生、只好抱残守缺、依依不舍的走完人生。\n人生如风，人来到这个世间、都会在世俗的泥淖里扑腾，在广袤宇宙的永恒时间和无限空间中、任何一个人都只能是蓝天中的一丝云彩，滄海一粟的比喻最恰当不过了。一个人的一生尤如轻风一缕一吹而过，不会留下过多的痕迹。天外有天、人上有人、四季更替、循环往复是亘古不变的真理，一个人以短暂有限的生命去与永恒和无限计较、其结果不言而喻。因此，人们只要专心致志做好自已应该做的事，无需与别人斤斤计较，面对琐碎杂陈的世俗之事都可以一笑了之，无需放在心上。天道酬勤决不是虚无，好人终有好报应是铁律。\n拨开云雾、茅塞顿开、经过不断修炼终会功德园满，这就是人生第三重境界。人回归自然、事事感到&quot;功德园满&quot;这个最高境界后、再去看日月星辰、阳光空气，看高山大川、江河湖海，一定就像《篱笆墙的影子》歌词中所唱：&quot;星星还是那颗星星，月亮还是那个月亮&quot;。\n人本是人、不必过分刻意去做人，刻意的去讨人喜欢，折損的只能是自我的尊严。世本是世、无须投机取巧去处世，投机取巧去处世失去的只能是做人的诚信。诚实做人、勤恳做事、廉洁奉公，一切顺乎自然活得就不会很累，真正做到知足常乐也就是做人处世的最高境界了。\n浙江天台山方广寺有一联说得好：&quot;风声水声虫声鸟声梵呗声，总合三百六十击钟声，无声不寂；月色山色草色树色云霞色，更兼四万八千丈峰峦色，有色皆空。&quot;化外观尘世，冷眼看凡夫。朝代兴废，名利追逐，不过境由心生。色即是空、空即是色。世人不明于此，造无数冤孽，禅心正定，悟道及此，方算得上人生第三境界&quot;功德园满&quot;。\n人生境界悟到难、做到更难，人生无难事，只要肯登攀。写在甲午六十四周岁生日。"},{"id":174,"title":"快乐秘诀","category":"散文","date":"二零一三年重阳节","body":"有一篇文章题为《争名次的经济学》说的是人们未必是追求财富的绝对多少，而是财富的相对多少。一个人不论他如何富有，只要他以为有更多的人比他更有钱他就会骂娘。如果真是这样，一个国家不论如何富有，百姓还是会不满意的，哪么追求财富还有什么意义呢？这仅是经济学对社会产生的一些不良后果。人生中如果没有快乐人活着又有什么意义呢？其实古人在《论语.季氏》第十六篇中就说：&quot;丘也闻有国有家者，不患寡而患不均，不患贫而患不安。盖均无贫，和无寡，安无倾。夫如是，故远人不服，则修文德以来之。既来之，则安之。&quot;后来有专家研究，财富对快乐不仅有负面影响而且也有正面影响，但财富对快乐的正面影响也不是决定性因素。倒是宗教、婚姻等起的作用更大一些。所以，社会光有经济学还远远不够，应该建立一门《快乐学》，它研究的范围应该是个人、社会以及全人类的致乐之道。应贯穿到从小学到大学教育的全过程，并用来指导国家的政策处理对内对外的关系。只有人人都感到快乐社会才会安宁。世界才会平静。\n对《快乐学》我并非有意认真的从学术专业上去研究，&quot;快乐秘决&quot;也绝不是什么玄虚，而是实实在在的自我感受、是我对人生态度的体验和总结，如何微笑着快乐着面对自已的人生，如何让自已在生活中找到快乐呢？在这里愿将我的&quot;快乐秘决&quot;与志同道合者分享。\n一、舍弃历史累赘。\n&quot;快乐自已、幸福别人&quot;这句话我是很赞成的。退休以后要做到&quot;老有所乐&quot;、其实并不难，只要&quot;忘记&quot;过去的一切，将名利地位、是非功过都搁置一边、随风而过。舍弃一切不必要的累赘，不要将沉甸甸的历史包袱背负在身上，认认真真地把自己放到一个普通老百姓的位置，从头开始，重新整理自已的人生，从自已身边寻找快乐，快乐就无所不在。\n二、敬重享受生命。\n人的生命只有一次，任何人仼何情况下都不可以拿生命去开玩笑。只有懂得了尊重生命，拥有达观的生活态度，在为人处事中才不乏有豁达向上的胸怀，有了乐观向上的心态，才不会过份计较生活中的得失，才不会因一点小事愁肠百结，跟自已生命较劲的人才是最愚蠢的人，有了正确的人生观就一定会展现发自内心的微笑，生活就会充实，人生才会快乐。\n三、培养幽默气质。\n能够微笑着生活的人、应该是具有幽默感的人，用幽默传递心中的喜悦感染生活的周围，让大家快乐起来。所以要自觉的培养自己的幽默气质，多学会一些富有生活哲理的小笑话，伺机适时在邻里、同事、朋友之间悄悄幽默一把，让大家沉浸在快乐之中。这样你不仅能成为一个给人带来快乐的开心大使，还可以让自己的人生充满乐趣。中国民间传说的《二十四孝》中有一则讲自娱娱人又孝顺老人的故事，老莱子（东周）春秋时期楚国隐士，为躲避世乱，自耕于蒙山南麓，他孝顺父母，尽拣美味供奉双亲，70岁尚不言老，常穿着五色彩衣、手持拨浪鼓如小孩般戏耍，以博父母开怀。一次为双亲送水，不慎摔倒，怕父母心疼，随躺在地上假装小孩哭，二老大笑。后人以&quot;戏彩娱亲&quot;比喻对老人的孝顺。\n四、富有阳光心情。\n世间万物，你从不同角去观察、就会得到不同的结果。生活就是这样，你给了它微笑，它也会回赠你一份明媚的心情。被阴云缠绕时不要忧伤，更不要垂头丧气，因为越是从逆境中走不出来、情绪就会更低落，如将其轻松放下，想点开心的事让自己笑起来，也许灵光一闪也就会全部释然。富有阳光心情，一切顺其自然，就一定会无烦恼无忧伤。一个人的心态好坏会影响一个人为人做事处世及生活中的各个方面，有好心态、把生活中的点点滴滴都向光明美好处想，就会善待一切，心情愉悦就会积极向上。\n五、学会寻找快乐。\n只有心中充满快乐的时候，你的嘴角才会挂着微笑，如果要让自己很靓丽，就要学会微笑。如果要让自已觉得很成功，不妨经常给自己一个微笑，当习惯了给自已微笑时，才能痛快地将微笑传递给别人。让别人愿意与你相处，你在别人的眼中一定会觉得：你有用、能给别人带来实用价值；你有料、跟您打交道能开阔眼界；你有量、能倾听别人的诉说并提供有价值的参考意见；你有容、能充分认可每个与你打交道人的价值；你有趣、能给别人带来愉悦的心情；你有心、懂得用真感情去交朋友。朋友永远是快乐的主题、朋友多了快乐就一定多，快乐的事情在每个人的身边都会俯拾皆是，只需要你有健康的生活态度、宽广爽朗的好心情就会发现它，去寻找吧！任何快乐的事情都会发生在寻找的路上，学会微笑，必定会拥有快乐灿烂的人生。心宽就会体胖。\n六、情绪影响寿命。\n据科学家研究与人的寿命相关的自然环境占7％，社会环境占10％，生活起居饮食条件占8％，遗传因素占15％，心态和情绪占60％。可以看出快乐才是长寿的根源，长寿需要快乐，有快乐才会有长寿。"},{"id":175,"title":"我对名利的新认识","category":"散文","date":"二零零八年八月二十八日","body":"人在职场老为衣食及所谓的工作奔忙，总觉得没有消停过，近日偶有闲暇，坐下来想动笔留几篇字以便日后玩味，一旦真正动起笔来又茫然得不知从何处入手，是写自然、地理、人文、历史？是写春雨、秋风、夏日、寒冬？是写亲情、友情、爱情、风情？是写父爱、母爱、情爱、博爱？这些永恒的文学主题早被中外历代文人墨客翻来覆去的蹂躏得&quot;粉身碎骨&quot;了，况且自己也不是&quot;写家&quot;那块料，曾痴想写几页自传，但回首一看已过去的大半生平淡得确实无事可记，审视自己的人生观、价值观还有几点可能与众不同的浅见薄识，于是就将对&quot;名利&quot;的新认识笔录下来。\n我出生于一九五零年、农历庚寅、属虎，虚度五十有七，在我的人生中务过农、做过工、当过兵、经过商、从过政，复杂的历练虽有一些坎坷，却没有大的跌宕起伏，一步一个脚印走到今天，也丰富了不少人生，从七十年代末当科级干部算起，在所谓的&quot;官场&quot;上也混过近三十年了，到退休己指日可待。有副对联写得好&quot;世事洞明皆学问，人情练达即文章&quot;，从年轻时起我也打算把自己塑造成一个&quot;世事洞明、人情练达&quot;的&quot;人精&quot;，可是越来越踏不上社会的步，越活越糊涂。譬如官场上的潜规则无论是学习讨论、开会发言、汇报工作把讲假话都当作平常事，讲真话才是特例。这种现象看得过的要看，看不过的事也要看，违心的话要说、违愿的事也要跟着干，把人都快逼成了&quot;双面人&quot;。如果你没有&quot;千根木头跟排走&quot;的从众心理，想躲进&quot;桃花源&quot;显示清高一是没人信你，二是没有附从的人群，你就很难立足、很难在这个社会上混下去。当然，在&quot;人&quot;和&quot;非人&quot;之间自己一定要用心去把握，只有通过人间炼狱和凤凰涅槃的洗礼，才能成为既不&quot;清高&quot;又不落俗套的奇人。\n年轻的时候，在我的成长过程中很多师长、领导都教导我：&quot;做工作、干事业要不为'名'不图'利'&quot;，告诫我：&quot;'名利'这个'东西'生不带来、死不带去&quot;。好像&quot;名利&quot;两字就是恶魔只要沾惹上就会为其所累、恩怨难了，难道&quot;名利&quot;真的有那么可怕吗？我的大半生中一直用师长、领导的教诲改造着自己的世界观，指导着我的为人处世。至今，我当正县级干部己有十余载，曾用此观念多次&quot;谆谆教导&quot;过单位的同志，劝说过多少亲朋好友。如今，细想起来用这些不成熟的思想去说教别人是不是有误人前途之嫌？\n如果世间没有&quot;名利&quot;或者世人不爱&quot;名利&quot;，那么，世人就真的无所牵累、世界上就没有情仇恩怨了吗？这是一道彻头彻尾的伪命题。&quot;名&quot;有好的声誉和坏名声之分，我这里是指高尚境界的一种精神追求。&quot;利&quot;也有正当利益和不正当利益之别，这里是指合法利益的一种物质享受。如果世间真没有&quot;名利&quot;，那么大千世界芸芸众生的人生动力是什么？人生如果没有任何追求，由人类组成的空间结构-----社会，怎么会发展？由人类延续的时间顺序-----历史，怎么会前进？记不清《红楼梦》哪一章节里有那么一句&quot;天下熙熙皆为利来、天下攘攘皆为利往&quot;，在成语词林中&quot;沽名钓誉&quot;、&quot;追名逐利&quot;好像都是贬义词，主要是指取得名利的手段和方法不当，这也说明&quot;名利&quot;绝不是一个空洞无物的名词，而是社会生活中人们无时不在追求的理想目标。只要存在就有它的合理性。\n人活着不就是为了摆脱寻常生活的苦恼吗？我想摆脱寻常生活苦恼的方法有两个，一是&quot;奋斗&quot;、二是&quot;逃避&quot;，只要&quot;奋斗&quot;就具有目标性，其目标应该是与&quot;名利&quot;沾边的，既不为&quot;名&quot;又不为&quot;利&quot;那么，所追求的目标是什么呢？无所追求只是一种逃避、肯定是不想付出任何努力和奋斗的。\n一个有健全思维的人不能枉自清高、&quot;林至静无鸟、水至清无鱼&quot;&quot;阳春白雪、和者必寡。&quot;这些都是古人的话、人生在世没有必要把自己完全抛弃在社会之外、与世隔绝起来、与社会人群所向往的&quot;名利&quot;对立起来，如果真有一次扬名立腕的机会摆到你面前、你会因为害怕被&quot;名利&quot;所累而轻易放弃吗？看不破名利，名利是名利，看破名利，名利还是名利，所不同的仅是我们对&quot;名利&quot;的态度而己，假若说我们真的看破&quot;名利&quot;就会对世界上的任何事情都会感到索然无味、一生会无所追求，到那一天老之将至，回顾你的人生一事无成时，你会不会问自己一辈子都干了些什么？如果根本看不破&quot;名利&quot;把利害得失看得比山高比水深、患得患失、一点儿也输不起，甚至可以为捞得一点名利不择一切手段，一本书名《厚黑学》教的缺德招数很多，我是很鄙视为截获名利采用不择手段的。失去了人的基本良知、不要人格得到的名利，所有正直的人都会嗤之以鼻，甚至会成为臭名昭著、遗臭万年的历史笑柄。&quot;人过留名、雁过留声&quot;，用现在最时髦的一句话说&quot;金杯、银杯不如老百姓的口碑&quot;这样的&quot;名&quot;有什么不好呢？\n对名利、爱也好、恨也罢、绝不要出格，要以一颗脱俗的平常心、淡然处之，所谓的&quot;平常心&quot;并不是对&quot;名利&quot;一点不动心，而是要诚实的对待别人、诚实的对待自己，既然我们内心深处都爱&quot;名利&quot;那就大胆的去爱。&quot;名利&quot;绝不会是天上掉馅饼的事，要想得到它必须去努力、去拼博、去奋斗，&quot;争'名'夺'利'&quot;好像也是一个贬义词，如果说某某同志在工作中争名夺利就好像是一件很不光彩的事，我认为争&quot;名&quot;夺&quot;利&quot;并不完全是一件坏事，最终裁判要看其手段和方法正当不正当，靠自己的真才实干去打拼争夺来的名利何错之有？&quot;名利&quot;并不是唾手可得的、每个人只有从点点滴滴的细小的事情做起，夯实基础等待机遇，命运之神一旦降临，在你人生的转折点上就会增加一份辉煌，成功源于注重细节的积累，这也是我对人生的一点感悟。但是，也许我们尽了最大的努力结果却与&quot;名利&quot;失之交臂，那也没有必要怨天尤人、痛心疾首。&quot;谋事在人、成事在天&quot;，这句话也不得不信，因为&quot;机遇&quot;的变数太多，只要我们努力过、奋斗过就没有理由责备自己。天道酬勤，机遇一般都是会赐给有准备的人的，我认为这才是一条打不破的真理。人的一生在名利面前，成功了不要得意忘形；失败了不要沮丧气馁；疲累了不要抱怨后悔；轻闲了不要烦躁颓废；重要的是调整好自己的心态、有一副好心情、让自己的身心时时刻刻都感到舒适快乐。对&quot;名利&quot;还是要看&quot;破&quot;一点，才不会为其所牵累。\n师长、领导教导我做工作、干事业要不为名、不图利、要看破&quot;名利&quot;的观念其实没有错，大概都是含蓄的向我指出既要做出人生努力，又不要跌入&quot;名利&quot;的苦海，我过去对&quot;名利&quot;的认识不足，只是我的悟性不够，理解得不深刻不透彻而己，请原谅我的无知。\n仁者见仁、智者见智我对&quot;名利&quot;新的认识其实还是很浮浅的，如有不对之处请师长、领导、亲朋、好友多多指正。"},{"id":176,"title":"棋中乐趣","category":"散文","date":"丙申年正月初五夜","body":"今年，春节期间到浙江温州参加一个朋友儿子的婚礼，在雁荡山前的雁荡镇上看到由镇文化中心组织举办的有一名象棋高手对二十人的车轮赛，我饶有兴趣的看了半天觉得很有意义，细想这也是弘扬中华民族的传统文化。现在，人们休闲娱乐大都是以四人麻将为主，打麻将还带一些小彩头，认为才有刺激，这样无论如何总避不了赌博之嫌。\n象棋活动曾经是人民群众喜闻乐见的娱乐方式，它不仅可以休闲娱乐，还可以修身养性，陶冶情操，增强智力，其功能妙不可言。中国象棋是我国正式开展的78个体育运动项目之一。如今几乎要被世人遗忘了。现在下象棋要么是阳春白雪，由赛手在体育馆成为竞技项目，要么是下里巴人，在街头巷尾仅成了老年人的娱乐工具。\n中国古象棋据传始创于先秦，《象经》里有日月星辰之象，以寓兵机之说。早期的象棋是象征当时战斗的一种游戏。现在的象棋说是有唐朝宰相牛增獳发明、自宋朝定型后一直植根于百姓，沿袭至今己有几百年。\n我对象棋活动从小就十分喜爱，小学六级时开始自学入门，既未拜过师，也没打过谱。到而今也没混上什么段别，只是对象棋的喜爱还是未减。中学时代的每年暑假期，每天上午十点准时会到镇上一茶馆看人下两个小时的象棋，下午两点到六点也是黏在茶馆里，还会入局杀上几把。上学时每天晚上做完作业也会和邻居家的叔叔玩上几局，我输了会给他泡茶，他输了会给我扎风筝。\n当兵时娱乐活动很单调，不过每逢周日与战友走几局象棋还是可以的。上世纪七十年代中期，从部队转业到了工作单位，单位的直接领导和好几位同事都是部队转业的，有共同爱好，周末下班后常着迷下棋，有时直杀通宵、可真算得上废寝忘食。还有几次惹得爱人不高兴。\n下棋不仅仅是一种娱乐，内中包涵着很多人生哲理，可供为人处世时参考。\n下棋首先是一种共享的乐趣，一局胜负未定时、是一个待揭之谜，不但待你去猜，更重要的是任你去行。\n下棋是摆在桌面上的&quot;阳谋&quot;，棋盘上云诡波谲，尔虞我诈都明明白白摆在桌面上，你看不破、看不透，都怨不得别人。\n其次，下棋总会有输蠃，胜固欣然，败亦可喜，棋枰上&quot;胜不骄、败不馁&quot;是告诫我们做人做事最简单的道理。\n第三，要善于总结失败的教训，北宋黄庭坚论棋有&quot;三败&quot;一是欺敌轻敌，不把对手放在眼里。好像奚落对方自已就会赢棋，有些棋手在对手略有迟疑时还会沾沾自喜，拿出日本电影《追捕》男主角高仓健的经典台词：&quot;朝仓跳下去了、唐塔也跳下去了，跳啊，你倒是跳啊！&quot;结果输的可能还是自己。&quot;推磨&quot;的方法只能偶尔用来开开心，羞臊对手的方式最好不用。\n下棋就是下棋，急什么？心无旁鹜才有气度。\n二是不识对手的布局。在谋阵布局时要多注意对方的棋势，别总按自已的思路打如意算盘，认清对手的意图极其重要，如若不识对方棋势，露出自己的破绽，更容易被对方利用。如果自以为攻势很顺，也许就是要中招的前奏。要胜券在握，最少提前看出对方三步棋，也才有可能算得上是棋中高手。\n三是多错。取胜不要寄托于对方的失误，要尽可能减少自己的失误，失误就是帮对手的忙，就是自己打自己。首尾相顾，不贪求蝇头小利而失去大势，即使棋势失利也不要慌张，别让对手牵着鼻子走。更不要缺乏信心，处变不惊审时度势，及时调整战略战术才是明智之举。\n黄庭坚的这&quot;三败&quot;确是经验之谈。\n第四，下棋要有赢的信心但又不可总是赢。首先要坦诚承认自己不是高手，如果盘盘皆赢，就更不是高手。别总夸过五关斩六将的得意之作，别望了有走麦城的失意之态。得意不可再往，世上真无常将军。\n如果你总是高看自已，即使有70％的取胜把握，此刻可能被你自己埋伏了至少30％以上的失败因子，老子说：&quot;福兮祸所伏，祸兮福所依。&quot;就是这个道理。因为象棋活动是两人世界，即便赢棋也是对方配合的结果，坚决不可目中无人。否则，就会没有人陪你玩。总赢棋会乏味，有输赢才会有趣味。\n第五，下棋要树立全局意识，这样棋盘上的棋子才会有相互照顾的内在联系，棋局才会得心应手、而不是散沙一盘，反之则会处处受制、捉襟见肘。行棋时要珍惜每一颗棋子，有时就可能会输在一个小卒上。弃子攻杀法讲的就是牺牲一子就必须赢得力量更大的一子或满盘的优势，形成一种威懾，逼对方就范。否则，决不做无为的牺牲。破釜沉舟取胜是偶然，而缩头缩尾导致失败却是常态。\n棋理告诉我们：不贪不虚、不浮不躁、不欺不悔、不骄不馁、为下棋之道。棋风如作风，棋品如人品。豪放粗犷、谨慎细腻、尽在其中......，下好棋、做好人，就是传承优秀传统文化。"},{"id":177,"title":"江南古镇行与思","category":"散文","date":"二零一五年元旦","body":"在无锡大街小巷院落的围墙上经常可以读到唐代诗人白居易以《忆江南》曲牌所作三首词的词首《江南好》，&quot;江南好，风景旧曾谙；日出江花红胜火，春来江水绿如蓝，能不忆江南？&quot;，不言而喻这完全可以让江南人引此为自豪和骄傲。\n另两首《江南忆》，&quot;江南忆，最忆是杭州；山寺月中寻桂子，郡亭枕丘看潮头，何日更重游！&quot;。\n&quot;江南忆，其次忆吴宫；吴酒一杯春竹叶，吴娃双舞醉芙蓉，早晚复相逢！&quot;。\n道的是杭州灵隐寺赏月赏桂、钱塘观潮；和苏州馆娃宫箫笙歌舞、饮酒作乐的人文情怀、意境奇妙，且每首都以深情之句作结，三首连到一起更显诗人对江南的情深意切。两首《江南忆》只是描写他在杭州和苏州任刺史时与上层社会的生活点滴。《江南好》中&quot;日出江花红胜火，春来江水绿如蓝。&quot;句也只是对江南纯自然美的赞赏，并未涉及到江南一般士民生活和风土人情。短短三首《忆江南》词，当然不能苛求它反映出江南盛景的全部。\n今非昔比，但真正能体现江南风情的、我认为应是江南水乡古镇，那种&quot;小桥、流水、人家&quot;适水而居的情调，那种人和自然混成一体的和谐环境，那种清丽婉约的水乡田园风貌，那种富有深厚文化底蕴的吴侬软语，无不充分显示独具中国特色的江南风光。\n江南水乡古镇本来就是人们集中居住的社会单元，在苏南、浙北随处于见，但最有代表性的是由联合国遗产中心亚太区主任明嘉杨女士建议将江苏的周庄、同里、甪直和浙江的乌镇、西塘、南浔综合为&quot;江南水乡古镇&quot;推荐给《世界文化遗产》。\n其实早在1984年赴美留学的陈逸飞、于纽约举办他个人画展，其中就有以周庄的双桥为素材创作了一幅题为《故乡的回忆》的油画，将姑苏的小桥流水、田园风光介绍给了美国观众，引起了极大轰动，也引发了水乡古镇旅游热。1985年这幅画又经陈逸飞加工，成为当年联合国协会的首日封。\n2004年1月《江南水乡古镇》入选《世界文化遗产预备名单》并在在乌镇举行了《江南水乡古镇》为主体的特种纪念邮票首发式，一套六枚，一镇一枚，浓墨淡彩，彰显了江南水乡共有又各具特色的古镇风情。特别是2004年10月APEC会议在周庄开了半天，让世界真正见识了中国的江南水乡风光。\n《江南六大古镇》都是有千年以上历史的古镇，我曾先后光顾过，它们既有共同点又各具特色，共同点是水多、船多、桥多、古宅庭院多、个个都是国色天香、都像设色的水墨画卷。\n&quot;周庄&quot;开发得早，知名度较高，周庄有八景《金福晓钟》《指归春望》《钵亭夕照》《蚬江渔唱》《南湖秋月》《庄田落雁》《急水扬帆》《东庄积雪》等，这些景点都是迎合旅游需要，有现代人总结出来的。其它古镇也都有与周庄相似的、属于自己的所谓景点。\n周庄最具特色的是&quot;双桥&quot;这是由一座石拱桥和一座石樑桥组成横跨于南北市河和银子浜两条小河之上合二为一的小桥，造型独特、一横一竖、桥洞一方一圆，镇内家家临水、户户通舟，再就是&quot;沈厅&quot;，原名&quot;敬业堂&quot;清末改名为&quot;松荗堂&quot;，其主人沈万三我自幼就听说过是苏州有名的富户，别名&quot;沈百万&quot;。\n&quot;乌镇&quot;的旅游搞得不错，古镇俨然成了博物馆，镇上的原住民大都搬到新区去居住，古镇就是观光旅游的文化场所，镇上的&quot;茅盾故居&quot;、&quot;明清百张古床博物馆&quot;可看，茅盾先生的小说改编成电影的《林家铺子》就是以此地为背景拍攝的。（当然是未经过旅游包装、从前的乌镇）乌镇分为两个游览区，东栅以商业街为主、西栅有12个小岛组成，60多座小桥相连，还开辟了夜间观光项目。\n&quot;南浔&quot;曾是江南最富庶的古镇，嘉业堂藏书楼与小莲庄隔溪相望，藏书楼是刘镛的孙子刘承干于1920年所建，是中国近代著名的私家藏书楼之一。小莲庄是清光绪年间南浔首富刘镛的私家花园、家庙、义庄所在。\n&quot;辑里湖丝&quot;&quot;善琏湖笔&quot;顶顶有名，也是镇上富豪起家发迹的基础，有&quot;四象、八牛、七十二只黄金狗之说。&quot;有银子五百万两以上的称&quot;象&quot;，有银子一百万两以上至五百万两以下的称&quot;牛&quot;，有银子十万两以上至一百万两以下的称&quot;黄金狗&quot;，据说四&quot;象&quot;（刘镛、张颂贤、庞云曾、顾福）四家拥有的财富相当于清政府一年的财政收入。（七千万两银子）\n南浔素有&quot;读书之邦&quot;的美称，宋、明、清三朝出进士41名，有任京官者56人、任地方县官以上者57人，有知名学者80余人，当代有副教授以上职称的240余人，可谓是人杰地灵。\n&quot;西塘&quot;的面积居六镇之首，保护了1．05平方公里古朴民居和25万平方米的明清建筑，西塘与其它古镇相比有桥多、弄多、廊棚多之誉。因廊棚多在西塘观光就另有一番风味、雨天不怕淋、晴天不怕晒。\n&quot;甪（读鹿）直&quot;有东方威尼斯之称，镇东直港有水路通向六处，甪直有史以来从未有过战乱和旱涝灾害，人们年年丰衣足食，镇内有沈宅、萧宅等景点。叶圣陶先生在此居住时以甪直&quot;万盛米行&quot;为题材写下了小说《多收三五斗》并入编到中学课本中当作教材，其《高高的银杏树》也是借甪直的七棵古银杏树抒发祟尚&quot;形象高大、意志坚强、气魄宏伟&quot;的感情，至今七棵古银杏树仍在，有四棵在保圣寺内，最大的一棵有50多米高、树龄已有1340余年。根据叶先生的遗愿他的骨灰就安放在保圣寺内的银杏树下，当地政府为他修了纪念馆供人瞻仰。\n&quot;同里&quot;的主要景点有一园、二堂、三桥，&quot;退思园&quot;，&quot;嘉荫堂&quot;柳亚子先生曾在此居住过，&quot;崇本堂&quot;里精美的雕刻很值得一看，镇内有15条河流、7个小岛由49座小桥互相连通。著名的三桥雄踞古镇中心，过&quot;三桥&quot;仍是古镇之风俗，&quot;走过太平桥，一年四季身体好。走过吉利桥，生意兴隆步步高。走过长庆桥，青春常驻永不老。&quot;这是多么美好的祝福。\n走过江南六大古镇后不妨说是初步认识了婀娜多姿的江南风光，领略到了&quot;中国古桥博物馆&quot;的真实面貌。\n有水的地方就有桥、就有船，水是桥和船的母亲，桥是水的儿子、船是水的女儿。没有水、没有桥、没有船、那就不是江南。\n有庭院就有迴廊、就有亭榭，就有太湖石，庭院是挂在心上的家，迴廊是曲折奋斗的路，亭榭是抵御风浪的港，太湖石是闲情逸致的情。没有庭院就没有江南人的智慧，就失去了江南的灵性。\n&quot;退思园&quot;是我退休后由夫人，女儿、女婿陪同去的，站在&quot;退思园&quot;里静观细想、亭阁楼台就夹杂在红花绿柳之中、镶嵌在宁静的水池四周，池中鱼儿悠哉游哉，其景其情必会叩击人的心灵，有此悠闲自得的世外桃源，功名利禄怎么会不成为过眼烟云？\n&quot;宠辱不惊，闲看庭前花开花落；去留无意，漫随天外云卷云舒&quot;。&quot;退思园&quot;大概就是古人追求&quot;精神、物质、文化&quot;的典范。现代人一味追求的是物质富裕，似乎精神和文化都可抛在一边，是不是可悲？\n六大古镇的景区里商铺林立，充斥着大街小巷，失去了古镇原有的宁静，让人感到的并不是繁华，倒有点俗不可耐的感觉，古镇的河水都遭到了严重污染，与九寨沟的&quot;水&quot;根本无法相比。过度的开发、过度的包装、过度的游客、过度的追求经济效益必然会让古镇失去原汁原味，失去它的本来面目。我到过的、凡属旅游景点的古镇、古城，如湘西的凤凰古城、芙蓉镇，云南的丽江古城、黄山脚下的屯溪老街、重庆的磁器口、杨州的东关街、无锡的惠山古镇、荡口古镇等等无一例外。\n六大古镇行过一遍，给人留下了很多遐想与神思。为此，我有《为古镇把脉》外一首诗相奉：&quot;商旅喧嚣浮华中，'悠闲'失却真面容。店家工匠乐其事，何时还我古镇风。&quot;这是古镇的现状，其实大多数人期盼的古镇风情应该是：&quot;白墙黛瓦绿映红，小桥流水行乌蓬。捕鱼採桑务农事，炊烟人家细雨中。&quot;\n人们旅游的目的是什么？或是饱览祖国的名山大川；或是游历纯朴的自然美景；或是探索幽秘的历史之迷；或是追寻深厚的人文积淀；或是拜谒净化心灵的佛国；或是寻觅放松心情的乐士。绝不会留恋于低俗的浮华。旅游景点的开发与古镇文化的保护是一把双刃剑，如何把开发与保护有机的结合起来，值得认真研究。\n与六大古镇相距不远的平望、震泽、七都、盛泽、木渎、光福......众多未经被所谓现代文明污染过、未经完全开发为旅游景点的古镇，既有现代生活气息又有古镇传统风味，那才是真正的&quot;江南水乡风光&quot;建议&quot;驴友&quot;们可以尽情去观光游览，汲取营养。"},{"id":178,"title":"我的七十岁生日","category":"散文","date":"己亥年孟冬","body":"岁月如白驹过隙不知不觉退休己近10年，自己的年龄也爬上了古来稀的台階，农历十月初三是我的生日。\n我是一个随意的人，平常不太注意生活细节，对于生日我向来都不很注重，总觉得只要生活得好，活得自在就比过生日有意义得多。在那物质匮乏的年代，过生日无非是有一顿比平时好一点的吃食。现在生活富裕了幸福感那么强，好像是天天在过年、天天在过生日。\n说生日，有那么一句俗语&quot;儿的生日、母的难日&quot;。一个人从脱离母胎时才成为一个独立的自然人，也就是从这一刻起生命才有意义；也就是从这一刻起就会沿着自己的脚印、记录你人生的轨迹；也就是从这一刻起你就要懂得感恩父母。 我母亲在我25岁那年因病溘然去世。当时我还在部队当兵，母亲的生养之恩未报，至今想起来总是我人生中最大的遗憾。\n记忆犹新的是 2010年六十岁生日之日也就是标准的退休之时、当时九十九岁的老父亲还健在，要做寿很不妥。老伴说60岁是人生中一个重要的转折点，我们可以为退休而庆祝，为开启新生活的起点而庆贺。理由很充分，拗不过她只好顺势而去配合她的安排，庆贺宴设在酒钢宾馆西楼餐厅，至亲厚友近百人到场致贺，气氛热烈。宴上推出一个花八百八十元订的大蛋糕。这是我人生所有大事中最奢华的一次，让我感动至今，感谢我太太为我过生日。\n今年的生日有很多特别也有很多感动，买好9月29日的火车票，准备携小外孙赶回无锡过国庆节。27日突然接到姜华夫妇的邀请说要提前给我七十岁祝寿，再三婉拒终不成功。说是28日在嘉峪关瑞景酒店、相约了数位密友及家眷为我们饯行而相聚。醉翁之意不在酒，宴会上还是上了生日蛋糕，给我准备了价值不菲的生日礼物。嘉峪关市老领导原常务副市长政协主席路志龙也送了裱装豪华的寿联及中堂一付，&quot;从军从政成就卓著，做事做人堪称楷模。&quot;如此高的赞誉实在是受之有愧。&quot;从军从政成就卓著&quot;有夸大之嫌，现在回想起来从部队转业到地方在嘉峪关一待就是三十几年，我是随这座城市的发展而一点一点成长起来的，给嘉峪关市社会经济建设留下了一点痕迹，若说是取得了一点成绩那也是工作职责使然，这点成绩始终是离不开党的改革开放政策的引导，离不开各级领导的关心支持，离不开社会各界人士的鼎力相助，离不开单位全体同仁的共同努力奋斗。对我所做的一点贡献、党组织也给予了充分肯定，让我从一名基层领导做到上级机关的副厅级干部，这些都是我应该感恩的。&quot;做事做人堪称楷模&quot;一说也差之甚远。我是一名入党近半个世纪，对共产主义具有坚定信念的老党员。&quot;为人民服务&quot;的根本宗旨一直牢记心中。同时也时刻将具有中华传统美德的&quot;仁、义、礼、智、信&quot;和&quot;温、良、恭、谦、让&quot;作为立身修为，改造和建立自已世界观、价值观，把自已培养成为一个社会需要的人的座右铭。一日三省严于律应是本分，堪称楷模很不够。\n这样的聚会友情深厚，这样的生日意义非凡。我想起唐朝诗人李白的一首《赠汪伦》&quot;李白乘舟将欲行，忽闻岸上踏歌声。桃花潭水深千尺，不及汪伦送我情。&quot;突然诗兴大发，随咏一首《赠姜华夫妇》&quot;世情人走茶就凉，何由苛求不寻常。姜华夫妇释大义，情归泪飞湿衣裳。&quot;以示感谢大家。\n回到无锡国庆节刚过完，女儿女婿又提起给我过生日的事。我说在嘉峪关已提前过了别再折腾了。他们当然不依，说是还有两个小外孙第一次给你祝寿，能随意拒绝吗？老伴也说别辜负他们的好意、扫他们的兴，还说在外工作几十年现已退休回到了家乡，但真正在老家待的时间很少，兄弟姐妹众多都有了三代人，大姐四世同堂，孙辈们对你是否熟悉，对你有多少了解？不妨全家人趁机聚一聚。只好随了他们。\n唐．贺知章《回乡偶书》&quot;少小离家老大回，乡音未改鬓毛衰。儿童相见不相识，笑问客从何处来。&quot;到是我的真实写照。让我想起维持血脉亲情毋勿相忘真有必要。我在《故乡――曲霞镇》一文中也有思乡诗一首&quot;人生飘泊时日长，别梦依稀常惆怅。老之将至念桑梓，叶落归根还故乡。&quot;聚餐就定在太兴。\n农历十月初三是阳历十月三十日星期三，为了不影响大家正常工作提前三天，日期定为十月二十七日星期天。为充分做好准备还请了庆典公司帮助策划和布置，女儿女婿忙了几天赶做了一个碟。当天女儿程玮亲自当司仪，除女儿女婿、两个小外孙给我献花敬酒外，亲家、兄弟姐妹、侄儿辈、孙子辈都给我敬酒，我兴奋到了极点，忘记了自己的年龄喝了好多酒。生日蛋糕上插了代表70岁的蜡烛、让我许愿，我简单回顾了自已的一生真是无怨无悔。遂许下让全家人平安如意幸福健康的愿望，吹灭了蜡烛，全场齐呼&quot;生日快乐&quot;。庆典举办得很隆重。\n女儿女婿给我庆生，让我很欣慰、很感动，让我感受到了亲情的温暖，家的温馨。朋友给我庆生让我很自信、很自豪，让我感受到了友情的珍贵。现在看来生日还是可以回顾记录从生命原点开始，测量人一生的标尺。我期盼我能走到&quot;耄耋之年&quot;，再开盛宴，欢聚一堂。\n感谢与我生命同行的每一位亲人友人。"},{"id":179,"title":"石痴论石","category":"散文","date":"甲午年立冬日","body":"我喜爱石头，历时不长、将近10年、在职时怕别人误解成&quot;玩物丧志&quot;，只是花很少精力、利用休息日悄悄地玩起来，确实没有耽误工作，退休后方才真爱起来，因为真爱、才去慢慢了解，算是初入&quot;石&quot;门。自从爱上石头以后才知道古人曾说过&quot;山无石不奇、水无石不清，园无石不秀、居无石不雅。&quot;经典之句的真实含义。\n也许局外人会认为、石头只不过这世界上最普通、最平常的东西了，硬梆梆、冷冰冰的石头有什么&quot;文化&quot;可言。殊不知，世界上所有文化都应与石头相关，人类生活几乎都与石头有缘，可以说&quot;石文化&quot;是人类文化的始祖。女娲炼五色石补天的神话传说就是用石头造福人类。\n在人类历史的漫漫长河里、所有的发明创造与文明、首先是从石器制造开始的。人类的祖先为了生存的需要、在不断的生活实践中、用自然界质地坚硬、块状均匀的天然石块、通过敲打磨制成为比较适合使用的各种生产生活工具。这是人类最早认识和利用&quot;石&quot;的开始。人类在进化过程中历经了二三百万年的石器时代，可见人类与石头的渊源深厚。人类进入青铜时代和后期的现代文明、屈指数来才有短短几千年的历史，与漫长的石器时代相比、实在微不足道。\n古人云：&quot;得石者福、玩石者乐、品石者寿，藏石者福禄寿。&quot;中国赏石文化源远流长，古人除了行风花雪月之雅事，对奇石更是情有独钟。\n雅士爱奇石，历代皆有佼佼者。&quot;卞和献石&quot;在历史上留下了&quot;完璧归赵&quot;的故事，卞和是楚国的一名奇石爱好者他在家乡荆山脚下采到一块&quot;落凤石&quot;雕琢成上纽交五龙，正面刻有李斯所书&quot;受命于天，既寿永昌&quot;八个篆字的印玺称&quot;和氏壁&quot;献于楚王，嗣后被历代君王作为皇权神授正统合法的信物，曾有130多位君王先后收藏了1600多年，据说到了唐太宗李世民的时候，已找不到&quot;和氏壁&quot;的影子，机智的太宗刻了几方&quot;受命宝&quot;&quot;定命宝&quot;之类的玉玺，假装自已是有传国玉玺的。历史又纷乱了几百年，唐朝灭亡。从此，&quot;和氏壁&quot;就神秘失踪，至今杳无音讯。尽管如此&quot;和氏壁&quot;还是首创了收藏史上最早、最长的世界记录。陶渊明、牛僧孺、李德裕、白居易、李煜、柳宗元、宋徽宗、苏轼、米芾、赵孟頫、徐霞客、郑板桥、蒲松龄、曹雪芹、张大千、寥静文、李準、沈鹏......，诸多历史和现代文人雅士都是品石、赏石、藏石高人，每人都有一段与奇石结缘的故事。\n唐朝晚期的宰相、牛李党争40余年，牛僧孺和李德裕，都是嗜石如命之人。牛僧孺朝夕与石为伍、常为之闭门谢客，他对石头的感情真是待石如宾友、亲之如贤哲、重之如宝玉、爱之如儿孙。他一生清廉、唯对石头来者不拒、另作别论。白居易曾对其说：&quot;公之僚吏多镇守江湖，知公之心惟石是好，乃钩深致远，献瑰纳奇，四五年间累累而至。公于此物独不谦让，东第南墅，列而置之。富哉石乎！&quot;有一次苏州刺史送他一块奇状绝伦的太湖石，他似逢三益友、如对十年兄。不但自已长诗吟之，还请石友刘锡禹、白居易酬答唱和，三家歌诗皆成咏石名篇。牛僧孺政治上的死敌李德裕爱石之心有过之而无不及。筑平泉山庄，收藏名花奇石。曾诗云：名山何必去，此地有群峰。临终遗言：以平泉一树一石与人者，非佳子弟也。宋人刘克庄评论二位：牛李势如冰炭、惟爱石如一人。\n唐代著名诗人白居易、曾任杭州刺史，爱石而不藏石，尤爱太湖石，&quot;烟翠三秋色，波涛万古痕。形质冠今古，气色通晴阴。&quot;是他对太湖石的褒奖。他作《太湖石记》指出品石赏石撮要而言：&quot;则三山五岳，百洞千壑，视缕簇缩，尽在其中；百仞一拳，千里一瞬，坐而得之&quot;。在他看来石头是知我心者。刚退任时他将几块太湖石运至香炉峰北、遗爱寺西畔，仅以二室四窗的草堂权作安身之地并作诗：&quot;弄石临溪座，寻花绕泉行，时时闻鸟语，处处听泉声&quot;。乐此不彼。将觅得的两块天竺石命以《涌云石》并题评：&quot;苍茫两片石，厥然怪且丑&quot;。（《素园石谱》中有记）晚年在洛阳建&quot;履道园&quot;有诗：&quot;渐空少年场，不容垂白叟，回头问双石，能伴老夫否？石虽不能言，许我为三友......&quot;。白居易爱石而不藏石为的是走一条&quot;中隐&quot;之路、避免陷入牛李党争旋涡之中。\n历史上的玩石大家应该是大宋皇帝宋徽宗赵佶，崇宁四年（公元1105年）蔡京就投其所好，在苏州设应奉局派心腹朱勔主持，专在江浙一带收集奇花异石运往汴京供其赏玩，&quot;花石纲&quot;历时二十余年最后耗尽民心国力，也玩完了大宋江山。\n郑板桥画石论石，曾云：&quot;米元章论石，曰瘦、曰皱、曰漏、曰透，可谓尽石之妙。东坡又言石文而丑，一丑字则石之千态百状皆从此出。彼元章但知好之为好，而不知陋劣中有至好也。东坡胸次，其造化炉冶乎。&quot;郑板桥知晓美丑互妙之理，发出&quot;丑而雄、丑而秀。&quot;之鉴石赏石新观。他所画，有兰有竹有石，有香有节有骨。所谓&quot;四时不谢之兰、百节长青之竹，万古不败之石、千秋不变之人。&quot;其书法，惯用乱石铺街布局的章法，细看起来是一片错落有致的怪石铺就十分招人喜爱。\n蒲松龄觅石写石，在老藤绕屋、怪石当门的石隐园，听蛙鸣、观鱼跃、会狐仙，完成了他的《聊斋》。\n曹雪芹一部怀金悼玉的《红楼梦》就是一篇高爱雅趣的《石头记》。曹雪芹不仅写石，还喜欢画石。他的一幅《题芹圃画石》配以四言律诗&quot;傲骨如君世己奇，嶙峋更见此支离，醉余奋扫如椽笔，写出胸中瑰磊时&quot;。更显胸襟阔大。\n奇石又名雅石、观赏石。玩石并不是中国人的专利，日本、韩国早就接受了中国传统文化。日本将未经雕琢的观赏原石叫作&quot;水石&quot;、韩国则称之为&quot;寿石&quot;。\n人爱美石，是对造化神奇的怜惜珍重，是对诗意情怀的立寓寄托。文人雅士的介入，让石文化形成了理论，提高了品味。\n随着时代的变迁，赏石品种的增加，石文化的发展，对赏石审美标准也在不断的丰富和完善，古人提出的&quot;瘦、皱、漏、透。&quot;已远远不够，今人又加上&quot;清、丑、顽、拙、奇、秀、险、幽。&quot;合在一起这十二字的赏石要决可谓恰当到位。真正识得奇石之美还要从质、形、色、纹、势五个方面去综合把控。\n当然，一个优秀的赏石者，还需要有大量的美学、文学、书法、绘画、雕塑等等知识及个人的审美情趣、素质修养。\n有关&quot;石文化&quot;不仅是审美标准，还有各石种的辨识，对奇石的养护、命名、奇石与环境的选择、奇石与其它文化的交融......，要真正懂&quot;石&quot;可不是一件简单的事。\n乱世黄金，盛世收藏。在圆中国伟大复兴梦中，中国人的口袋是鼓起来了，各类收藏比比皆是，赏石藏石列为一类。就在这人心浮躁、金钱至上的市场经济大潮中将本应可以愉悦心情、陶冶情操、益智益寿、雅俗共赏的赏石藏石之事却被搞得俗不可耐。据统计目前玩石圈内大约有300多万人，俗话说：林子大了什么鸟都有，人数之多必然会泥沙俱下、鱼龙混杂。\n赏石藏石界目前最大的弊端有二：一是肆意炒作，将某些石种或某些石块动辄几十万上百万有的甚至炒到成亿或上千万、搞乱了人心、搞乱了市场、使奇石交流受到了很大影响。\n二是造假骗人，造假者用锈蚀，雕凿、砂磨、酸洗、粘贴、注胶、激光打磨、添增色剂、褪色剂各种无奇不有的手段，把原本属于大自然精雕细刻的天工之物、搞得面目皆非、充斥市场、骗人骗钱。据行家介绍，目前长江石、大化石、戈壁石形象姣好的假货居多、若是市场上热炒的石种、出现假货的也居多，必须小心留意。\n赏石如品茶本应是清雅高尚之举，现如此状况，令人心费，令人神伤。敬告石友在奇石市场上一定要严加防范、谨慎行事。\n我爱收藏的是摆放在案头的图案画面石，至今有极品一块、精品十数方，在中国奇石网上可检索到。因为一块好的图案画面石、要经过亿万年地质变化、无数次河水荡涤，石碰砂磨，最后得到的可谓鬼斧神工之作，都是永恒的艺术瑰宝。坐守寓内，高山流水、河泻海涌、花鸟灵兽、春意秋色，江山人物尽收案头之上，件件小巧，方方玲珑。执一壶香茗静观细品皆有&quot;立体的画、无声的诗；远古的意、当代的景；历史的书、岁月的文。&quot;的意境。&quot;品小石头，看大生活；观小画面、悟大世界。&quot;的心绪油然而生。鉴赏那些造型奇特，画面俏丽、内涵丰富的奇石，无不让人心旷神怡、流连忘返。\n雅士爱石，因其有可爱之处，奇石之美、可分表里，形色悦人之外，石头的禀赋也很重要。石头沉静，不追风逐流；石头古老，有深厚底蕴；石头坚贞，无奴颜媚骨；石头稳固，能矢志不移；石头洁净，无世俗之气；石头天真，非刀斧人为。石头谦卑、石头忍耐、石头既刚强耿直，石头也温润园融。尤其是石头的沉默，最令相与者抚之安然、倚之悠然、处之泰然。也非石不能言，精美的石头一定会唱歌，言有可解可不解，石言石语皆心悟，一切是非皆与石头无关。\n奇石之所以受人倍加喜爱，还在于它自然古朴的性格，饱经磨砺的品质，永恒亘古的顽强，优雅不俗的灵气，可以让人在鉴赏品玩中感受美丽、体悟人生，修身养性，淡定做人。真正会赏石的人一定是一个低调的、谦恭的、宁静的、有修养的人。\n&quot;花不解语还多事，石不能言最可人&quot;苏轼称颂奇石的绝美佳句流经几百年不衰，至今仍与爱石者共振心扉。\n我爱奇石，石心石意，绝不随波逐流，这一辈子一定会继续爱下去。"},{"id":180,"title":"离别感言","category":"散文","date":"2009年元旦前夕","body":"公元2008年12月28日、星期天，这一天也是我终生难忘的一天，很感谢省工商局陈其寿副局长和人事教育处的侯文科副处长冒着冰天雪地的严寒来嘉峪关市宣布我的离职调任命令，免除我嘉峪关市工商局党组书记、局长职务，根据甘肃省委组织部的安排调任省工商局副地巡视员。\n1976年从部队转业至嘉峪关市工作已有三十多年，先后在商业局任政治处保卫干事、团委书记、嘉峪关市委核查&quot;三种人&quot;办公室成员、市政府财贸办公室秘书科科长等职。自1979年恢复工商行政管理局就在工商局工作至今、正好与改革开放同步，在科级干部岗位上干了整十年、在县（处）级领导岗位上干了二十年。光阴荏苒，三十年在人类历史的长河中仅是转瞬即逝的弹指一挥间，可对一个具体的人来讲、特别是一个人一生的有效工作时间来讲、三十年则是全部的青春年华，是有效工作时间的&quot;大半辈子&quot;呀。 就要离开整整工作了三十年的岗位、离开与我风风雨雨一起走过来的难分难舍的战友们、同志们，此时此刻我的心情十分激动、就像打翻的调味盒、辛酸苦辣、咸麻香甜什么都有，感慨也很多......首先我要感谢党组织对我长期的关怀与培养，感谢上级领导对我一贯的关心与爱护、感谢同志们对我不懈的支持与帮助，如果没有党组织的关怀与培养、没有上级领导的关心与爱护、没有同志们的支持与帮助也就没有我的今天。中国有句古语&quot;滴水之恩、涌泉相报&quot;，我要用感恩之心虔诚的向所有在我前进之路上帮助过我的人们深深的鞠一躬、以表达我诚挚的谢意，同时要在今后的工作和为人做事中用实际行动一一予以报答。\n在嘉峪关市工商局工作的三十年中、我见证了嘉峪关市工商局从无到有、从小到大、从弱到强、整个工商事业恢复、发展、壮大的成长过程，历经了工商行政管理系统几次重大体制变革，我深深体会到嘉峪关市工商局的今天始终离不开历届地方党委、政府的关心与支持，始终离不开历届省工商局领导的关心与支持，始终离不开全市各界人民群众的关心与支持，始终离不开嘉峪关市工商人的共同努力与奋斗。在此，我再一次向所有关心支持工商工作的领导和同志们表示深切的谢意！\n在嘉峪关市工商局工作的三十年中能和同志们合作共事我认为是一种缘分，在共同学习工作的过程中大家都是我的老师，我向大家学到了很多很多，领导和同志们的关爱呵护让我学会了大度与善良，有一些反对过自己的不同意见也教会了我宽容与坚强。在我担任嘉峪关市工商局主要领导的十五年中、虽然我的主观愿望是想把所有的工作干好、把同志们的事情办好、真正做到为官一任造福一方。但是，在这么漫长的时间里、长踞在领导岗位上、工作中难免有一些决策失误的地方，也有可能不自觉的伤害了一些同志，（对那些工作失责受到纪律处分的人另当别论）特别是好多同志想办的事情没有给大家办好，没有达到大家的满意、这些都说明我这个领导当得还不够合格，现在想起来很愧疚也很抱歉，请大家给予充分的理解与原谅。从今天起我就要离开现在的岗位履职新任，我真诚的希望随我离开现任岗位之时，让我们共同捐弃前嫌、让几十年来结成的友谊长存、让愉快永远充满美好的回忆之间。在新的岗位上我一定加倍努力弥补自身的不足，大家有什么要求我也一定尽力去办，努力为大家服务好。\n2008年就要过去、2009年即将到来、新年伊始，让我们在省工商局新一届班子的坚强领导下，认真贯彻落实好中央、省、市各级政府经济工作会议和全国、全省工商行政管理工作会议精神，用新思路去认识新形势、用新姿态去迎接新任务，借助学习实践科学发展观的时代东风、乘风破浪、勇往直前。在新的一年里全面地履行好工商行政管理的各项职能、更好地为地方经济发展服务，为工商事业的进步、为取得更加辉煌的成就，贡献我们的智慧与力量。\n最后让我为大家默默的祈福、祝愿同志们新春愉快、合家幸福、工作顺利、万事如意。\n谢谢大家！\n调任离职会议上的发言、修改于2009年元旦前夕"},{"id":181,"title":"立志箴言","category":"散文","date":"二零一三年元旦节后","body":"人的一生都要立下多个志向，也就是奋斗目标，虽说&quot;有志不在年高&quot;，但年轻时所立志向最容易好高骛远，不切实际。没有志向的人生就等于没有生活方向，如果所立志向不切合实际也容易迷失人生方向。到了真正走入社会、特别是人到&quot;四十不惑&quot;的年龄后就必须适当做一些调整，所立志向更应该适应社会现实，尽量做到随遇而安。这样才能培养自己成熟的人格力量。\n贫困，有时像一种挥之不去、困扰人一生的梦魇。\n贫困不一定是缺乏金钱和物质，而是一种&quot;无为&quot;的困惑，或者是被希望及机遇憧景击破的挫败感和失落感。在官场很多人都感到自己努力奋斗的精神和成绩、领导没有看到和认可，害怕可以提升的时间越来越短，空间越来越窄，所以常常是怨天尤人，应对的方法不是急躁难耐就是产生颓废情绪破罐子破摔，由此影响正常工作，其实这样更会难以自拔，一辈子也无法冲破匮乏与弱势的局限。\n因此，人到中年后无论在言谈、许诺及设定目标方面，都更要慎思和坚守，定目标不能好高骛远、许承诺不能言而无信。更不能给别人留下囂张、慵懒、埋怨、脆弱和依赖的印象。个人的魅力表现在克己自律、诚实守信、随和谦虚和真正&quot;守得住清贫、耐得住寂寞&quot;的持之以恒中，所有这些元素连结在一起就能凝聚和塑造一个成功的基础。\n&quot;失败是成之母。&quot;半途而废往往是成功的大敌。这种正反双向思维的模式不仅是克服悲观情绪、而且也是获得成功的投资。更有可能是建立自信、实现自立、激励自强、获得成功的阶梯，当机遇一出现就有能力和胆量去担当。把贫困毫不犹豫地甩在背后，在不断进步的道路上放开脚步勇敢的前行。\n人生励志有诸多方法，圣训、名言、家风、榜样、都可以给人开朦启迪，我励志的道路上特别坚信这么一句话：&quot;一命、二运、三读书。&quot;这应该是我人生路上的座右铭。坚信&quot;命运&quot;、绝不是坚守&quot;宿命论&quot;，&quot;一命、二运、三读书。&quot;这句话完全可以用马克思主义哲学理论解释它。\n&quot;命&quot;，是&quot;规律&quot;、是一般性的普遍规律，&quot;命&quot;是先天的，既为&quot;规律&quot;只能就势顺从、不能逾越、也不可能任意的去改变它。信&quot;命&quot;，就是相信规律。就象人有&quot;生老病死&quot;一样、谁能跨得过这一坎去？就象人的出生一样、谁又能自己去挑选？既然是命中注定、只有认可、不必怨得怨失、怨张三怨李四。\n&quot;运&quot;，是&quot;机遇&quot;、具有普遍矛盾中的特殊性。&quot;运&quot;是外在的，有条件的，其&quot;特殊性&quot;是可以把握掌控的、只要认识及时、运用灵活、方法得当、其效果一般会很好的。既然是&quot;机遇&quot;其变数也是很大的、&quot;机不再来、时不我待&quot;一旦坐失良机就会追悔莫及，&quot;机遇&quot;经常是给有准备的人预留的，没有准备的人肯定不会成就什么事业。&quot;机遇&quot;来时、只要经过我们努力即使不成、也不必懊悔。\n&quot;读书&quot;是积累知识和能力的过程，是决定&quot;内因&quot;起变化的手段。内因是根据，外因是条件。对于一个有智慧的人来说、其素质即其&quot;内因&quot;、也不是一成不变的，&quot;读书&quot;是给一个有准备的人提供准备的条件，要想让自己有能力得心应手的去解决发生在身边的一切事情、就要不断的去壮大自己、不断的学习充电。&quot;读万卷书、行万里路。&quot;这种&quot;理论与实践&quot;的统一、必然是一个人事业发达的准备。只要把自己提高到能随时孵化成鸡、&quot;蛋&quot;的素质，终有一日就可能孵化成&quot;鸡&quot;，&quot;石头&quot;是永远孵化不出&quot;鸡&quot;来的。\n&quot;一命、二运、三读书。&quot;这句名言其哲理本身就是一条基本规律、这三者之间的关系是相辅相成、缺一不可的，我们在励志及发展事业的道路上要不断加深学习理解、融会贯通，这样对自己、对亲人、对朋友、对社会才能成为追求进步的正能量、才会大有裨益。\n有思维、有能力、有承担，可以建立自我。\n有理想、有目标、有原则，可以追求无我。\n舍此认知和操之过急大都是不能成功的缘由。"},{"id":182,"title":"老家-曲霞镇","category":"散文","date":"二零一二年八月十八日","body":"在1：1000000的中国地图上可能找不到曲霞镇这个名字，但它的的确确存在于东经119°7ˊ北纬32°17ˊ的交汇点上，它确实是我童年和少年时期生长的地方。\n曲霞镇是解放以后划分行政辖区起的名，解放前叫霞幕圩，（'圩'既不读wei也不读xu，方言音同'鱼'）为什么叫曲霞镇和霞幕圩不知缘由、可能也无从考证。曲霞镇是曲霞人民公社的驻地，辖周围的五岳观、东八圩、小庄、芦昌圩、刘洋圩、李家圩、季家圩、曲水圩、芮音圩、掛口圩、许家九圩、安乐桥、李家垈、亭子三圩、三茅殿二圩、埂子五圩、风月村、丁家桥等近二十个村庄，人口约有5万人左右。曲霞镇当时有10个生产队、人口有近5千人，现在人口可能己翻了两番。\n我确确实实是从这里带着梦想和希望走出去的、而且一走就是40多年，飘泊在外的40多年我很少回去，近几年才勤一些，加到一起也只有十几次吧，平均两年还不到一次，且从未回去与亲人过个团圆年，每次回去也都是怱怱而返、没有与昔时的朋友聚一聚叙叙旧，可能朋友还会议论我这个人会摆架子，这两点真是很值得遗憾的事。\n唐.贺知章的一首《回乡偶书》：\n&quot;少小离家老大回，乡音难改鬓毛衰。儿童相见不相识，笑问客从何处来。&quot;\n与我回家时的处境到是蛮相似的。年轻时在&quot;好儿女志在四方&quot;、&quot;何处黄土不埋人&quot;价值观的影响下，对老家的观念是淡薄了点，但对故乡的感情总是难以割舍的，我曾经写了一篇文章题为：《故乡情结》。今年，我和老伴都退休了，老家在我心中的份量更加重了，也勾起了我对四十几年前的一些记忆和要回老家度晚年的想法，为表达我的思乡情感，随意诌诗一首题为:\n《游子思归》\n&quot;人生飘泊时日长，别梦依稀常惆怅。老将随至念桑梓，叶落归根返故乡&quot;。\n不管怎么说叶落归根还是中国人的传统观念。\n曲霞镇是苏中平原上一个不起眼的地方、地形地貌也没有什么特别，在镇西头有一条南北走向的大河、人们把它叫&quot;港河&quot;大潮时河面大约有30米宽，据说沿河北上可通大运河，向南是通长江的，实际上我都未亲历过，但通长江是肯定的、因为河水随长江每天有两次潮涨潮落。解放前曲霞镇的酿酒业比较发达，有好几家知名的大糟坊，酿出来的酒都是从这里用船通过长江运出去的，公私合营前后就慢慢衰落了。\n我童年时老家没有公路、不通汽车，要出行、近处靠双脚板走，或雇一辆独轮车、那还是靠车夫的脚板。童年曾随我外婆到她娘家七圩就是这样去的。走远处就得乘&quot;快船&quot;走水路，快船就是鲁迅先生笔下的乌蓬船，记不清是两天还是三天才有一班、若天气不好就不定时了，依稀记得快船是从季家市那个地方出发经曲霞再经若干个码头到长江再从江南转入京杭大运河的，哪里是航程的终点？可能只有乘客和船家知道。后来毘盧寺有了公路通了汽车，快船就逐渐从人们的视线和记忆中消失了。曲霞镇到毘盧寺还有十二华里土路是不通汽车的，这一段是靠&quot;二轮车&quot;也就是自行车运载，在自行车后架上绑一块等宽稍长的木板搭乘的人就坐在后面，到七九年我结婚和爱人一起回老家探亲时还是这种情况。如今交通己很发达实现了村村通汽车，但&quot;港河&quot;还在不知疲惫地背负着更多的汽油驳子（机动船）和木帆船为人们服务着、发挥着水上交通的作用。\n曲霞镇也算得上是水乡吧，它所处的位置是包在四条河沟之间的，沿着&quot;港河&quot;向东平行一字排开四条河，除最南边的叫&quot;三节沟&quot;外其它都没有名称，延伸到哪里我也说不清楚，港河是它们的源头和出口。每条河之间的距离都不足五百米，河的宽度大潮时水面也只有近二十米，镇的中心就夾在四条河的中间，逼仄的街道当中是用五条麻石和青石铺就的，街道近两公里长，两边是拥挤得歪来扭去的一些盖着黑色屋瓦的低矮房屋，几十家商铺有餐饮小吃店、百货日杂店、酱园店、药店、银匠店、皮匠店、木匠店、木行（hang）、竹行、老虎灶（卖开水的地方）和一些政府的办事机构社会团体如食品站、供销社、工商联、邮电局、信用社、供电所等等就散落在其中。\n尤其是夏天的傍晚、街头巷尾叫卖炒螺蛳、香干、臭干、菱角、馄饨等小吃的吆喝声响至今还记忆犹新。\n镇东头有好几座牌坊不知何时为何人所立、也记不清牌坊上刻的是什么了，有一座小石桥就称&quot;牌坊桥&quot;，从我朦胧记事起不知何故就将牌坊全拆掉了，桥到我离家时仍在使用。街道两边的路灯过年过节才亮几天外，平常一到晚上到处都是黑黢黢的，中学隔一条河在镇东北角、放晚自习走回家真还有一点害怕。还有一些社办工厂、医院和居民住宅都不规则地分布在当中两条河的南北两岸，当时全镇没有一幢楼房。\n四条河的水质都比较好，最边上的两条河里都长着菱角和荷花。中间两条河是饮用水的水源，夏天可以游泳、摸蚬子和螺蛳、钓虾钓鱼，后来不知道是哪一年被填掉了一条河、上面修了农贸市场，其余的都污染得成了臭水沟，去年回去时镇政府根据建设社会主义新农村的要求、又要把填掉的河开挖出来建成新的景观带。\n河汊多小木桥就多也便于出行，我家在主街道的河南面、一九七一年由我母亲主持翻盖了三间房面积约120平方米，翻盖房子时因资金材料不足，我母亲到处想方没法东挪西借吃尽了苦。家西边紧邻人民医院，后边就有一座木桥叫&quot;堂子桥&quot;桥对面有一浴室、家乡人把浴室叫做&quot;洗澡堂子&quot;，桥头边有一烧饼店、店主姓许，他烤出来的&quot;斜角饼&quot;在一里多外就可以闻到香味，至今也让人难以忘怀。\n在南北向的港河上连系东西方向的仅有一座三拱石桥、根据地理位置在镇西边、人们都叫它&quot;西石桥&quot;己有一两百年的历史了，上世纪九十年代初老家通公路要在河上建一座水泥大桥，当材料备足开建时，一天凌晨石拱桥突然倒塌，没有伤一人一物，而且事先全然没有一点要倒塌的迹向，据传说石拱桥是有灵性的，它是被要建的水泥大桥气死的。是真是假只有让个人的心灵去感应了，真是天下之大、无奇不有。\n老家的民风民俗也很淳朴，邻里乡亲有事都会出手相帮，我外婆的一个干姊妹我们称&quot;季家奶奶&quot;，我们小的时候、特别三年自然灾害期间家里比较困难、全凭这位奶奶照顾，以后她老无所依，我们兄弟姊妹就把她当作我们的亲人，给她养老送终。我姐上高中也是乡亲邻里你2元他3元凑的学费。我的母亲也是一个乐善好施的人，我家那时比较困难、但只要比我家更穷困的宁可苦自己总要竭力相助。因此，从小就培养了我们乐于助人的好品德，也让我们终身树立了知恩图报和坚信好人必有好报的思想观念。在我们这个熟人社会的小镇上至今还有很多买东西可临时赊欠、熟人间借款借物无须打借条、邻里乡亲谁家有难众人相帮的故事。小镇现在虽然也很开放、但美好的传统道德、公序良俗在乡亲们当中至今也没有变。\n昔日的同学、战友和朋友很多、听说有几位很有才华的己经作古、令人痛惜。健在的联系得也很少，希望有机会补上这一课，也希冀父老乡亲、村人故旧能记起从这个镇上走出去的我。\n现在的曲霞镇与记忆中的曲霞镇面目己绝然两样，随着时光的变迁、新的必然要崛起，旧的终归要消失。变是合乎宇宙运动的永恒法则，不变是印在人们脑子里的美好记忆，其实变与不变只是人们心理的体验过程。\n值得回忆的事情很多，大都是少年时代最纯朴的、点点滴滴的、真实的生活。能勾起和打动我情感的故事也很多，它都深深地印在我的脑海里。\n总觉得能让人思念的曲霞镇是可爱的，当然现在的曲霞镇更可爱。\n我爱我的老家-----曲霞镇。"},{"id":183,"title":"考察之杂感","category":"散文","date":"二零零六年八月","body":"今年五、六月间，有幸随市人大代表团视察酒钢集团公司本部以外所建的分支机构：兰州榆中钢厂和山西翼城钢厂，感触自然甚多。榆钢、翼钢的建成投产并获得了可观的效益，是酒钢人又一次把市场经济的战略眼光和弘扬&quot;铁山精神&quot;结合成功的典范。&quot;理念新、敢拚搏、速度快、起点高、能吃苦、管理好&quot;，是我对他们两厂创业经验的总结，无论是企业管理还是行政管理都很值得借鉴。\n这次视察活动中沿途考察学习了各地人大的工作，同时还参观游览了祖国的很多名山大川、世界文化遗产、民族风情和现代化旅游景点。如：甘肃平凉崆峒山、陕西宝鸡法门寺、蒲城县杨虎成将军的公馆、唐睿宗李旦的寝陵-----桥陵、西安大雁塔、大唐芙蓉园、渭南的关中风情园、西岳华山、山西阳城清康熙年间（陈敬廷）的宰辅相府-----午亭山村、明朝大移民祖根之地洪洞县大槐树、平遥古城、乔家大院、尧都华门、太原晋祠、五台山。\n五台山是我国四大佛教名山之一，（山西五台山、安徽九华山、四川峨嵋山、浙江普陀山）五台山是文殊菩萨的道场，文殊菩萨是智慧佛，所修的法门认为没有文化就会愚昧，倡导学习文化、关心教育、尊重知识，尊重人才。安徽九华山是地藏菩萨的道场、佛说：&quot;我不入地狱谁入地狱&quot;主张处处事事以身作则、率先垂范。父母是子女的表率，师长是民众的榜样，做领导的要有胸怀，&quot;人非聖贤孰能无过&quot;对有过失的人要宽容、要给予改过的机会。四川峨嵋山是普贤菩萨的道场、以教化众生为已任。感恩是为人之道，首先要感恩父母，人为父母所生所养，成才也离不开老师领导的教育与培养，感恩要在忠诚的基础上孝顺父母、报效国家。浙江普陀山是观世音菩萨的道场，其布道的核心思想是：&quot;大慈大悲、救苦救难&quot;以慈悲为怀、人与人之间心灵的距离就近了。提倡善心、赞美善心、与人为善、助人为乐、是为慈。世事不尽人意、对有困难的人、不幸的人、要有怜悯之心、同情之心、是为悲。做人要有善心多做善事，你就是佛，佛在心中你就可以成佛。\n北岳恒山悬空古寺、大同云岗石窟（云岗石窟是我国著名的三大石窟之一，最著名的应是甘肃敦煌莫高窟，次之为河南洛阳龙门石窟。天水麦积山石窟和永靖县炳灵寺石窟我也曾参观过。）呼和浩特昭君墓，敖包祭、鄂尔多斯成吉思汗陵、宁夏银川西夏王陵、电影城，石嘴山沙湖风景区等，参观考察尤如蜻蜓点水、走马观花，但仍然感受到了泱泱大国的悠久历史和华夏文明的博大精深，激励我们中华儿女在新世纪的世界民族之林中更应该矗立起我们中华民族应有的位置。\n攀登西岳华山和北岳恒山是我多年的夙愿，五岳之首的东岳泰山是二零零五年国庆节期间专程去攀爬的，南岳衡山和中岳嵩山都是前几年出差路过时登顶的，五岳的绝对高度都不算太高，大约记得东岳泰山的海拔高度是1524米，西岳华山的海拔高度是2160米，南岳衡山的海拔高度是1329米、北岳恒山的海拔高度是2017米，中岳嵩山的海拔高度是1440米。这几座山的绝对高度与我去西藏途经的海拔5300米的昆仑山口和我四次登顶的5600米的祁连山&quot;七、一&quot;冰川相比还真是小巫见大巫。东岳泰山的海拔比嘉峪关市区的平均海拔1640米还要低百米多。但东岳泰山和西岳华山的相对高度还是不小的，尤其是华山从几乎垂直的天梯徒步登顶，如果没有亲身经历是不会体会到其难其险，也感受不到登顶之后&quot;与天奋斗、其乐无穷；与地奋斗、其乐无穷；与人奋斗、其乐无穷。&quot;的那种乐趣。\n去年，泰山登顶之后确有一种傲视天下的心情，并想记录下来，不知道是因为忙？因为懒？因为体会不深刻？特别是历代帝王登山封禅都留下祭文、一个小人物还能有什么可说的压力，致使至今未能成文，这次登上华山之顶，情感发生了变化似乎又悟到了新的玄机与禅意，遂将两次的思绪凑合到一起有感而发。站在雄峙的高山之颠可随意驰骋想象、放牧思想，伸向天际、指向无极，心旷神怡、思无羁绊，极目远眺、仰观苍天、浩瀚宇宙、无边无垠；俯瞰大地，山川村落、一览无余，此境此景不仅心情跟天地一样广阔旷达，而且还有&quot;会当凌绝顶、一览众山小&quot;豪气十足的感觉，这一点儿都不夸张。此时，人在天地之间，孰大乎？孰小乎？人，站在高山之颠就是&quot;征服&quot;大山的证明；航行在大海之中就是&quot;征服&quot;大海的证明；遨游在太空就是&quot;征服&quot;宇宙的证明。人是伟大的。人，任何时候都无须妄自菲薄。人，终归是大自然的产物，大自然才是世间万物真正的主宰。人在泰山面前宏伟吗？人在华山面前雄壮吗？答复是肯定的。直面时间、空间，人是十分渺小的。人，任何时候都不能妄自尊大。那么，人到底是伟大的还是渺小的呢？屹立高山之颠、位列高天阔地之间只能凭借自己微薄浮浅的知识、涉世不深的阅历、茅塞初开的悟性找一条粗糙的理由来安慰涌动的心灵。\n人，万物之精灵，他（她）们有思维、有精神、人的智慧是无穷的、人的精神是无限的，具有精神的人可以狂想一拳击碎地球，可以狂想一口吞掉太阳，可以狂想把天上的星星摘下来串一条项链，幻想不受限制，大胆的狂想永远都不能变成现实。当然，具有智慧的人绝不会胡思乱想、胡作非为。宇宙间只要有人，精神就是永恒的，但精神绝不是万能的，具有智慧的人才是伟大的。大自然孕育了生命。作为&quot;物质&quot;的人，区区血肉之躯，用沧海一粟比喻毫不为过。人的力量，在大自然面前、在宇宙的时空里微不足道，就现在的科技水平而言，人对大自然和对自身的认识还谈不上一知半解，很多自然现象至今仍是未知的谜。如果说，人在哪一方面&quot;征服&quot;了自然，我认为也是不值得骄傲的，这种&quot;征服&quot;无非是对自然善举现象的利用罢了。如果人真正敢与大自然较量那简直是蚍蜉撼树不自量力。有关统计资料显示中国女性目前的平均寿命是75岁，男人的平均寿命是72岁，就生命而言在浩瀚的时空里这一丁点儿算得了什么？&quot;心比天高、命如纸薄&quot;这就是一般肉骨凡胎普通人生的结局，所以，人啊人，还是好好珍惜你那美好、短暂的一生吧！\n人生的道路虽然短暂，但在人生的道路上每个人都背负着很多责任和欲望，都希望生命发光，放弃责任尤如行尸走肉，生命就会毫无意义，背负贪婪的欲望，生命也会失去光芒，要让生命辉煌就要找到平凡与幸福的结合点，理解快乐与幸福的奥妙。佛家诠释&quot;舍得&quot;就是要学会&quot;舍弃&quot;，只有学会&quot;舍弃&quot;才会有所&quot;获得&quot;，&quot;舍弃&quot;本身是一种智慧、一种品质、一种操守、是一种凤凰涅槃，舍弃对&quot;金钱、名利、美色......&quot;贪欲的追求；舍弃对&quot;阴谋、邪恶、仇恨......&quot;角逐的念头；舍弃对&quot;虚伪、浮躁、是非、......&quot;沉湎的缠绕。舍弃一切需要舍弃的无谓欲望，舍弃一切应该舍弃的包袱累赘，就会减少许多人与人之间不必要的计较和伤害。坦然的舍弃，是一种对恶的大度，也是一种无私的宽容。勇于舍弃者果断、乐于舍弃者豁达、善于舍弃者智慧。懂得舍弃、学会舍弃才会走出炼狱、获得新生，获得真诚、善良、和谐、安宁、无私、高尚，才能彻悟人生，进入一种纯洁无暇、至高无上的新境界。攀泰山、登华山让我汲取了天地聪慧之灵气、人间浩然之正气，明白了一点人生真谛，找到了人生旅途的方向，生命需要阳光、生活需要豁朗，为所有真正的&quot;人&quot;祈福，学会&quot;舍弃&quot;吧！"},{"id":184,"title":"让生命辉煌起来","category":"散文","date":"二零零五年九月八日","body":"每个人的一生都具有不同的经历，否则就没有个性，每个人的一生又大都不会在一帆风顺中度过，遇到磕磕碰碰，坎坎坷坷的事总是难免的，这是共性 。没有痛苦的历炼和潜心的修养也许就没有高尚的人格、就没有做人的尊严，古人说：&quot;天降大任于斯人，必先苦其心志、劳其筋骨、饿其肌肤&quot;，&quot;宝剑锋自磨砺出，梅花香从苦寒来&quot;，说的就是这个道理。\n让生命辉煌起来，这是每一个人一生都在追求的目标。我理解生命的辉煌，并非是有多少头衔的达官贵人，或有多少资产的商贾富豪。身体健康、家庭和睦、事业顺利、心情舒畅，就是生命中的辉煌。\n一个人从狭义上讲，不能决定自己生命的长度。但是，你可以拓展生命的宽度，让生命更有质量，现实生活中，你不必刻意去想如何影响别人，但完全可以好好掌握自己；你不可能全然预测明天，但可以充分利用今天；你不可能做到事事顺心，但你可以做到事事尽心。把握自己、把握今天、踏实做事、问心无愧，这也是生命中的辉煌。\n在生活中，要让自己懂得豁达大度，因为豁达大度才能做到不钻牛角尖，潇洒自如，乐观进取。\n在生活中，要让自己经常愉悦开朗，因为愉悦开朗才能把快乐带给别人，告别烦恼，远离是非。\n在生活中，要让自己学会与人为善，因为与人为善才能多个朋友多条路，与人方便，与己方便。 \n要让生命辉煌、生活美满，就应该有一颗不奢求太多、轻松无忧的心。快乐，不是因为拥有得多，而是因为计较得少。多是负担，是另一种失去；少非不足，是另一种有余； &quot;事能知足心常乐，人到无求品自高&quot;，只要不好高骛远、不盲目攀比，去非分之想、弃不义之心，哪还有什么不快乐的呢？对什么都不满足的人，也很难得到高兴和快慰，富兰克林说：&quot;对于不知足的人，没有一把椅子是舒服的&quot;，知足者才能常乐。\n人，从获得生命的那一刻开始，以及后天所拥有的一切，都是大自然、父母、子女、社会、朋友的赐予，任何一个人在真空中绝对不能够独立生存，自古以来困扰人们的&quot;名&quot;和&quot;利&quot;，真是生不带来、死不带走的&quot;东西&quot;，无底的欲望就像洪水猛兽一样，一旦泛滥、必成大灾，纵欲如玩火、玩火必自焚，所以，我们不仅要学会紧束名缰利索，还应该懂得满足。懂得淡泊名利，更要学会感恩，要有滴水之恩涌泉相报的胸怀，应该感谢苍天、感谢大地、感谢所有应该感谢的人。\n幸福快乐就像绚丽多彩的气球，自由自在的飘浮在湛蓝无垠的天空，放飞人生的寄托、放飞美好的心情，无非是有的人放飞得多些、有些人放飞得少些、有的人放飞的高些，有的人放飞的低些。每个人只要有自己的一片天空，足矣，何必计较你多我少、你高我低。因此，我奉劝大千世界里的芸芸众生、人生苦短、不必自找烦恼！若有机会我真心的愿意，把我放飞的那一部份，分送给最需要的人，让大家过得都幸福美满。\n具有同情心，对需要帮助的人，竭尽全力不图回报的给予，这是生命中的又一种辉煌。\n有一位挚友给我发了一条短信说是要送我三个瓶子，装满一瓶幸福、装满一瓶快乐、还要留一个空瓶子给我装生活中的烦恼，我真的感谢我的这位朋友，我一定把生活中所有不愉快的事统统装到这个魔瓶中尘封起来，让幸福和快乐永远伴随自己。\n人的一生中，重要的不是遇到什么事，而是面对现实问题的态度和处理方法。当我们面向阳光时，感到的是光明；当我们背向阳光时，看到的是阴影；当我们给人献花时，闻到花香的首先是自己；当我们算计别人时，算计的首先也是自己。所以，我们要像在棋枰上博弈一样，做到&quot;胜不骄、败不馁&quot;，以一颗极其平常的心对待自己，同时要用一颗善良的心对待别人。常怀好意、常做好事、光明磊落、一生无悔，坚信好人一定会一生平安。\n人格成熟的标志还表现在，当遇到困难和挫折时应该平静乐观的去对待它，真正做到随遇而安，不要为一些生活琐事斤斤计较，不要怕被谗言小人的流言蜚语中伤，更不要把坏人的魔障伎俩当作沉重的包袱压在心头上，一定要相信自己；一定要相信&quot;君子坦荡荡、小人常戚戚&quot;；一定要相信&quot;善有善报，恶有恶报&quot;；一定要相信、蠢人总是&quot;搬起石头砸自己的脚''。\n人的一生中，心境会随着生活的内容而不断的跨越和延伸，一帆风顺也好、岁月沉浮也罢，发生变化的是生理，可以不变的是心情。我祝愿我所有的朋友、永远让幸福、让美满、让快乐、充实生命，让辉煌起来的生命，在平静、平和、平安中陪伴我们踏踏实实度过每一秒、每一分、每小时、每一天、每一年，度过一生。"},{"id":185,"title":"说说酒文化","category":"散文","date":"二零一二年春节","body":"常为喝酒的事与老伴讨论有害与有益的问题，老伴列举了诸多喝酒伤身、酒多误事的根据，意在让我戒酒。我也找出酒能健体、酒能燃情的不少理由，坚意喝到底，各执一词、有时互不相让。其实，我们所讲的有害与有益都是很片面的，要认识这个问题还得借助唯物主义辨证法、一分为二、全面的去看，正确地把握&quot;适度&quot;肯定有益，&quot;物及必反&quot;绝对是真理。\n一、酒的历史。\n说到酒文化，必然要去追寻酒的历史。中国酿酒的历史悠久，很多古籍上都有记载如：东汉《说文解字》上说&quot;古代仪狄作酒醪，禹尝之而美，遂疏仪狄。&quot;&quot;酒&quot;的条目中有&quot;杜康作秫酒&quot;的解释，《世本》中也有同样的说法。公元前二世纪史书《吕氏春秋》云：&quot;仪狄作酒&quot;，汉代刘向编辑的《战国策》中说：&quot;昔者，帝女令仪狄作酒而美，进之禹，禹饮而甘之，曰：'后世必有饮酒而亡国者。'&quot;据传夏桀、商纣亡国皆因负于&quot;酒&quot;。从禹算起酒的历史己有五、六千年、可与中华文明发展同步。还有传说从黄帝时代就开始酿酒，《黄帝内经.素问》中有提到黄帝与歧伯讨论酿酒的事情，当时的&quot;醴酪&quot;就是用动物乳汁酿成的甜酒。\n我国三千余年的文学和历史著作都与&quot;酒&quot;相伴如：《诗经·小雅》中有一篇文章《鹿鸣》就讲到酒，&quot;我有旨酒，嘉宾式燕以敖。&quot;说的是我有美酒怎么不邀嘉宾一同品尝呢？四大名著皆于酒结缘，《三国演义》开篇词《临江仙》中就有&quot;一壶浊酒喜相逢&quot;句，第二十一回&quot;曹操煮酒论英雄、关公赚城斩车胄&quot;中描写：曹操与刘玄德&quot;随至小亭，己设樽俎，盘置青梅，一樽煮酒，二人对坐，开怀畅饮。酒至半甜，忽阴云漠漠，骤雨将至。&quot;......《水浒传》中，吴用智取生辰纲、武松醉打蒋门神。《西逰记》第五回&quot;乱蟠桃大圣偷丹、反天宫诸神捉怪&quot;中有诗为证：&quot;天产猴王变化多，偷丹偷酒乐山窝。只因搅乱蟠桃会，十万天兵布网罗。&quot;第二十九回&quot;脱难江流来国土、承恩八戒转山林&quot;中写道：国王闻得此言，十分欢喜心信，即命九嫔妃子&quot;将朕亲用御酒整瓶取来，权与长老送行。&quot;《红楼梦》中刘姥姥醉卧怡红园、憨湘云醉眠芍药裀等皆是因酒而起、哙炙人口的故事。\n盛唐时期是我国文学人才辈出的年代、当时湧现出了近200名著名诗人。因此，唐诗是我国文学史上一颗璀璨明珠，不朽的诗篇大都与&quot;酒&quot;有关，流传于今。现录几位著名诗人的&quot;酒诗&quot;供大家欣赏。李白的《将进酒》&quot;君不见黄河之水天上来，奔流到海不复回。君不见高堂明镜悲白发，朝如青丝暮如雪。人生得意须尽欢，莫使金樽空对月。天生我材必有用，千金散尽还复来。烹羊宰牛且为乐，会须一饮三百杯。岑夫子，丹丘生，将进酒，杯莫停。与君歌一曲，请君为我倾耳听。钟鼓馔玉不足贵，但愿长醉不复醒。古来圣贤皆寂寞，惟有饮者留其名。陈王昔时宴平乐，斗酒十千恣欢谑。主人何为言少钱，径须沽取对君酌。五花马，千金裘，呼儿将出换美酒，与尔同销万古愁。&quot;\n杜甫的《饮中八仙歌》&quot;'知章骑马似乘船，眼花落井水中眠。'（贺知章）'汝阳三斗始朝天，道逢麯车口流诞，恨不移封向酒泉。'（汝阳王李琎是唐玄宗的侄子。）'左相日兴费万銭，饮如长鲸吸百川，衔杯乐圣称避贤。'（左丞相李适之）'宗之潇洒美少年，举觞白眼望青天，皎如玉树临风前。'（崔宗之）'苏晋长斋绣佛前，醉中往往爱逃禅。''李白一斗诗百篇，长安市上酒家眠，天子呼来不上船，自称臣是酒中仙。''张旭三杯草圣传，脱帽露顶王公前，挥毫落纸如云烟。''焦遂五斗方卓然，高谈雅辩惊四筵。'&quot;\n白居易的《同李十一醉忆元九》&quot;花时同醉破春愁，醉折花枝作酒筹。忽忆故人天际去，计程今日到梁州。&quot;\n杜牧的《江南春》&quot;千里莺啼绿掩红，水村山郭酒旗风。南朝四百八十寺，多少楼台烟雨中。&quot;\n曹操&quot;对酒当歌，人生几何。&quot;&quot;何以解忧、唯有杜康。&quot;的名句几乎家喻户晓。汉时&quot;鸿门宴&quot;、宋时&quot;杯酒释兵权&quot;的故事经久不衰。\n还有很多美丽的传说，汉时霍去病征西获胜、汉武帝赐御酒犒赏、霍去病为了让三军将士分享、将酒注入泉中、随之就有了&quot;酒泉&quot;之说。\n现代的文人也是好酒的，朱自清、汪曾祺两位散文大家，都是我的老乡，在他们的作品中也可看到对&quot;酒&quot;独钟的影子。\n有实物为证的是从河南信阳地区罗山蟒张乡、距今己有三千余年的商代墓中、装在一青铜卣内的古酒，出土时密封依旧完好。另一处是河北平山县境内、战国中山王陵墓中出土的两壶酒，一园形卣中存酒约七成重六千克，另一壶存酒一半重四千克，两壶酒啟封时仍清澈透明、娇绿欲滴、香气四溢。\n2005年到非洲进行商务考察，有幸到埃及国家博物馆参观、馆内陈列着从大金字塔内出土、距今已有7000年历史的美酒。地球上有224个国家（193个）和地区（31个）我去了约十分之一，亚洲、非洲、欧洲、北美洲、大洋洲足迹所至，无论哪个国家、哪个地区、哪个民族真没有发现与&quot;酒&quot;绝缘的。酒是苍天賜给人类的圣品。\n我国是一个酿酒大国，也是一个酒的消费大国，全国有332个地级行政建制、其中地级市265个至今还未听说有哪个市没有酿酒业的，酿酒大省有贵州、四川、江苏、山东、山西、陕西、甘肃，我所在的甘肃不仅14个市州都有酒厂、一半以上的县也有酒厂，有资料反映中国人每年喝的酒约一个西湖的储水量。\n二、酒的种类。\n中国酒的种类繁多、质地精良、风格独特，按酒精含量的多少划分有60度以上的为高度酒，40度至60度的为中度酒，40度以下的为低度酒三种。按酒的饴糖浓度高低划分有甜型、半甜型、&quot;干&quot;型酒三种。按制作方法可划分为发酵酒、蒸馏酒、配制酒三种。按商品分类可划分为白酒、黄酒、啤酒、果露酒、药酒五类。白酒从香型上还可划分为清香型、浓香型、酱香型、米香型、复香型五个类型。\n三、酿酒工艺。\n酿酒是酵母菌在厌氧环境下将糖类分解为酒精、水和二氧化碳的过程。\n白酒酿造多采用固态发酵的方法其过程是将原料（高粱、玉米、大麦、小麦、大米、豌豆、薯干......）、加入一定数量的疏松剂（稻壳、谷糠、高粱皮、......）、弃酒糟和水按一定比例混合拌匀后、闷料三十分钟以上待升温至45度再上甑煮料、蒸煮后的混合料冷却到35至40度后、拌入糖化用的曲子或酵母放在窖内或缸内发酵并保持温度18至28小时，再降温到30至37度、保持温度5至15天再进行蒸馏出酒后，即可第二次投料如此循环往复，蒸馏出来的酒在窖中陈酿，装瓶前再进行勾兑。其工艺流程是：原料粉碎 -拌料浸泡-入甑初蒸 -起堆焖料 -入甑复蒸 -出甑摊晾-加曲拌匀 -装箱培菌 -入窖发酵 -蒸馏出酒 -陈酿催化 -勾兑装瓶 。\n葡萄酒以葡萄汁为原料，经葡萄酒酵母发酵而成。制作过程包括葡萄破碎、控制发酵、酒窖管理、陈酿和勾兑。破碎去梗后的葡萄及果汁装入大桶发酵经酵母作用葡萄中的糖分解为二氧化碳和酒精、发酵期为数天至数月、根据工艺不同可酿制出红、白、桃红或玫瑰色的葡萄酒。\n啤酒是以大麦为原料、以啤酒花为香料经过麦芽糖化和啤酒酵母酒精发酵制成。由于发酵工艺与一般酒精生产不同，啤酒中保留了一部份未分解的营养物，从而增加了啤酒的香味。\n四、酒品酒德。\n酒是一种精神文明、是一种文化传承、自产生以来，便给人类的社会增添了丰富的生活情趣和文化内涵。中国素有&quot;礼仪之帮&quot;之美誉，中国的政治制度、伦理道德、风俗习惯、无不讲究&quot;礼节&quot;。《礼记.乐记》制定的&quot;酒礼&quot;中规定：能饮酒的人可以饮；不能饮酒的人可以不饮；决不可以强灌，要做到不沉不湎，饮而成欢，不生是非。在酒席上如有谁喝醉出言不逊、或随意骂人，失态損德还要受到处罚。古人吴彬提出酒要禁忌&quot;华诞、连宵、苦劝、争执、避酒、恶谑、喷秽。&quot;程宏毅在《酒警》中指出饮酒要&quot;警骂座、警苛令、警趋附、警喧谈、警煞风景&quot;。&quot;酒礼&quot;就是指人们在喝酒当中必须遵循的行为规笵，文人雅士推崇的是超凡脱俗的境界和儒雅飘逸的风度。千百年来，酒文化一直受传统思想的浸润、也必然会渗透到现代生活当中，在人们的日常交际中起着重要的作用，世有&quot;酒见人心、酒见人性、酒见人情、酒见人品&quot;一说，一个人酒品酒德的好坏、不仅折射了他本人品格和道德的好坏，同时及也反映了其处世的声誉如何。\n&quot;酒，吉凶所造也&quot;酒有利有弊、既能让人如痴如醉、使人性尽善尽美，又能让人祸害连连、荒淫无度、尽露人性之恶相。鉴于它的两重性、酒便有许多充满褒贬含义的别名：&quot;欢伯&quot;、&quot;琼浆&quot;&quot;甘露&quot;、&quot;神品&quot;、&quot;祸水&quot;、&quot;狂药&quot;、&quot;魔浆&quot;、&quot;祸泉&quot;等等。\n中国人喝酒颇有讲究，凡有客来接风洗尘，亲朋相聚把酒言欢、节日喜事举杯相庆、愁上心头借酒消愁，婚丧嫁娶都要设宴招待，而且有&quot;无酒不成席&quot;之说，且喝酒吃饭不仅可体现人们日常生活中的贵贱、长幼，同时酒也是连亲情、待朋友、弥裂缝的&quot;粘合剂&quot;，酒更是当今社会官场、商场中不可或缺的&quot;交际花&quot;。&quot;敬酒&quot;是酒席中的主要形式，一般情况是由主人宣佈开席共同敬各位宾朋三杯酒，酒过三巡接着由辈份小或地位低的向席中的长者或主要客人先敬酒、依次类推，敬酒可根据不同情况可敬一杯、二杯、三杯、四杯、六杯，且各有说词。敬酒有给客人敬自己不喝的，这个传统是物质匮乏时留下的。现在也有先喝为敬的，也有敬一碰一的，以示对客人的尊重。敬酒一般是对参席人员全数敬，也是表示对所有客人的尊重。敬酒程序完毕后是&quot;劝酒&quot;，劝酒可根据席中人员关系情况、可以找不同理由分别劝人喝酒。&quot;文劝&quot;，被劝之人可商量喝酒的数量，&quot;武劝&quot;是令人不堪忍受的强行劝酒、或单挑或围剿、甚至揑着鼻子给人灌酒，或是声嘶力竭的豁拳，赢拳的以胜利者自居得意忘形、输拳的沮丧认倒霉以喝酒为罚，总是千方百计想把人灌醉。酒可以令人在由兴奋到麻醉的过程中暂时忘怀一切。有一条短信形容所有喝酒的人是这样的：未喝之前慢言细语、喝到三分甜言密语、喝到七分豪言壮语、喝到微醉胡言乱语、喝到大醉不言不语。\n各国人民都喝酒但文化差异很大，有一年法国国防部长访华从上海乘机返回巴黎正好与我国一名外交官同机，闲谈中说这次访华很成功，但有一件事他不太高兴，就是为什么喝酒的时候要强迫，为什么不喝就不够朋友？外交官随即解释在我们的文化里对能喝酒的人是比较尊敬的，因为酒后吐真言，那是真朋友。部长说我还是不理解，喝多了以后难受的是我呀，并且说话语无伦次让别人笑话，这不是对朋友应有的态度吧？另一次是俄罗斯总统叶利钦到上海访问还是这位外交官接待，因叶利钦心脏不好，就交待晚宴上不要准备烈性酒，宴会上叶利钦见无烈性酒可不干了，说上海人不喝茅台吗？上海市场上没有茅台吗？随即给他上了茅台酒，他喝了七杯方罢休，他的保健医生在另一桌己喝得烂醉如泥。酒文化各个国家不一样。因此，喝酒不仅因&quot;人&quot;而宜而且还要因&quot;国&quot;而宜，否则有可能好心变坏心，贻误大事。总之，违反&quot;酒礼&quot;有伤酒德的喝酒场合和方法我是不赞成的。\n自古至今，酒一直伴着历史兴亡的脚歩前进，兴也有酒、亡也有酒。酒确可谓经盛衰而无废，历百代而作珍。&quot;酒之为福矣？酒之为祸矣？&quot;，其实皆不然、人的品格优劣与酒无干。善者为善、恶者为恶、有酒无酒、喝与不喝，都改变不了什么，智愚在人，我们无须对酒颂之过高、责之过重，对酒的态度应该是不禁不纵、有仪有节、趋利避害。\n&quot;花看半开、酒饮微醺&quot;才是却到好处。"},{"id":186,"title":"谈谈茶文化","category":"散文","date":"二零一四年十一月","body":"中国文化源远流长、博大精深、也可以说无所不包。平民百姓的开门七件事&quot;柴米油盐酱醋茶&quot;，关乎老百姓日常生活的&quot;茶&quot;也在其中，更有文人雅士重要活动的&quot;琴棋书画诗酒茶&quot;，酒和茶一样不少。&quot;酒&quot;和&quot;茶&quot;文化的内涵、也是众多中国文化内涵中的一种具体表现。茶文化即是通过沏茶、观色、闻香、啜茗、品茶等习惯、与中国人特有的礼仪形式相结合，提练出一套程式化的礼节现象。\n酒和茶都是饮品，酒性味浓刚烈、茶性清淡柔顺，可算是同根同源。我曾写过一篇《说说酒文化》夸赞其五千多年不败的原因，茶文化其当亦是，酒和茶、一刚一柔、一张一弛、相得益彰，表现的是中华民族子孙的性格和精神。\n中国是茶的故乡、也是茶文化的发源地，中国茶的发现及利用也己有五千多年，历史非常悠久，《华阳国志．巴志》中就有&quot;周武王伐纣实得巴蜀之师茶蜜皆纳贡之&quot;的记载，《诗经》总集中对茶也有记述。中国茶文化发于神农、闻于鲁周公、兴于唐朝、盛于宋明，且长盛不衰、传遍全球。如今影响日本至深的茶道就是宋时传入，日本《类聚名物考》明确记载&quot;茶道之起，在正元中、筑前崇福寺开山南浦、昭明由宋传入。&quot;茶文化是中国文化大家族中的一朵奇葩，也应是我中华儿女对世界人类的一大贡献。茶是中华民族的举国之饮，中华茶文化糅合了中国佛、儒、道诸派思想、独成一体，主要表现在修身养性、陶冶情操。它的社会功能有发扬传统美德、展示文化艺术、促进经济贸易、加强民族团结的作用。\n我国是茶叶生产的大国，茶叶的主产区主要分布在东经94-122度、北纬18-37度范围内，因为这里土地肥沃、水源丰富、阳光充足、气候湿润。有名的四大产区：\n一是华南产区，包括广东、广西、福建、海南、台湾，盛产黑茶、红茶、乌龙茶。\n二是西南产区，包括云南、贵州、四川、西藏东南部，这里是我国最古老的产茶区。\n三是江北产区，位于长江中下游北岸包括河南、陕西、甘肃、及苏北、皖北、鄂北等地是我国最北部的产区。\n四是江南产区，包括浙江、湖南、江西和苏南、皖南、鄂南等地、是我国最大的茶叶产区、茶叶产量占全国茶叶产量的三分之二以上。\n中国也是世界上最大的茶叶生产国，茶叶产量占世界产量的三分之二以上，茶叶出口占世界第一位。\n中国茶叶的种类繁多、十分复杂，归纳起来有六大类：\n一是绿茶，绿茶又分为炒青、烘青、晒青、蒸青。炒青的主要产品有龙井、碧螺春，烘青的主产品有浙闽烘青，晒青的主产品有滇青、川青，蒸青的主产品有煎茶、玉露。\n二是乌龙茶（又名青茶），乌龙茶有闽北、闽南、广东、台湾乌龙之分。闽北乌龙其代表有武夷岩茶，闽南乌龙其代表有安溪铁观音，广东乌龙其代表有凤凰水仙、单枞，台湾乌龙其代表有冻顶乌龙。\n三是红茶，红茶有小种红茶、功夫红茶、红碎茶。小种红茶其代表有正山小种，功夫红茶其代表有滇红、祁红、闽红，红碎茶其代表有叶茶、碎茶、片茶。\n四是白茶，白茶有芽茶、中茶。芽茶其代表有银针，中茶其代表有白牡丹。\n五是黄茶，黄茶有黄芽茶、黄小茶、黄大茶。黄芽茶的代表有君山银针，黄小茶的代表有温州黄汤，黄大茶的代表有霍山黄大。\n六是黑茶，黑茶的代表有潽洱茶、六堡茶、湖北老青茶、湖南安化黑茶。\n中国茶名扬四海，1915年巴拿马万国博览会上评出了中国十大名茶，其顺序为：杭州产的西湖龙井（绿茶）、苏州产的洞庭碧螺春（绿茶）、河南产的信阳毛尖（绿茶）、湖南产的君山银针（黄茶）、安徽产的黄山毛峰（绿茶）、福建产的武夷岩茶（乌龙茶）、安徽产的祁门红茶（红茶）、四川产的都匀毛尖（绿茶）、福建产的安溪铁观音（青茶）、安徽产的六安瓜片（绿茶）。\n2001年3月26日美联社和《纽约时报》公布的十大名茶是西湖龙井、黄山毛峰、洞庭碧螺春、六安瓜片、蒙顶甘露、庐山云雾、信阳毛尖、都匀毛尖、安溪铁观音、苏州茉莉花茶。\n2002年1月18日香港《文汇报》也公布了十大名茶其顺序为：西湖龙井、洞庭碧螺春、黄山毛峰、六安瓜片、福建银针、祁门红茶、都匀毛尖、武夷岩茶、安溪铁观音、信阳毛尖。由此看来、历经百年十大名茶的品名和品质变化並不是很大，可谓名不虚传。\n说到茶文化还真有名人轶事，略举一二说明中国人对茶的挚爱。大清乾隆皇帝六下江南不仅是体察民情，也有旅游休闲之意，江南出名茶，西湖龙井、洞庭碧螺春有口皆碑，一次乾隆在杭州狮峰山下啜茶品茗，对色香味形绝佳的龙井茶大加赞赏、性致一起随挥毫作诗，留下&quot;火前嫩、火后老，惟有骑火品最好&quot;之句，茶农为感皇恩随把乾隆&quot;垂青&quot;的十八棵茶树围圈起来作为&quot;御茶园&quot;以志记念、至今犹在。\n另一次在苏州，当地官员奉上茶品，乾隆帝发现冲泡后绿汤澄汁品尝后赞不绝口&quot;好茶、好茶&quot;问其茶名，官员回答说当地茶农取名，&quot;吓煞人香&quot;乾隆听罢嫌其名过于粗俗很不中听，遂据茶叶形像蜷曲的螺丝肉，色泽青翠、且在清明前采摘，钦定为&quot;碧螺春&quot;，从此名闻天下、延袭至今。制作一斤上等碧螺春茶需要九万颗芽尖。\n乾隆到了晚年更是到了病茶的地步、饮茶成瘾、一次作隐退让位之举、一大臣当即叩头面奏&quot;国一日不可无君&quot;乾隆手捋银须、哈哈大笑幽默地说：&quot;君不可一日无茶&quot;呀。\n我与龙井茶结缘是在上世纪七十年代初、当时在解放军二十军五十九师一七六团当兵，军部就驻在杭州，我有幸参加了军里组织的全军侦察兵骨干、反坦克作战训练，驻训地点就在龙井茶原产地的梅家坞公社，初识龙井茶后就终身酷爱。上世纪八十年代初我的一位同学陈董生来嘉办事赠我出口转内销的龙井茶一盒，打开盒盖清香扑鼻，至今其香仍驻鼻尖、熟记于心，茶早已故去，其盒我仍存留一来是对同学情谊的记念、二是对龙井茶的思念，自此以后再也没有喝上如此好的龙井茶。现身居无锡对无锡地产的太湖翠竹、无锡毫茶、宜兴毛尖、阳羡雪芽（旧称阳羡贡茶）也另有钟爱。\n《红楼梦》作者曹雪芹是一位多才的作家、他不仅精通琴棋书画诗词、对茶的精通更不一般、书中对茶的风俗、茶的种类、饮茶的文化都描写得十分精彩，茶俗有家常茶、敬客茶、伴果茶、品尝茶、药用茶......，说到茶的种类有西湖龙井、君山银针、福建的&quot;凤随&quot;、有云南潽洱茶中珍品&quot;女儿茶&quot;、暹罗（泰国）贡茶......，他在《红楼梦》四十一回《栊翠庵茶品梅花雪、怡红院劫遇母蝗虫》中，将茶叶之&quot;叶&quot;，煮茶之&quot;水&quot;，烹茶之&quot;方&quot;，饮茶之&quot;器&quot;，品茶之&quot;法&quot;，无不演绎得出神入化。他还将自已的诗情与茶意、巧妙的结合在一起，写出了很多令人赞不绝口的佳句，如写夏夜的&quot;倦乡佳人幽梦长，金笼鹦鹉喚茶汤。&quot;写秋夜的&quot;静夜不眠因酒渴，沉烟重拨索烹茶。&quot;写冬夜的&quot;却喜侍儿知试茗，扫将新雪及时烹。&quot;\n清．杨州八怪之首郑燮、题镇江焦山自然庵茶联：&quot;汲来江水烹新茶，买尽青山当画屏。&quot;设身处地极为般配。\n清代名士溥山既是画家又是诗人他有一联：&quot;竹雨松风琴韵，茶烟梧语书声。&quot;酷似一幅优美的风景画，潇潇竹雨、阵阵松风，在这样的环境下调琴煮茗、读书赏月岂不美哉，此联与任何一幅山川煮茗图相配都是不俗的。\n我国现代书法家王梓梧先生以&quot;融通三教儒释道，汇聚一壶色香味。&quot;一联赠丁以寿先生（中央统战部赠送澳门回归礼品画《九九归一》的作者）联中虽无&quot;茶&quot;字，却颂得丁先生的才学与人品。\n还有一联以茶名所作&quot;龙井云雾毛尖瓜片碧螺春，银针毛峰猴魁甘露紫笋茶。&quot;也不失儒雅。\n谈茶更少不了中国第一人茶圣陆羽，陆羽（公元733-804年）名疾，字：鸿渐、季疵、号：竞陵子、桑苎翁、东岗子、茶山御史。唐朝复州竞陵人（今湖北天门）人，一生嗜茶、精于茶道，著有世界第一部茶叶巨著《茶经》可谓是&quot;茶文化&quot;的集大成者、从此以后的茶事皆以此为指导、以此为规范。\n中国的茶道具体表现形式有三种，一是&quot;煎茶&quot;，煎茶把茶叶投入水中一同煎煮，讲究如何选&quot;好茶&quot;、选&quot;好水&quot;，如何&quot;煎煮&quot;让茶更好喝。二是&quot;斗茶&quot;又名&quot;茗战&quot;，由文人雅士自带茶和水，自已动手冲泡，通过互相观其汤色、品其汤味，最后鉴别&quot;茶&quot;和&quot;水&quot;的优劣。三是&quot;功夫茶&quot;、讲究品饮功夫，至今仍流行于福建漳州、泉州、广东潮州一带。中国茶道主要讲究&quot;五境&quot;之美，即茶叶、茶水、火候、茶具、环境。\n宋代的茶道有&quot;三点&quot;和&quot;三不&quot;之说，&quot;三点&quot;有：&quot;新茶、甘泉、洁器&quot;为一点，有&quot;好天气、好心情&quot;为二点，有&quot;风流雅士趣味相投的佳客为伴&quot;为三点。&quot;三不&quot;：&quot;茶不新、泉不甘、器不洁&quot;为一不，&quot;天气景色心情不好&quot;为二不，&quot;品茶者缺乏教养举止粗鲁&quot;为三不，即遇到这三种情形决不作艺术品饮以免败兴。\n中国的茶道已提高到程式化，如绿茶的茶道分为十二式：焚香除妄念、冰心去凡尘、玉壶养太和、清宫迎佳人、甘露润莲心、凤凰三点头、碧玉沉清江、观音捧玉瓶、春波展旗枪、慧心悟茶香、淡中品致味、自斟乐无穷。\n北京盖碗茶的表演形式有二十四套：恭迎嘉宾、敬宣茶德、精选香茗、理火烹泉、鉴赏甘霖、摆盏备具、流云拂月、执权投茶、云龙泻瀑、初奉香茗、陶然沁芳、泉入龙潭、品评江山、百味凝春、重酌酽香、再识佳韵、即兴诵章、书画会赏、尽杯谢茶、嘉叶酬宾、洁具收盏、茶仓归一、再宣茶德、致谢话别。\n中国茶道十分繁琐复杂，我对其没有作过认真细致的深入研究，仅从相关资料中摘取片言只语，初步了解了一些茶文化的要义，真要用其修身养性，茶道中的程式倒是不可任意删减的。要想悟到茶道、人道的至高境界还真不容易，当然世界上的任何事都是人为的，就看你能不能真心去做，毛泽东主席曾说过：&quot;世界上怕就怕'认真'二字，共产党最讲认真。&quot;，只要真心去做就不怕达不到目的。\n&quot;茶文化&quot;不是喝水的文化，茶不仅是用来解渴的更是用来清心的、心很玄乎，清心的事很玄妙，也很难衡量。\n&quot;茶&quot;很具体，是用&quot;火&quot;煮&quot;水&quot;，将&quot;叶子&quot;冲泡其中，再用&quot;茶具&quot;盛出，让&quot;舌头&quot;品出味道。\n茶叶和水是自然大地的产物、是形而下的，&quot;茶&quot;却是形而上的，它道法自然、天人合一、清心寡欲、是通过&quot;人心&quot;的评价才得到的。\n喝水解渴不养心，茶水不过是树叶泡过的水、此水已不是彼水，茶可以清心。&quot;茶&quot;不是一般的物、也不是心、它是天人合一的&quot;茶&quot;，是中国人才有的茶。这是我对中国茶文化的一点感悟。\n现代人经过科学分析认为喝茶可以延年益寿、可以防辐射、可以防癌、可以解体内毒素、可以降血压、可以瘦身、可以防口臭、可以坚固牙齿、可以治疗粉刺、可以利尿明目。诸一不等。有如此好处，我也建议大家多喝茶。\n茶喝多了清心寡欲的理念、自然就可能体悟到，就会有利于为人一生。"},{"id":187,"title":"实录北美之旅","category":"散文","date":"二零一二年五月","body":"转动地球仪一看，北美洲基本是美国和加拿大的版图，对于这块土地、我早就有在退休前有机会一定要去看看的想法。因为，在此以前我己去过欧洲的英国、瑞典、丹麦、挪威、芬兰，去过非洲的南非、肯尼亚、埃及，去过横跨亚欧的俄罗斯和土耳其，去过澳大利亚，去过日本、越南和哈萨克斯坦，也就是说地球上的五大洲我己涉足四大洲，到美洲去一下就算是周游世界了，能到五大洲去走一走、看一看感觉也是自己人生辉煌中的一个亮点。\n今年4月终于成行，这次去美国、加拿大考察学习商标工作外、一路上还对这两个国家的地理国情、历史掌故、风俗人情、自然风光做了一些简单的考察了解、现记录下来与大家分享。\n美国，位于北美洲南部、东濒大西洋、西临太平洋、南接墨西哥、北靠加拿大，国土面积963万平方公里比中国略大一点，世界排名第三位。总人口约2.5亿多，多为欧洲移民后裔，美国建国历史比较短、从1776年7月4日至今才有200多年的历史，美国的星条旗是由十三条红白相间等宽的线条及左上角50颗蓝底白星组成，十三条线代表美国独立时十三个州的辉煌历史，50颗星代表现在的50个州。美国有高度发达的市场经济，2008年以来虽呈下降趋势、但其国内生产总值和对外贸易总额仍占世界首位。2011年其国内生产总值（GDP）初值为150877亿美元，按可比价格计算比上年增长1.7％，增幅比2010年回落1.3个百分点，净增5689亿美元。人均（GDP）48373美元，外贸进出口总额3.2万亿美元，欧盟仍是其最大的贸易伙伴，其次是毗邻的加拿大占19％、中国占12％、墨西哥占11％、日本占8％。\n美国的信息、生物技术产业发达，服务业在经济总量中占的比重较大，全国四分之三的劳动力从事服务业。美国是最大的农业出口国之一，主要农产品有大豆、玉米、小麦、糖、烟草，工业品有汽车、飞机、电子产品、钢铁、军火。美国的旅游业也很发达世界排名第三，美国人均收入为46000美元，人民比较富裕。\n美国的政治制度实行三权分立、《宪法》拥有至高无上的权力。国会是最高立法机构，由众、参两院组成、两院议员由各州选民直接选举产生，参议员每州两名共100名、任期6年、每两年改选三分之一，众议院按各州人口比例分配、选举产生共435名，任期两年、期满全部改选，两院议员均可连任、任期不限、众参两院议员均系专职，不得兼任政府职务。\n导游告诉我们、美国除了国会众参两院议员、总统的选举外，各州的州长、议员选举；各市的市长、议员的选举连连不断，民众每年都忙于选举之中，凡登记具有选民资格的选民都要去投票，除总统是间接选举外其它都是直接选举。\n司法独立、联邦最高法院由一名首席大法官和八名大法官组成、终身任职、联邦最高法院有权宣布联邦和各州的任何法律无效。\n美国总统实行的是间接选举、一届四年、可连选连任一届，美国总统看似权力很大、但执行起来权力又很小，在行政方面有权发布政令、处理国家事务和联邦政府的各种工作，可以任命组成联邦政府的高级官员。总统又是美国武装部队的总司令，可以调集军队和各州的国民警卫队为联邦政府服务。在立法方面有权否决国会通过的任何法案，除众参两院各有三分之二的多数票推翻他的否决，否则该法案就不能成为法律。在司法方面有权提名仼命联邦最高法院的司法官员。在外交方面有权任命驻外使节，接受外国使节递交的国书，与国外缔结条约。由于三权分立总统权力又会受到宪法和法律、国会、联邦最高法院、各州政府、公众权利等多方面的约束，还有可能受到弹劾。\n加拿大，位于北美洲的北部、同样东瀕大西洋、西临太平洋，北连北冰洋、南与美国接壤，国土面积约998万平方公里、仅次于俄罗斯居世界第二位，其中陆地面积约909.35万平方公里。是英联邦成员国、有独立的立宪修宪和外交权，全国分十个省三个地区，全国有人口3350万人，现有华人约145万。加拿大同属英、美法系国家，政治制度与美国基本相似。1970年10月13日与我国建交，双边关系发展顺利。加拿大是西方七大工业化国家之一，制造业、高科技产业、服务业发达，资源工业、初级制造业、农业是国民经济的支柱产业。加拿大以贸易立国、对外贸依赖度较大，经济上受美国影响较深，2008年的国内生产总值（GDP）16024.7亿加元（1美元约合1.01加元）人均48179.8加元、约于美国相等。中国是加拿大第二大贸易伙伴，加是中国第十三大贸易伙伴、2009年中加贸易额达到297亿美元。加拿大的旅游业也很发达、据世界旅游组织统计、旅游收入世界排名第九。\n据导游讲加拿大社会保险体系比较完善，失业、医疗、养老等保险基本全复盖，另外家庭津贴、残疾津贴、贫困救助等多项内容也都由联邦政府、省和市三级政府分类负担和管理。三分之二以上的家庭有自有房产，77％以上的家庭至少有一辆汽车，加拿大是一个典型的福利社会，民众的幸福指数比较高。也是各国移民比较向往的国家，这几年政府对移民有了严格管控。导游还介绍加拿大人喜欢开大马力、大排量的汽车、究其原因是汽油价格比较便宜、一公升约合一加元左右、按人民币汇率计算比国内油价便宜好多、如果用居民收入比例计算那就更便宜了。虽如此，我认为不值得提倡，只要是地球人就应当承担起节能减排的义务，还地球一个洁净无暇的空间。\n这次北美之行是省工商局组织的、由宋金圣副局长带队，嘉峪关市局许万勤局长、白银市局李玉进局长、省局办公室陈林主任和我一共五人，我们这个团的主要任务是，到美国和加拿大考察学习商标发展、监管和维权方面的知识。他们四位在商标发展、监管、维权方面都是专家、在我省商标工作中都有突出贡献。\n我于2006年8月与省局原副局长张汉文等五人、参加过国家工商总局在西藏拉萨召开的西部省（区）商标协作座谈会，会后我对商标工作在经济发展中的重要地位才有了更深层次的认识。因此，到省局工作后、专题对兰州市和全省的商标工作、做了一次比较深入细致的调研，2009年8月在深圳国家工商行政管理学院第四期地级干部培训班上，结业论文也是就商标发展、监管、维权方面做了一些献策建言，自认为参加这个考察团不会拉他们的后腿。\n4月5日和4月11日的上午、分别与多伦多伯纳比（Burnaby）市经贸局的主管和洛杉矶经济法专家Gary.patterson教授、进行了两国《商标法》及具相关法律制度和实际运用效果的探讨，从实践和理论方面相互进行了交流学习，取得了比较丰硕的成果，对做好我省今后的商标管理工作一定会有十分积极的借鉴指导意义，我个人从中也获益匪浅。\n这次去美国、加拿大考察学习借道韩国，4月4日从北京国际机场T2航站楼乘KE856航班13：20起飞约3小时后到首尔的仁川机场、经停三个半小时、再转乘KE071航班18：50起飞于次日当地时间12：30到达温哥华国际机场，（除去时差）空中实际飞行约10个小时，接机的导游是加籍华人李先生（河南人）随即安排参观斯坦尼公园、加拿大广场、盖斯镇和唐人街。\n“斯坦利公园”距市中心约10分钟车程、公园面积6070亩、公园是以红杉等针业树木为主的原始森林、自然生态保护得很好。公园内人工景物很少，“图腾木雕群像”是原住民卑斯省北方印第安人雕刻运来供游人参观的，由于时间关系公园又较大所以仅看了这一角，就怱怱撤离奔向第二景点。\n“狮门大桥”是目前世界上古老的知名悬索吊桥之一，若与我国现在海上和长江上的悬索大桥相比那真有小巫见大巫的感觉，但值得一看的是它于1939年就建成投入使用，按那时经济、科技水平来衡量真的很壮观、很了不起。\n“加拿大广场”是一座很现代化的温哥华地标建筑群，1983年始建1985年建成，1986年世博会加拿大馆就设于此，该建筑最具特色的设计是其顶端有五组平行的白帆、也在海边上，与澳大利亚悉尼歌剧院有异曲同工之妙，且有扬帆起航之寓意，周边还有“温哥华会议中心”、“太平洋大酒店”、“温哥华世贸中心”等建筑。\n“盖斯镇”是温哥华的老城区，1971年时卑斯省就将其列为文化保留区、一些古老建筑才得于保存，盖斯镇上一座古老的“蒸气钟”真值得一看、至今还在工作、每15钟喷出蒸气一次，地下是铺着圆石的街道、地上有众多的维多利亚式古老建筑，是体验加拿大人原汁原味生活的好去处。\n“中国城”，凡国外稍有名气的城市都有中国城或叫“唐人街”，也是中国游客必去观光的地方。温哥华中国城据说是北美第二大中国城，位于盖斯镇的南边，住在这里的中国人是19世纪中叶、美国加州淘金者北上加拿大后、落地生根繁衍的后代，现温哥华地区就有华人移民40万。世界真大、也真小，在温哥华用餐时、无意间还碰到了一位去了温哥华的移民是宋局长在兰州认识的一个熟人，温哥华的华人之多可见一斑。“千禧门”是中国城的特色标志、牌坊式结构，红色是城内的主色调、有喜庆祥和的气氛，生活在这里的中国老乡都比较滋润。\n半天的参观时间让人走到哪里都感到很急促，即使这样浮皮潦草的看一看，还是让人觉得温哥华灿烂的阳光、清新的空气、绿色的草地、金色的沙滩、加之4月初温和的天气真能让人陶醉。\n参观结束后回“Trave1odge.Hote1”酒店，次日上午公务活动、午餐后即乘AC148次航班于14点起飞去加拿大的东部城市也是加拿大的第一大城市多伦多。飞机空中飞行时间约5个小时、于当地时间下午21：30分左右（有近3个小时的时差）正点降落在皮尔逊国机机场。当地导游康健先生也是加籍华人、家在山东青岛，司机小于河南郑州人，接机安排晚餐后入住“Ho1iday.Inn”酒店休息。\n4月6日早餐后驱车去参观“尼亚加拉大瀑布”（附另一篇文章《观尼亚拉加大瀑布》不再赘述）后返回多伦多参观市政大厦、多伦多大学、CN电视台。\n“市政大厦”建于1965年，是由一栋25层高68.6米和一栋31层高88.4米的双体弧形大楼相拥中间一座形如蘑菇的多功能大厅及周边三层裙楼所组成，是多伦多的一座地标性建筑。依我看这座大楼除了是多伦多市的政治中心外、再也没有看到有其它很特殊的地方。\n“多伦多大学”始建于1827年、是北美大陆最古老、也是世界最重要的研究院校之一，它以规模大、学科多、设施全、师资厚闻名于世。现有注册学生55000名、其中研究生有8000名，有来自世界100多个国家和地区的学生3700名，此外还有非全日制学生12000名。学校有教员工4000余人，其中教授1080人、副教授878人、助理教授430人、讲师337人。校园内建筑特色古色古香、树木草坪枝繁叶茂、氛围宁静清谧宜人、在喧闹的市区中有这么一块闲逸之地供人读书思考真不容易。\n“CN电视塔”建成于1976年、塔高553.33米，刚建成时是世界第一高塔、现排列第三，共有147层，此塔造型优美、324米高处是一个玻璃露天景观台、塔顶上有360度旋转餐厅，每年有200万人登塔参观，不愧为有多伦多美丽风景线和重要地标之称。CN塔是铁路集团施工承建的，因此在塔下还有一个露天的蒸气机车陈列馆免费供人们参观游览。\n参观完所有景点后也就结束了在加拿大的三天活动。当地时间下午4时乘AA4633航班从多伦多的皮尔逊机场飞美国的纽约，空中飞行约2小时后抵达纽拉瓜迪国际机场，导游接机后随入住“Fairf1e1d.Inn”酒店休息。\n在美国除了4月11日上午的公务交流活动外、其余时间基本用于参观考察。在美期间的导游是华人，名张仲四上海人，去美近20年己入美国籍。\n“自由女神”是重要的观光景点，铜像是法国1876年赠送给美国独立100周年的纪念物，安放在纽约附近的自由岛上、1884年竣工、1886年10月28日正式揭幕，己被列入世界文化遗产名录。参观“自由女神”是乘游艇去的，拍了不少照片。\n“华尔街证券交易所”在国际金融界可谓无人不知无人不晓，它位于曼哈顿岛的最南端、与世界艺术表演中心的“百老汇”毗邻而立，距著名的“唐人街”也只有一箭之遥。华尔街这条仅长540米的狭窄街道两侧簇拥着上千家金融和外贸机构，全纽约有50万金融从业人员、华尔街就拥有10万人，“证券交易所”实行会员制、非会员不得入内，但在它的二楼有一条狭长的全封闭的公共通道、每天上午10时至下午4时免费开放供人参观，人们可以隔着密封的玻璃窗清晰地看到万头攒动、喧嚣紧张的交易场面。让我依稀又看到了1995年在日本参观的“东京证券交易所”。\n“华尔街证券交易所”以梦幻般的魔力一直对世界经济产生着巨大影响。它是梦想家的天堂、不知道有多少暴发户从这里跨入金融巨子的宝座，它又是企业家的地狱、也不知有多少知名企业家一夜之间从这里破产身亡。1929年10月24日、属于美国1280家最有名望的企业股票、急剧下降、瞬间失去了控制、到中午12点短短几小时就发生了两名银行家、一名经纪人破产自杀的惨案，最终全部证券贬值一半、几百万人也因此破产，如今提起这个“黑色的星期四”仍会令人毛骨悚然。\n人类创造了财富、制造了金钱、可人类又在一点点地失去自身的本质、成为金钱的奴隶，血的教训应值得记取。虽如此，华尔街巨大的诱惑和实力在国际金融业仍占有显赫地位、起着举轻重的作用，仍然是世界经济的晴雨表。\n“华尔街铜牛”是一位来自意大利西西里岛的艺术家、叫阿图罗迪.莫迪卡（Arturodi.Modica）设计的。他去美国多年其艺术水平都未得到社会认可，一日他突发奇想、华尔街是世界金融的心脏、如果他的作品放在此处就有可能一鸣惊人，于是他就想创作一头铜牛在1898年圣诞节前放在证券交易所门前，以祝福来年股市牛气冲天。经过两年运作终于在1898年12月15日夜将一头重6300公斤的铜牛作品、运到交易所门前的圣诞树下，第二天一早果然被记者、警察和围观人群围得水泄不通，市政府当局盛怒之下要他立即拉走，此时百老汇南端鲍林森林公园的负责人（Bor1inggreen）由此经过即想让莫迪卡把铜牛放到他们公园内，可莫迪卡坚持要将铜牛有条件的拍卖，他的愿望一是买主要将铜牛捐给市政府，二是铜牛不得移动地方，所以铜牛现在是纽约市的公共财产，不准任何人买卖，莫迪卡拥有肖像权。\n“时代广场”是位于第42大街、洛德街与第七路交叉的三角地带，是曼哈顿的心脏地块，虽说是“广场”实际上面积很小，是纽约最老的《时代杂志》社址所在地，素有“世界十字路口”之称。\n“百老汇（Broadway）”原意为“宽阔的街”，它是纽约南北走向的一条大道、南起巴特里公园、由南向北纵贯曼哈顿岛、全长25公里，由于沿路两旁分布着几百家影剧院、己成为音乐、歌舞、戏剧的代名词。\n“时代广场”和“百老汇”真没有可看的，团友们在第五大道闲逛了一阵、为亲人朋友随便购了一些礼物。\n“联合国大厦”位于曼哈顿东河沿岸1949年始建1951年6月建成，它由秘书处大楼、会议大厅、大会厅和哈鸟舍尔德图书馆四栋建筑物组成，广场前矗立的192根旗杆上飘扬着成员国五颜六色的国旗，联合国总部主要有秘书处、安理会、经济及社会理事会、托管理事会四大机构，现任秘书长是潘基文。\n联合国总部的会议厅及公园内有各成员国捐赠的礼物，我认为有几件看了后是很值得人们深思的，第一件是1959年由前苏联赠送的“铸剑为犁”象征着人类要求终结战争、把毁灭的武器变为创造的工具，化干戈为玉帛，造福人类。第二件是树立在广场公众入口处的一尊雕塑“打结的枪管”，这是卢森堡赠送的，弯曲的枪管表示了人们对非暴力的向往、呼吁国际裁军行动。第三件是日本于1954年赠送的“和平钟”它是用60个国家儿童收集的硬帀铸成并安放在一座由柏木制成的典型神社式结构物中，“自由钟”每年敲响两次己成传统，一次是“春分”日也就是春天的第一天，另一次是秋季每年9月21日，2001年联大表决己将这一天确定为“国际和平日”。各国赠送的礼品很多、寓意也都很深。我国在1974年赠给联合国的是一座“象牙雕”用八支象牙由98个工艺师雕刻了两年才完成，描述的是1970年自力更生建成的成昆铁路通车情景，工艺十分复杂、精湛。在曼哈顿还参观了“帝国大厦”、“世贸大厦再建工程”、“水门事件大楼”。\n在纽约市皇后区法拉盛一条小街上（纽约市第三大区，也是穷人比较集中的一个地方）居然碰到了在嘉峪关认识的王先生，在嘉时他经营一个烤肉店已经小有名气，后来就消失不知了去向，在这里偶然的遇见、可算是世界之大无其不有。王先生在这条街上仍经营他的老本行卖中式烤肉串，生意做得风生水起还挺兴旺的。王先生告诉我们他虽是摊主而不是餐车的主人，他是受雇于他的一个远房亲戚。我问他为什么自己不申请一个属于自已的餐车呢？他说在纽约街头售卖有三难。第一，要取得街头贩售许可证很难，根据美国宪法第一修正案规定，除了在街头售卖报纸、杂志、书籍、CD、等艺术品外，其他所有的街头售卖行为都需要许可证。1979年纽约市议会通过有关法律规定街头售卖小贩人数上限是2万，一般来说退伍老兵或其家属是许可证提供的主要对象，如果普通人申请只能等空余配额。负责颁证的卫生部门在有空余配额后，会以抽签的方式来分配，中签的概率跟中彩票差不多，申请到一张许可证等10年、20年都有可能。有了餐车许可证，经营者还需有上岗证，要取得上岗证首先要花53美金、参加2天关于食品卫生方面要求和规定的培训、才能参加上岗知识考试，合格后方可发上岗证。第二，执行管理规定难。在纽约能管理摊贩的部门很多，警察局、卫生局、消费者事务局、清洁局、环保局等都会来监督检查。比如说摊位放得是否合理有警察局管理，在纽约5000张餐车许可证中，能够在全市五大区非管制路段摆摊的只有3000张左右，像王先生的餐车只允许在皇后区设摊。另外纽约市对摊位摆放规定得很细，摊位必须离开路沿0.4米、摊位与横道线的延长线为3.1米、如果附近有商店、那么摊位离开店门的斜线距离不得少于6.8米，多一点少一点都不行，违规就要被罚。有严细规定的还好说，对于食品摊贩来说最怕的还是卫生局来巡查摊位的卫生状况，一有不慎就会接到罚单，卫生要求规定操作人员必须带手套、口罩、炉子的位置摆放得必须合理、食材的储存要有洁净的容器和合适的温度，王先生说有些规定很笼统，很难执行，今天刚罚了400美金，理由是垃圾箱太满没有及时清理。第三，摊贩业主维权难。在纽约看起来执法人员很文明、很公平，纽约摊贩指南明确规定，管理人员来执法时，小贩有权利要求对方出示证件，也有权利自行拍照存证。但是在检查和开罚单时不得与执法人员争辩，特别是和警察当场争辩会罪加一等。因为警察在开罚单时还会开出一张听证通知，这意味着给你日后争辩的机会。如果你认罚，可以直接交款，如果不认罚，就可以去听证会申请法庭裁决。王先生说大都数摊主都认罚，如果让法庭裁决、时间你就拖不起，不如多争取点时间多做一点生意多挣一点钱做个补偿。\n我在工商局工作几十年与市场管理有摆脱不开的情结，对纽约街头摊贩的管理，所见所闻真是涨了见识，这也是这次考察学习取得的额外收获。\n4月9日早餐后由纽约乘汽车去华盛顿相距237英里（约合381公里）途经费城顺道参观了自由宫和“独立钟”，独立钟现存放在费城的自由宫中、它见证了美国的独立、是美国的一级文物、1776年7月4日伴随着钟声的响起《独立宣言》首次在此公布于世，1783年4月16日钟声在此再次响起时、宣告美国独立战争取得伟大胜利、从此脱离英国的殖民统治，此后每逢美国国庆日的庆典仪式都要敲钟庆贺。\n汽车旅程近5个小时，在车上导游给我们介绍了华盛顿景点的一些情况和历史掌故，他说华盛顿有两个“1234”，第一个是按建筑物的形状所讲有一尖（华盛顿纪念碑）、二平（白宫总统官邸）、三方（林肯纪念堂）、四圆（国会大厦）。第二个是有关历史事件所讲有一条河（波多马克河）、两个宣言（独立宣言和盖茨堡宣言）、三场战争（二战、韩战、越战）、四位杰出总统（华盛顿、杰弗逊、林肯、罗斯福）所以参观到这些地方时我都比较关注。到华盛顿用晚餐后即入住“ComfortSuites”酒店。\n4月10日在华盛顿观光的主要景点有：“华盛顿纪念碑”是为纪念开国总统所建，用材全部是大理石、碑身呈方形、碑顶为尖形、碑高169米、底部面积39平方米。华盛顿特区规定在华盛顿不得再建高于此碑的建筑物。\n乔治.华盛顿在美国独立战争中担仼大陆军总司令，为美国的独立作出了杰出的贡献，独立战争后任第一任总统。1787年在他的主持下召开了制宪会议，制定了宪法。在美国被尊称为国父。\n“白宫”位于华盛顿宾夕法尼亚街、从外表看是一幢并不十分豪华的白色平顶建筑、是历任美国总统的官邸，有不少人误将园顶的国会大厦当作“白宫”、我也是这次才真正认识了“白宫”。现任总统奥巴马是第45位总统、也是有史以来的第一位黑人总统。\n“林肯纪念堂”是一栋方形建筑，是为纪念美国第16位总统亚伯拉罕.林肯所建，门廊的巨大园柱与方形建筑交相映辉、相得益彰、十分壮观。\n林肯是一位深受美国人民崇敬的总统，他的功绩是领导北方军队击败了南方的分裂势力，化解了分裂的危险、维护了国家的统一。另外是他在1863年11月19日发表的“盖茨堡宣言”，他说：“八十七年以前、我们的祖先在这块大陆上创造了一个新的国家，孕育了自由，并且献身给一种理论，就是所有人类生下来都是平等的。......我们在此坚决地表示不让他们白白地死去，要使这个国家在上帝的庇祐下得到自由的新生，要使那些民有、民治、民享的政府不至从地球上消失。”从此，废除了奴隶制度，使黑人得到了解放。\n波多马克河是美国中东部一条重要的河流，是南北战争的分界线、现在也是一个惹人喜爱的旅游景点。\n“杰弗逊纪念堂”实际上是一个很大的公园，园内春意盎然，树木、花草、流水还有一些园林建筑在多处将托马斯.杰弗逊各种姿势的雕像巧妙地放置到一起，让人看了很顺眼。\n杰弗逊是美国历史上的第三位总统，1776年6月11月以他为首的《独立宣言》五人起草委员会成立，杰弗逊任主编，他于6月28日仅用17天时间就编写成功、并于7月4日正式通过。此时他年仅33岁，才华横溢，把自由民主的理念、渊博的历史知识和精湛的文学功底汇集一起，将被美国人民认为不朽之作的《独立宣言》一气呵成。而且在1800年还以一个在野党领袖身份从执政党手中和平地取得政权的第一人。\n富兰克林.罗斯福，是美国的第32位总统，执政前正好遇到1929---1933年的世界经济危机，银行倒闭、企业破产、商业萧条、失业增加、农民贫困遍及美国。1932年他执政后立即实施“罗斯福新政”，主要措施是：成立应对经济危机的专业工作机构，提高农产品收购价格、恢复农业繁荣、向大中企业贷款扶持企业开工生产、刺激消费活跃商业、向失业人员发放救济、提供就业机会，实施新政后美国经济形势逐年好转，得到了工人、农民和一般社会下层人士的支持，是唯一获得连任四届的总统。\n“二战纪念广场”是布什总统任职期间开建的2004年4月29日落成，处在华盛顿纪念碑和林肯纪念堂之间。广场呈椭园形、中间是一个圆形水池、水池后56根花岗岩石柱呈“八”字形分立两旁，每柱代表一个州或一个盟军参战国，中间稍后处是纪念馆，两侧各建一个拱形塔楼、塔楼的门上分别刻有“太平洋”和“大西洋”代表两大战区，塔楼内的拱形上各有四只雄鹰衔起象征胜利的花环，在弯曲的自由墙上刻有4000颗金星代表着二战中的阵亡者。我参观过的莫斯科“二战纪念广场”是1995年建成的，无论是规模和设计理念让人感觉应该比美国的大、比美国的好。\n“韩战和韩战纪念园”，韩战也称朝鲜战争打了三年一个月零两天，于1953年7月27日签署《停战协定》美国耗资200亿美元，联合国军伤亡109万人、其中美军39万人、南韩66万人、其它联合国军4万人。中朝军队伤亡63万人。韩战纪念园很小、有三部份组成，第一部份是有用不锈钢铸造的与真人相仿的19个美国军人成战术队形散落在野外的战场上，他们头戴钢盔、持枪跃进、面部表现出“无奈、恐惧、警惕”的表情。第二部份是一座黑色的花岗岩光面墙、上面是根据韩战当时新闻照片临摹蚀刻的美军各兵种无名士兵脸部的表情，也是一脸无奈的真实历史记录。第三部分是一组置于地面的方砖、上面所刻记录美军和联合国军分别阵亡、受伤、被俘、失踪的人数和碑文：“我们的国家以它的儿女为荣，他们响应召唤，去保卫一个他们从未见过的国家，去保卫他们素不相识的人民。”这样的碑文似乎大有国际主义之精神、真是为维护世界和平充当国际警察可敬，否则就是悲哀。\n“越战和越战纪念墙”，越南战争是二战后美国投入参战人数最多、影响最大的战争、也是以失败而告终的战争。，20年的战争中美国向越南投下了800万吨炸弹、远远超过二战期间各战场投弹的总量，造成越南军民死伤160多万人。美国的损失也很惨重，耗资4000多亿美元，死亡了58000多人，受伤了30多万人。“越战纪念墙”与“二战纪念广场”和“韩战纪念园”相距都很近，都处在“华盛顿纪念碑”和“林肯纪念堂”之间。是用黑色花岗岩砌成500英尺（约合150多米）长的“V”字形碑体、并以阵亡时间为绪镌刻着58000多名将士的姓名。纪念墙的设计者林璎是美籍华裔建筑师，她设计的这座建筑物平铺开来看好像是平坦的地平线被战争狠狠的砍了一刀，深陷的“V”中轴与两墙边线有3米深，立起来看又像是沿中轴线从地下向地面在不断地浮升，两端分别指向象征着国家形象的“华盛顿纪念碑”和“林肯纪念堂”，这两座建筑物在大地的映衬下显得高耸而端庄。从纪念碑体两端向中轴线看则又有从地面不断向地下绵延的意境、让人感觉到的是悲痛和哀伤。这一高一低、一阴一阳的对比，会让人产生很多遐想。\n黑色墙体光洁得像两面镜子，意在让人永远记住这段黑色的历史。当生命成为战争代价时它真正的意义是什么？只有痛苦。渴望和平、渴望光明才是人类最现实的理想。这也许就是这段墙要告诉我们的真缔。\n华盛顿有几十个各式各样的博物馆、都可免费供人参观、在此我们还参观了航空航天博特馆。完毕后于当地时间17：50分从华盛顿乘AA075航班飞洛杉矶，空中飞行5小时，当地时间20：45分到达（有约2小时的时差）当晚入住“BestWesten”酒店休息。\n4月11日上午公务活动，下午游览了环球影城看了一场比较刺激的水上战争秀、拍攝电影的外景地和一些电影特技镜头，参观了中国大戏院、在好莱坞明星大道上走了一走。总体上没有体会到有什么太美妙可以留下深刻印象的地方。\n4月12日结束访美的全部日程，当地时间12：45分从洛杉矶国际机场乘KE018航班飞韩国，空中飞行时间约14个小时、于13月日下午17：50分抵达首尔仁川国际机场，返回所乘飞机是空客380、确实享受了一把空中巨无霸的滋味。晚餐后入住“汉江酒店”。\n4月14月日在韩国的首尔活动一天，上午参观了景福宫、民俗博物馆、青瓦台、看了哨兵的换岗仪式，中午品尝了真正的韩国餐，下午继续参观仁寺洞步行街（自由市场）、南山韩屋村、东大门、免税店、晚上在入住的饭店即可看到清溪江夜景。由于本文写的是美洲行，韩国的情况就不一一介绍了。\n4月15日上午11：05分由仁川机场乘KE855航班飞行2：15分到北京后入住科技会堂小结休整一天。17日上午团友们返兰州、我飞回无锡。这次出行时间正好在春天，所到之处都是阳光灿烂、鸟语花香、气候宜人、沿途自然景色美不胜收，一路又受到团友的照顾，从内心很感谢他们。"},{"id":188,"title":"赴江苏考察杂记","category":"散文","date":"2010年5月底","body":"经省局党组批准5月12日至16日由陈其寿副局长带队率8人考察团赴江苏省学习履行工商职能服务地方经济发展的先进经验。我“五、一”期间已先期回江苏探亲，12日下午乘动车组从无锡赴南京江苏省政府招待所西康宾馆集中报到，晚上江苏省局佘义和局长在西康宾馆设欢迎晚宴，金宝林副巡视员作陪。宴中，陈其寿付局长代张绪胜局长向佘局长表示问候并汇报了此次考察的意图并请求给予支持，江苏省局当即就做了周密的安排。\n13日上午由南京玄武区工商局王志坚局长（其寿局长的好朋友）接待参观了其辖区内的爱国主义教育基地、中山陵和民国时期的总统府、历史上也曾是明清时期的江南巡抚府和太平天国时期的天王府，两个景点。并设午宴款待。下午江苏省局对应组织了个体处李晓东处长、孙原生付处长、注册局蒋常彦处长、食品安全监管处陈德美处长、公平交易执法局朱付局长、信息中心单荣主任、局办公室邵德冲付主任等处室领导在机关会议室进行了交流，介绍了他们服务地方经法发展的政策及措施。\n江苏省现有人口7724万人，国土面积10.26万平方公里，占全国总面积的1.06％，2009年GDP达3.4万亿元，个体私营经济的贡献率为39.4％，全省人均达到6475美元，大口径财政收入8404亿元，地方一般性收入3228亿元。\n截止今年3月底全省有各类市场主体377万户，列总数第一的广东省后，其中各类企业112万户，企业总数中含私企92万户，私企数量位列全国第一，农民专业合作社25800户位列全国第三，江苏省工商系统有干部职工22000余人，每年财政下拨的预算经费是26亿元，因南京市是计划单列市其干部职工人数及经费均不含在省局系统内。\n据介绍2009年江苏省工商行政管理系统行政执法办案罚没款4.2亿元，比过去的6亿多元下降了30％，案件与罚没款的逐年下降，一是说明市场法人主体的法律意识在得到不断增强、能够进行守法经营，二是说明工商行政管理部门行政指导、提前警示等为市场主体的服务性措施得到了全面贯彻落实，我们了解到因此江苏省工商局的行政执法形象不仅在地方党委、政府而且在管理对象中也越来越好。行政性罚没款虽然与工商廉政形象没有直接的必然联系，但在经济不发达地区肯定会受到一定的影响。所以，对我省近两年行政执法办案数量和罚没款直线上升的趋势、要认真加以科学的分析、只有制定出适度的监管政策和服务措施，才能更有利于经济的发展和工商形象的改善。\n今年，江苏省局为支持地方经济发展制定了26条政策他们对这些政策研究得很深很透、原则上只要不与法律法规相抵触就鼓励大家大胆去尝试，有些政策在全国工商系统都处于领先地位，既有前瞻性、又有可操作性，他们那种紧密联系实际、大胆解放思想、勇于探索创新、“敢为天下先”的精神很值得我们学习。晚上张振飞付局长在省局培训基地设招待晚宴。\n14日上午早餐后由江苏省局个体处孙原生副处长陪同赴南通市考察，行程3个半小时。因南通市工商局蒋亚亭局长正在办移交手续准备赴无锡市履任新职，（原无锡市孙连才局长己提任省局副局长）文峰宾馆共进午饭后他委派李菊生副局长和个体科的朱建东科长随我们一起到海门县三星镇的家纺城市场进行学习考察。三星镇（叠石桥）是清代末科状元、我国近代实业家张謇先生的家乡。\n据市场负责人介绍他们早与世博会组委会签订协议，今年上海世博会上所用的家纺产品全部由他们提供。其家纺产品在国际国内声誉很高，国内市场份额己占40％以上、市场年成交额300多亿元，同时还有大量产品出口，三星镇家纺产品年销售收入己超过500多亿元。一个产业做大做强后带动了物流业、旅馆业、餐饮业、旅游业等三产业的迅速兴起，提供了大量的就业岗位，为当地农民的脱贫致富、走上富裕道路作出了重大贡献。可见，规模效益是促进经济发展的有效途径。目前，家纺城正在进行三期扩建，到2012年全部竣工后，将是全国最大的家纺产品及辅料市场，交易额可以再翻一番，其服务也会达到一流的国际化标准。\n在海门县工商局举办的交流会上赵国兵局长首先介绍了海门县和县工商局的情况：海门县国土面积只有1100平方公里、人口103万，2009年的大口径财政55亿元，地方一般性收入27亿多元，海门县在江苏省仅是一个中等发达的县。海门县工商局下辖10个分局（所）、管辖各类市场主体7万余户，有工商干部职工212人，人均监管约350户，监管任务虽然很重，但管理规笵有序，他们真正将管理寓于服务之中，为当地的经济社会发展做出了巨大的贡献。所以，当地党委、政府对他们很信任，监管对象对他们也很欢迎。\n我省现有在职干部职工10100余人，有市场主体约60万户其中：个体工商户49万户、各类企业11万户，按此计算、每人平均只监管60户左右，是海门县的六分之一强，与江苏省全省的干部职工和监管对象人均170余户来比较、我省人均监管数也只有其三分之一强，且我省市场主体的密度及数量主要还在兰州市辖区内，大多数市州还达不到平均水平，监管对象的情况也不相同、江苏省市场主体中的企业数占市场主体的30％左右，我省市场主体中的企业数只占市场主体数的18％左右。众所周知企业越多监管难度相对也越大。且我省的工商所均为科级建制、科级干部配备的比例也很高，而江苏省的工商所均为股级建制，我们有什么理由监管不好呢？就我省目前基层干部职工状况来看，还没有真正摆脱开以费代管、以罚代管的阴影，干部职工的业务素质相对来说还比较差，对诸多现代业态还缺乏管理知识，管理方法、不知道如何去监管，对多元化的市场主体也不知道服务什么，如何去服务，监管、服务水平之差、效率之低，确实令人担忧，奋起直追、势在必行。\n年初，张绪胜局长在全系统工作会议上把今年确定为“素质效能提升年”很有前瞻性、很有必要。只有在全系统形成共识，上下团结一心、切实贯彻执行，使干部职工的整体素质和履职效能在现有基础上得到大幅度的提升，总局周伯华局长提出的“四个只有”才有可能在我省不落空。否则，工商行政管理服务发展的措施如何落实到位？良好的工商管理形象又何谈之有呢？\n在海门看望了我省在此挂职锻炼的10名基层干部。南通市工商局的干部培训基地设在海门县。陈达江代表挂职的同志就工作、学习、生活方面的情况向考察团和江苏省、南通市局的领导做了简要汇报。其寿局长勉励了挂职的同志并提出了新要求，同时代表省局党组和挂职干部向江苏省、南通市和海门县局，在工作上给予无私的传、帮、带，在生活上给予无微不致的关怀，表示衷心的感谢。\n蒋亚亭局长特地从南通市赶到海门参加海门县局所设的欢迎晚宴，夜宿南通市文峰宾馆316室。晚上原坦克十二师副师长现转业在南通市科协工作的路云山夫妇二人到宾馆看望了我，聊了一段别后情况。\n15日是星期六，上午参观南通狼山景区，景区有沿长江边的剑山、军山、狼山、马鞍山、黄泥山五座小山的自然景观和人工所建的滨江公园组成，最高的军山海拔118米，狼山最高点116米，坐索道上山从山下至山上只用4分钟即到，是国内旅游景点最短的索道。山虽不高但面临长江十分险峻，晴天站在山颠或江岸上都可隔江望到苏州的常熟市，面对滚滚东去的浩淼长江，《三国演义》的开篇词即湧上心头：“滚滚长江东逝水，浪花淘尽英雄。是非成败转头空，青山依旧在，几度夕阳红。白发渔樵江渚上，惯看秋月春风。一壶浊酒喜相逢，古今多少事，都付笑谈中。”心胸顿时也开阔无比。狼山景区已经开发建设得十分漂亮，是南通市民节假日休闲的好去处，南通市民真是好福气。\n狼山又名紫琅山，不仅有很多美丽的传说，而且也是苏中平原上的一处佛教圣地，我自幼就知道狼山菩萨很灵验，有求必应，且有先照远后照近的说法，这其中也说明南通人的大度，先人后己。改革开放以前交通并不是很方便，距我家乡曲霞镇约有一百五十华里的路程，辗转乘车跟徒步而行用的时间差不多。因此，很多人去拜佛都选择徒步前往，五至七天才能一个往返，心诚则灵。\n我是一个无神论者，但在狼山也许下了求菩萨保佑全家幸福安康的心愿。我想为人一生只要时刻牢记“离头三尺有神灵”，对神有敬畏感，同时记住儒家孔老夫子“勿以善小而不为、勿以恶小而为之”的古训，多做好事、善事，不做坏事、恶事，作为一名党员领导干部更要时刻遵守党纪国法，许下的心愿哪会有不灵验的呢？\n午饭安排在景区内以江鲜为特色，饭后离开南通赴扬州市局考察学习。两个多小时行程后到达扬州，何月林局长（镇江人，在这次江苏省局的干部调整中也提拔为副巡视员）早就安排纪检组长朱彤和个体处王处长等待，陪同我们参观了全国四大私家园林之一的《个园》、另外三个是北京颐和园、河北承德山庄、苏州拙政园。《个园》是清朝扬州盐商黄志云的私宅，东关街是一条百年老街，经过整修面貌一新，还有江泽民同志的故居东圈门16号等景点，平山堂所在的大明寺此前曾参观过。晚宴设席文津酒店，让团友品尝了真正的淮扬菜系，是夜下榻扬州市局培训基地文津酒店。江苏省局为了满足干部培训经常化的需要，省局和各市局都有一个培训基地，不仅轮训本级干部而且还要交叉承担全省系统内干部的培训任务。在我们到达海门的前两天，我省挂职干部还到扬州参加了三天培训。\n我省的干部培训工作近几年虽制定了规划、强化了措施，但从提高全省干部素质的需要和至今没有一个固定的场所的实际情况既让我们看到了原因和差距的所在，也给今后工商事业的发展留下了一个问号。\n16日是星期天，上午参观了瘦西湖。在南通时路云山同志嘱咐我有时间写一篇游记，人在旅途未暇顾及。参观扬州后进一步了解到扬州市申遗成功、已荣膺世界历史文化名城的殊荣。扬州开埠甚早，在历史上一直是商旅发达的重要码头，自古就有隋炀帝开凿大运河看琼花的故事，据说琼花只生长在扬州，其他地方不能成活，此说令人难以置信又不得不信，我自幼至今在离扬州只有近百里的家乡还真正没有看到过琼花。鉴真和尚东渡日本、杜十娘怒沉百宝箱、民族英雄史可法抗清、乾隆皇帝六下江南游扬州、郑板桥等扬州八怪及现代文坛中散文大家朱自清、汪曾祺先生、中国工程院何祚庥院士，更有前任党的总书记江泽民同志、现任总书记胡锦涛同志等等一批古今名人轶事。（泰州市原属扬州所辖，因扬州市原有800余万人口于1996年分设了两个地级市。）\n历史上还遗留下不少的自然景观、淳朴的民风民俗、丰富的饮食文化等诸多道不尽的典故、说不完的故事，虽然有感想发，但写游记绝对是不能勉强的了。因为，朱自清老先生于1934年11月20日就在《人间世》杂志上发表了散文《说扬州》，把扬州的历史渊源、人文遗迹、自然景观、民风民俗、饮食文化表述得淋漓尽致，况且在自己以前的一篇短文《故乡情结》中也略有叙述，不得再去重复，就此写杂记一篇、赋《七绝》一组，撰楹联一付，作为此行的纪念吧。\n《美在扬州》（外四首）\n三月烟花美扬州，千年古城故事多。人杰地灵今胜昔，华夏赤子续春秋。\n《游瘦西湖》\n桃红柳绿满堤岸，塔桥亭榭隐其间。游客摩肩踏青来，舟随船娘歌谣远。\n《逛东关街》\n青砖青瓦青石街，院内花香扑面来。“长安客栈”长安客，恍若置身百年外。\n《谒平山堂》\n香客趋鹜平山堂，皆源追崇大和尚。百折东渡播友谊，盛举憾世誉扶桑。\n《参观个园》\n个园玲珑夺天工，堂舍巧布山水中。观石赏竹胜景处，春夏秋冬一院逢。\n《楹联一付》\n瘦、瘦、瘦，竹瘦、石瘦、湖瘦，瘦出奇秀。\n美、美、美，花美、月美、人美，美在扬州。\n横披为：“奇秀扬州”\n扬州又称“月城”。\n下午返南京禄口机场4点乘中国东方航空公司的MU2895航班经停西安回兰州，回到市区已有9点多钟，灯火阑珊，流光溢彩，别有一番景象。回顾几天的考察学习，收获颇丰。\n考察期间团友们常对我说：老天真不公平，江苏经济发达、自然风光好、人们的生活富裕滋润，真不愧为上有天堂下有苏杭。甘肃经济落后、生态环境差、人们的生活仅为生存。你是江苏人是不是很骄傲很自豪？为家乡而骄傲自豪，理所当然。其实，我到甘肃已生活了三十多年，一方水土养一方人，在我心目中甘肃就是我的第二故乡。事实上甘肃也不是处处都落后，也有很多优点。确实经济发达地区有很多长处，也有很多先进经验可学。但我们也不要自卑，要认真审视自己的长处和不足，既不可妄自尊大，更不可妄自菲薄。他山之石可以攻玉，一定要把这次考察学习的成果举一反三、运用到实际工作中去，这样才能不断进步，超越前者。\n我祝愿我的故乡越来越美好，我更祝愿甘肃在党中央、国务院的关怀下发展越来越迅速。［（今年5月2日国务院办公厅印发了《关于进一步支持甘肃经济社会发展的若干意见》）（这个《意见》应该说是去年6月中旬国务院组织34个部委到甘肃调研的成果。当时，我全程陪同参加了“市场流通和对内对外开放组”在全省各地的调研）］。同时，我一定会在有效工作时间内为建设第二故乡尽我绵薄之力。\n赴江苏考察学习期间正好是农历的三月底四月初，到处山青水秀、阳光明媚，一片江南春色、气候宜人，所到各地又受到了热情接待和周密安排、心旷神怡、身心俱释，痛快之极。在此对江苏省及各市县局的领导和参加接待的同志深表衷心感谢！同时在考察期间受到各位团友的关心照顾在此也一并致谢。"},{"id":189,"title":"端阳节","category":"词","date":"乙巳年五月初五","body":"（渔家傲）\n柳丝轻拂送燕。\n榴花带雨展新容。\n节序端阳古遗风。\n四海同,\n摘苇叶缚香粽。\n插艾饮酒驱邪虫。\n更闻江上鼓角重。\n龙舟到处敬英雄。\n情与共，\n屈子离骚千秋颂。\n\n三省轩主程康年\n乙巳年五月初五。"},{"id":190,"title":"江南美食笔记","category":"文","date":"乙巳年五月十五","body":"中央电视台有一档栏目“三餐四季”我很喜欢，它介绍了全国各地各具地方特色的美味佳肴，中国人对吃”是有很深研究的将吃列为“民以食为天悠悠万事唯此为大，且食不厌精，脍不厌细。\n自然也就拱出了“饮食文化”。\n根据各地的独特风味和烹饪技艺总结出“十大菜系”：粤菜清淡鲜美，淮扬菜清新爽口注重本味、川菜麻辣酸辣怪味重、湘菜香辣味道浓厚、鲁菜色泽艳丽香味浓郁、徽菜重油重色醇厚入味、浙菜口感新鲜色泽清丽、闽菜清淡爽口原汁原味、东北菜以炖菜烧烤为主，西北菜以牛羊肉面食领冠，还有满汉全席都各有妙不可言的精到之处，一方水土养一方人，这十大菜系所取的食材万变不离其宗大都是属于当地当时的绝品。\n前几天在无锡餐旅文化沙龙听了都老师“百年花韵百年味的讲座，情深之处让人垂涎欲滴不能忘怀。\n今天我也将几宗江南美食介绍给大家，表示对所有参与传承饮食文化并作出贡献的“食中人”的一片敬意。\n一、“乌米饭”，它是江南一带立夏时节吃的一种传统美食其制作方法是摘乌米饭叶将其洗净放入破壁机中打碎，过滤掉叶渣将洗净的糯米泡入汁液中浸泡的间大约需二十四小时，当糯米的颜色完全呈现墨绿色时捞出上锅蒸三十分钟即可，取出稍凉加糖食用味更美，制作乌米饭重要的是掌握好浸泡时间和蒸煮的火候、否则会影响美食之味道。\n乌米饭叶是杜鹃花科越橘属的一种披针椭圆形、顶端短尖基部楔形边缘有细锯齿、表面平坦光滑的常绿灌木又名南烛，是一种良好的园林观果绿化树种，它喜温暖气候及酸性土地耐旱、耐寒、耐贫。\n入药有抗氧化、延缓衰老、抗疲劳、降血糖、抗癌防癌、改善视网膜功能等作用，多食有利于身体健康。\n二、“青团”，也是江南清明到立夏期间最有名的一种应时传统美食，其制作方法是寻新鲜艾草清洗干净焯水后捣烂成糊状、按一定比例与糯米粉加适量的粘米粉、澄粉调和捏成剂加馅再捏成团，上锅蒸十至十五分钟即可，出锅时在其表面刷一层香油可防止青团冷却后变硬、也有为青团增色的作用。\n馅料可以根据不同人的口味分为甜口如豆沙芝麻或咸口如咸蛋黄、肉松、肉圆等也可以荤素分为各种各样的口味。\n总之只要你想吃什么口味的就调成什么样的馅料即可随心所欲。\n艾叶有温经止血散寒止痛调经安胎以及祛湿止痒之功能艾叶归肝脾肾经、具有运化补益肝、脾、肾、脏腑的功能,有利于体内多余的水湿邪气排泄、从而缓解湿疹、泄泻久等病症，适当食用对身体有一定的益处。\n三、“梅花糕”，无锡梅园南临太湖北倚龙山是重要的旅游胜地，从一九一二年荣崇敬、荣德生兄弟两人购地筑园植梅饰山至今己有一百多年历史，目前园内占地面积八百余亩，植有梅花的五个区域有一百二十余亩梅花近万株，品种近百种，每年一至三月是赏梅的最好季节，无锡梅园搜集保存了全世界登录的梅花品种有近四百个，是很有名的育种基地。\n无锡的“梅花糕”并不是现今的文旅新创、并非与梅园应时而生、而是源于明朝到清朝时已成为一种具有独特风味的传统美食，据传“梅花糕”的名字还是清乾隆皇帝下江南时所赐如今却与“梅园”的旅游产品相得益彰。\n梅花糕比起乌米饭和青团的制作要简单很多，只要将糯米粉、细砂糖、各种食用色素加水调和到一定的粘稠度倒入预先准备好的模具压实成型后取出放入蒸锅中火蒸十五绅即可，出锅凉凉、粘糯甜爽适口很好吃，现在也有不用色素而直接用鲜花制作的。\n四、“萝卜丝饼”，也是走进江南平民百姓家的一道美食，制作很简单，将萝去皮擦丝后用适量的盐腌渍十分钟左右取出萝卜丝、在所留的汤汁中加上鸡蛋适量的香料面粉调成稠糊状再将萝下丝倒入和匀，将油烧至一百五十至一百七十度左右，即可将盛在模具内的糊状物下油锅煎炸，成型后倒出模具炸至两面金黄出锅，热食用酥脆味美盈口，制糊时可根据个人口味添加各种食材今年五月有朋友从重庆来，我们在宜兴参观东坡书院后到农家乐吃到乌米饭和萝卜丝饼对其美味赞不绝口，至今仍回味无穷。\n所列的江南美食只不过是多若灿星中的微乎其微，实不足为奇，因篇幅所限无锡的本帮菜系未列举一二，很遗憾“无锡三白”、“江南水八仙”都是江南人的口福，当令菜肴当令吃才是最鲜美最健康的。\n\n三省轩主程康年\n乙巳年五月十五"},{"id":191,"title":"太湖十八湾","category":"诗","date":"乙巳蛇年芒种日","body":"十里青山半入城，\n一湖碧水映家门。\n江南美景何处觅，\n十八湾前君自闻。\n云蒸霞蔚旭日升\n小溪塘浜筑香。\n烟雨田园皆仙境\n宗师欲画愧无能。\n\n三省轩主程康年\n乙巳蛇年芒种日"},{"id":192,"title":"蠡湖晚霞","category":"诗","date":"乙巳年六月初六","body":"鑫湖晚霞\n浩瀚宇宙万物容，\n奇幻美景夕阳中。\n云霞余辉烧天边\n光波亲吻半湖风\n自然之手力无穷\n神工描画天地动\n人间哪能皆如此\n心系晚情诗意浓。\n\n三省轩主程康年\n乙巳年六月初六"},{"id":193,"title":"人生的意义在哪里","category":"文","date":"乙巳年六月廿五","body":"与好友商榷人生的意义特殊的社会环境会造就特殊的生活方式，特殊的生活方式又会带给人们特殊的心灵感受，好友王生福局长以《剑铭》、《茶则》、《砚铭》三首短诗来描述自己十年特殊人生的深切体会，总结出了一些人生的意义，特殊生活方式洗尽了燥气、戾气、和怨气，悟得了十年磨一剑的真谛，收获了平心静气、宠辱不惊、心如止水、与世无争的精神升华，使自己的人生、活得更加通透，引申开来看就是明白了人生的意义，读来令人钦佩。\n其实，什么是人生的意义是一个很大、很深奥的哲学问题，或者说人生的意义本来就是一个伪命题，人生的意义从某种角度看就是个人价值和个人对社会价值的体现。\n是一个人对物质财富、道德规范及宗教信仰多维度相互平衡的追求和实践。\n不同的人生过程就会有不同的人生的意义。\n其实我对此未做过任何研究，仅是一知半解。\n一眼人生七十几年就过去了，回首看总觉得是活在云里雾里、是在“混日子”，人生的意义至今也没有搞清楚，仅从正人古训和几十年来讨生活的经验总结出了一些个人的浅见薄识，仅仅是个人认知，并不一定对，因此也就不需要大家认同，管窥之见、仁者见仁、智者见智。\n人生，是指一个人从出生到死亡的一个过程，出生是无可选择的，从出生时起人就划分为三六九等，如出生在上流社会、一辈子无需为生活而奔波，如出生在底层社会、就注定一辈子要为生存而奔忙，因为在这个过程中人首先要解决的是生存问题，其次是如何生活得更好的问题。\n“钱、权、势”是划分社会层级的标准，你拥有或分享到的财富和权力会奠定你的原生社会地位，你的活动能力会加持你的社会影响力也就是“势”如果一个人想要从底层社会跃升到上流社会就要不断的努力学习和奋斗，不断的挑战自我追求新目标，不断的总结人生的经验教训，不断的改变适应上流社会的生活方式。\n我认为这几个“不断”就是一部分底层人士向上流社会爬升的的人生意义。\n另一种底层人士就是躺平的底层人士，无时无刻不切实际的在追求自由平等、公平正义，这种追求也就是这一类人的人生意义。\n其实任何社会形态下绝对的平等也是绝对不存在的。\n物以类聚，人以群分。\n上流社会的人物也是有正负面的，负面人物是高度精致的利己主义者，可以不择手段、不顾别人死活的去取社会财富据为己有，如当今的美国百分之一的富人掌握了百分之九十九的财富。\n这些人会把取社会越多引以为荣，会把积聚的财富越来越多作为人生的意义。\n这也是当今腐败现象不能根除的真正原因。\n正面人物是忧国忧民，修身、齐家、治国、平天下的社会精英。\n他们会懂得社会底层人士生活的艰辛，他们会为改变这种不平等的现象努力抗争与担当。\n北宋理学家张载说：为生民立命为天地立心、为往圣继绝学、为万世开太平。\n宋·范仲淹的《岳阳楼记》中写道，“先天下之忧而忧，后天下之乐而乐”，这种担当哪怕发生微乎其微的变化也是积极的人生意义。\n《人物志·序》中所说“圣贤之所美、莫美乎于聪明，聪明之所贵、莫贵乎知人”。\n聪明之人又有高明、精明之分，曾国藩在《挺经·明强篇》说：人见其近楼则所见远矣，登山则所见更远矣。\n一般人只看到眼前的事物，只有可以看到更加深远的事物，深谋远虑才叫高明。\n一般人只看到粗大显眼的东西，只有可以看到别人不注意的细节，有真知卓见才叫精明。\n高明取决于天资，精明全靠后天的学习和钻研。\n人是有信仰的，入党半个多世纪对党的纲领、对马列主义的唯物史观、对毛泽东思想为人民服务的宗旨，应该是坚信不疑的，但是现代社会的负面影响让我对人生的意义陷入了困惑不解。\n人生只是从出生到死亡的一个过程，赤条条的来最后赤条条的去。\n什么也带不走，那么人生到底有没有意义呢？\n结论是信其有则有、不信则无。\n其实一辈子做一个聪明人为自己为家人活明白，才是至关重要的。\n\n三省轩主程康年\n乙巳年六月廿五"},{"id":194,"title":"献给仙侣庭院主人","category":"文","date":"乙巳蛇年八一节","body":"云侣仙踪戎马侄您时未闲解甲归田着青衫。\n深谱国学追贤仁醉别酒泉崇州还。\n筑山为园筑山万难胜治瞳植树种菜必亲躬。\n饲鸡训犬堪桃源修身养性园美梦暮鼓晨钟湖清倒影白塔峰，心聆暮鼓听晨钟。\n仙风道骨悟禅意，逍遥自在数邹公。\n觉悟人生呼朋唤友临仙山，静思雅听藏法眼。\n功名利禄随云去，是非曲直一笑谈。\n\n三省轩主程康年\n乙巳蛇年八一节\n附记：手我与邹公相识\n相交多年，是我一生\n中难得的挚友之一我\n们曾都是军人，更有\n共同语言，邹公做人\n做事诚直率，利落\n大方、决断明快、和\n气善良，是我学习的\n榜样，今年五月应邹\n公所邀去了一趟邹公\n自己在重庆票州市道\n明镇仙侣山开发的仙\n侣庭院度假胜地小憩\n之日，实现了多年未\n谋面的愿望，随写了\n一篇《再游成都·重\n庆记》只把在仙侣庭\n院的感悟一带而过有\n失敬重，前日好友生\n福写一篇仙侣庭院赋\n赞邹公开山立寨之盛\n举，我有同感，随其\n意补写短诗一首：献\n给仙侣庭院主人，表\n达谦意，望望诸君不各\n赐教，为感。同庆八\n一节，祺颂大安！"},{"id":195,"title":"立秋感悟","category":"诗","date":"乙巳蛇年立秋日","body":"时序立秋欲远行，\n流火褥暑势渐停。\n万物悄露梧桐色，\n捧献硕果酬辛勤。\n奋斗自慰愈心灵，\n功名利禄皆浮云。\n人生旅途犹短暂，\n天道有情亦公平。\n秋风秋雨秋日晴，\n历经世事见洞明。\n四时轮回催人老，\n自足常乐延高龄。\n\n三省轩主程康年\n乙巳蛇年立秋日"},{"id":196,"title":"立秋感悟","category":"文","date":"乙巳蛇年立秋日","body":"时序立秋欲远行，流火褥暑势渐停。\n万物悄露梧桐色，捧献硕果酬辛勤。\n奋斗自慰愈心灵，功名利禄皆浮云。\n人生旅途犹短暂，天道有情亦公平。\n秋风秋雨秋日晴历经世事见洞明。\n四时轮回催人老，自足常乐延高龄。\n\n三省轩主程康年\n乙巳蛇年立秋日\n附注全诗的释义：\n立秋是二十四节气\n的第十三节，它告\n诉农耕时代的人们\n秋天来临了，俗话\n说立秋三日分早晚\n闷热难耐的酷暑即\n将告别，夏日的炎\n威之势会不断减弱、\n一场秋雨一场凉夏\n天也就会渐行渐远\n没有梧桐树引不来\n金凤凰，秋天的主\n打色彩就是金黄色，\n所有的植物在一岁\n一枯荣的定律中都\n会悄悄的染上金黄\n色，秋天是丰收的\n季节，经过人们半\n年的辛勤劳作，大\n地一定不会辜负人\n们的希望，春种一\n粒栗秋收万颗籽大\n地母亲一定会用累\n累硕果来酬谢人们\n挥去的汗水。春华\n秋实人生也是好此\n秋天犹如人们的高\n光时刻，家庭、事\n业发展得无论怎么\n样都无所谓，只要\n我们奋斗过，努力\n过，问心无愧就行，\n其实功名利禄真像\n一片浮云，人生本\n是赤条条的来，两\n手空空的走，短暂\n的人生只是历史长\n河中的一名忽过\n客，一切都不必过\n分计较，从容度过\n一生才是最重要的\n天道是有情的，也\n是最公平的，生老\n病死谁也逃不过这\n个劫。秋天有风雨\n也有晴朗之日，人\n生有苦难，也有幸\n福之时，人生只有\n经风雨才能见世面，\n世事洞明皆学问人\n情练达即文章，如\n果修炼到难得糊涂\n才是思想境界的最\n高点，人生的苦难\n皆来源于两个字牵\n挂，舍去牵挂就会\n一身轻松，就会延\n年益寿。此所悟只\n是一生磨难的小结\n仁者见仁智者见智。"},{"id":197,"title":"秋有所思","category":"诗","date":"乙巳年七月初七","body":"金风送爽夜骤寒，\n秋霖湿玉苑。\n晨雾朦胧隐干山，\n晚霞默然抹万滩。\n野径草枯花渐残，\n疏林叶凋雁声蝉。\n静思苦海红尘事。\n知足常乐心自宽。\n\n三省轩主程康年\n乙巳年七月初七\n附注：大西北的秋天\n总是比江南来得早些\n八月二十五日晚一场\n雨连下一天两夜，气\n温也降至十三至二十\n五度，二十八日要回\n无锡为两个外孙的暑\n假结束，新学期的开\n学做好准备，随便查\n看了一下无锡的天气\n预报，二十八日气温\n仍在三十七度和二十\n七度中衙，高高温未\n散，暑仍在。但无\n缘再享受嘉峪关的清\n凉世界。特别是回到\n嘉峪关受到很多老朋\n友的热情款待更是恋\n恋不舍不愿离开，但\n又不得不向第二故乡\n和诸多亲朋好友告别，\n朋友的盛情我会永记\n心怀，在这里代表我\n的家人再一次谢谢你\n们，并诚挚的欢迎你\n们来无锡作客。嘉峪\n关的一场秋雨让我有\n所见有所思，阳随成出\n诗一首给大家分享并\n作纪念。"},{"id":198,"title":"记抗战胜利八十周年","category":"诗","date":"乙巳年九月三日","body":"山河破碎遭铁蹄，\n同仇敌汽人心齐。\n英勇抗战十四年，\n铁血历史永牢记。\n九三阅兵堪称奇，\n正义和平不分离。\n警惕倭寇毁我意，\n中华复兴泰山移。\n\n三省轩主程康年\n抗战胜利记念"},{"id":199,"title":"中元追思","category":"诗","date":"乙巳蛇年中元节","body":"荒凉野家枯草埋，\n紫怀幽魂五十载。\n追思先人传家训\n慰籍心灵筑祭台。\n人生犹如一尘埃，\n飘忽不定九天外。\n他年我赴黄泉去，\n化作青烟不复来。\n\n三省轩主程康年\n乙巳蛇年中元节"},{"id":200,"title":"庆国庆","category":"诗","date":"二零二五国庆节","body":"（沁园春）\n国之华诞，中秋相伴，\n双节安宁。\n看/大海潮，长城蛇蜓\n黄河奔腾，一路前行。\n大地铺金，山川抹银\n风光猗扼入眼帘。\n朗朗日，瞧/神州焕彩，\n盛世梦赢。\n巨龙传承文明，\n唤睡狮崛起民族林。\n看/东方大国，园梦复兴\n图强奋进，立威扬名。\n铭记历史，宫常保警醒。\n继往开来永不停。\n从今后，享亨通国运，\n万世太平。\n\n三省轩主程康年\n二零二五国庆节"},{"id":201,"title":"九月九太湖赏秋","category":"诗","date":"乙巳重阳节","body":"重阳登高赏金秋，\n千里江山眼底收。\n长天湖水共一色，\n赤橙黄绿漫山坡。\n堤边芦花点白头，\n路旁桂香沁心窝。\n架下葡萄紫成串，\n树上石榴红熟透。\n人生慈念盼长寿，\n淡欲自在亦足够。\n邀友放浪饮三日，\n醒后归来九月九。\n\n三省轩主程康年\n写于乙巳重阳节"},{"id":202,"title":"惠山菊展","category":"诗","date":"乙巳年菊月十二","body":"惠山菊展风韵雅\n紫嫣红满园花。\n远闻二泉琴弦音，\n近看妆姿羞云霞。\n邀友静赏品茗茶\n墨客笔舞字和画。\n梅兰竹菊四君子,\n一揽清风入我家。\n\n三省轩主程康年\n乙巳年菊月十二"},{"id":203,"title":"神舟圆梦","category":"诗","date":"二五年十月卅一","body":"热烈祝贺神舟二十一\n号载人飞船发射成功\n神舟圆梦\n露凝霜降催枫红，\n极目仰望远空中。\n群星眼迎贵客，\n宇宙添增小弟兄。\n神舟扬名数天宫，\n天地对话悉畅通。\n日巡盖亚十六周，\n深载中国复兴梦。\n\n三省轩主程康年\n二五年十月卅一"},{"id":204,"title":"神舟圆梦","category":"文","date":"乙巳菊月廿五日","body":"祝贺神舟二十一号载人飞船发射和神舟二十号乘组返回双成功。\n神舟圆梦一极目仰望深太空骄子问天乘东风。\n宇宙张臂敬宽怀，群星添增小弟兄。\n乘组交替驻天宫飞船往返责任重。\n探索之路虽艰险。\n厚载中国复兴梦神舟圆梦二人类探空从未休，神舟堪比阿波罗。\n嫦娥舒袖迎贵客，吴刚捧酒奏笙歌。\n远征天眼识星河坐地日巡十六凋。\n科技添翼震四海，飞天足惊五洲。\n\n三省轩主程康年\n乙巳菊月廿五日\n注解：中国航天工程是人类的\n一大奇迹。公元二零二五年十\n月三十一日二十三时四十四分\n神舟二十一乘组在酒泉东风发\n射场顺利升空。原定于十一月\n五日返回的神舟二十乘组偶遇\n小故障，乡经航天工程师全面评\n估确保安全后、虽延迟了9天\n也于11月14日在东风着陆场\n确保安全顺利着陆凯旋而归。\n发射返回双成功可庆可贺。\n一九九九年十一月二十日\n六时三十分零七秒神舟一号在\n酒泉卫星发射场成功发射，为\n我国的航天事业开了新的\n篇章，当天我有幸受东风场区\n铁管处张毓枫处长的盛邀、偕\n夫人到现场观看了发射实况，\n很是感动。二零零三年十月十\n五日九时零分神舟五号首次载\n人（杨利伟）在东风发射场发\n射成功、又揭开了我国载人航\n天事业新的一页，这次发射时\n间正好与甘肃省工商局在酒泉\n市召开的一次业务会议时间上\n有交结，东风场区工商局在全\n国也是一个特殊的体制，工商\n行政管理人员全是现役军人编\n制、行政上隶属部队社会保障\n部直接领导，业务接受省工商\n局指导。受东风场区领导的特\n邀我又有幸亲临现场观看了发\n射实况。由于保密需要有发射\n任务时、东风场区对外是不开\n放的、因此受邀人数很少，能\n进入场区审核也十分严格。\n神舟一号和神舟五号的发\n射是首次航天和首次载人航天\n都有着特殊的使命，其意义十\n分重大，且这两次发射央视都\n未直播、均由央视全程录屏以\n后再播出的，能到现场观看实\n况觉得很幸福很荣耀。我到东\n风场区去了若干次、大都是陪\n着客人前去参观学习的，星箭\n组装车间、航天员出发的问天\n阁、发射场的发射架和航天展\n览馆等是必看的内容，展览馆\n是甘肃省红色教育基地它深藏\n着更多的航天精神。由此我也\n结识了李树斌、范庄、引张毓枫\n王中校、梁生全、唐铁军、李\n盛春、社会保障部的杨政委等\n很多场区的领导并和他们成了\n好朋友现在他们大都转业或升\n任要职离开了，这些好朋友我\n也一直怀念着他们i。\n看到神舟二十一号的成功\n发射和神舟二十号乘组的安全\n返回，让我激动不已。从神舟\n一号到神舟二十一号仅短短的\n二十六年时间、我国的航天事\n业就取得如此巨大的成就、世\n人谁不惊叹？同时还勾起了我\n脑海里这些深深的无穷尽的回\n忆，手我还能无动于衷吗？随作\n出诗两首《神舟圆梦》来歌颂\n英勇无畏的航天员们和繁荣昌\n盛的伟大祖国"},{"id":205,"title":"闻江南大雪","category":"诗","date":"乙巳大雪日","body":"大雪无痕时序迁\n随风可见舞落英。\n金菊吐蕊添新雅，\n銀桂留香隐娇妍。\n竹翠杏黄欺霜凝，\n柳绿枫红压寒烟。\n莫叹严冬多萧瑟，\n诗笔情暖艳阳天。\n\n三省轩主程康年\n写于乙巳大雪日\n注释:时间已到二\n十四节气的大雪\n江南的气候还犹\n如十月小阳春今\n天大雪无痕，无\n锡晴天，气温在\n零上七度到十九\n度，温暖如春身\n心都觉得很惬意，\n随作诗一首以\n记之。"},{"id":206,"title":"再游惠山寄畅园","category":"诗","date":"乙巳大雪后两日","body":"自从退休定居无锡后，惠\n山古镇每年都必去打卡几次\n那里听不完的故事、看不完的\n风景总让人魂牵梦绕，恋恋不\n舍，而且去一次就有一次不同\n的认知和收获。这几年经过修\n缮扩容后古镇的面貌发生了巨\n大的变化、越发显得端庄大气\n实用得体了。\n去年的十一月廿五日随无\n锡市老年大学金石声老师“无\n锡文化游学”到惠山古镇寄畅\n园上外课，金老师以他渊博的\n知识和独特的见解、讲述了惠\n山古镇及寄畅园的前世今生和\n很多人至今也未知晓的历史上\n的人文掌故，让我拓宽了视野\n丰富了头脑获益匪浅。随后还\n写了一篇短文《寄畅园一课》\n与大家分享。\n惠山古镇景区有三大特色\n区别于全国所有园林。第一\n古镇有密集的祠堂群据统计大\n约有一百一十八座，一镇据有\n如此多的祠堂应为全国之首。\n第二，“寄畅园”得名出自王羲\n之“取欢仁智乐。寄畅山月阴”\n的诗句“寄畅园”又名“秦园”是\n北宋著名词人秦观的后裔明朝\n名臣秦金始建，不管时代如何\n变迁，历经近五百年始终都是\n由秦氏家族的后人一代一代改\n扩完善传承有序从未易主，直\n到一九五二年由秦氏二十二世\n孙秦存仁献给国家成为人民公\n园，这在全国十大私人园林中\n独树一帜不可不称为奇迹。第\n三，清朝的康、乾二帝每人都\n是六巡江南七次驻于此、并\n留下了很多赞誉的诗词、对这\n有江南第一山天下第二泉的园\n林真是情有独钟、乾隆帝对此\n园更是厚爱有加，他命人按一\n比一的比例将此园复制到北京\n颐和园内取名“谐趣园”这更使\n寄畅园名声大振盛誉远播\n昨天是今年农历二十四节\n气大雪的后一天，天气晴好阳\n光明媚、虽己入冬但气温仍在\n八至十七度之间温暖如小阳春\n很适宜外出畅游，确好也是金\n老师本学期的最后一节外课\n这一节课主要是让大家领略寄\n畅园历代建园人的智慧、实地\n体验园内各景点相互映衬借景\n点、精布置的巧思妙作，园内\n步步有景，处处有情。\n寄畅园位于惠山古镇横街\n的西端，园内面积虽不足二十\n亩但因紧贴在锡山东北麓的余\n脉上与锡山顶上的龙光塔自然\n可以无缝搭配，又与干年古刹\n惠山寺相邻，寺中的那株古银\n杏树胜造一景，此树龄已有六\n百一十岁，高二十一米、直径\n约两米、要四人才能围抱起来\n这几天来此打卡的毫不夸张的\n说是万头瓒动人流如织，稍有\n微风吹起树叶犹如金蝴蝶一样\n翻飞飘落下来树下像是铺了一\n张黄金打造的大地毯。黄金，\n俯拾皆是，还会让人想起叶落\n归根的深刻含义。树旁有一块\n听松石无锡人称偃人石，据传\n阿炳的另一首二胡曲《听松》\n即诞生于此。\n寄畅园同时将自然界的真山\n与园内叠起的假山相融，将园\n内的一塘水池与锡惠公园里的\n映山湖相连，真假相映远近相\n接这种以小博大、借景生景少\n有的构思实在天工之作。让人\n虽置身于园外又有身临其中的\n感觉并不觉得公园的小，反而\n感到园区的宽广硕大、园内以\n假山水池为中心，楼台亭阁、\n山泉水榭、石桥迥廊，应有尽\n有，园内古木参天竹影婆娑，\n所植树木花草皆与四季应时\n所以“春有百花秋有月，夏有\n凉风冬有雪”，四季风景皆有\n不同才是它的真实写照。这些\n造园巧思让园林美得不可言喻\n这其中也不知蕴含着造林者的\n多少心血。\n寄畅园小巧灵珑的美景有\n别于名山大川的峻峭雄伟，有\n别于大草原的的辽阔妩，也\n有别于大漠风光的壮实通透\n它更像江南美女一样温柔细腻\n婉约纤巧、雅致灵动，到这里\n来游园不管你年龄大小都会感\n觉到岁月的安好，在园内不管\n你行在何处都仿佛置身于山水\n画中，脚下的每块石都像是泛\n动的琴键会弹奏出最美妙的乐\n章，连拍照打卡做的每一个姿\n势都蕴藏着浓浓的诗意。金老\n师带领大家边走边拍照边介绍\n让大家用心去欣赏寄畅园的美\n简直是美不胜收，这是本次游\n学我的又一点收获，课中学友\n们也拍了很多视频和照片我想\n他（她）们一定会情融寄畅。\n好天气、好风景、好心情\n好想让人放歌也引发好多遐思\n让我用镜头录下的美景和我拍\n到的一帧“福从惠山来”的照片\n赠送给老年大学的每一位学友\n祝福你们在尊老爱老的社会氛\n围中享有幸福的晚年。同时我\n也真诚的欢迎我的老领导亲戚\n朋友来探访无锡惠山寄畅园，\n我和寄畅园一定会将人间真情\n纳福于您。“福从惠山来”，殷\n切期望你们来，来，来。\n\n三省轩主程康年\n乙巳大雪后两日"},{"id":207,"title":"孤寂","category":"词","date":"乙巳冬月冬至日","body":"（长相思）\n月朦胧。人朦胧。\n窗外霜凝寒气重。\n孤影独持盅。\n情也浓。意也浓。\n岁月流逝皆成空。\n人生一场梦。\n\n三省轩主程康年\n乙巳冬月冬至日\n注：长相思，词\n牌名，双调三十\n六字。上下段各\n四句，正体三平\n韵，一叠韵。另\n有变体数种。"},{"id":208,"title":"元旦两感悟","category":"文","date":"二零二六年元旦","body":"我最亲爱的老领导，老朋友及家人们二零二五年已悄然过去，至堑新的二零二六年扑面而来，在这里我首先祝大家元旦快乐，合家安康。\n同时将填写的一首词《元旦两感悟》分享给大家解压，真诚的祝福你们在新的一年里，天无忧无虑无灾妄，有情有意有希望，川顺风顺水顺财旺，原愿有所得实现梦想。\n元旦两感悟（南楼令）梅开迎元旦。\n回首思维艰。\n忙生活，压力如山。\n任重道远谋生计。\n莫迟缓，铁肩担。\n弹指一挥间、白发复苍颜阅世事，嵯叹无限。\n功名利禄随风去。\n菩提树，心相安。\n\n三省轩主程康年\n二零二六年元旦\n附注:1、南楼令词牌\n名，又名唐多令，正\n体双调六十字，上下\n片各三十字，四平韵，\n另有变体六十一字六\n十二字。\n2、“菩提”是禅宗六\n世祖惠能自性清净的\n四句偃语：“菩提本无\n树，明镜亦非台，本\n来无一物，何处惹尘\n埃”此四句的核心思\n想是要打破人们对物\n质世界的执念，引导\n人们回归对物质本质\n的正确认知。在这里\n借用其本意，不能将\n菩提这种象征高质能\n的智慧、过分去追求\n其具体化物质化。\n3、《两感悟》的是时\n间犹如高铁线上的列车\n一年很快就奔驰而过，\n年青人在这经济形势下\n行、就业不充分的状况\n下，受生活重担的挤压\n一定觉得很艰难，但生\n活仍需继续不得不在新\n的一年里早作谋划负重\n前行。\n已退休享受晚年的老年\n人而讲，纟经历了世事很\n多变化虽未完全看破、\n看透这个世界，但总是\n看多了这个烟火人间，\n感悟一定不少，同时也\n积累了一定的金钱物质，\n有了最基本的养老条件\n无须再抱有一些不切实\n际的奢望，清心寡欲轻\n松的欢度晚年，比什么\n都好。这就是我一个最\n普通最普通人的感悟，\n对新一年的愿望。"},{"id":209,"title":"元旦又感","category":"文","date":"二零二六年元旦","body":"琼花飞舞迎新年，锡城遍地起瑞烟。\n万家灯火团圆聚，提报人间临春天。\n太平盛世罗充盈民生大计谋在先老骥奋蹄志不渝心无旁福寿延。\n\n三省轩主程康年\n二零二六年元旦\n附记：二零二五年向\n二零二六年的跨年\n之夜、是一个让人\n兴奋不已的不眠之\n夜，虽然气温降了\n今年的最低点，但\n无锡三阳广场依然\n人头赞动，以热情\n甚浓的年轻人居多\n他们将会在零点钟\n声敲响的同时將数\n以万充满新年愿望\n的气球放飞，无锡\n人以其特有的豪爽\n与全新的姿态放飞\n梦想放飞希望，迎\n接新一年的到来。\n今年在获得“世界\n音乐之都”盛誉的\n同时又一处新地标\n拔地而起刚竣工的\n音乐厅首演了新年\n音乐会，座无虚席，\n证明了无锡人的高\n雅之风。凌晨一场\n瑞雪轻柔飘舞酒落\n在这片诗情画意的\n大地之上洗了二\n零二五年所有的铅\n华，将一个鲜亮的\n无锡奉献给了居住\n在此的人们，奉献\n给了祖国，奉献给\n了世界。瑞雪兆丰\n年，新年的首场雪\n一定会给无锡带来\n好景，乡给生长在这\n里的人们带来好运。\n在拙词《元旦两感\n悟》外又心生新感\n悟，仅以此诗并几\n张照片和一段视频\n共存记录之并与我\n最亲近的人们分享。"},{"id":210,"title":"大寒遇雪随感","category":"诗","date":"乙巳蛇年大寒日","body":"岁暮大寒雪旋飘，\n江南风光换颜貌\n天地混沌城廓隐\n山川田园披素袍。\n人生张驰凭运道\n草木枯荣复一遭。\n历经风霜逍遥客。\n余生苦度伴寂。\n\n三省轩主程康年\n乙巳蛇年大寒日"},{"id":211,"title":"腊八共情怀","category":"词","date":"乙巳年腊月初八","body":"（.念奴娇）\n时近岁暮，腊八逢五九。\n家家熬粥，八宝纷呈凝瑞气。\n一锅翻腾相逐，满室溢香。\n小儿垂诞，个个增食欲。\n天地酬勤，不忘备耕种谷。\n霜压琼枝惊扰，雪打梅梢。\n凌欺篱旁竹，春风荡起寒意肃\n祈年丰足。\n万里山河，阳光普照。\n大地谱新曲，莺歌燕舞。\n四海同春纳吉福。\n\n三省轩主程康年\n乙巳年腊月初八\n《念奴娇》词牌\n名，双调上下两\n片各十句，四厌\n韵，上下两片共\n一百字，上片四\n十九字，下片五\n十一字。另有多\n种变体。"},{"id":212,"title":"新年贺辞","category":"词","date":"丙午年正月初一","body":"尊敬的王局长:新年好！\n值此丙午新年来临之际\n我用《念奴娇》词牌填\n一首首《新年贺辞》并携\n家人在故乡给您全家拜\n年了，《新年贺辞》即\n我所愿，祝福伟大的祖\n国繁荣昌盛，祝福您全\n家在新的一年里幸福美\n满，吉祥如意，万事顺\n遂，有所愿皆有所得。\n（念奴娇）\n金蛇乍去，马踏祥云来。\n钻天礼炮，\n迎千家万户团圆。\n送温暖雾光照\n春联铺红，大地萌绿，\n山河换新貌。\n国泰民安\n沧桑乃是正道。\n惠风吹醒柳梢，干树梅开\n神州春来早\n天地人神贺新年。\n恭祝亲朋好。·\n合家安康，万事顺意，\n孝行得善报。\n祥符瑞兆，\n福禄寿喜财运到。\n\n三省轩主程康年\n丙午年正月初一\n注：《念奴娇》词牌名\n又名名《百字令》。《\n江月》会等，双调，上\n下片各十句，四厌韵\n共一百字，上片四十\n九字，下片五十一字。\n有多种变体。"},{"id":213,"title":"喜庆元宵","category":"词","date":"丙午马年上元节","body":"（行香子）\n皓月当空。佳酿醇浓。\n庆元宵，天地人融。\n华灯齐放，焰火映穹。\n看/花干树。灯干盏。\n谜干重。\n人间蟾宫。团圆偕同。\n闹社火，百戏舞龙。\n流光岁月。一路追梦\n愿/心上人。天上月。\n喜上逢。\n\n三省轩主程康年\n丙午马年上元节"},{"id":214,"title":"无锡梅园纪行","category":"文","date":"丙午正月廿二日","body":"无.锡梅园纪行赏梅、写梅、画梅是古今文人墨客的永恒主题，如今赏梅已进入寻常百姓家，尤其在无锡冬春之交的季节、梅园已成为大家休闲打卡的必到之地三月九日，天气晴好春风己赶走了严寒，最高气温摄氏十三度昭告人间最美三月天就要来临了。\n随金老师《无锡文化》外课走进了无锡梅园收获满满、不仅观赏了品种繁多的梅花，从低处向高处看犹如一片粉色的云霞，从高处向低处看就是一汪波动的花海。\n这次外课还了解了梅园建园前世今生的不少故事以及梅园在旅游文化方面的历史地位与作用。\n早在国民政府期间、国民政府规划建立三个大都会，南京为政治大都会、上海为经济大都会、无锡为文化旅游大都会，无锡的梅园在推进文化旅游大都会建设中是发挥了很大作用的。\n无锡梅园是荣德生老先生游览苏州留园后许下“为天地布芳馨”在无锡建一花园之宏愿的杰作，与兄长荣宗敬二人共同出资于一九一一年起购得太湖边上、东山和浒山南坡一百二十亩的小桃园始起，购地筑园，依山植梅三千余株、前后历经约十年才基本建成。\n梅园虽说是私家花园但荣老先生一生以为民造福为己任，园林造好后直接对外开放任何人都可以免费参观，荣老先生一生创办学校十一所其中的江南大学是无锡现在唯一的“211”大学，还累计造桥九十二座，修路无数连接了无锡多个旅游景点，为无锡成为全国文化旅游重点城市作出了重大贡献。\n无锡梅园位于西郊、背靠龙山九峰距市中心约七公里、面临万顷太湖距岸边约一点五公里，园内以梅饰山、倚山植梅，梅以山而秀、山凭梅而幽。\n一九五五年荣毅仁（曾任中华人民共和国副主席，二零零五年十月二十六日在北京病逝享年八十几岁）遵父所嘱将梅园赠献给国家，从上世纪六十年代起、地方政府对园林的修复扩建、完善不断加大投入现己拥有八百亩山林、所植梅树逾万株、品种四百多个，世界梅花登录园品种二百八十多个，并有很难一见的盆栽艺术梅桩二千多盆。\n园内有赏梅景区、博览园景区、花溪景区三大功能区，除赏梅外一年四季皆有花可看、有景可赏，己成为国家AAAA级旅游景区和全国重点公园和文物保护单位。\n人们赏梅大概率是以下几个目的，一是像毛主席咏梅词中所讲“俏也不争春，只把春来报”赏梅是盼望春天早一点到来。\n二是梅花有“岁寒三友”“花中四君子”之称，它有不畏艰难、清雅高洁的气质值得人们崇敬学习和陶冶情操。\n三是识梅、休闲欣赏，梅花的品种和变种很多，大品种有三十多种小类可划分为三百多种从枝态看可分为直枝类、垂枝类、龙游类、杏樱李类。\n从花型色彩看也可分为若干类。\n四是人们可以从长期猫冬中走出来亲近大自然，赏梅能提供更多的情绪价值、更有利于身心健康无锡梅园从建园起就陆续建了不少景点如：天心台、洗心泉、清芬轩、招鹤亭、读书处、乐农别墅、念劲塔、诵圈堂、梅园石刻...等多个景点再配以古树、老藤、新桂、奇石更显它的高雅与古朴，赏花与赏景相得益彰。\n“天心台”蕴含有“梅花点点皆天心”之意，台前立的三峰太湖石酷似福禄寿三字故称”三星石”这是对见者的祝福。\n“洗心泉”则有物洗则洁、心洗则清”可以洗涤人们的杂念、清化人们的心灵。\n“念劲塔”是梅园的最高点共三层十八米是荣氏两兄弟为纪念母亲石太老夫人的养育之恩所建，初拟名“念慈塔”后采纳名士钱振锂的建议改为“念勉塔”此意出自诗经《蓼》篇中“哀哀父母生我劳、哀哀父母生我劳痒”之句。\n“诵圈堂”是梅园的正厅坐北朝南又称“楠木厅”，也是出自诗经里的诗句，此诗有八个小节，记录的是农夫一年来生产生活方方面面的真实场景，很有人间烟火气。\n经常诵读会不忘底层百娃的哀忧喜乐。\n梅园里的每个景点都有自己的故事，可以慢慢去品尝。\n周边的苏州、杭州也有很多赏梅的地方。\n我曾有幸光临过。\n苏州光福的香雪海植梅两千多株与梅园相比只能是小兄弟了，但苏州是无园不梅，每个公园植梅数量虽然不多但每株梅树与园中的山、水、亭廊、门、窗、石、径等景緻相搭配、都会让人有谐然成趣的感觉、体会到建园人的匠心。\n在苏州赏梅尤如江南女人般的婉约淡雅、小巧玲珑。\n杭州植物园里植梅五干多株规模己经不小、但也只是无锡梅园的一半。\n临近杭州西湖的孤山梅树虽然只有三百多株但以古梅居多，今年春晚《贺花神》就以梅花比喻在此隐居的宋代著名诗人林通，他出身于杭州有名的儒学世家，自幼刻苦好学、通晓经史百家、书法绘画皆有成就更擅长于写诗词，长大后性孤清高、恬淡好古自甘贫困、四十岁后隐居在杭州西湖孤山植梅养鹤，一生不仕终身不娶，自为“梅妻鹤子”是晋陶渊明后第一隐士。\n卒后宋仁宗赐谥和靖先生。\n无论在何处赏梅都会领略到各有特长各领风骚、都会留下深刻的记忆，但我总觉得还是无锡梅园最好。\n古今名人对写“梅”情有独钟，唐太宗李世民、宋徽宗赵信，清雍正胤祺，伟人毛泽东孟浩然、王安石、杨万里、唐伯虎.等诸多名士都留下了情意相融绘炙人口并让人耳目一新的诗词。\n我平生深爱写“梅”的诗词一是宋·陆游的卜算子《咏梅》“驿外断桥边，寂寞开无主，己是黄昏独自愁，更著风和雨，无意苦争春，一任群芳妒，零落成泥碾作尘，只有香如故”。\n这首词更贴近他所处的时代和个人的背景，更显他的孤高雅洁不入凡俗的信念。\n他一生笔耕不、留下了很多诗文“山重水覆疑无路，柳暗花明又一村”至今仍被传诵林通《山园小梅》“疏影横斜水清浅，暗香浮动月黄昏”。\n这两句简直是干古绝唱他通过描写梅花的神清骨秀、幽独飘逸，淡然自在来隐喻自己的情怀志趣，寄托自己超凡脱俗的品格，读后令人心旷神怡。\n如今人们己将“疏影”“暗香”作为梅花的代名词。\n我尤其钟爱的是宋代诗人卢梅坡的《雪梅》诗中的两句梅须逊雪三分白、雪却输梅一段香”它以哲学思辨的语言告诉人们、世界上人无完人、物无全美。\n尺有所短、寸有所长，做任何事看任何人都要一分为二的看，这样在人生的路上才不会迷范。\n写到此我也用（卜算子）词牌随意填《赞梅》词一首：“花败草衰凋，欺雪凌霜傲。\n严寒料峭抖精神，独秀花枝俏，为冬默添彩，只催春早到。\n人间三月春光好，淡然香陨消”。\n送给各位学友分享。\n我收藏近三十年的一幅《梅花清香图》是西安画家邓云女士为我专作，是我挚爱奉为至宝今天也拿出来一并与大家分享。\n\n三省轩主程康年\n丙午正月廿二日"},{"id":215,"title":"咏梅","category":"诗","date":"丙午年二月初二","body":"盘枝蔓劲舒张，\n浅露孕苞抗严霜。\n素影婆娑报春早，\n英姿独秀骨。\n借来东风一夜情，\n满园雲霞堪流芳。\n赏梅捧雪烹阳羡，\n唇高准各争香。\n\n三省轩主程康年\n丙午年二月初二\n写于无锡四为斋\n注：《咏梅》诗释义\n数九寒天百花凋\n在这冰天雪地严酷\n的日子里、梅花却不\n惧严寒，它那弯弯曲\n曲像盘龙游走的身躯\n上悄然的萌动着、伸\n展出了新的枝蔓，浅\n浅的露出刚刚孕育出\n来的新芽花苞，以清\n瞿朴素的身影在寒风\n中轻轻的摇摆着向人\n们预告春天即将来临\n的好消息，同时以不\n屈不挠的勇气和勃勃\n生机与严寒抗争，渐\n渐绽放出淡黄色的花，\n并暗送出恬淡的香味\n彰显自己独有的\n铁骨。借来一夜东风\n唤醒了所有梅树、将\n梅园点缀成缤纷的世\n界，盛况空前，这花\n的海洋可以用诗文画\n作、相机等不同形式\n记录下来当作经典流\n传下去。供人们慢慢\n的品赏。赏梅时用手\n將压在花枝上的积雪\n捧下来烹茶，此时香\n味在空气中弥漫开来\n是茶香还是花香？口\n鼻各不相让。这种被\n烈火烤炙出来和经苦\n寒历炼出来的“香”才\n是“真香”，无须去判\n定谁更香。对这淡然\n生活意趣的追求和对\n梅花品格的崇敬才是\n诗人藏匿心底难以窥\n到的全部心境。\n阳羡”是出自无锡\n宜兴的贡茶，有“天子\n未尝阳羡茶，百草不\n敢先开花”之传说。\n唇和高准是嘴\n巴与鼻子的雅称。"},{"id":216,"title":"雨中赏樱","category":"诗","date":"丙午清明前两日","body":"潇潇细雨洒泪痕，\n飕飕冷风断花魂。\n落英粘贴佳人脸，\n柔似美女送亲吻。\n\n花好月圆别较真，\n风雨无情碾作尘。\n霎时树下添新塚，\n世间多有护花人。\n\n三省轩主程康年\n丙午清明前两日\n写于无锡四为斋\n\n附：清明时节雨纷纷，路上行人欲盺魂，此时正是踏青祭祖的最佳时刻，加之从四月一日起、中小学生放春假和清明假一起可连休六天，世界三大赏樱盛地鼋头渚樱花谷的游客从全国各地纷至沓来，根据过往经验、花盛期园内必然是游客如织摩肩接踵，三月三十一日无锡阴有小雨，忖度游客会少些、这天气去赏樱意在可以避开更多的人群、是日游人还是佷多。四月一日天气晴好阳光明媚，苏州有客来访又陪同再去赏樱。两天中由于气候气温的截然不同，樱花在阳光下和风雨中的姿态气质也就大不相同，人们的心情也随之会发生很大的变化。春风拂过阳光下的樱花次第绽放如霞似雪漫染枝头、荡漾着温柔的光晕，游客们有的驻足凝望沉醉于花影婆娑，有的轻歌曼舞与缤纷落英谐然成趣，有的将这江南春日绝色的景緻定格到手机相机之中，留给人们共享美景共赴美好的祝愿，这满园繁花、这人间烟火为无锡春日画卷和浓浓诗意铺展得淋漓尽致，令人心生愉悦留连望返。那在风雨中飘摇受到侵蚀的樱花又是另一种景色，虽也有柔姿百态但总有一种落寞感敲击缠绕于人心、会让人产生更多的怜悯之情，雨中赏樱的机会是很难得的从另一种角度随手写下这段略有伤感之情的短诗以记之。"},{"id":217,"title":"游学杜鹃园随笔","category":"文","date":"丙午年三月初六","body":"农历三月初四是二十四节气中的谷雨，雨生百谷，是时在南方种瓜点豆遍插早秧，在北方也是春小麦播种的最佳季节。\n这天天气阴、最高气温二十三度，空气清新很利于外出郊游，前一天三月初三是上已节、古代的上已节既是追祭先人的节日、也是女子节，女子可以结伴户外踏青郊游，临水洗灌嬉戏、被楔不祥、祈福未来，一千六百七十年前王羲之的《兰亭集序》记载的就是这类春游活动，传承至今可见中国文化的博大精深。\n这个季节我们随老年大学无锡文化游学班的金石声老师去杜鹃园踏青、观赏无锡市花由于是阴天园内云蒸霞蔚、古木参天、游人如织，盛开的杜鹃花娜多姿、色彩斑、真是饱了眼福。\n精于摄影的张开贵同学还为大家留下很多精彩瞬间。\n杜鹃园是锡惠公园的一部分位于映山湖的西南角，是开发利用荒山坡道建成、曾获全国公园设计一等奖。\n园内有三百多个品种的杜鹃，且有全国少有的珍贵品种都用盆景展示于各厅阁之中。\n金老师是园林艺术专家潜心于园林整体格局的研究，很有成就，在杜鹃园的建设中亲历亲为发挥了重大作用，他倾心于一草一木,一廊一榭、一山一石、一径一的谐然搭配使情景相融，让人看后难以忘怀。\n这次游学金老师给我们拓荒了许多建园的理念和如何游园观赏的知识。\n无锡从古至今就是一个人杰地灵、人文荟萃的地方。\n它不仅是享誉世界的音乐之都，同时旅游资源十分丰富、在全国也可算是数一数二的旅游盛地，也是多次被评为最适合人类居住的城市。\n因为它有最宽广的绿化面积、有最良好的生态环境，境内有碧波万顷的太湖、有被誉为“江南第一山”的惠山，锡山，有低海拔的雪浪山、九龙山、军漳山古道、有太湖绝佳处的头渚、有世界三大赏樱盛地之称的樱花谷、有闻名遐迩的荣氏梅园、有玲珑剔透的蠡湖公园，既有皇家钟爱的锡惠公园也有现代伟人喜欢的锦园。\n无锡名人及其故居纪念馆比比皆是、薛福成故居、钱钟书故居，陆定一故居博古故居、东林书院、顾毓秀展览馆、荣巷..等等。\n还有钱、杨、秦、蒋、唐、荣.．··等等几大家族的杰出人物在历史上还有今天为新中国的革命和建设作出的不朽贡献都永载史册。\n这些在金老师无锡文化课中都有比较详细的评述。\n无锡还是一个花的世界早春从梅园的万株梅花怒放开始，次第开的是头渚的樱花最近开放的是杜鹃园里无锡市花杜鹃，同时开的还有渤公岛公园三里长棚中的紫藤，即将开放的是龙寺玫瑰园里的月季和蔷薇、无锡是水的世界花的海洋，有水必植荷花，荷花唯以管社山庄最为壮观，百亩荷塘有两里多长的木栈道贴于水面与荷花相依，赏荷更有亲近感，无锡人爱荷花骨子里是与周敦颐的《爱莲说》情意相通的。\n八月金秋雪浪山的千亩薰衣草和桂花香溢全城，九月底全国性的菊花展无锡己举办了十几届。\n展出的品种有八百多个，属于我国原种地的有六百多个、引进国外的品种二百有余。\n初冬，宛湖花海的粉黛乱草、醉蝶、向日葵、蜀葵绽开后又是一片新景，市内每条道路旁皆以花草相饰，无锡真是个“花花世界”花开花谢终有期，尔去我来无间息。\n时序轮循、天道律定，人生也是如此。\n在人生这人过程中无论是谁留下的一点痕迹，点总会有一天消失殆尽。\n所以，珍惜当今犹为重要\n\n三省轩主程康年\n丙午年三月初六"},{"id":218,"title":"惠山寄畅园即景","category":"诗","date":"丙午年槐月初九","body":"龙光塔顶绕祥云，\n锦漪池清映碧天。\n枫杨探身露倩影，\n八音涧流觅知音。\n金莲桥下水生烟\n御碑亭内赋诗篇\n郁盘对奔无胜负\n知鱼槛前哲思辨瓣\n窗含远山一片绿，\n园藏花木四季青。\n二泉映月琴声悠。\n余生乐享赛神仙。\n\n三省轩主程康年\n丙午年槐月初九\n写于无锡四为斋。"},{"id":219,"title":"镇江漫行记之一","category":"文","date":"丙午年槐月廿三","body":"翻开6月5日的日历，这天正好是农历四月二十、也是二十四节气中的芒种，芒种是农耕时代农事最忙的季节“抢三夏”（夏收、夏种、夏管）对一年中是否能取得丰收有很重要的意义。\n就是这天我们随都老师餐旅文化沙龙游学去了镇江。\n镇江有土地面积三干八百四十万平方公里，人口三百二十二万多，二零二五年的Gdp五千七百三十点七八亿元在江苏十三太保中排名“老九”虽如此仍超过许多省会城市。\n八点整五十多名学友从无锡人民大会堂门前乘大巴车准时出发，一路观赏车窗外的风景、有农谚说：“四月十六蚕老麦熟”此时所见江南麦田里的麦子早已收割完毕，抢收抢种的抢”绝非虚言，从中央台新闻里看到“三夏”已急切的推送到江淮之间。\n两小时的车程十点准时到达焦山景区。\n焦山是国家五A级风景名胜旅游景区，位于镇江的东北边、从游客中心登船约五、六分钟即到，山上古木参天、葱郁苍翠，山虽不高海拔仅七十多米但鼻立在浩荡东逝的长江之中更显陡峭险峻古朴幽雅。\n焦山原名为樵山，东汉未年汉献帝三次下诏让焦光入宫做官但焦光不愿与腐败的政权同流合污，拒不应诏遂隐居樵山采药炼丹为民治病，百姓为纪念他将樵山改名为焦山。\n焦山景区内的定慧寺、佛学院、吸江楼、万佛塔、古炮台、碑林、郑板桥的读处....每一景点都有一个故事。\n景区内一棵已有五百二十五年树龄的枫杨从它那饱经风霜的躯干可见历史的沧桑，但那茂盛的树冠仍然可以为人们遮一大片阴凉。\n草木可以一岁一枯荣，人呢？\n因急于返回一个多小时的参观游览仅是走马观花留下很多遗憾。\n约十多分钟车停到西津古渡旁，在注册名为“苏锡常”江南渔庄的老饭店用午餐，餐食以镇江当地的名点为主，依次上的有桂花糕、蛋挞、蒸饺、烧卖、贴饼、有马齿苋，萝卜丝、大肉三种馅的包子、蟹黄汤包，刀鱼小馄饨这些都是现在平民百姓餐桌上的平常食材，并不物以稀为贵。\n菜品当中唯以“镇江肴肉”为尊，也属镇江独有，据传还有一个故事很早以前镇江酒海街一对夫妻卖卤蹄为生，一日错将父亲制鞭炮的硝当作精盐腌制买来的蹄跨，第二天发现己晚只能以错将错，洗净后加调料焖煮，出锅冷却后晶莹剔透、皮色洁白瘦肉红润、清爽软糯香味诱人，不柴不腻更适合老年人食用、如佐以姜丝和镇江香醋更是美味一绝。\n午餐后游览了西津古渡西津古渡已有干年的历史，它座落在镇江西边的云台山坡上云台山古称“算山”据传三国时期诸葛亮和周瑜在此定下一计火攻连营的“赤壁之战”至今仍被视为最成功的战例。\n西津渡古街全长只有五百多米青石板铺就，元明时期的石塔“昭关塔”和西边的小码头街仍存有唐风宋韵的历史感，由于江滩淤涨江岸逐渐北移，渡口现离江岸己距有三百多米，一座古时供人们避风遮雨、歇息待渡的“待渡亭”仍屹立在江边，这就是历史的见证。\n“超岸寺”始建于一千三百一十年，原名玉山报恩寺，晚清时才更改现在名。\n玉山位于云台山之西，名称玉山实则是一个土丘，海拔高还不足十五米。\n西津古渡唐朝时就具有完备的渡口功能，一直是我国南北水上交通、漕运的枢纽，唐代诗人李白、孟浩然都曾在此待渡过。\n宋熙宁元年春王安石应诏赴京、扬帆北去在此停泊小歇见景抒情留下了一首烩炙人口的《泊船瓜洲》“京口瓜洲一水间，钟山只隔数重山。\n春风又绿江南岸，明月何时照我还”还经常在人们耳边回响着。\n鉴真和尚六次东渡日本也都是从此地由江出海，前五次因各种原因皆失败只有最后一次才获得成功。\n英国领事馆的旧址在西津渡古街的五十三坡上，一八五八年六月二十六日第二次鸦片战争期间清政府签订了丧权辱国的《中英天津条约》镇江辟为通商口岸，一八六四年英国在此建领事馆，该馆占地十七亩多共建有办公住宿领馆监狱共五幢房屋，一九九六年十一月二十六日被国务院公布为全国重点文物保护单位，让人们永远牢记勿忘国耻。\n在此基础上镇江市又扩大五千一百五十八平方米、建成一座地方历史综合艺术博物馆，馆藏有从石器时代至明清时期的文物三万余件，古籍十万余册，珍藏国家国宝级文物“青铜凤纹尊”一件，国家一级文物七十余件、国级二级文物三百余件。\n馆内分五大展区《镇江出土吴文化青铜器展》《古代工艺精品展》《历代陶瓷器精品展》《京江画派书画精品展》《镇江金银器工艺精品展》。\n从西津古渡返回时想起古渡北移仅几百年间竞人是物非，“时间”就是一块磨刀石，由于世事的变迁，现代交通事业和交通工具的发达西津古渡失去了原有的作用，但它又崛起成为旅游的景点，成为凭吊历史的地方，它的价值依然存在。\n游学不仅是看看景点更应该有所悟。\n在西津古渡边上我想起杨慎的《临江仙》“滚滚滚长江东逝水，浪花淘尽英雄。\n是非成败转头空。\n青山依旧在，几度夕阳红。\n白发渔樵江渚上，惯看秋月春风。\n一壶浊酒喜相逢。\n古今多少事，都付笑谈中。\n”他将世事看得那么通透此词就是指导我们人生的座右铭。\n所以，人生中又何必要有那么多计较呢？\n当天的气温二十二摄氏至三十一撮氏度，还是很宜人出行旅游的，镇江的旅游景点还有很多，如金山寺景点就有一个与《白蛇传》相关的很美丽的传说，北固山景点就有辛弃疾率全城百姓抗金的故事。\n这次活动都老师和胡班长周班长安排得很周到细緻，因为都是老年学友活动时间不宜太长让大家不要感到太累。\n所以，有些景点没有安排到这次活动中，也给我留下机会写《镇江漫行记之二》，下午三时准时返回，在这次游学中好多学友照了很多照片，如与文章中提到的景点认为需要可配发到一起留存，更便于今后拾起来回忆。\n谢谢都老师，谢谢各位学友。\n\n三省轩主程康年\n丙午年槐月廿三\n写于无锡四为斋"},{"id":220,"title":"端午祭屈原","category":"词","date":"丙午年五月初五","body":"艾叶菖蒲榴花繁，\n五月梅雨未停闲。\n香包美酒裹金粽，\n汨罗江上祭好汉。\n龙舟竞渡争先难，\n旗鼓相当复呐喊。\n忠烈报国再无许，\n英魂离骚留人间。\n\n三省轩主程康年\n丙午年五月初五\n写于无锡四为斋"},{"id":221,"title":"时蔬谱","category":"文","date":"丙午马年夏至日","body":"菲芽冒尖着新衣，球葱出土裹红皮。\n青菜地里一片绿,萝卜开挖带出泥。\n架下黄瓜色泽翠，枝上紫茄懂人意。\n藤缠长豆如游龙，斑澜彩椒称稀奇。\n菌类品种难全计，丝瓜软嫩养身体。\n蕃茄又名西红柿，豆薯成熟多兄弟。\n大棚种菜四季宜，科学栽培更便利。\n有机蔬菜无公害，餐桌安全须牢记。\n\n三省轩主程康年\n丙午马年夏至日\n写于无锡四为斋"},{"id":222,"title":"江南水八仙","category":"文","date":"丙午五月十五日","body":"江南水八仙，美味数顶尖。\n简单做介绍，愿君牢记心。\n菱白四月有，供应较长久。\n洁白如凝脂，清炒特爽口。\n莲藕心眼多，出塘在深秋。\n桂花加蜜汁，入口香甜糯。\n荸荠微脆甜，成熟冬至前。\n生熟皆可吃，J功效利消炎。\n芡实营养多，煮粥真软糯。\n常吃补肾气，时机不可错。\n水芹嫩茎杆，炒食配香干。\n春节前上市，亮丽年夜饭慈姑味甘苦，炖肉赛卤煮。\n不食不知味，风味特别古。\n菱角实在好，中秋不缺少老菱煮着吃，嫩的适合炒。\n莼菜做金汤，入喉味清香。\n应市季节短，抓紧来品尝。\n三餐四季味，孝季节紧相随。\n江南多美食，时迟莫后悔。\n\n三省轩主程康年\n丙午五月十五日\n写于无锡四为斋"},{"id":223,"title":"咏叹二十四节气","category":"文","date":"丙午年六月初二","body":"《立春》料峭大寒冰未消，门开立春梅绽俏。\n不觉柳枝抹新绿渐见路边发新草。\n《雨水》河边看柳春来早，生机萌动水涨潮。\n紫气东来燕飞雨水充沛丰年兆。\n《惊垫》惊垫雷声天地开，唤醒百虫起身来。\n新雨润田沐春光万物复苏人释怀。\n《春分》节序列次到春分，昼夜时长获均等。\n四季轮回必有律，天行地势定乾坤。\n《清明》清明时节雨纷纷，种瓜点豆机抓准。\n人勤花繁总有得，祭祖数典莫忘本。\n《谷雨》春山谷雨绿映天,满目瑞草笼轻烟。\n姑娘巧手探嫩芽，好茶精制清明前。\n《立夏》塘边蛙鸣蒲花黄披吆牛扶犁杖。\n耕读传家实笃本，立夏不误插早。\n《小满》南国春辞小满天，子规声里雨如烟。\n鱼初上添珍新插秧苗绿满田。\n《芒种》蚕老麦熟枇杷黄，三夏来临农事忙。\n披星戴月催芒种，农民期望多打粮。\n《夏至》赤日似焰悬长空，大地皓热如蒸笼。\n夏至褥暑露锋刃熔金裂石赛火龙。\n《小暑》小暑炎炎夏日长，荷风淡淡送幽香。\n蝉鸣蛙闹催三伏，流蜜如星夜纳凉。\n《大暑》泽国大暑汗如蒸，空有雷雨绿荫深,手摇蒲扇驱热浪，窗外穴声烦煞人。\n《立秋》残暑悄然歸隅行，朗朗碧空走白雲。\n一枕新凉觉立秋，夜雨送来梧桐情。\n《处暑》金风渐送三伏天，处暑凉意贵如金。\n岂料遇上秋老虎，降魔再借芭蕉扇。\n《白露》夜沉雾凉凝玉珠，朝霞五色映白露。\n待看候鸟南回迁方知稻熟黄染树。\n《秋分》天高气爽好时光，一阵风雨一程凉。\n秋分日后白昼短，农家辛劳忙收藏。\n《寒露》疏影轻摇寒露重，夜冷侧隐悲鸣虫。\n闲来捧壶观皓月,细思人生一场梦。\n《霜降》寒临霜降浸长夜,菊盛荷蕉兴与衰。\n眼观庭前红枫叶,秋过冬去待春来。\n《立冬》野径阡佰花草枯立冬霜冷北风呼。\n扫落银杏金黄叶，赏菊蟹伴读书。\n《小雪》小雪随风舞穹间,凌花跌碎不忍看。\n山林田园裹素色谁怜穷人五更寒。\n《大雪》岁暮大雪乱纷飘鳌龙激战碎玉袍，天地混沌隐城廓,人生张驰凭运道。\n《冬至》冬至日影昼渐长数九送寒阴复阳。\n墙外腊梅抢先开,窝冬消遣煮优黄。\n《小寒》寂寞无聊度小寒，多怀伤感自无欢。\n夜浅友来茶当酒晨见檐下凌成川。\n《大寒》大寒冰封万物寂，北风怒号西风烈。\n区区严冬抗几时,款款春风吹来急。\n\n三省轩主程康年\n丙午年六月初二\n写于无锡四为斋\n注：一年分春夏秋冬四季，每\n季又分六个节气，全年有廿四\n个节气，一个节气又分三候全\n年七十二候，一侯五天共三百\n六十天、节气与候的组合称气\n候，是农耕时代指导农事活动\n的大概率时间，彰显了先人的\n聪明才智。虽然每个节气的交\n接时间都严格规定到哪月哪日\n几时几分，但因为各地所处的\n地理位置不同，和所存在的纬\n度、海拔高度、日照温度之间\n的关联差异，其物侯现象必然\n纷呈不一、东西南北各有干差\n万别，这更显得伟大祖国的幅\n原辽阔、地广物博。我曾在长\n江下游和西部高原生活和工作\n过，对这些地方的气候特点、\n农时农事活动有一定的了解，\n诗中的物候现象基本以这两地\n区为多，同时将过去一些与现\n在己不同的生活方式也交织到\n一体融入诗中。全诗主题是写\n甘四节气的，应偏重于节气中\n的物侯现象和农事，其中也灰\n杂了一些个人的认知与情感，\n虽有喧宾夺主之嫌，但我自以\n为还是可以认可的。"},{"id":224,"title":"赏荷","category":"诗","date":"丙午荷月大暑日","body":"湖孕吴越暑中游，\n塘掩菡萄开藿头。\n蓬上蜻蜓点水乐，\n水下鱼儿戏无愁。\n红粉并蒂连天碧，\n雨中小舟逐烟波。\n绿伞开合随风意\n管社观月伴赏荷。\n\n三省轩主程康年\n丙午荷月大暑日\n写于无锡四为斋\n注释：这首诗写在无锡，夏日\n的江南凡有水的地方一定有荷\n花，诗人在大暑酷热之中去了\n两个特别有代表性的地方赏荷\n一是头渚，苔头渚景区的荷\n塘面积都不大，但给夏日游景\n区添了点晴之笔，那舞动的蜻\n蜓、追戏的鱼儿给人们带来了\n无限的情趣和清凉。二是藿头\n对面的管社山庄，管社山庄\n是无锡植荷面积最大的地方。\n干亩荷田紧贴水面铺装了约两\n公里长专供人们赏荷用的木栈\n道，荷花惊艳盛放时、色彩斑\n斓、姿态各异、娇嫩欲滴、暗\n送幽香，特别招人喜爱。泛一\n小舟穿行在雨中的荷塘里更有\n文人墨客的风味。如果在有月\n光的晚上邀三五好友去赏荷，\n边饮酒或边品茗，那“荷塘月\n色”的意境可以美得让你不敢\n想像。相信无论是在头渚的\n小格局还是在管社山庄大气场\n的赏荷、都会给人们带来满满\n的幸福感。"},{"id":225,"title":"秋意","category":"词","date":"丙午荷月立秋日","body":"各位亲朋好友今日\n立秋，填一首词送\n给您。“春华秋实”\n衷心的祝愿你和你\n的家人，人寿年丰，\n幸福满满。\n\n（临  江  仙）\n\n云淡风轻疏秋韵，\n山色溪光梵钟。\n晨雾如纱天地濛。\n茅舍升炊烟，\n夕照拂梧桐。\n\n人生如梦肩负重，\n如影随行相逢。\n眼寬心静自从容。\n倚窗望星汉，\n露寒起秋风。\n\n三省轩主程康年\n丙午荷月立秋日\n写于无锡四为斋\n\n注释：清康熙乾\n隆皇帝都六下江\n南，七次驻跸于\n寄畅园，对寄畅\n园情有独钟留下\n了很多夸赞寄畅\n园的诗篇，康熙\n所题“山色溪光”\n和乾隆所题“玉\n戛金枞”镌刻在\n石碑上的篇额如\n今镶嵌在寄畅园\n进门左边的院墙\n上。与寄畅园相\n邻的是惠山古刹，\n凡寺院皆有暮鼓\n晨钟。钟罄之声\n不绝于耳，可净\n化人们的心灵。\n寄畅园里有一棵\n百年以上的老枫\n杨斜探身姿倒影\n在锦汇漪中，尤\n在朝霞初映时那\n惜惜相依的姿态\n十分招人喜爱。\n“夕阳无限好只\n是近黄昏”。秋天\n虽是收获的季节，\n但也不免寄生有\n苍凉感，让人触\n景生情、恍然若\n失，感染出各种\n各样的情绪。词\n的上片是借康乾\n二帝所题篇额意\n境写大自然的景\n色，下片写的是\n诗人触景生情之\n悟、如此“秋意”\n绵绵、留给仁者\n见仁、智者见智。\n\n（临江仙）词牌，\n多以抒情为主上\n下两片各三十字，\n词牌以六十字五\n十八字为多，三\n平韵，也有五十\n二、五十四字多\n种变体，二、三\n五句押韵，上下\n两片一韵到底。"},{"id":226,"title":"贺志龙兄长八秩寿辞两首","category":"诗","date":"丙午年","body":" 贺志龙兄长\n   八秩寿辞两首\n\n  （     一     ）\n八旬老叟儒家风，\n为人师表受敬重。\n积善之家有余庆，\n崇尚美德贯始终。\n\n治家勤俭清如许，\n从政情理法兼用。\n平生年华未虚度，\n不负乡贤南山松。\n\n   （     二     ）\n人生苦短嘉年华，\n善植八秩长寿花。\n昔年治政安黎庶，\n今日修文伴诗茶。\n\n人格敦厚儒风雅，\n两袖清风传世家。\n怡孙养心勤锻炼，\n福寿康宁乐无涯。\n\n三省轩主程康年\n丙午年X月X日\n写于无锡四为斋\n\n志龙老哥的八十岁大寿应在今年，老弟愚钝具体何月何日却没有搞清楚，请老兄不啬寿酒一杯共庆人生至伟，恕小弟手慢撰劣诗两首以奉敬意。具体什么时候能喝上寿酒随时应诏多谢，多谢！"},{"id":227,"title":"寄畅园","category":"诗","date":"丙午槐月小满日","body":"意境相融称寄畅，\n园小景深借龙光。\n千年銀杏仰头看，\n惠山古刹隔一墙。\n\n锦漪池水清如镜，\n夕照倒影斜枫杨。\n春夏秋冬闲探幽，\n品茗二泉韵悠长。\n\n三省轩主程康年\n丙午槐月小满日\n写于无锡四为斋"},{"id":228,"title":"永远的怀念","category":"诗","date":"丙午三月廿六日","body":"应牛永福司令严\n父离世所嘱而作\n\n悬壶济世几十载，\n厚德美誉记人怀。\n耄耋安然长辞去，\n一缕清风化尘埃。\n\n族人抛泪动地哀，\n乡亲谢恩悼英才。\n耕读孝善传家风。\n心中立碑筑祭台。\n\n三省轩主程康年\n丙午三月廿六日"},{"id":229,"title":"丙午上元节","category":"诗","date":"丙午马年上元节","body":"东风劲吹杏花开，\n焰火狂舞炫异彩。\n众星捧月上元节，\n赏灯猜谜人如海。\n\n今朝迎福马上来，\n来日奋斗广进财。\n中华文化传统日，\n合家团圆共情怀。\n\n三省轩主程康年\n丙午马年上元节"},{"id":230,"title":"上元节","category":"诗","date":"丙午马年上元节","body":"怀念风暖杏花开，\n开花焰火炫异彩。\n彩雲追月上元节，\n节庆赏灯谜语猜。\n\n猜谜迎福马上来，\n来日奋斗广进财。\n财运亨通达四海，\n海潮生月共情怀。\n\n三省轩主程康年\n丙午马年上元节"},{"id":231,"title":"题朋友真情谊","category":"诗","date":"丙午年槐月初一","body":"云伴春风春伴云，\n勤俭示人示俭勤。\n清风柔吹柔风清，\n明月斜照斜月明。\n\n情感缠绵缠感情，\n行为贵重贵为行。\n心附魂灵魂附心，\n平生梦对梦生平。\n\n三省轩主程康年\n丙午年槐月初一\n写于无锡四为斋\n\n注：前四句是写\n以朋友为伴相互\n依存，朋友就是\n三观相同可以相\n互依靠的人，物\n以类聚人以群分，\n真朋友的习惯与\n情趣是会相互感\n染的，我中有你\n你中有我，近硃\n者赤、近墨者黑\n可能就是这个道\n理。\n后四句是写人的\n情感是细腻的灵\n魂是相融通的所\n以江湖上有句俗\n语说为朋友可以\n两肋插刀，当然\n绝不是无原则的\n相帮，而是以心\n相交，朋友在最\n困难时要敢于出\n手，一生中如交\n到这样的朋友才\n有真情谊称得上\n真朋友。"},{"id":232,"title":"秋意缱绻","category":"诗","date":"乙巳中秋后两日","body":"月色苍茫照九洲，\n烟雨江南借一簑。\n孤身独影归何处，\n浪迹江湖任扁舟。\n\n陋巷小憩几回眸，\n临风把盏知深秋。\n斜倚竹篱思浮生，\n尘缘暮色付东流。\n\n三省轩主程康年\n乙巳中秋后两日\n\n注释诗意：\n    人有悲欢离合、月有阴晴圆缺，此事古难全。这是古人的发现。\n       太阳光的强烈与人心的欢快相适应，月色將太阳光反射到地球上的每一个角落，暗淡灰冷这与人的伤感而契合。为什么会有如此鲜明的对比呢？不可而知。\n       地球在浩瀚的宇宙中只能算是小兄弟，借助北斗卫星科学的手段，将卫星地图放大再放大、发现在烟雨江南有偏隅一处小若一簑，诗人在与世事无常的纷扰中不断的拼博奋斗现在老了、累了、借此避风遮雨淡度余生。这种硕大无比与纤细微渺相辅相成又是为什么呢？至今也未找到正确答案。\n       明与暗、大与小、生与死只是哲学的思辨，对立统一规律就是真理。何谓人生，就是从母亲的十月怀胎起到生命终结止大约就是三万天左右。不声不响迎来了童年，无声无息的离开了青年，莫名其妙的丢失了中年，毫不情愿的走进了老年。人生就像一粒尘埃、在风雨中飘来飘去沉浮不定，又像大海中的一叶扁舟、摇摇晃晃随波逐流，在天地间的大势面前、一般人是无法掌控的，只能千根木头跟排走、凭由自已的情智大浪淘沙顺势而行，其间无论是顺利还是坎坷、是快乐还是艰辛，所有的历程都必须去面对，所有的酸甜苦辣都必须去尝试，逐梦而行将薄情的世界活成精湛的人生才算真聪明有智惠。人生旅途有很多个转折点，只要天时地利人和适时抓住机遇，一般就能心想事成，要想在高别人一階的平台上过得更好一点，就必须不断的努力攀升，这可能就是人生的全部意义。\n    人生的归宿在哪里呢？说法有三，一是说好人可以驾鹤西去到西方的极乐世界享受天堂的快乐，二说是恶人按作恶的大小多少、会分别打入十八层地狱，沉没在九泉之下，三说是无论好人坏人只要生命终结肉体就会还原给大地、灵魂就会出窍，就会像大数据一样与量子纠缠永远共生共存。科学的终结是哲学，哲学的终结是宗教，好人恶人有如此不同的结局是因果报应，这是宗教信仰劝戒世人要少做坏事、多行善积德、也是人们向好向善的心灵自慰，其实这几种说法都是无法论证的。\n       唐朝诗人刘锡禹的《陋室铭》“山不在高有仙则名，水不在深有龙则灵，斯是陋室，惟吾德馨”，直抒“谈笑有鸿儒，往来无白丁”的骄傲，他所交朋友都是时代的精英“无丝竹之乱耳，无案牍之劳形”在这所简居里可以享受无拘无束，自由自在的愜意生活，这也是世人所追求的目标。\n       今天的诗人在烟雨江南的偏巷陋室中、倚窗佇望临风把盏一人独酌，有时又到院中注目凝视快开败的菊花、仿佛是自己的影子，看到年龄和季节相似已到深秋、与下一个轮回也为时不远，略有些伤感但不惊讶也不沉论。\n       回顾前半生在茫茫人海中闯荡江湖、“工农商学兵”的平凡履历、都详细记录在档案之中。很庆幸在人生的每个階段都有贵人相助。记得在五十多年前离家外出闯荡江湖时慈母的叮嘱:“在家靠父母、出门靠朋友”，我一生将这句金玉良言作为安身立命的座右铭，几十年来为人处世注意择人而交以诚实守信待人、获得了很多朋友的青睐与信任，虽未达到“谈笑有鸿儒、往来无白丁”的最高境界、但也是有高朋好友经常相惜相问的。“一个篱笆三根桩、一个好汉三个帮”在奋斗成长的道路上始终得到了亲人的关心和爱护，得到了好友的帮助与支持，得到了师长们的提醒与鼓励。我会一如继往的去总结过去、善待如今，把握未来。会以良知和绵薄之力感谢所有的恩人。\n       生与死是人生逃不脱的过程，只是离开这个世界时略有早晚罢了。时间如白驹过隙行色怱怱一路走来，终究有一天会化作一缕青烟、一粒尘埃随风飘走随滚滚的长江直奔大海而去。\n       诗人早就做好了充分的思想准备，为自已最后的结局祈祷，早日向厄运告别摆脱苦难的人生，在可知的世界里消失得无影无踪到天堂寻找快乐或与量子纠缠共存共生。"},{"id":233,"title":"春之韵","category":"诗","date":"2013年春分日","body":"（一）\n檐下冰凌化素琴，\n岸边翠柳听鹂鸣。\n己是大雁归乡时，\n百花春雷谁为先？\n（二）\n丝丝细雨润田畴，\n九尽遍地走耕牛。\n夜来东风缱绻过，\n晓看红杏闹枝头。\n（三）\n三月踏青人如潮，\n艳阳惠风女儿姣。\n曲溪觞饮丹青伴，\n晴空碧洗风箏闹。\n（四）\n田园村落流暖香，\n蜂飞蝶舞采花忙。\n桃李不言自成蹊，\n山河怎能不换装？"},{"id":234,"title":"沁园春·新年致意","category":"词","date":"辛丑年除夕夜前","body":"岁月静好，牛奔虎啸，此夜相交。\n送新春大吉，万事顺意，合家安康，福满寿高。\n千家团圆，万户欢笑。\n更添梅开迎雪飘\n好时节、看春晚冬奥，其乐陶陶\n江山如此多娇。\n享太平盛世莫内耗。\n愿/祖国繁荣，人民幸福，四海同春，五洲相邀。\n世界倡和，灾祸弥消， 好运连连胜今朝。\n除夕夜、寄无限憧景，共度良宵\n\n您好！在壬寅新春佳节来临之际，我在无锡新填沁园春词一首《新年致意》献给你，给您和您的家人拜晚年，恭祝：吉祥如意，幸福安康。"},{"id":235,"title":"追忆非洲见闻（之二）","category":"文","date":"二00七年二月","body":"11月27日星期日，结束了在南非的愉快旅行，早餐后收拾行囊赴机场11：30分乘KQ461航班去肯尼亚首都内罗毕，在机场导游帮我们顺利办完了行李托运和换票手续就挥手“拜拜”了，安检口的安检员很认真，让你把外衣鞋子都要脱掉腰带要松开，安检后在候机厅办理退税手续还闹了一场笑话，因为每个团友在南非都购了物、多少都可以退一点税，但我们的团友中没有一人真正懂英语、东撞西撞找到了退税窗口还要排队等待。南非因为失业需要找工作的人很多，但是机场退税窗口工作人员的工作效率很低、半天办不完一个手续、离登机时间己经很近了团友们仍在后面排长队，后来听一个中国老乡说还有一个办税的绿色通道，团友们又像一群无头的苍蝇乱撞好不容易才找到这窗口、等大家都办完手续早己超过登机时间、候机大厅的广播大声叫喊谁也听不懂，登上飞机己延误飞行时间约半小时，飞机只好推迟飞行，满飞机的人又等了约一个小时才起飞，匆忙中还有一个团友忘记取所退税款。\n飞机约五个小时后降落在内罗毕市郊的恩克贝西机场，接机的导游祁先生是中国江苏盐城人，他哥嫂在八十年代初就到内罗毕经商，经营餐饮和娱乐业，九十年代初他跟随哥嫂来到内罗毕，现已成了家取得了绿卡，在内罗毕与几个老乡还合伙开了一个中餐馆“上海酒店”据说生意挺好。\n肯尼亚位于非洲东部、地跨赤道，面积58万多平方公里、座落在平均海拔1000－－1200米的高原上，东非大裂谷纵切高原南北、有300公里长、将高原划成东西两部份，大裂谷谷底在高原以下450－－1000米，东部高地肯尼亚山海拔5199米的基里尼亚加峰是全国最高峰、也是非洲第二高峰、山顶终年积雪。年平均气温24摄氏度左右。人口2040万人，农业是国民经济的主要支柱、全国85%的人口从事农、牧业，主要农作物有玉米、小麦、咖啡，茶叶、咖啡和花卉是三大出口创汇项目，旅游业较发达。\n首都内罗毕得名于流经于本市的内罗毕河，因市内绿树成荫、花团锦簇又有“阳光下的绿城”之称。内罗毕位于肯尼亚中部的高原地区、面积684平方公里，距赤道南140公里、距印度洋480公里、市内平均海拔1525米、人口约250万是全国政治、经济和文化中心。全国有48个部族，吉库尤族为最大部族其次是卢希亚、卢奥、康巴等族，全国分设七个省和一个省级特区，省以下设区、乡、村。夜宿“Jacaranda－Hotel”四星级宾馆。\n距内罗毕西南280公里的边境地区、有一片1510平方公里的金色草原，这就是马赛马拉自然保护区、是世界上最大野生哺乳动物园，养育着170余种300多万只以上的野生动物，其中绝大多数为食草动物。随着季节的变化，每年的11月食草动物都会越过马拉河奔向肯尼亚国界南侧坦桑尼亚的“塞伦盖蒂”——意思是广阔无边的大草原。12月到5月期间动物主要散布在“塞伦盖蒂”，长雨季过后的7月庞大的动物群又涌向马塞马拉，每年进行两次大规模的迁徙，很遗憾的是我们去马塞马拉已错过了大迁徙季节，所以没有亲眼目睹到大迁徙的壮观景象。但是，从内罗毕向西南走了约100公里看到东非大裂谷后沿途随处都可以看到斑马、野牛、角马、瞪羚、麇羚和珍稀的马羚、长颈鹿、大象等多种动物在活动。280公里路程、路状很差走了约六个小时才到达马赛马拉“keekeroke－Lodge－Hotel”。宾馆是在荒原上修建起来的与外界没有任何隔绝，野生猴群随时都会光顾，下午我们换乘观光车去追逐野生动物的足迹、感受置身蛮荒的乐趣，又有驼鸟、野猪、狮子和沿途己看到的各种动物不时映入我们的眼帘，尤其是悠闲自得地卧在灌木丛下的狮群见到观光车和观光客、任人拍照丝毫没有害怕的迹象。\n开车的黑人司机对我们很友好、他说中国给肯尼亚援建了一条长200公里的高速公路是他们国家目前最好的道路，肯尼亚的公路上是没有收费站的，不管谁买车上了牌照就可以跑也无需买养路费，公路建设的经费完全有国家承担，因为经济不发达、国家没有能力拿出更多的钱来修路、所以全国的路状都比较差。他还说现在中国人到肯尼亚观光旅游的多了、要学一点中国话，我们就把所见到的动物名称和一般的日常用语教给他，他学得很快也很标准，为了日后不至忘记他又认真的记到笔记本上。在马赛马拉我也学了一句招呼语“哦吧”——就是你好的意思。在内罗毕和马赛马拉往返途中休息场所遇到的马塞人都很友好、他们知道你来自CHINA会主动向你要清凉油。当晚在宾馆的小型广场上团友们一边纳凉一边用自己带去作礼品的国酒茅台开了一次小型酒会，个个尽欢而散。\n第二天，早晨刚起床又看到长颈鹿在宿舍门前任意游荡，到宾馆搭起的观光台上看到不远处的水塘里有一群河马在活动。在这里真正领略到了人和动物、人与大自然和谐相处的美好景象。肯尼亚把非洲的五大动物野牛、大象、狮子、豹子、犀牛印到货币——肯尼亚先令上供人们随时观赏。不知道是什么原因珍贵稀有的犀牛始终未出现，所以也就没有亲眼目睹到，不能不说这是一个很大的遗憾。肯尼亚对野生动物保护得很好，谁无故伤害野生动物一定会受到法律严厉的惩罚，所以导游告诉团友象牙类的旅游纪念品千万不能买，否则、出海关时检查到有此类物品、不仅会受到罚款可能还会惹出很多麻烦。早餐后本应去纳库鲁国家公园（红鹤湖）观赏火烈鸟，因要绕道近100公里加之路状不好有些团友怕途中颠簸就改了行程由马赛马拉直接返回内罗毕。\n纳库鲁湖国家公园占地188平方公里，海拔2000米左右，这里生活着约450种禽鸟，是世界上最好的“观鸟天堂”，这里最著名的是火烈鸟有200多万只占全球火烈鸟的三分之一。未去纳库鲁湖观鸟是整个旅程的一大憾事。返回的途中我们经过一个马赛人的部落、团友们一致要求参观一下，部落首领要求付费否则不能参观，后在导游和司机的协调下给了50美元才同意到部落内参观拍照，同时还给我们表演了最原始的土著歌舞。\n在东非的200个部族中居住在洛伊塔平原马赛马拉自然保护区的马赛人非常著名、厚嘴唇、大耳洞、瘦高个是他们的显著标志，至今他们还保留着独特的原始部族文化和生活方式，男人身披“束卡”，实际上就是红底黑条的两块布，一块围住下身、一块斜披在肩上、手持一根细长的木棍任何时候都是这一身装束，手持的木棍说是赶牛和防身用的即使进城逛街也从不离身。妇女们都穿着马赛妇女传统的“坎噶”颈上配有兽骨做成的各种并不漂亮的饰物（因审美观的不同）以放牧为主的马赛人平时的食物都是以牛、羊肉以及奶、血为主、尤其喜欢把牛的鲜血和奶掺到一起喝，这是他们每天早餐的必需品，取新鲜牛血的工具很简单是一根约50－60厘米长中间具有凹槽的三角形铁钎，但放血是一门技术活、从牛颈下部刺下通过导槽把血引放出来、还不能影响牛的存活和正常健康。马赛人是不打猎的也从不吃野生动物，这源于他们对大自然的崇拜，但对于伤害他们的猛兽也从不畏惧，据说男孩子成人后还要以个人的力量猎杀狮子来证明自己的勇气才能娶妻。我所见到的马赛人的部落是用树枝围起的一个大园圈、面积大概有3000——4000平方米，在圈内搭有10多个窝棚，窝棚也是用树枝搭成上面随便用牛马粪和土一起抹了薄薄的一层既不避风又不遮雨，探身到一个窝棚内看了一下没有任何家俱和生活必须品、只有一张直接铺在地上的草席、一只不堪入目的破铝锅、再无他物，晚上人畜都拥挤在部落内，人在窝棚里动物在窝棚外，到底是怎么满足最基本生活需要的？真是不可而知。人类己进入现代工业文明社会、可马赛人的生活基本上还没有脱离原始社会，恕我未深入考察、仅从现象判断如果用中国历史比对最多也只能是奴隶社会阶段。当然居住靠近城市的马赛人也有了经济头脑、学会推销旅游产品、也会造假，搞鱼目混珠，在一个路边小店我买了几件动物木雕准备回国送朋友，他们极力推荐说原材料是肯尼亚黑木。黑木又称乌木，木质结构密实、质量比重大也比较珍贵。回来一看有一些仅是用硬杂木制作后再染上黑色并非黑木。肯尼亚是东非最不公平的国家，财富被1/10的人口所垄断，官员与职员收入悬殊，反腐委员会主席月薪260万先令其属下只有4000先令。\n在内罗毕我们拜会了联合国环境规划署区域合作司副司长王之佳先生，联合国环境规划署总部设在内罗毕。王之佳先生是中国人、曾在非洲几国任过大使、现就职在联合国环境规划署，代表团将嘉市的情况与他进行了交流、争取联合国环境组织对我市的环境治理与建设给予关注和支持，王先生表示一定尽责。\n12月30日早晨离开肯尼亚去北非的埃及继续进行考察访问。\n嘉峪关市工商局三省轩主程康年\n二00七年二月完稿"},{"id":236,"title":"逰渤公岛随想","category":"诗","date":"癸卯闰二月卄四","body":"遠离尘嚣洗铅华，\n岛上茅舍安几家。\n鸡犬相伴勤耕读，\n闲来琴棋亦书画。\n种粮种菜也种瓜，\n自酿美酒自煮茶。\n耳闻鸟鸣溪流声，\n研习养生无牵挂。\n赋诗填词话桑麻，\n酒醉常卧东篱下。\n胜似桃源自在日，\n神交渤公非自夸。"},{"id":237,"title":"不是杂文的杂文","category":"文","date":"二零一二年春节","body":"梦想有揭示自己精神世界、又属于自己文字的一本书，不知不觉也写了几十篇不伦不类的所谓文章，这都是为了退休后、在回顾自已一生点点滴滴心路时、积攒一点参考资料，当然不一定要正式出版。\n\n自己有时也在自问为什么不写《自传》呢？细想起来自己的一生平凡又平凡、普通又普通，想写也无东西可写。只好把这些\"四不象\"的文字硬凑到一起编本书。书名暂定为《草根闲杂集》。\n\n退休后想写一点东西的根本原因是想尽快的转换人生角色，及早的适应退休后无事可干的生活，不能让自己的脑子闲下来，过早的发生老年痴呆症，同时从\"写\"中寻找自己的一点人生乐趣。\n\n有这样一句俗话\"种豆得豆、种瓜得瓜\"，袁隆平先生是世界级的水稻专家，如果播他制的种，收获时一定是金灿灿沉甸甸的稻谷，用经济学家的眼光看任何事情总有投入产出，我\"写\"一点文字犹如\"种草\"，当然收获的还是\"草\"，遂有一枚\"种草堂藏书\"的闲章，这闲章有两层意义，主要是自己写的东西不发表、不出版，只由自己收藏，《草根闲杂集》由此而生。另外对我喜欢的书籍搞一点收藏，也以文雅自居立一个堂号。\n\n想编书，就必须按书的格式和要求写个\"序\"，写序一般是请领导、长辈、挚友更好是请到文学界的知名人士，因为文学界的朋友给你写\"序\"、你的书就容易出彩，很可惜在朋友圈里掰开指头数一数、还真没有一个文学界的朋友，即使文学界里有朋友、这本书的序也不能请他们写，免得给人添麻烦。因为我写的这些文章体裁不一、有心得体会、有游记、有诗歌、有辞赋、有散文、有杂文、编书至少要做到分门别类，从现在的情况看无论哪一类数量都不够，捏在一起让别人又不好评价。\n\n自己的事还是麻烦自己、写一篇不是杂文的\"杂文\"代为本书的\"序\"。请无意读到的人多加批评指正。"},{"id":238,"title":"咏雪","category":"诗","date":"辛丑年冬月大雪","body":"一、冬雪\n风助严寒雪如刀，\n云压半空雪似瀑。\n天降祥瑞雪呈兆，\n地披银装雪增俏。\n松立群峰雪成涛，\n竹咬悬崖雪添娇。\n梅开清香雪自傲，\n兰吐新蕊雪全消。\n二、独居\n窗外白絮旋舞飞，\n轻飘洒落大地归。\n柔抚麦苗盖层被，\n润物无声情为谁。\n炉边独酌微熏醉，\n又闻箫埙艾声随。\n孤灯单影心意冷，\n今夕寂寞将梦碎。"},{"id":239,"title":"小品·酒歌","category":"诗","date":"二零二零年冬至","body":"咏酒风\n先人酿酒创世风，\n史册留名有醉翁。\n文化传承又一脉，\n古今中外皆相通。\n独把蛊\n人生百劫化吉凶，\n无须看轻和看重。\n借酒消愁解百纳，\n切忌沉缅独把蛊。\n亲情融\n时光虽短恍若梦，\n幸福来自简单中。\n闲时逍遥多小酌，\n翁婿对饮亲情融。\n宴宾朋\n远来好友近相逢，\n好酒宴宾情义重。\n酒酣无伦忆往事，\n兴推高潮又一碰。\n论英雄\n文豪侠客论英雄，\n酒中故事数百崇。\n血性男儿醉不休，\n四海之内皆弟兄。\n附记：前几天从微信中看到一位\n朋友所发“来二两”的小\n视频，唤起了我对酒的记忆。\n“对酒当歌，人生几何”我曾\n写过一篇《说说酒文化》的\n碎文，从酿酒的历史渊源，酿\n酒的工艺流程，酒在现实生活\n中的意义及作用，喝酒的礼仪\n等方面做了一些叙述但很不全\n面。《小品.酒歌》以现实生活\n的视觉，写出了几种喝酒的场\n景和感悟，只为诸位朋友闲聊\n时多提供了一个话题，实在浅\n薄，敬请谅解。"},{"id":240,"title":"我眼中的越南","category":"散文","date":"二零零三年十月补记","body":"有幸与敦煌市工商局的王经华局长、张掖市工商局刘滿年副局长、省工商局《中国工商报》记者站发行部的陈志全同志一行四人出席《中国工商报》社2003年在广西北海举办的中国工商报全国记者通联站代表及《中国工商报》发行会议。\n\n会址设在北海市银滩大道的海湾大酒店。此次会议嘉峪关市工商局通联站和我个人都受到了《中国工商报》社的表彰。\n\n三天会议议程全部结束后，会议组织者和广西省与北海市工商局为了尽东道主之谊，根据与会代表自愿原则组织大家去越南来回共三天的考察，有此机会大部份参会代表都参加了考察活动。身居西北高原信息比较闭塞的我们当然不会轻易放弃，甘肃参会的四人全都报了名。为了得到更好的考察结果我也做了一些准备，查阅了一些有关越南的简单资料。\n\n越南，是由越南共产党领导的社主义国家。地处中南半岛东部，北与我国接壤，西与老挝人民民主共和国、柬埔寨王国交界，东面与南面临南海、海岸线长3260多公里。地形如S状，两头较粗中间略细，南北长1600多公里、东西最窄处50公里，陆地面积约32.96平方公里。酷似甘肃省的形状、也是两头较粗壮中间略细，东西蜿蜒1600多公里、南北最窄处19公里，总面积42.58万平方公里。\n\n越南全国划为58个省，河内市是越南的首都，总人口约8500万，有54个民族、主体是京族、约占总人口的87％。\n\n越南的自然资源丰厚，矿产种类多样主要有：近海的油气、煤、铁、铝、锰、铬、锡、钛、磷等，其中煤、铁、铝储量较大。海洋生物丰富其中鱼类有2000多种、蟹类300余种、贝类300余种、虾类70余种、森林面积1000万公顷。主要经济林木是橡胶。\n\n越南是传统的农业国，农业人口占全国总人口的75％，主要粮食作物有：水稻、玉米、马铃薯、番薯和木薯，主要经济作物有：咖啡、腰果、茶叶、花生、蚕丝等。\n\n越南也是一个发展中的国家，1996年越共八大提出要大力推型国家工业化、现代化、由此开始实行真正意义上的革新开放，2001年越共九大确定建立社会主义定向的市场经济体制，并确定了三大经济战略重点即以工业化和现代化为中心，发展多种经济成份，发挥国有经济主导地位，建立与市场经济配套的管理体制。越南实行革新开放后，经济保持较快增长、总量不断扩大、三产结构趋向协调、对外开放水平不断提高，基本形成了以国有经济为主导、多种经济成份共同发展的格局。与我国改革开放的步骤基本相似。\n\n参加考察的一行人马从北海乘车至东兴、再由东兴乘游船出发从海上游览下龙湾。下龙湾位于北部湾西部，是越南北方广宁省的一个海湾、距离首都河内市150公里，1994年联合国科教文组织已将下龙湾列入《世界自然遗产名录》，风景区分东西南三个小湾，从海面上冒出的山峰显现了大自然的鬼斧神工、从不同的角度可以看到不同的形状、真是多姿多彩，其景观确有独到之处，除山峰的密度稀少外、形状真酷似中国的桂林山水，因此有“海上桂林”之别称，可谓是名不虚传。\n\n下龙湾游完后即驱车去河内，此时导游也换成了越南小伙，他说他家就住在越中边境，我觉得他的汉语水平还不错。一路穷聊，他告诉我们到河内的注意事项及特色外，说越南现在还很穷很落后，一切皆以“瘦”见长。一是国土“瘦”，越南的地形图像是一块“肉骨头”南北两头的略粗南北长1600多公里、中间较细最窄处的宽度只有50公里，当地人多以“一根扁担挑两个箩筐”来形容国土的地形地貌。二是道路“瘦”，通往河内的路算是最好的公路了，路状最多相当于我国的二级公路，路面较窄且不平整，长途客车犹如海上游船随浪时上时下、速度起不来同样颠簸得人腰疼，在越南绝大多数公路都是两车道、非常狭窄，摩托车很多与汽车同道而行，路面不平整，司机的驾驶技术不过关真的不敢开。铁路也瘦，法国人留下的窄轨铁路还在运营，火车要比中国的小一号，极像中国森林里拉木头的小火车。\n\n三是房屋“瘦”，越南政府规定临街民宅宽不得超过5米，所到之处不管是农村还是河内看到的都是清一色的长方形、2---6层高低不等的小楼，像火柴盒一样密密匝匝地树立在街道两旁，这离奇瘦长单薄的楼房能否牢固？真让人担心会不会大风一刮就倒。楼房多为红色尖房顶、浅黄色外墙、这样的建筑元素仍保留法国殖民时期的基调。商店也是如此、门面宽度同样不得超过5米，向空中和纵深发展不限，这种建筑风格真是独特。四是人“瘦”，可能是因为天气炎热，人的食欲偏低、加之消耗的高热量食物偏少，这里无论男人女人、老人小孩普遍看来都是健康的黑瘦。城市里姑娘的肤色还是较白的，越南的姑娘个个都是魔鬼身材，从大姑娘到小媳妇，无论是餐饮店的服务员、挑担摆摊的女商贩，还是公路上骑摩托车的女学生身材大多苗条，装束多为头戴斗笠、身穿短衫肥裤、脚蹬拖鞋、个个亭亭玉立、小巧多姿，构成的是一道流动的风景线，使人很难忘怀。沿途所见真如导游所讲“瘦”得出奇。\n\n由于导游小哥的直爽、幽默，我大胆的向他提出了一个较敏感的政治问题：越南的普通民众对1979年中越自卫反击战都是什么看法？导游小哥直言不讳的告诉我，那时他还未出生，标准的80后对于这段历史不太知道、长大后才从书本上和老人口中了解一些。他说越南普通民众现在认为，中国和越南同属社会主义国家，在越南抗法、抗美战争中中国给了很大支持，尤其是在胡志明伯伯时代与中国老一代革命家结成的友谊胜似亲兄弟，兄弟间拌嘴打架是常事，事情过去了就过去了、兄弟仍然是兄弟。尤其现在中国的改革开放很值得我们学习。导游小哥把一个国家与国家之间错综复杂的外交关系、比喻成人与人之间的兄弟失和既恰当又似乎不太恰当，这就是普通人的心态和看法，不足为怪。\n\n第二天，游览了巴亭广场，观看了升旗仪式。巴亭广场位于河内市中心，面积约有北京天安门广场的三分之一，是举行重大集会庆典的主要场所。长1000多米宽24米的雄王大道贯穿广场，周围除有政府办公机关外就是外国大使馆，外墙米黄色调的主席府只有四层高，并不显眼，周围没有高楼大厦。广场东靠巴亭会堂西侧是胡志明主席的陵墓、墓西北边是胡志明主席的故居高脚屋，里边的陈设很简朴，西南面有胡志明博物馆、馆前是著名的独柱寺。广场四周绿树环绕、有数条辐射状的林荫大道与市内其它道路相通。\n\n还剑湖是河内市中心区的另一处景点。湖面呈楕园形、面积约12公顷、平均水深1.5米、湖周四岸树木青翠绿荫如盖、湖水清澈如镜、环境幽雅娴静。岸边伴有笔塔、和风塔和水谢、凉亭等古式建筑，水中有玉山祠、栖旭桥、镇波亭和龟塔等胜迹点缀，不乏为一个休闲的好去处。\n\n河内市没有多少高楼大厦，滿大街上跑的都是电动摩托车，汽车的档次也不高，第三天返回，从芒街出境，在芒街稍作停留参观了一个刚竣工的赌场，说是专为中国人建的，可见中国人的赌性太重。通过越南海关大楼后要穿越中越友谊大桥，大桥全长111米，桥中央有一条斑马线，是中越两国的边界线，跨线后就回到了中国，再通过中国的海关大楼即回到国内。\n\n原来出国和回国就这么简单。"},{"id":241,"title":"知秋三首","category":"诗","date":"辛丑年重阳节后","body":"一、（早秋）\n暑气渐消见天凉，\n残荷败叶遮河塘。\n鸣虫低吟声无力，\n大雁南飞排成行。\n窗前魏紫胜姚黄，\n盆中兰香溢滿堂。\n远方山色美如绘，\n近处竹海两茫茫。\n二、（中秋）\n四季往复皆有常，\n春播夏管辛劳忙。\n五谷丰登六畜旺，\n农家喜庆获收藏。\n人生旅途有辉煌，\n世间月圆无久长。\n功名利禄随烟云，\n珍惜身体迎重阳。\n三、（晚秋）\n一湾清溪绕山庄，\n疾风扫落滿地苍。\n此景扰人易感叹，\n更著寒露凝成霜。\n情通心融眼似窗，\n遥祝亲友别无恙。\n默送严寒悄然去，\n万物醒来又春光。"},{"id":242,"title":"节气悟道","category":"文","date":"乙巳年六月初","body":"中国历史源远流长造就了中国文化的博大精深，儿时就背得滚瓜烂熟的二十四节气歌：“春雨惊春清谷天，夏滿芒夏暑相连。秋处露秋寒霜降，冬雪雪冬小大寒。”原本就是古人根据农耕文化总结出来的务农经验，将一年划分为二十四个节气，用来指导哪个节气该干什么样的农活的。"},{"id":243,"title":"贺华诞","category":"词","date":"二零二一年七一节","body":"（沁园春）\n民族脊梁，红船启航，百年沧桑。\n历／九死一生，武装起丈，千回\n百转，会师井岗。\n遵义拨乱，长征百上，解放大军\n渡长江。\n天安门、闻／领袖高呼，屹立东\n方。\n信守初心不忘。\n率工农大众谋小康。\n借／改革开放，科学布局，韬光\n养晦，蓄积力量。\n牢记使命，与时俱进，中流砥柱\n永担当。\n今崛起、矗／民族之林，复兴在\n望。\n附注：沁园春，词牌名，\n上下两片。上片十三句五\n十六字，四平韵。下片十\n二句五十八字、五平韵共\n一百一十四字。上片四五、\n六七、八九下片三四、五\n六、七八句为对句。一句\n逗式句皆为上一下四句法"},{"id":244,"title":"赏荷","category":"诗","date":"二零一七年七月二日","body":"翠盘银珠轻摇摆，涟漪荡起送凉风。\n一塘荷花万点红，蜻蜓戏水舞池中。\n君子真崇爱莲说，众人随意赞芙蓉。\n备注：\n七月二日、星期天，阴，偶有几丝小雨，稍闷热。余与女儿女婿及小外孙，一家五口去无锡管社山庄赏荷。山庄座落在无锡著名景点鼋头渚的对面，隔湖相望。进入游览区映入眼睑的是大片红色的荷花间夾杂着粉红、白色荷花及红色、黄色的睡莲，相互斗奇争艳。又见数种蜻蜓、盘旋低飞、不时落到荷花上、摇着头用前脚搓脸，十分灵动可爱。\n是日，正逢公休日逰客如织，梅雨季虽略有小雨、却丝毫未影响到逰客赏荷的兴趣。受此景此情触动，欣得几句跃在笔尖，趴到纸上，作《赏荷》备考。\n右录：宋理学家周敦颐（1017—1073）《爱莲说》“水陆草木之花，可爱者甚蕃。晋陶渊明独爱菊。自李唐来，世人盛爱牡丹。予独爱莲之出淤泥而不染，濯清涟而不妖，中通外直，不蔓不枝，香远溢清，亭亭净植，可远观而不可亵玩焉。\n予谓菊，花之隐逸者也；牡丹，花之富贵者也；莲，花之君之者也。噫！菊之爱，陶后鲜有闻；莲之爱，同予者何人？牡丹之爱，宜乎众矣。"},{"id":245,"title":"走进宝岛台湾","category":"散文","date":"二零一二年十二月十日","body":"宝岛台湾，在我的心目中与西藏一样具有神秘感，同样令人神往。西藏，我分别于2000年和2006年去过两次。到台湾去的夙愿、也于11月下旬在嘉峪关君和旅行社参团、赴台观光旅游成行后如愿以偿。这次旅游团以嘉峪关农村合作信用银行的人员为主，还有我和老伴不多的几位散客，另加旅行社的南燕领队共有25人。\n\n这次旅游来回共计10天，在台湾的环岛游历经8天7晚。虽说是走马观花，但相对去台湾之前还是增长了不少见识，收获也颇多，我仅将个人的一知半解记录下来作为走进台湾旅游的成果吧。\n\n一、一路行程游台湾\n\n11月26日，搭乘东航MU9202次航班本应下午3点起飞、后晚点5小时才起飞、到浦东机场己是凌晨2点，接机后入住沪南路9191号的桃城度假村。\n\n11月27日，上午由浦东机场1号航站楼搭乘东航MU5007次航班12点30分起飞经1个半小时的飞行于下午2点正点抵达台北桃园机场，由台湾知见旅行社黄世名导游接机后即赴[国父纪念馆]参观卫兵换岗仪式，和[台湾地标101大楼]俯瞰台北市全景，晚歺后有小雨、团友们急忽忽的参观了[士林夜市]，是夜下榻于台湾最有名的\"园山大酒店\"。\n\n11月28日，从台北经新竹到台中。早歺后前往[野柳地质公园]、[故宫博物院]参观，鬼斧神工的大自然力量塑造出维妙维肖的女王头像确实能让人惊奇不已，台湾故宫博物院陈列的镇馆之宝\"毛公鼎\"、\"翡翠白菜\"\"玛瑙肉石\"件件都是价值连城，馆内收藏的62万件藏品，无论是书画玉石、青铜器、象牙雕、历代瓷器、珊瑚制品、都是中华艺术的瑰宝，都体现了中华文化的博大精深，同属故宫博物院可惜分隔两地。晚入住台中市\"金典大饭店\"。\n\n11月29日，从台中经日月潭到嘉义。早歺后往[中台禅寺]参观、中台禅寺的建筑风格很有特色、打破了传统结构，远处乍一看像一座金字塔，中台禅寺的建设据说化了30亿新台币，内饰也比较奢华，与无锡灵山的梵宫相比可能还略逊一筹，但中台禅寺设有自己的小学和中学，学生必须用佛教义修行外还有更多的是学习现代的科技文化知识。台湾寺院建设的经费都来自信众的捐助。午歺后参观[日月潭风景区]，日月潭位于南投县渔池乡水社村是台湾唯一的天然湖泊，面积约9平方公里、湖的周长35公里、湖面海拔760米，平均水深30米，最深处47米、湖中水质很好。湖中有一岛名光华岛(岛上有一玄光寺)将湖面分隔两面，北半湖状如圆日、南半湖状似弯月，故此得名日月潭。潭被群山环抱、重峦迭嶂、碧波晶莹、群峰倒映、优美如画。游船在行进中导游告诉我们有句歌词\"阿里山的姑娘美如水\"、这位\"辣妹\"就在岛上，当年轻的团友正在神往的关键时刻、导游又说她今年不是十八而是八十、在此卖茶叶蛋己卖了五十多年，她的茶叶蛋的味道跟别人就是不一样。稍顷，弃船登岛映入眼帘的是一个小广场、密匝匝的游客正围在一起、看一中年艺男边弹奏键盘边唱邓丽君的歌曲、韵味不错。隐掩在人群后有一小木屋、里边架着几口铁锅飘溢出浓浓的香味，引人涎水欲滴，门前若市，一名短发老妪通过小窗台将一枚枚茶蛋递给游客，后面有数人帮忙煮蛋和包装，一锅蛋一定要煮6至7小时、才能真正入味。据说很平常的日子每天都会卖出2-3千只，节假日及旅游高峰期会成倍。为什么生意如此火爆？主要是讲信誉，从不偷工减料，导游给每人花10元新台币买一只，品尝后觉得味道真不错。途经云林县时导游告诉我们这里是邓丽君小姐的家乡。车上也播放了邓丽君很多好听的歌曲。夜宿嘉义\"耐斯王子饭店\"。\n\n11月30日，由嘉义经阿里山往高雄。阿里山属阿里山山脉、其风景区位于嘉义县东部76公里的阿里山乡，中心区为沼平公园一带、名列台湾八景之一，海拔2274米、阿里山的山势并无多少险峻奇特，但景观颇多且一年四季皆可游览、春可赏花、夏可避暑，阿里山的五奇有：高山铁路、森林、云海、日出、晚霞。高山铁路小火车是日本统治时期掠夺森林资源的见证，阿里山森林是台湾三大林场之一、阿里山桧木树龄最长的已有2000多年、生长得也很奇特，有的三代叠生在一起，有的长相像巨大的象鼻、树高40米，树围要有15人左右手拉手围一圈才能相抱。在潮湿地带生长的桧木与戈壁沙漠里生长的胡扬同样有千年不死、死了千年不倒、倒下千年不朽的动人故事。(姐妹潭)只是森林中西个相距10米左右的高山小湖泊，其故事也是很感人的。在嘉义的中埔茶叶展示中心品尝购买了高山云雾茶，价格不菲。晚餐后到六合夜市进行了一番体验、夜市上人头抬攒动，小吃品种很多，烤制品中以烤虾最为闻名，木瓜奶制品也别有风味。三百米长的夜市尽头是一家书店，在此化了一千多新台币买了一套钱币收藏。夜宿高雄园山饭店，饭店规模要比台北的小多了。\n\n12月1日，由高雄往台东。高雄是台湾的省辖市、也是台湾的第二大城市、面积3500平方公里、有人口315万，在高雄参观了[西子湾风景区]、[高雄钻石店]也就是手饰店，项链挂件设计得挺精巧。[佛光山]，佛光山是星云法师(原籍江苏江都人1927年出生)率弟子于1967年建成、任第一、二任住持，是临济正宗四十八世传人，现在的第七任住持心培和尚是临济五十世传人。游览了台湾最南部垦丁市的[猫鼻头]、[南湾海滩]景区[猫鼻头]是典型的珊瑚礁侵蚀地形、海岸像百折裙、看上去很美。更有意义的是[猫鼻头]正是台湾海峡与巴士海峡的分界线。晚上入住台东的[高野大饭店]、该饭店位于台东县卑南乡温泉村内规模还挺大的，估计有六至八百个床位，店内可免费泡温泉，是夜饭店接待了45个旅游团队，有好几百人，基本上都是大陆同胞。\n\n12月2日，由台东往花莲。早歺后在台东观看了[珊瑚店]老伴购了一条珊瑚项链和一串手链。随后沿花东海岸公路去花莲，途中参观了[北回归线纪念塔]、[石阶平]，[太鲁阁国家公园]的燕子口和九曲洞风景，很险峻也很壮观、台湾政府正在申遗。[长春祠]是为纪念开筑中横公路所殉职的老兵而建的，开筑中横公路用了三年九个月零十八天，死了225人，其中[长春祠]中祭祀有名有姓的212位，还有十几位连姓名都无从知晓。在花莲还观看了当地土著阿美族原生态的歌舞表演，游玩了南宾公园夜市并到海边放花炮。晚上入住花莲海悦饭店，凌晨1时45分始遭遇5.1级地震约2分钟，1小时后有余震，震时地动山摇、感觉明显、有惊无险、留有后怕。\n\n12月3日，从花莲经宜兰返回台北。早歺后参观了[花莲大理石厂]，主要的产品是台湾当地的玉石产品，这里的玫瑰石和七彩石很有特色、价格也很昂贵，在此化了一千八百元人民币买了一个心仪的七彩罐既当一石种又是一个工艺品可以收藏把玩，老伴也买了一些玉石手饰，随后乘火车经1小时10分左右到宜兰的东奥下车再转乘旅游大巴返台北。从花莲到宜兰也有公路可通，这一段应称苏花公路，全在崖壁上十分惊险，落石经常伤车伤人，2008年泥石流冲走两台旅游大巴和21游客的残迹仍在，至今也未找到踪影。因此，台湾观光局为保证游客安全，规定这一段路一定要乘火车。到台北后参观了阳明山下山青水秀、繁花似绵的[士林官邸]、官邸是蒋介石和宋美龄原来居住的地方，现己辟为公园供游人观赏。当天恰遇菊展，参观的人很多。布展的菊花中有很多难得一见的稀有品种，据说\"大丽菊\"这一品种相当名贵。在园丁的巧妙布置下、千姿百态很吸引人。菊花在中国传统文化中有很高的地位，被文人墨客誉为\"四君子\"。晚歺后又去免税店购物，老伴为女儿买了少许化妆品。晚上还到西门町游览了一番，西门町是一个商业区也就是购物步行街，是唯一留下来的日本统治时期的见证。街旁灯火辉煌、商品琳琅满目，档次要高于其它参观的夜市。这里与世界上很多城市一样，什么都有又什么都没有，有的是商品、没有的是特色。夜宿福君海悦大酒店。\n\n12月4日，参观了中正纪念堂和自由广场，随后乘车去松山机场乘FM-802航班返回13点40分正点降落在上海浦东机场。12月5日上午由浦东机场2号航站楼乘坐FM-9205航班9时起飞途经西安于下午3时安全回到嘉峪关，顺利结束这次旅程。\n\n二、台湾的历史地理\n\n台湾自古就与大陆有着密切联系，我国古代文献中称台湾为夷州，隋、唐、宋、元时因书写不统一有称\"流求\"也有称\"琉球\"的，明朝时称\"小琉球\"和\"东蕃\"，明末后称台湾至今。16世纪台湾被西班牙和荷兰人占领统治过38年，1662年郑成功收复台湾，1684年清政府设台湾府隶属福建省，1894年甲午战争清政府失败后签订丧权辱国的《马关条约》割让台湾给日本，1945年8月抗日战争胜利后台湾光复、回归祖国。\n\n台湾现设5个直辖市：台北市、新北市、台中市、台南市、高雄市、16个县，368个市镇、7835个村里。总人口有2319万余人，有14个少数民族，阿美、泰雅、排湾、布农、卑南、鲁凱、邹族、雅美、邵族、曹族、葛玛兰、赛夏等、高山族人口最多约17万、邵族人口最少2829人，少数民族人口约43万人，占总人口的2%，汉族占总人口的98%。\n\n台湾省位于环太平洋火山地震带上，地壳不稳是一个多震区，东临太平洋、南界巴士海峡与菲律宾相邻、西隔台湾海峡与福建省相望，扼太平洋航道中心，是重要的交通枢纽。\n\n台湾省总面积为36191平方公里，包括本岛、兰屿、绿岛、钓鱼岛等周边21个附属岛屿及澎湖列岛的64个岛屿。台湾多山、高山与丘陵占全部面积的三分之二以上，有五大山脉：中央山脉、雪山山脉、玉山山脉、阿里山山脉和台东山脉。有四大平原：宜兰平原、嘉南平原、屏东平原和台东纵谷平原。有三大盆地：台北盆地、台中盆地和埔里盆地。超过100公里以上的河流有6条：浊山溪、高屏溪、淡水河、曾文溪、大甲溪、乌溪。\n\n北回归线从台湾中部穿过，南部是热带气候、北部是亚热带气侯，年平均气温22攝氏度，年降雨量平均在2000毫米以上。台湾的物产丰富、主要经济作物有：蔗糖、高山茶、大米、热带水果、花卉。森林资源有：台湾杉、桧木、樟木、楠木。鱼业资源也十分丰富，现代工业科技发达，IT业占很高的经济比重。\n\n三、台湾的社会风情\n\n台湾的人文社会风情很有意思，1949年蒋介石兵败去台湾带走200万人，全国各地的人都有，所以至今全国各地婚丧嫁娶、传统节日的风俗习惯保持得很多，国学、儒家思想传承得也很多。人们的语言除本岛的闽南语外、用普通话交流一点都不成问题，文字仍袭用的汉字繁体、有一些词汇如\"捷运\"\"机车\"\"冷气机\"与大陆的\"高铁\"\"摩托车\"\"空调\"不一样，稍加注意也可领会。而且台湾的语言很有人情味，如大陆人讲\"死亡\"、台湾人讲\"往生\"是可获重生的意思；大陆人讲\"下葬\"、台湾人讲\"上山\"，说的是人不管是活是死都要往高处走；大陆人讲\"流产\"、台湾人讲\"落胎\"，说的是叶落归根；大陆人讲\"痴呆\"、台湾人讲\"失智\"……，诸如此类都表现了台湾人的素质。这些都得益于1945年台湾光复后当局教育部门就强调学校要用普通话教学。\n\n台北在某种意义上说，是最具有中国传统文化韵味的城市。市区几条东西向的大道从北住南依次以忠孝、仁爱、信义、和平命名，还用典自四书五经中的四维八德之类来定路名，此外还有以大陆地名命名的街道如广州街、天津路、青岛路等而且基本按照中国版图方位排列。台北市区残存的老城门、山脊飞檐、琉璃瓦顶的\"国父纪念馆\"、\"园山饭店\"、\"台北故宫博物院\"貌似北京天坛的\"中正纪念堂\"无不具有典型的中国传统建筑风格。满街繁体字的广告牌和书店摆满的文化典籍及商店里售卖的文房四宝都充满中华传统文化的韵味。\n\n李登辉执政时想搞一中一台、陈水扁执政后承其衣钵想去中国化搞\"台独\"，当时岛上凡带有\"中国\"字样的均要改为\"台湾\"，因大多数民众的反对和改革成本太高才放弃，据此看无论干什么都要顺潮流合民心，\"民为邦本\"的观点在台湾又得到了一次实证。\n\n台湾在1949年蒋介石登岛前只有600万左右的人口，现有人口2300多万，仍在鼓励生育，少数民族生一个小孩政府补助新台币6000元、汉族补助4000元，小孩的教育费用从上幼儿园起到中学毕业全由政府负担，虽如此台湾的生育率还是全球倒数第一，30-40岁未婚女性的比例世界第二。\n\n导游黄世名告诉我们，十九世纪初清政府向台湾有过一次较大的移民活动，大部分来自福建的泉州和漳州，他家祖籍泉州，家谱记载是从十一代世祖移居台湾的已近200年历史他是第十七代人。\n\n台湾政府比较注重民生，他说他父亲前年生病住院三个月直至去世共化去新台币近120万元折合人民而26万多元，个人只承担了不足11万新台币折合人民币2万多元。他自己做了一个小手术住院三天各种费用加在一起折合人民币不足200元与他每月所交医疗保险费相等。\n\n导游说2008年马英九执政后很快就解决了两岸的直航问题、扩大了两岸经济文化交流，大陆多个省都组团去台湾采购农产品，2010年后每年赴台观光的游客有400多万人其中90%是大陆同胞，大大缓解了前几年就业难的问题，为激活台湾经济走出金融危机的泥淖起了决定性的作用，现在台湾民众的日子也好过多了幸福指数在不断上升。导游说蒋经国先生在台湾民众心里还是有好感的，他还说他个人没有政治倾向，只要时局平稳、有工作可干、生活质量不断提高就行。\n\n导游还说台湾政府现在很重视大陆游客的人生和购物安全，对各旅行社监管得很严，对各旅行社使用的旅游大巴及司机的管理都有严格的规定，凡游客购物只要是品保协会会员单位的、质量一定有保证，价格虽然高一点，但不得乱要价比较公平，凡购物遇到假冒伪劣一经投诉查实后商家一定会受到严励处罚，游客的合法权益也会得到保障。\n\n在台湾生活处处都感到很方便，走在台北的街头几乎每隔三五百米就有一个便利店，就算在台东、花莲、阿里山这些相对偏辟的地方找一家便利店也非难事，台湾的便利店与大陆的超市相似，它不仅供应人们日常生活的商品、还有很多功能与服务、就连在医院就诊、政府机构排队办事、都有便利店在你身边为你服务，有的便利店还为游客购买郵寄当地的名特产品，甚至在假期聘请老师驻店、为周边居民提供照看小孩做功课的服务，据台湾媒体报道遍布全岛的便利店己有一万多户、平均2000多人就有一个便利店为其服务，100平米左右的一个便利小店竞可以储备包括衣食住行等方方面面的3000多种商品供人选购，还有各式各样的服务让人挑选。台湾的便利店真正强大的不仅是商品而是其服务功能，只要是人们生活需求的、它其本都可以做到。\n\n台湾的交通也比较发达，西部从北到南有捷运、高速公路、环岛铁路，东部因地势险峻没有捷运和高速公路，岛内有3个国际机场和6个支线机场。\n\n这次去台湾旅游很成功、天气比较帮忙，从未因天气影响参观行程。台湾八景：阿里奇观、日月风姿、鲁阁幽峡、南投极致、阳明风光、北投温泉、野柳公园、除乌溪飞瀑未能看到外都有幸参观到了，能近亲祖国大好河山确实很开心，虽说是走马观花但对宝岛台湾有了更多的了解也长了不少见识。这篇文章很简陋很平实，不像日记也不像游记，对所到景点没有用文字去刻意表现它的美丽，因为现代观光旅游不仅是用自己的心和眼去看，而且有更先进的攝像机、照相机等设备去做细致翔实的记录，刻录后比用文字记录得更直观、更便于记忆和保存。\n\n最后撰联一副作为这次旅游的心得体会也作为本文的结束语：\n\n兄弟和睦、两岸和顺、世事和谐、民众添福祉。\n\n骨肉同根、四地同心、殊途同归、国家必昌盛。\n\n横批：大业有成"},{"id":246,"title":"踏青·江南春","category":"诗","date":"壬寅年清明节前","body":"春到阳山峰叠翠，\n蓝天白云映碧水。\n桃红柳绿围村舍，\n油菜花香沁心扉。\n蜂儿採蜜蝶双飞，\n燕子嬉闹鸟声脆。\n杜鹃啼血催农事，\n农夫扛犁犬追随。\n踏青赏景勿陶醉，\n清明祭祖寻根归。\n中华文化传千秋，\n孝亲莫等治后悔。\n附记：三日二十四日艳阳高照，\n天高气爽难得的好天气，\n好友老施约了鞠姓朋友\n我和老伴去阳山踏青赏\n花，阳山是无锡水蜜桃\n的生产基地、有果园三\n万亩，近日正是桃花盛\n开期，跌入花海一片粉\n色世界。阳山水蜜桃皮\n薄、汁多、味鲜甜，远\n近闻名，六月即可上市，\n生活在这里也算有口福，\n阳山也是家婿履职之地\n据反映人设还行。天气\n好、心情好、一切皆好\n以此小诗及几张照片仅\n作为此春逰的纪念。"},{"id":247,"title":"辛丑重阳两首","category":"诗","date":"辛丑深秋于无锡","body":"•重阳节风俗\n重阳九久渊源长，\n尊老佳节呈瑞祥。\n老有所养传美德，\n孝亲不在徒悲伤。\n柿红枝头伴菊黄，\n春华秋实丰收忙。\n饮酒吃糕登高处，\n遥念先祖与故乡。\n二、重阳节感怀\n今度重阳在深秋，\n天地朦胧雨不休。\n无缘登高献家祭，\n后生有愧心知羞。\n岁月静好逝如梭，\n知足常乐多添寿。\n黄昏夕阳虽然好，\n银叟轻叹亦有忧。"},{"id":248,"title":"雪中情思","category":"散文","date":"二零一五年大寒","body":"光阴似箭、日月如梭、此话不假，二零一五年就像高铁线上飞弛的列车，瞬间就抛到身后去了。元月十六日与老伴搭乘上海至新疆伊宁的204次列车从无锡返回嘉峪关，抵达后的第二天晚上就遇到了一场大雪。冷风嗍嗍吹，雪花满天飞，清晨起来，气温冷得异常。窗外，高山上、田野里、大街小巷积着厚厚的雪，似有“忽如一夜春风来，千树万树梨花开”的感觉，家人告诉我们这己不是今年的第一场雪了。在北方见到下雪不足为奇，南方下雪也是有的但很少，在北方工作生活了几十年，所见南方下雪、现在回忆起来还是儿时的事。\n\n北方的雪自然不同于江南雪的细腻婉约，大都迎着呼啸的寒风、一路肆虐而来，十分粗犷、十分豪放、无拘无束、纷纷扬扬、冷性十足、硬劲铮锵，跌落在人们的脸上感觉生疼。南方的雪很象江南女子、深闺之秀，羞涩而腼腆、飘逸而潇洒，柔美至极，来也轻轻、去也无声、多偏水性、落地即化，飘落在人们的面颊上轻轻柔柔，用舌尖一舔还有丝丝甜意。也许它来就是为看一眼江南的秀美，为带走冬的消息送来春的和暖。其实，无论是江南还是北方的雪我都十分喜欢，不仅喜欢江南雪的洁白如玉、清纯婉约、深情款款的柔弱之美，更喜欢北方雪的苍劲凋零、冷傲孤洁、萧瑟清寒的阳刚意蕴。雪，世间无物能伦比它超俗的洁净，也无人能超越它傲骨的坚强。\n\n雪中静思、岁月沧桑、变换的是季节、流逝的是年华。回首流年，漫步人生旅途怱怱忙忙，眨眼又过去了一年，在过去的一年里有几个月与老伴一起帮女儿带孩子，小外孙八个多月学会床上翻身、十个多月学会滚爬转腾、十二个月学会站立行走，十四个月己会呀呀学语、迭音词的称呼和日常生活用语己经学会不少，整天绕膝呼外公、享受天伦之乐。另患腿疾手术治疗后休养数月基本康复，二零一五年有这两大收获，很是满足。\n\n退休以后人生最美的风景大多遗失掉了，如果一生的贡献能像落地即化的瑞雪，用另一种形式滋润着大地，哺育着生命，也应当感到欣慰。在无锡己生活了一段时间、虽然这里人杰地灵、物产富饶、自然生态、生活环境都很不错，但感到要融入进去比较难。因为你没有参与这个城市的建设与创造，所以你就没有自豪感、满足感、幸福感。虽然嘉峪关是第二故乡，但只有回到嘉峪关才有回家的感觉，因为我一生的青春年华全都奉献给了这片土地。\n\n仔细斟酌，在历史的长河里惟念生命最重要，一个人要以清醒的心智和从容的心境走过岁月，也许最不能缺少的就是像雪花一样的无私和恬淡，学会用欣赏的目光看待煌煌大千世界，用宽容的心态看待周围的人和事，便会看淡世间一切浮华。只要多几分坦然和矜持，就会少好多私心和杂念，少好多奢侈和欲望，就会象雪花一样平淡与安然、恪守生命的素雅。\n\n唯愿雪花融化心灵、心灵融入雪花，留下宁静与回想、留下禅意的感悟。\n\n雪是季节的使者，是美的化身，是苍穹赐给大地的圣洁之物，每一片雪花都是一个甜美的祝福。在雪中融入雪景，感受万物的恩赐，分享这个不同于其它季节的美，令人心犷神怡。“春有百花秋有月，夏有凉风冬有雪。若无闲事挂心头，便是人间好时节。”望着这一览无余的纯白，生活中纵有千丝万缕的情愫，经纯洁的雪花洗礼后，剩下的便是会心一笑的宽容与豁达。\n\n雪还是诗的海洋，北宋诗人卢梅坡的《雪梅》“梅雪争春未肯降，骚人搁笔费评章。梅须逊雪三分白，雪却输梅一段香”脍炙人口、流传至今，殷秀梅的一曲《塞北的雪》余音绕梁、令人难忘。因为有雪，风景愈发美丽、空气更加清新；因为有雪，笑容变得灿烂、步伐显得轻快；因为有雪，尘埃都被洗净、灵魂己经荡涤；因为有雪，心田才被滋润、心中永存希望。\n\n冬天来了，春天还会远吗！"},{"id":249,"title":"“文化”——精神的家园","category":"文","date":"二零一零年十月底","body":"党的十七届六中全会通过了《中共中央深化文化体制改革、推动社会主义文化大发展大繁荣若干重大问题的决定》提出了把我国建设成为文化强国、文化大国的重大战略措施，随之在各媒体上的建言献策也多了起来，有谈如何加强文化自信的、有谈如何加强文化软实力有效性的、有建议文化建设中既要防止文化的“物化”又要防止文化过度“意识形态化”的，还有建议“十二、五”期间要在调整文化结构的基础上大力发展文化创意、影视制作、出版发行、印刷复制、演艺娱乐、数字内容和动漫等七大文化产业的林林总总。仁者见仁、智者见智。\n文化到底是什么？我从《现代汉语词典》中获得的定义是：、人类在社会历史发展过程中所创造的物质财富和精神财富的总和，特指精神财富，如文学、艺术、教育、科学等。、考古学专用语，指同一个历史时期的不依分布地点为转移的遗迹、遗物的综合体。同样的工具、用具、同样的制造技术等、是同一种文化的特征，如仰韶文化、龙山文化。、指运用文字的能力及一般知识：如学习文化、文化水平。相关“文”和“化”的词类解释有近个、让人眼花缭乱。\n《周易贲卦彖辞》有云：“刚柔交错，天文也；文明以止，人文也。观乎天文，以察时变，观乎人文，以化成天下。”文化的内涵是与“人”的生命、人格、价值、权利、尊严和自由分不开的，每个受文化熏陶的人必有修养、必有优雅之气质和完善的人格。\n社会发展到今天人们又把生活方式的某一方面（衣、食、住、行）从历史到现代进行归结，搞出诸如酒文化、茶文化、饮食文化、服饰文化等等。\n我对文化的理解是：音乐歌舞、文学艺术、科学教育、风俗习惯、物质与非物质遗产……只是传承“文化”的载体并不能代表“文化”的本身。\n文化应该是一种经过几千年来祖祖辈辈洗炼陶冶积淀下来、至今仍铭刻在中华民族子孙骨子里、融化在血液中的图腾崇拜、传统美德，是体现全民族、全社会乃至每个社会成员整体素质的表现。“文化”是一种意识是人类最高的精神活动，是我们的精神家园。当然这样理解文化也会让人摸不着边。但可以从以下几个方面去理解：\n文化是一种信念。\n文化，其实体现在一个民族、一个人如何对待自己、对待他人、对待自己所处的自然环境。在一个文化积淀沉实的社会里，人懂得尊重自己他不苟且，因为不苟且所以有品位；人懂得尊重别人他不霸道，因为不霸道所以有品德；人懂得尊重自然他不掠夺，因为不掠夺所以有品质。品位、品德、品质是文化积累的总和。文化，不过是代代积累沉淀在现实生活实践中的习惯和信念。\n文化是一种价值。\n文化，是要有底蕴的，这个底蕴就是社会成员共同认同的价值观。这就是崇尚、追求“真、善、美”在一个文化功底深厚的社会里，不一定是上了多少年学、读了多少书，获得过什么学位的人才有文化。如“尊师重教”、“孝顺长辈”、“和睦邻里”、“诚实守信”、“独善其身”、“通情达理”、“顺其自然”、“敬惜字纸”……这些由祖辈父辈层层传递、由左邻右舍耳濡目染、潜移默化指导做人做事的“道理”就是“文化”。总之，文化是经过历代洗礼、大浪淘沙后留存下来的、社会成员又都认同的“真、善、美”的东西，是每个人心中某种“价值”和“秩序”的坚守。\n文化是一把钥匙。\n以人类心灵终极归属为目标的思辨，是搭建人与人之间相互理解信任的平台。信息的交流沟通是要一定基础的。“人以群分、物以类聚”“心有灵犀一点通”，依靠的就是文化这把钥匙打开人的心灵。人本是散落的珠子、随地乱滚，文化就是那根柔软又强韧的细丝将零散、疏离的珠子穿起来、连结而成精神相通、休戚与共的群体或社团，再将这些群体或社团串到一起便成为公民社会。因为公民社会不需要依赖皇权或神权来坚固它的底座。所以，文化便是公民社会最重要的粘合剂。但政治领袖一定要明白“公民社会”是政治的基础，“文化”又是公民社会的基础。一个稳定有序完整的社会、文化的传承与发展是不可或缺的。\n文化是国家灵魂。\n社会主义初级阶段的主要矛盾是什么？马克思早就告诉我们社会主义初级阶段的主要矛盾是：人民日益增长的物质文化需要同落后的社会生产之间的矛盾。解决这个矛盾不仅仅是发展经济，千万不要认为物质的丰富就是社会的文明与进步，始终不要忘记文化在构建民主、文明社会的政治、经济行为上是一个极其重要的元素、是一种引领、是一种动力。否则，政治家们所制定的政治纲领、经济政策，就会成为无源之水、无本之木。\n文化的影响是深刻的。对个人来说，文化一定是个人独见、无所不在，无论是在乡村坊间、大街小巷、教室课堂，与每一个人的工作、学习、生活、所有内容和质量息息相关。考量一个人的文化素养，从他的言行举止之中就可以看到高低，当然也与政治家制定的政策环境有关。\n文化决不是唱唱歌、跳跳舞、画几幅画、写几部书、编几部戏、拍几部电影电视剧，盖几幢影剧院、音乐厅、美术馆、图书馆之类的事，更不是文学家、艺术家、少数精英人物随便比划的小事，它应该是与人民大众日常生活休戚与共的大事。\n文化的影响是深刻的。对于国家来说，文化是基础教育，是整个社会有益的教化。它奠定的是国民最基本的素养和品位，它决定人们对社会上耳闻目睹各种事情是非美丑的判断。\n文化是一种产业、含有一定经济量的成份，媒体广告、建筑设计、音乐歌舞、文学艺术、影视电子、体育竞赛、旅游观光……，早已成为一些发达国家的经济项目。\n文化是一种外交，当政治协商遇到阻碍时、文化是消弥敌意最好的方法，我国七十年代初的“乒乓外交”就是最成功的笵例。文化是强大的、尤其对于弱势国家，文化可以是以柔克刚的军队，温柔渗透的武器，“三十六计”中这样的历史故事是很多的。\n文化首先是属于个人的，但也是属于国家和世界的。文化的发展应致力于使“人”更像人，绝对功利不得，更不能让人沦落为攫取物质的工具。\n尊重与坚守、发掘与传承、交融与发展，这是时代赋予的我们的历史责任，也是我们每个人对“文化”应有的正确态度。\n三省轩主程康年\n二零一零年十月底"},{"id":250,"title":"道德经》读后感","category":"文","date":"二零零九年八月五日","body":"老子所著的《道德经》，亦称《老子》、《道德真经》、《老子五千文》等，它被道家学派尊奉为道教的《第一经典》，因此，老子也被道教徒公认为是道家学派的开山鼻祖和元始天尊。老子及其《道德经》对中国文化的影响并不仅局艰于道教、而是中华文化宝库中的一枝奇葩，是取之不尽、用之不竭的思想源泉。\n老子，是中华民族中一个伟大的思想家、一生不求闻达，“以自隐无名为务”因此，其人其事在汉代就无法确切考证了，司马迁《史记老庄申韩列传》中说：“老子者、楚苦县（今河南鹿邑县）厉乡曲仁里人也。姓李氏、名耳、字伯阳，谥曰聃，周守藏室之史也。”\n“老子修道德，其学以自隐无名为务，居周久之，见周之衰、乃遂去。至关，关令尹曰：‘子将隐矣、强为我著书’于是老子乃著上下篇，言道德之意五千余言而去，莫知其所终。”据研究司马迁的上述记载基本可信，但也不能尽信；他抱着存疑的态度又说：“或曰：老莱子亦楚人也、著书十五篇，言道家之用，与孔子同时云。盖老子百有六十余岁、或言二百余岁，以其修道而养寿也。自孔子之后百二十九年，而史记周太史儋见秦献公曰：‘始秦与周合而离，离五百岁而复合，七十岁而霸王者出焉。’或曰：儋即老子。或曰：非也。世莫知其然否。”这表明司马迁本人也搞不清楚老聃、老莱子、太史儋三者是不是同一个人，这个问题迄今也无定论。\n老子其说博大精深，其主旨可归纳为“言道德之意”“道”、“德”两字是《道德经》中提纲挈领的两个概念。“道”其实就是“无”，但这个“无”并不是纯粹的空无、只是“无形”而己。在老子来“道”和“物”是不同的，“物”是有形的、可感知的，而“道”却是“无形”的是“视之不见”、“听之不闻”、“博之不得”的。所以，从“物”的观来看，“道”一方面是“无物”，另一方面“道之为物、惟恍惟惚。惚兮恍兮，其中有象；恍兮惚兮，其中有物。窃兮冥兮，其中有精；其精甚真、其中有信”。这个“恍惚窃冥”似物而非物。老子又说：道、“湛兮，似或存”、“绵绵若存”，显然、“道”是“有”中的“无”，又是“无”中的“有”，似物而非物。从“道”不可感知的角度来看，“道”是“不可诘”的，因而是“无名”的。但这个“道”却是真实存在的，老子说：“有物混成，先天地生。寂兮寥兮，独立而不改，周行而不殆，可以为天下母。吾不知其名，字之曰‘道’。”可见“道不过是强之名”而己。“道”是“无形”且“无名”的。\n由“无形无名”（否定性）所规定的“道”，先于天地而又产生于天地、万物，不可视听捉摸却又无所不在，是“天下母”、“天地根”、“万物之宗”。\n“道”的规定性，除了“无形、无名”而外，还有“无为、无欲”。老子说：“道常无为而不为”，“无为”和“有为”相对，“有为”是指着意的行为，也就是刻意强求的妄为。老子要求“辅万物之自然不敢为”、“莫之命而自然”，可见“无为”与“自然”可以融通，“道法自然”与“道常为而无不为”是相通的。由“无为”出发，老子提出了一系列处世和治国的道术，包括“无事”、“不欲”、“柔弱”、“处下”、不争”、“守雌”、不敢为天下先”等等。\n用“无名、无形、无为、无欲”一否定的概念来规定“道”，乃是老子一贯思想，老子说：“有生于无”又说“有无相生”，从表面看这两个命题岂不相互矛盾？其实，老子是以“无”（道）根本的同时不废“有”（物）。“无”（道）是“有”（物）的根本，“有”来自于“无”；但“有（形之物）”变通不居、其变化的归宿也将是“无”。因此，“有”的发展变化的规律是“周不殆”而不是“逝而返”。根据这一原理得知事物与其反面是可以相互转化的。因此，老子说：“祸兮福所依、福兮祸所伏”。说：“反者道之动”。有人说《道德经》暗契于《易》是很有道理的。\n老子所谓的“德”，是有得于“道”的意思，天、地、人、物有得于“道”即其“德”，且“德”就是“本性”。《道德经》中没有“性”字，其中的“德”有时可以看作“性”；另外，老子屡屡提及的“朴”、“素”和“赤子婴儿”相当于来诸子所讲的“性”。老子之所以用“朴”、“素”、“赤子婴儿”来表示“德”和“性”只是一象征意义。“朴”是指没有被斧斫的原木，“素”是指没有染色的原帛，“赤子婴儿”是指没有被矫情虚伪所掩的“人之初”、“善”的自然纯真本性，“恶”是天的是人为之“伪”，“德”来自于仁义的推行、法令的颁布、忠孝的提倡、智巧的运用。老子抨击道：“大道废、有大义；智慧出、有大伪；六亲不和、有孝慈；国家昏乱、有忠臣。”因此，要想恢复人的本真，须要“见素抱朴、少私寡欲”，就是说：“绝圣弃智、民利百倍；绝仁弃义、民复孝慈；绝巧弃利、盗贼无有。”也只有这样才能达到老子那种“小国寡民”的政治主张和伦理思想。\n以上只是对老子生平及其《道德经》思想根源的研判，见识浮浅。洒洒五千言的《道德经》共分八十一篇章，章章精悍、句句珠玑、一篇一个观点、篇篇都是处世格言，其旨要是让世人道法自然，从躁动不安的灵魂中解放出来，用一颗平静之心对待世间一切，时时、处处、事事都顺其自然，如若人人都将《道德经》烂熟于心、行成于思，这个纷繁复杂、乱象丛生社会里的矛盾，大部份都会得到化解，一个平和共荣新秩序的社会必然会呈现在人们面前。\n《道德经》是诸子百家思想宝库里的一枝璀璨奇葩，文约义丰、哲理深厚、博大精神、世人誉之为哲学诗，被尊崇为中国传统文化的“三玄”之一，在世界思想宝库中也占有重要一席、影响巨大，作为国学、龙的传人更要拜读并践行之，以传我中华民族之精神。\n三省轩主程康年\n二零零九年八月五日"},{"id":251,"title":"再  游  千  岛  湖","category":"散文","date":"二 零 一 七 年 国 庆 节 前 夜","body":"       时间过得真快，上次到千岛湖观光至今相隔已有十多年，第一次到千岛湖是2004年春天，那时还在工作岗位上，一次机会到浙江省考察学习市场监管经验，工作之余由浙江省局市场处和建德县工商局共同接待，同仁们的好客、热情、大方，至今历历在目，不能忘怀。\n\n       这次去千岛湖是女儿女婿休公休假陪着我和老伴及外孙于9月18日至21日共四天，自驾游。与第一次相比时空有了距离，随着改革的深入发展人文环境，各方面都发生了很大们的变化，简直就是日新月异。\n\n      千岛湖位于浙江省杭州市西郊淳安县境内，东距杭州129公里，西距著名旅游景点黄山140公里。浙江千岛湖内有翠岛1078座，与加拿大渥太华西南200多公里的金斯顿千岛湖和湖北黄石阳新仙湖岛并称“世界三大千岛湖”。\n\n      千岛湖即新安江水库，是因1959年我国自行设计、建造的第一座水电站，拦坝蓄水而形成的人工湖。水库坝高105米、水库长约150公里、最宽处10余公里、水最深处达100余米，正常水位情况下面积约580平方公里，比杭州西湖大108倍，蓄水量178亿立方米是西湖的3000多倍。\n\n       千岛湖以千岛、秀水、金腰带（岛屿与水相接处环绕着一层金黄色的土带、称之为“金腰带”）为主要特色景观，是我国首批命名的国家级风景名胜区之一，景区总面积982平方公里。千岛湖水明亮清澈，完全达到国家一级水体标准，不需要做任何处理即可饮用，获有“天下第一秀水”的赞誉。2001年被评为首批5A级旅游景区。景区开发出的景点共有十几个岛屿，主要的有：梅峰观岛、孔雀岛、龙山岛、清心岛、霭云洞、黄山尖、三潭岛、桂花岛、天池岛、月光岛、鱼乐岛……。三潭岛位于千岛湖中心湖区与东南湖区的交界处，距千岛湖镇约10公里，景区占地面积80公顷，主要有山寨遗风、娱乐参与、美食餐饮三大区块组成。山寨遗风区内设有民间用品陈列馆、山越文化馆，在这里可以观看到民间歌舞，感受吴越民俗文化。娱乐参与区设有鹿苑、蛇园、放生园、山涧溪流、晃晃桥、同心乐园。可以看到多种珍稀动物，与动物嬉戏交流。擂鼓观湖、临水而漁，让你耳目一新大饱眼福。桂花岛又名猴岛秋季可享受到满山桂花齐放，花香扑鼻的月宫胜景，平时可以看到聪明灵惠的生灵、十分逗人的猴戏表演，可以看到猴子跳水。蟠龙台、通天石门、玉兔蟾宫、岩桂问猴、鞋帽台、问字石、乌龙瀑布等绝美佳境。孔雀岛必然与观赏孔雀有关，可以欣赏到孔雀开屏、孔雀群飞，喂食拍照，又是另一番情趣。月光岛是千岛湖中心区一个最具诗情画意、韵味独特的景点、景区内情园、逸园、系园、心园、梦园五岛互连相通。情园以锁文化为主体不仅展示了大量的奇珍异锁，更多的是锁住了恋人、爱人，一生一世对感情的承诺。逸园是一个豪华休闲园、在这里啜茶品茗，恍若置身仙境，你可在此当一回没心没肺，思绪无遮拦、飘逸无止境的小神仙。系园是一个浪漫的攝影基地、在这里拍攝婚纱照可创作诸多精美小品，是诸多想结婚的恋人向往的处所。是足以让你终生可回味幸福浪漫的地方。心园是父母对子女表达美好祝福的地方，有望子成龙、望女成凤的都可在这里祈祷祝愿，而大多能心想事成。梦园是由状元群雕、状元祠、状元博物馆组成、展示中国丰富的状元文化，这里更是受到众多高考学子的青睐。月光岛以景为托、以情为线，融合国人的情感的创新设计是聚旅游人气的杰作。岛上还有鱼乐桥、幸运桥、状元桥等也是美不胜收。黄山尖位于南湖珍珠半岛，是较高的一处山峰，距千岛湖镇西园旅游码头5公里，游艇只需5、6分钟，山下有缆车直达山顶，登高远眺景区内碧波万顷、风光旖旎，岛屿千姿百态、疏密有致，宛如一串串珍珠洒落其中，“天下为公”几个字是由几个岛屿浑然天成活灵活现，字字清晰逼真、笔笔刚劲有力，是实属难得一见的奇观。即兴赋诗一首：　　　　\n                        \n                        《黄山尖顶纵览》\n　　　　\n　　　　　　　　千岛湖光添秋色，\n　　　　              万顷波碧迎宾客。\n　　　　              大把珍珠神工撒，\n　　　　              天下为公鬼斧刻。\n　　　　\n　　这次旅游是女儿女婿为我和老伴晚年生活幸福，而尽的孝心之举，订的是千岛湖洲际假日酒店、五星级，全是景观房，条件不错。临湖而居，湖区风光尽收眼底，真可以怡悦心情，又是另外一种享受。从酒店到黄山尖乘游艇单程大约需要20分钟左右。去千岛湖，往返途中所经都是江南丘陵地带，处处竹木成林、青山绿水。高速公路夾在其间，人在此行、身融其中、犹入仙境，也作诗一首颂之。\n\n　　　　              《过客途中观景》\n　　　　\n　　　　              千峰叠翠相抱连，\n　　　　              万壑似练任绵延。\n　　　　              瑰丽村舍如棋布，\n　　　　              人间仙境即眼前。\n　　　　\n　　　　       三   省   轩   主      程   康   年\n　　　　       二 零 一 七 年 国 庆 节 前 夜 完 稿"},{"id":252,"title":"嘉峪关市诚信单位展示长廊序言","category":"文","date":"二零零六年三月","body":"“诚实守信”是中华民族的优秀美德之一，在中华文明发展史上有着极其重要的作用。今天，历史已跨入了二十一世纪，新时代呼唤新精神。党中央、国务院顺天应人发出：打造诚信城市、构建和谐社会的伟大号召，给“诚信”赋寓了更多新时期的信息。因此，继承发扬中华民族优良传统的历史重任义不容辞的落在了我们肩上。今年，我市首次评选了一百五十个诚信单位并对其中最优秀的进行展示。这是为推进诚信嘉峪关、文明嘉峪关建设的尝试，热切期望有更多的单位踊跃参加这支队伍。让“诚信”的大旗引领我们前进；让“诚信”之花开遍雄关；让全市人民共同拥有一个经济繁荣、生活富裕、社会和谐、幸福美满的明天！\n中共嘉峪关市委宣传部、精神文明办公室\n嘉峪关市工商行政管理局、消费者协会\n二零零六年三月\n作者：三省轩主程康年"},{"id":253,"title":"在无锡的秋天里","category":"散文","date":"二零一五年立冬","body":"秋意\n左膝关节有炎症，做了关节镜微创手术，出院后在家静养多日，有些无聊、也有些急躁，为排解情绪、分散注意力，想随意写点东西。\n写点什么？无锡刚走出秋天、即将步入冬的世界，秋天好像仍在身边，就以《在无锡的秋天里》命题，审后似觉欠妥，此题太累赘、太古板、没有一点新意、估摸着也不会写出好的文字。省略掉题中的介词和定语写赤裸裸的《秋天》如何？但秋天在古今文人墨客的笔下也早已有秋风秋雨、秋山秋水、秋愁秋恋、秋哀秋怨、秋情秋绪等数不尽的文章。当然照文人章法、造糅拿揑、拼接粘贴、将众多华丽词藻堆砌一起，还是可以让《秋天》活色生香、具有诗情画意的。\n不懂了，非得让秋天一副面孔、一种色彩、一种情调吗？难道大兴安岭、漠北草原、青藏高原、苍山洱海、橘子洲头、名山大川、南疆北国的秋天没有自已的特色吗？\n秋天总是令人怀念的，与春天的浓艳热闹相比秋天是肃静寥寂的；与夏天的杂芜荗密相比秋天是简洁透明的；与冬天的空灵虚幻相比秋天是宽容充实的。无锡以往的与今年的秋天相比，由于气候条件不尽相同必有式微变化。无锡与某一特定外地的秋天相比，由于时间和地理位置的不同定会各具特色。没有时间线、没有座标轴的秋天，是千孔一面、似曾相识的秋天，是漂浮不定、没有根的秋天。无锡的秋天应该是有根有躯干骨骼的。\n退休后选择了在无锡这座陌生的城市里定居，虽然它距出生地太兴市曲霞镇直线距离不足五十公里，但从上世纪六十年代末离家、到现在折还回来己有四十余年、时间距离可谓久矣。无锡到第二故乡甘肃嘉峪关市相距有三千公里，空间距离可谓远矣。虽说定居实则上还没有度过一个完整的“年”，因此对无锡的秋天在时空概念上、没有任何经验积累，仅凭直觉去写《在无锡的秋天里》这个题目，写出来中不中意己无所谓只是练练笔而己。\n无锡今年与往年的秋天相比、与其它地方的秋天相比应该似同非同，既有相同之处、又有相异之别。“春风暖万众、夏云多奇峰、秋雨如丝网、冬雪秀青松”。秋天是一年四季中的第三季，农历二十四节气中的任何一个节气在全国都是同一天，但由于各地的纬度和海拔不同、立秋后入秋的时间是不一样的，气象学认为连续五天平均气温在以下才算进入秋天，嘉峪关入秋时无锡还可能在炎夏酷暑中。\n无锡的秋天是比较长的，严冬无几日，受几次寒潮相侵春天就来了。嘉峪关过了冬天即夏天、过了夏天即冬天，春秋两季很短暂，甚至可以忽略不计。无锡的秋天更有情韵，秋天的日子恬静柔美，有小桥流水、枯草斜阳，十月小阳春就是对无锡秋天的赞美，也是大自然赐给人们的一种享受。\n无锡的秋色是比较美的，进入中秋满城桂花飘香，接着火红的枫叶、不凋的青松和各种不知名的花草树木、层次不齐的显露出赤橙黄绿青蓝紫，将锡山惠山打扮得色彩斑斓。公园内的菊展刚过，一株历经千年沧桑的古银杏树，就吸引了不少游客来欣赏它落叶的曼妙轻舞、聆听它落叶的寂静无声，体味它落叶的叶落归根。片片树叶为感恩回报尽情地热吻着脚下的土地，将一片金黄奉献给自然、奉献给人们。\n梅园、蠡园、吟园、长广溪、鼋头、渤公岛处处风景如画，节假日总是人海如潮。\n无锡的秋岚是有特色的，嘉峪关那种秋高气爽、碧空如洗、粗犷豪放的秋天在这里是很少见的，当然类似无锡烟雨濛濛、连绵秋雨的天气在嘉峪关也是极难得的。\n无论是晴天还是阴天、站在阳台上向远处眺望总会有烟岚的，晴朗的天气它就像一层薄纱，将大地上的一切轻轻爱抚在怀中，让人感到大自然有宽阔无边温暖情怀；如是多云天气它就像一张帘，会看到山水村舍、小区楼群笼罩在轻轻的浮云和淡淡的烟靄之中、若隐若现变幻无穷，天与地没有了明显的界限，让人有山，天地一片朦胧的感觉；若是阴天它就像一幕墙、烟霭会吞掉大地上的一切，百米之外什么都看不见，会有一种扑朔迷离神秘莫测留给人们去探索去想象。如果没有烟岚，可能就没有江南，没有无锡的秋天。\n秋天是成熟的季节、收获的季节，“春种、夏长、秋收、冬藏。”是季节变迁的定律。无锡是鱼米之乡，物产十分丰富，时令果蔬不断，无锡大米、太湖三白、甘露青鱼，菊花湖蟹、远近闻名。无锡的秋天是可以吃到的，太湖大闸蟹的鲜美真是一绝，秋天在无锡是品尝各种美食的极好季节。同时，无锡的秋天也是可以闻到的，进入农历八月桂花盛开，香溢滿城，扑鼻而来，沁入心脾，令人心旷神怡，所以无锡被评为最适合人居的城市毫不夸张。\n曾看过一篇写秋的文章中有秋天收麦的场景，开始觉得匪夷所思，细想起来那种高纬度高海拔地区、播种的春小麦收获不就是在秋天么？如果说无锡秋天收麦那才是大笑话。秋天的同与不同一目了然，也蕴含着让人无尽遐想的情思。\n秋思\n无锡的秋雨是比较多的，张爱玲《秋天的雨》一文中这样写道：“雨，像银灰色黏霭蛛丝，织成一张轻柔的网，网住了整个秋的世界”。入秋后清凉的日子会接踵而来，伴随的绵绵秋雨也经常会不期而至，而且十天半月会赖着不走。秋天应该是清澈、透明、美好、充实的。景由象生、情有景生，身临其境、触景生情。那种凋零、失落、惆怅、忧郁的心绪有时也会随着连绵阴雨由然而生。\n果不然，从早晨起又是一场不停，敲到窗外空调盖上的滴嗒滴嗒声惹人心烦。随手翻开案头蒋捷（江苏宜兴人，宋咸淳十年进士，宋亡，深怀亡国之痛，隐居不士，专攻诗词）的《虞美人．听雨》“少年听雨歌楼上，红烛昏罗帐。壮年听雨客舟中，江阔云低、断雁叫西风。而今听雨僧庐下，鬓已星星也。悲欢离合总无情，一任階前点滴到天明。”读来很是喜欢，唯觉有些伤感更喜淡然随心。\n人生处处在听雨，少年时听雨尤如春雨声声急促，对前途有期望、对生活有目标，雨声里充满鸿鹄之志；壮年时听雨好像夏暴滴滴狂猛，人生奋力打拼、事业功成名就、雨声里夾着得意之神；老年时听雨不急不躁、慢条斯理，夕阳无限好只是近黄昏，雨声里蕴含垂暮之气。人生听雨好像雨的节奏是由慢到快、再由快到慢且越来越慢，慢到任它点滴到天明。我也在听雨。\n我在雨声里，情怀缱绻，觉着自己老了、真是老了，老是老矣只是微老，因为我的年龄还未达到现在中国男人岁的平均寿命。刚走完人生的大半，就像银杏叶子微微泛黄，黄得还不透还不厚，还没有在阳光下耀金、在秋风中飘落。\n秋雨凉夜，贸然细想，人生奋斗的轨迹不就像一颗子弹头的抛物线，由低往高、再由高往低的吗？人的一生就是在世间兜了一个圈子，归宿是从哪里来回哪里去，回到原点。\n离年的月日（因各种原因退休手续延迟了二十个月才办理完毕）彻底办完退休手续已有三年余，这期间读了点儿国学，回忆一些往事，检点一生秉持“清白做人”和“温良恭谦让”的为人处世之道，无怨无悔也无愧于天地良心。羁绊世人一辈子身外之物的“名利”，对我来说早束之高搁心中已荡然无存，我与“名利”之间的因缘也早已了结。唯有随季节更迭的时间不肯轻易舍去，牵掛一生的父母子女、兄弟姊妹情缘不能相负，还有相交一辈子的良师益友也不能随便忘记。\n雨还在轻轻的下，天已经渐渐的黑，秋自然慢慢的去，感谢时间送给我人生一掬凉，让静静的思绪开出一条回首的路。\n举杯祝福：为无锡的离秋壮行。也为我自已的渐渐老去端上一杯酒趁早祭典。\n三省轩主程康年\n二零一五年立冬"},{"id":254,"title":"学习实践科学发展观宣讲材料","category":"文","date":"省局宣讲稿","body":"3月份在全省各市（州）己全面铺开的第二批“学习实践科学发展观活动”、工商系统的同志们也在此列，为了将省局机关第一批学习实践的成果弘扬光大、同时结合工商行政管理工作的特点、引导全系统将这次学习实践科学发展观的目标要求落到实处，下面我将个人学习实践的点滴心得体会与大家互相交流、以期抛砖引玉。\n一、中国特色社会主义理论体系是马克思主义中\n国化的最新理论成果。\n（一）、马克思主义理论体系的基本内容\n1、什么是马克思主义。\n在这里让我们重温一下什么是马克思主义。马克思主义是无产阶级的科学思想、是共产主义运动的旗帜。完整的马克思主义体系包括三大组成部分：《哲学》《政治经济学》《科学社会主义》\n（1）、《哲学》、哲学是世界观或宇宙观的学问，（四方上下为宇、指的是空间、往来古今为宙、指的是时间。）它研究的对象是人们对整个世界、其中包括自然界、人类社会和人的思维本质的根本观点和看法。是从各门具体科学中抽象概括出来的一般观点、原则，是从总体上把握世界最一般的规律。马克思主义哲学认为：“世界是物质的、物质是运动的、运动是有规律的、规律是可以把握的。”认为世界万物是有序的。\n马克思主义哲学是迄今为止人类哲学思想和科学知识发展的最高成果，是唯一科学的世界观，它的主要内容有：三大规律（对立统一规律、质量互变规律、否定之否定规律）五大范畴（本质和现象、形式和内容、原因和结果、必然性和偶然性、可能性和现实性）\n马克思主义哲学是无产阶级的科学世界观和方法论，它为无产阶级提供了观察和处理问题的立场、观点、方法，是无产阶级认识世界、改造世界锐利的思想武器。\n（2）、《政治经济学》经济学研究的对象是物质资料生产的科学。政治经济学研究的对象是物质资料生产统一体中、生产关系及其发展规律的科学，它是通过人类社会各个发展阶段生产、分配、交换、消费的过程来揭示生产力与生产关系、上层建筑与经济基础矛盾运动的规律、从而使人们认识了价值与剩余价值、认识了剥削的实质。\n（3）、《科学社会主义》研究的对象是人类社会发展的一般规律。科学社会主义是人类发展的高级阶段也是人类社会发展的终极目标，它包括三个方面的含义，一是指共产主义的思想体系。二是指共产主义的社会制度。三是指共产主义运动。（社会主义是共产主义的初级阶段）\n2、马克思主义产生有着深刻的社会历史原因、理论来源和自然科学前提。\n（1）、马克思主义产生的社会历史原因。\n十九世纪初期，机器大工业生产在西欧各国发展起来，资本主义所固有的各种矛盾越来越尖锐，无产阶级反对资产阶级的斗争进入了一个新的阶段。从十九世纪三十年代起欧洲一些国家的无产阶级已经在政治上表现了独立行动，例如：法国里昂工人起义、英国的宪章运动、德国的西里西亚纺织工人起义等。为了推翻资本主义旧世界建立新世界，无产阶级迫切需要有自己的哲学作为认识世界和改造世界的思想武器。正如马克思所说：“哲学把无产阶级当作自己的物质武器。同样地，无产阶级也把哲学当作自己的精神武器。”由于当时的英国和法国已经完成了资产阶级革命，而德国正处于资产阶级革命的前夕、德国便成了当时革命运动的中心，在德国资产阶级革命中无产阶级作为独立的政治力量发挥了创造历史的伟大作用。在这样的历史条件下马克思、恩格斯亲自参加并领导了当时的工人运动，在实践中他们科学地总结了革命斗争的经验，创立了马克思主义及其哲学。\n（2）、马克思主义的理论来源。\n马克思主义理论是批判继承人类历史上全部优秀思想的成果。特别是批判地继承和改造了德国古典哲学、（德国古典哲学代表人物黑格尔的辩证法和费尔巴哈的唯物主义是马克思主义哲学理论的直接来源，马克思、恩格斯直接抛弃了黑格尔的唯心主义体系、吸收了他辩证法的“合理内核”，又批判了费尔巴哈的形而上学和历史唯心主义吸收了他的唯物主义基本思想，经过批判和改造把唯物主义同辩证法有机的结合起来。）英国古典政治经济学、（英国古典政治经济学奠定了劳动价值论的基础，说明了剩余价值论的一些基本形式，并且对资本主义社会各个阶级和阶级对立作过经济的分析。英、法空想社会主义（英国和法国空想社会主义揭露和批判了资本主义的罪恶、指出了资本主义并不是永恒的制度，对于未来理想作了描述，主张消灭私有财产制度和劳动雇佣制度，消灭城乡对立和工农差别等等。）这些是马克思主义理论产生发展的基础，对马克思主义的形成都发挥了重大作用。\n（3）、马克思主义理论的自然科学前提。\n马克思主义是放之四海而皆准的真理，而又不是包罗万象的“绝对真理”的体系，它只是在己有科学成果的基础上对自然界、人类社会和思维本质及其发展普遍规律进行了总结和说明。它把各个领域的特殊规律的研究留给了各门具体科学，它既是自然科学和社会科学的最高概括、是科学的世界观，又反过来成为指导科学研究和实践活动的方法，是科学世界观和方法论的统一。\n（4）、马克思主义是与时俱进、不断发展的马克思主义。\n马克思主义并不是形而上学的教条主义，马克思主义从来都是在批判中发展、在斗争中前进的，马克思主义任何时候都不能停步不前、《共产党宣言》发表一百六十年的实践证明，马克思主义只有与本国国情相结合、与时代发展同进步、与人民群众共命运，才能焕发出强大的生命力、创造力、感召力。在当代要坚持发展马克思主义、就必须回答世界无产阶级和革命人民面临的新的重大课题。\n（二）、中国特色杜会主义理论体系及其内涵。\n马克思主义是无产阶级革命政党制定正确政治纲领和确立科学的思想路线、方针、政策，建立科学的领导方法、工作方法、和发扬优良传统和作风的基础。\n1、马克思主义是中国共产党的行动指南。\n中国共产党是无产阶级的政党，是工人阶级的先锋队，她代表了中国最广大人民群众的根本利益，中国共产党人从她诞生的那一天起、就把马克主义当作自己的指导思想和行动指南。中国共产党在长期领导中国各族人民的革命和建设中、经过几代人的探索和实践，认真总结正反两方面的经验得出了这样一条结论就是：“把马列主义的普遍真理与中国革命的具体实际相结合。”如果遵循了这一条理论联系实际、实事求是的思想路线，中国的革命和建设就会取得胜利、反之就会受到挫折。\n从1840年鸦片战争开始，中国的近代史上许多仁人志士都在寻求救国救民的真理、像太平天国运动、义和团运动、戊戌变法等等，最后都是以失败而告终，因为他们都没有革命的理论做指导。\n近一个世纪以来，我国先后发生了三次伟大革命。第一次是孙中山先生领导的辛亥革命，推翻了统治中国几千年的君主专制制度，为中国的进步打开了闸门。第二次是中国共产党领导的新民主主义革命和社会主义革命，推翻了帝国主义、封建主义、官僚资本主义在中国的统治，建立了新中国，确立了社会主义基本制度，为当代中国一切发展进步奠定了根本政治前提和制度基础。第三次革命是我们党领导的改革开放这场新的伟大革命，引领中国人民走上了中国特色社会主义广阔道路，迎来了中华民族伟大复兴的光明前景。\n2、中国特色社会主义理论体系的提出。\n在社会主义革命和建设阶段我们党曾走过一段弯路，但在党的十一届三中全会以后迅速得到了纠正，找到了一条适合我国国情、具有中国特色的社会主道路，早在1979年3月邓小平同志就提出：我们党要在中国的建设问题上要像毛泽东同志当年领导我们党在中国革命问题上一样完成开创自己道路的任务。他说：“过去搞革命，要适合中国情况，走毛泽东同志开辟的农村包围城市的道路，现在搞建设，也要适合中国情况，走出一条中国式的现代化道路。1980年1月他提出，在发展经济方面，要“寻找一条合乎中国实际的，能够快一点、省一点的道路”。1982年9月，在党的十二大开幕词中，他又提出“走自己的道路，建设有中国特色的社会主义”。同以毛泽东同志为代表的中国共产党人一样，经过反复探索，在总结正反两方面经验的基础上，才找到中国自己的革命道路一样，以邓小平同志为代表的中国共产党人，也是在总结建国以来正反两方面经验的基础上，在研究和借鉴国际经验的基础上，在改革开放崭新的实践中，才找到中国自己的建设道路。这是因为，在中国这样落后的东方大国无论革命和建设都是史无前例、前无古人的，都是马克思主义发展的新课题，指望着照搬书本、照搬外国，是根本行不通的，必须从我们自己的国情出发，把马克思主义的基本原理同中国革命的具体实际相结合，在实践中开辟具有中国特色的革命和建设的道路。\n3、中国特色社会主义理论体系的主要内容。\n党的十七大报告指出，在新时期，“我们党坚持马克思主义的思想路线，不断探索和回答什么是社会主义、怎样建设社会主义，建设什么样的党、怎样建设党，实行什么样的发展、怎样发展等重大和实际问题，不断推进马克思主义中国化”。党的十一届三中全会以来富于理论创新的中国共产党人在三十年的改革开放实践中相继创立了邓小平理论、“三个代表”重要思想、科学发展观等重大战略思想，党的十七大报告中将这些重大战略思想总结归纳为中国特色社会主义理论体系。这说明了中国特色社会主义理论体系是与马克思主义一脉相承的，是马克思主义中国化的最新成果。\n（1）、邓小平理论\n邓小平理论的内容很丰富，所阐述中国特色内容的主要有：（ａ）社会主义初级阶段论、（1987年8月29日《一切从社会主义初级阶段的实际出发》一文中说：社会主义本身是共产主义的初级阶段，而我们中国又处在社会主义的初级阶段，就是不发达的阶段。一切都要从这个实际出发，根据这个实际来制订规划。）（ｂ）社会主义市场经济论、（1990年12月24日在《善于利用时机解决发展问题》一文中说：我们必须从理论上搞懂，资本主义与社会主义的区分不在于是计划还是市场这样的问题。社会主义也有市场经济，资本主义也有计划控制。1992年1月18日至2月21日在《武昌、深圳、珠海、上海等地的谈话要点》中说：计划多一点还是市场多一点，不是社会主义与资本主义的本质区别。计划经济不等于社会主义，资本主义也有计划；市场经济不等于资本主义，社会主义也有市场。计划和市场都是经济手段。）（Ｃ）社会主义本质论（1987年4月26《社会主义必须摆脱贫穷》一文中讲：搞社会主义，一定要使生产力发达，贫穷不是社会主义，要建设对资本主义具有优越性的社会主义，首先必须摆脱贫穷。1992年1月18日至2月21日《在武昌、深圳、珠海、上海等地的谈话要点》中说：社会主义的本质、是解放生产力，发展生产力，消灭剥削，消灭两极分化，最终达到共同富裕。）以及党在社会主义初级阶段“一个中心、两个基本点”的基本路线。（一个中心：以经济建设为中心，两个基本点：对内改革、对外开放。）\n邓小平理论的伟大历史功绩在于、正确界定了我国现实社会的历史方位和主要矛盾，正面回答了什么是社会主义、怎样建设社会主义的问题，明确提出了党在社会主义初级阶段的兴国之要就是要以经济建设为中心，立国之本就是要坚持四项基本原则，强国之路就是要坚持对内改革、对外开放，使困惑在社会主义基本制度建立后如何去建设社会主义的问题得到了破解，找到了一条适合中国国情、具有中国特色社会主义的道路。\n（2）、“三个代表”重要思想\n以江泽民同志提出的“三个代表”重要思想为标志，是世纪之交的中国共产党人，在深刻认识和把握新的历史条件下世情、国情、党情发生的变化，进一步回答什么是社会主义、怎样建设社会主义问题的同时，又创造性地回答了建设什么样的党、怎样建设党的问题，从而正确界定了我们党的历史地位，并从代表中国先进生产力的发展要求、中国先进文化的前进方向和中国人民的根本利益的高度，提出了坚持和发展党的先进性、提高党的执政能力和立党之本、执政之基、力量之源这一系列根本性的问题，充分反映了我们党更加自觉地从新的历史高度来认识自己、完善自己、全面加强自己的新境界。\n江泽民同志执政十三年中的重大历史贡献，一是上世纪八十年代末期，共产主义运动受到强烈“政治地震”、使前苏联为首的许多社会主义国家都轰然坍塌、纷纷改旗易帜，国际共产主义运动受到了重创。在中国，江泽民同志受任于危难之时，坚决反对在中国全盘西化、坚定不移的坚持党的“一个中心、两个基本点”的基本路线、坚定不移的坚持四项基本原则（坚持社会主义道路，坚持人民民主专政，坚持党的领导，坚持马列主义、毛泽东思想。）使中国共产党几代人创建的社会主义伟大事业岿然不动。二是党的十一届三中全会以后邓小平同志提出了社会主义市场经济理论，不断得到了探索和实践，江泽民同志积极推进市场经济体制改革，实行了由社会主义计划经济体制向社会主义市场经济体制的历史性转变，促进了生产力的发展。同时也将理论变为现实。三是江泽民同志提出的“三个代表”重要思想，解决了我们党由计划经济体制时期执政党的领导方式过渡到市场经济体制时期执政党的新的领导方式，提高了党的执政能力、保持了党的先进性，使我们党的执政地位更加巩固。\n（3）、科学发展观的战略思想\n党的十一届三中全会后，中国式的现代化，“三步走”的战略目标，统筹城乡经济社会发展，坚持走生产发展、生活富裕、生态良好的文明发展道路，构建社会主义和谐社会、让人民共享经济改革成果等战略思想的提出都具有科学发展的含义，但把它作为科学发展观重大战略思想提出、是党的十六大以后以胡锦涛同志为总书记的党中央，从我国社会主义初级阶段基本国情出发，科学分析我国在新的历史起点上发展阶段性的特征，根据加快社会主义现代化、全面推进小康社会建设的新要求而确定的发展方向。\n科学发展观战略思想提出的深远历史意义和重大现实意义在于、把发展的问题提到体现以人为本、体现社会公平正义、体现人和社会的全面发展以及资源环境的可持续发展的高度，明确地提出了发展之本、发展方式、发展规律一系列根本问题，从而解决了我国社会主义现阶段实现什么样的发展、怎样发展的问题。\n4、中国特色社会主义理论体系基本特点小结\n中国特色社会主义理论体系归结起来有八个方面一、理论体系的起点是提出什么是社会主义、怎样建设社会主义，建设什么样的党、怎样建设党，实现什么样的发展、怎么发展等基本问题。二、理论体系的主题是发展。三、理论体系的主线是改革开放。四、理论体系的精髓是解放思想。五、理论体系的核心是以人为本。六、理论体系的本质是马克思主义中国化。七、理论体系的关键是党的领导。八、理论体系的方向是开放和发展。\n（三）、科学发展观的深刻内涵\n科学发展观的内涵十分丰富、概括起来有四个方面，第一、科学发展观的第一要义是发展。第二、科学发展观的核心是以人为本。第三、科学发展观的基本要求是全面协调可持续。第四、科学发展观的基本方法是统筹兼顾。\n1、科学发展观的第一要义是发展。马克思主义认为：“一定物质财富是一切人类生存的第一个前提，即一切社会历史的第一个前提”。毛泽东同志指出：“社会主义革命的目的是为了解放生产力”。当前，我国社会主义初级阶段的主要矛盾仍然是：落后的生产力与不断满足人民日益增长的物质文化需要。解决好这一主要矛盾是我们党义不容辞的使命。邓小平同志指出：“中国解决所有问题的关键是要靠自己的发展”。“发展才是硬道理”。江泽民同志也指出：“党要承担起推动中国社会进步的责任，必须始终紧紧抓住发展这个执政兴国的第一要务，把坚持党的先进性和发挥社会主义优越性，落实到发展先进生产力、发展先进文化、实现最广大人民利益上来，推动社会全面进步，促进人的全面发展”。改革三十年的实践证明，坚持以发展为主题，用发展的眼光、发展的思路、发展的方法解决前进中的问题，就能把中国特色社会主事业不断推向前进。（例：我国国内生产总值从2002年的12万多亿元人民币增长到2007年的25万多亿元人民币，连续五年两位数的增长。国家财政收入从2002年的1.89万亿元人民币增长到2007年的5.13万亿元人民币，年均增长22.1%。进出口贸易总额从2002年的6000多亿美元增长到2007年的2.17万亿美元，年均增长28.5%，2008年我国的经济总量已在美国、日本、德国之后排世界第四位，ＧＤＰ已超过30万亿元人民币折合美元已有4万多亿、人均已超过3000美元。去年三驾马车拉动经济增长的贡献分别是：投资17万亿元同比增长了25%，消费108488亿元、同比增长21.6%，进出口贸易总额己达2.56万亿美元、贸易顺差2900亿美元，2003年至2007年的五年间我国的消费需求在ＧＤＰ中的贡献率己从35.3%上升到39.4%平均每年上升13.5%。受国际金融危机的影响今年的发展速度肯定会有所下降、但党中央未雨绸缪、在今年的中央经济工作会议上己制定出积极的财政政策和宽松的金融政策并制定了拉动内需的十项措施来应对金融危机如：实行结构性减税、家电下乡给农民13%的补贴、大幅度增加对“三农”的投入，继续加大对就业、教育、医疗、社会保障的支出力度，加强基础设施建设的投入，振兴汽车工业计划等等，并确定今年的经济增速仍保持到8%，预计今年的经济总量就会上升到世界第三位，我国与世界发达国家水平的距离越来越接近，有些经济学家认为中国改革发展三十年的速度相当于欧美等发达国家一百年的速度。所以，有些别有用心的人就到处散布“中国威胁论”。）\n要实现全面建设小康社会和现代化建设第三步战略目标，进一步提高人民物质文化生活水平要靠发展；增强我国综合国力、实现中华民族的伟大复兴要靠发展；坚持“一国两制”方针、实现祖国完全统一要靠发展；履行维护世界和平、促进共同发展的责任，在国际局势中立于不败之地要靠发展；解决我国经济和社会生活中的各种矛盾、维护社会稳定要靠发展；增强国防实力、维护国家安全要靠发展；解决人们的思想认识问题、说服那些不相信社会主义的人、坚定对社会主义祖国未来前途信念和信心，最终也要靠发展。\n2、科学发展观的核心是以人为本。以人为本是历史唯物主义的一项基本原则，中国古已有之。我国古代的思想家早就提出“民惟邦本、本固邦宁”、“天地之间、莫贵于人”、“水能载舟、也能复舟”等价值观念、强调要惠民、裕民、养民、利民。马克思主义在阐明人类社会发展规律的同时就认为人民群众是生产力中最活跃、最革命的因素，是推动社会发展的决定性力量、是历史的创造者。\n以人为本之所以是科学发展观的核心，就是因为我们党从执政党的宗旨和理念出发，把党全心全意为人民服务的根本宗旨与立党为公、执法为民的本质紧密结合起来，始终坚持人民的利益高于一切，坚持把落实好、维护好、发展好人民群众的根本利益作为一切工作的出发点和落脚点。同时，回答和解决了为谁发展、靠谁发展、发展成果如何分配等一些发展观的基本问题，明确指出了发展是为了人民、发展要依靠人民、发展成果要由人民共享。只有这样才能最充分地调动人民群众的积极性、主动性、创造性，最大限度的集中全社会、全民族的智慧与力量投身中国特色社会主义伟大事业。所以胡锦涛同志反复强调要求全党同志一定要坚持以人为本，把“权为民所用、情为民所系、利为民所谋”。落实到各级领导干部的思想和行动中去，落实到关心群众生产生活的各项工作中去。\n3、科学发展观的基本要求是全面协调可持续。科学发展观所追求的全面发展，就是要按照中国特色社会主义事业总体布局推进经济、政治、文化、社会的建设，这四个方面缺一不可，最终目的就是在实现经济社会全面进步的基础上实现人的全面发展。科学发展观的协调发展，是指各个方面的发展要相适应。就是要统筹城乡发展、统筹区域发展、统筹经济社会发展、统筹人与自然和谐发展、统筹国内发展和对外开放、统筹中央和地方关系、统筹个人利益和集体利益、统筹国内国际两个大局。确保生产关系和生产力、上层建筑与经济基础之间的相互协调。科学发展观的可持续发展是讲人类的延续和代传是社会发展的基本前提和要求，每一代人的发展都要以高度负责的态度给下一代留下更好的生存发展空间和条件、不能搞竭泽而鱼的发展。因此，我们推进发展就必须充分考虑资源和环境的承受能力，既要重视经济增长的指标又要重视环境指标，既要考虑当前的发展又要考虑未来的发展，既要满足人民群众现实的物质文化需要又要为子孙后代留下好的发展条件。就是要走一条生态良好、资源节约，生产发展、速度高效，社会和谐、生活富裕，经济社会永续发展的道路。\n4、科学发展观的根本方法是统筹兼顾。统筹兼顾是科学的方法论，我们做任何事情都要善于抓住事物的主要矛盾。只要学会总揽全局、统筹规划、抓住要害、突破重点“牵牛鼻子”的工作方法，就会得心应手的解决好一切问题。八个方面的统筹发展是贯彻落实科学发展观的切入点和重要途径。\n------统筹城乡发展，就是要坚决贯彻工业反哺农业，城市支持农村的方针，逐步改变城乡二元化结构，加快社会主义新农村建设，着力解决好“三农”问题，逐步缩小城乡发展差距，推动农村经济社会全面发展，形成城乡经济社会一体化新格局。（改革开放三十年来计划经济时代的农产品价格剪刀差仍然没有得到很好的解决，农民增产不增收、2007年底我省城市人口平均收入为11000元、农村人口平均收入仅2000元。改革开放三十年20%的城市人口享受了80%的公共事业投入，80%的农村人口只享受到了20%的公共事业投入。从目前的状况看城乡差别不但没有缩小而且有拉大的趋势。）\n------统筹区域发展，就是要继续实施区域发展总体战略，深入推进西部大开发，全面振兴东北老工业基地，大力促进中部地区崛起，积极支持东部地区率先发展，逐步扭转区域发展差距拉大的趋势，形成东中西相互促进、优势互补，共同发展的新格局。（2008年我省的ＧＤＰ总量是3100亿元人民币、大口径财政470亿元，地方一般性预算收入260亿元，2008年实际支出935亿元、其中中央财政转移支付近680亿元、由此可见中央对我省的支持力度。）\n------统筹经济社会发展，就要在大力推进经济发展的同时，更加注重社会发展，加快科技、教育、文化、卫生、体育、社会保障、社会管理等社会事业发展，不断满足人民群众在精神文化、健康安全等方面的需求，（这次十一届全国人大二次会议上通过了《食品安全法》说明食品安全己关乎到重大民生问题。食品安全监管是工商行政管理内容的重中之重、责任重于泰山，我们一定要履行好法律赋予的职能、抓好监管工作。）提高人的素质和人力资源能力，实行经济发展与社会进步的有机统一。\n------统筹人与自然和谐发展，就要高度重视资源和生态环境问题，处理好经济建设、人口增长、与资源利用、生态环境保护的关系，增强可持续发展的能力，走生产发明、生活富裕、生态良好的文明发展之路。（现实生活中有好多地方政府和企业的领导只片面追求ＧＤＰ增长速度和企业利润、以牺牲环境为代价换来经济发展，这种经济增长的风采实际上是血染的风采，有些经济发达地区经济发展了但环境污染了、有的地方甚至连一杯干净能喝的水都没有，现在讲科学发展就是要讲转变经济增长方式、要从外延扩大再生产转换到内涵扩大再生产；就是要调整产业结构、大力发展第三产业；就是要自主创新、增加工业产品的科技含量；就是要搞循环经济，走节约发展、清洁发展、安全发展、和谐发展、和平发展的道路；就是要把节能减排作为考核经济发展的重要指标，再不能以拼资源拼环境来求发展。）\n------统筹国内发展和对外开放，就是要处理好国内发展与国际环境的关系，既利用好外部的有利条件，又发挥好我们自身的优势，利用国际国内两个市场、两种资源，立足于扩大内需、把扩大内需与扩大外需、利用外资与利用内资结合起来，努力实现国内发展与对外开放相协调。（今年尽管全球经济形势日趋恶化、但金融危机也给我国带来了机遇，由于受金融危机的冲击，国外大宗能源产品价格跌入低谷，一些资源性企业面临资金短缺等经营困局，急需资金注入和支持。此时、无论是参股或收购成本都比较低、政府干预也相对较少，这就为我国获取某些战略资源提供了难得的机会。今年2月12日中铝斥资195亿美元收购力拓股权、2月16日五矿集团斥资17亿美元全资收购澳锌矿公司，2月17日中俄两国签署250亿美元的“贷款换石油协议”，2月20日中古两国签署100亿美元的“贷款换石油协议”，仅2月份在海外能源投资就达到630亿美元，这些都彰显了我国面对“后危机时代”的战略决策。）\n------统筹中央和地方关系，就是要尊重基层群众的首创精神，正确处理好中央与地方的关系，合理划分经济社会事务管理的权限和职责，（政府的主要职能：调控宏观经济、管理社会事务、监管市场秩序、提供公共服务。）做到事权与财权相匹配、权力与责任相一致，既维护中央的统一领导，又更好地发挥地方积极性。\n------统筹个人利益和集体利益、局部利益和整体利益、当前利益和长远利益，就要坚持从全体人民的整体利益、长远利益和根本利益出发，做到个人利益服从集体利益、局部利益服从全局利益、当前利益服从长远利益，既切实维护好最广大人民群众的根本利益，又着力解决好人民最关心、最直接、最现实的利益问题。（在这次学习实践科学发展观活动中，我们每个同志都要做到顾大局、识大体，正确摆正位置、处理好个人利益与集体利益、局部利益与全局利益、当前利益与长远利益的关系。）\n------统筹国内国际两个大局，就要深刻认识国内大局和国际大局、内政和外交的紧密联系、善于从国际形势和国际条件的发展变化中把握发展方向、用好发展机遇、创造发展条件、把握发展全局，做到审时度势、因势利导、内外兼顾、趋利避害，为我国发展营造良好的国际环境。\n二、开展“学习、实践科学发展观活动”的重大意义。\n伟大的实践产生伟大的理论、伟大的理论引领伟大的实践。一个先进的政党，需要一个与时俱进的科学理论来武装，一项伟大的事业需一个不断发展创新的科学理论来指导。\n去年，胡锦涛总书记在全党深入学习实践科学发展观活动动员大会暨省部级主要领导干部专题研讨班开班式上发表重要讲话时指出，当前党的执政能力与新形势新任务的要求还不完全适应、不完全符合，一些党员、干部的思想观念、能力素质与党的先进性要求还不完全适应、不完全符合，一些基层党组织的管理手段和创新能力与经济社会发展任务还不完全适应、不完全符合，一些地方党的组织、领导班子、领导干部党性党风党纪方面还存在这样那样的问题。有一些干部缺乏宗旨意识、大局意识、责任意识、作风飘浮、管理松弛、工作不扎实，有的甚至对群众的呼声和疾苦置若罔闻，对关系群众生命安全这样的重大问题麻木不仁。\n改革开放以来，我们党高度重视自身建设，坚持党要管党、从严治党、全面推进党的建设新的伟大工程，推动党的建设在不断改进中得到加强。同时，我们必须清醒地看到，随着改革开放和社会主义市场经济的不断发展，随着党执政时间的不断增长和党员队伍的变化，党的自身建设面临许多新课题、新考验，党面临的执政考验、改革开放考验、发展社会主义市场经济考验将是长期的复杂的，党要管党、从严治党的任务比过去任何时候都要繁重。只有按照科学发展观的要求，切实加强和改进党的自身建设，才能为科学发展提供可靠的政治和组织保障，才能使我们党始终保持蓬勃生机和旺盛活力。因此，我们可以从以下几个方面去理解深入开展学习实践科学发展观的重大意义。\n1、科学发展观是加强党的思想建设的锐利武器。科学发展观是中国特色社会主义理论体系的一个重要组成部分，是对党的三代中央领导集体关于发展的重要思想的继承和发展，是马克思列宁主义、毛泽东思想、邓小平理论“三个代表”重要思想一脉相承又与时俱进的科学理论，是我国经济社会发展的指导方针，是发展中国特色社会主义必须坚持和贯彻的重大战略思想。只有坚持用马克思主义中国化最新成果武装全党，我们才能进一步引导广大党员、干部特别是领导干部自觉用发展着的马克思主义指导客观世界和主观世界的改造，不断提高运用科学理论分析和解决实际问题的能力。\n2、科学发展观是提高党的执政能力的重要保证。在全党开展深入学习实践科学发展观活动，是党的十七大作出的战略决策，是用中国特色社会主义理论体系武装全党的重大举措，是“三个代表”重要思想学习教育活动和保持共产党员先进性教育活动的继续，是深入推进改革开放、推动经济社会又好又快发展、促进社会和谐稳定的迫切需要，是提高党执政能力、保持和发扬党的先进性的必然要求。\n3、科学发展观是全面推进小康建设的迫切需要。在全党开展深入学习实践科学发展观活动，就是要在世情、国情、党情发生深刻变化的条件下，更好地用中国特色社会主义理论体系这一马克思主义中国化最新成果武装和统一全党思想，动员全党更好地为实现党的十七大和十七届三中全会提出的宏伟蓝图和行动纲领而奋斗。深入学习实践科学发展观，是在深刻变化的国际环境中推动我国发展的迫切需要，是落实实现全面建设小康社会的需要，是以改革创新精神推进党的建设新的伟大工程的迫切需要。\n三、开展学习实践科学发展观活动的目标、要求和方法。\n（一）、目标。\n这次学习实践科学发展观活动的总体目标是，全面贯彻党的十七大和十七届三中全会精神，高举中国特色社会主义旗帜，以邓小平理论和“三个代表”重要思想为指导，组织广大党员特别是各级领导班子和党员领导干部深入学习实践科学发展观。学习就是要提高认识、统一思想，实践就是要付诸行动、见到实效。紧紧围绕“党员干部受教育、科学发展上水平、人民群众得实惠”，进一步解放思想、实事求是、改革创新，切实增强贯彻落实科学发展观的自觉性和坚定性，着力转变不适应、不符合科学发展要求的思想观念；着力解决影响和制约科学发展的突出问题、以及党员干部党性党风党纪方面群众反映强烈的突出问题；着力构建有利于科学发展的体制机制，提高领导科学发展、促进社会和谐的能力，使党的工作和党的建设更加符合科学发展观的要求。最终可以用四句话概括：提高思想认识、解决突出问题、创新体制机制、促进科学发展。\n（二）、要求。\n为了把这次学习实践科学发展观活动落到实处，一是要加强组织领导。各级党委（党组）要切实负起责任，特别是“一把手”要进一步履行好第一责任人的职责、不仅要带头揭摆查找自身存在的问题更要把这项工作真正抓到手上、一抓到底、抓出成效。同时要正确处理好学习实践活动和当前各项工作的关系、统筹兼顾、合理安排、相互协调、合理推进，要把学习实践科学发展观的成果落实在各项工作中。二是要真正把群众发动起来。要坚持走群众路线、查找突出问题要依靠群众、解决突出问题要请教于民。最终要以人民群众满意不满意作为评判这次学习实践科学发展观成果的标准。三是要防止形式主义、短期行为、克服被动应付思想、这次学习实践科学发展观活动时间长、内容多、任务重、一共划有三个阶段十一个环节，首要环节是制定整体学习实践方案、第一阶段学习调研中的三个环节，一是抓学习培训、要精读细读中央领导的重要讲话和有关文件精神真正认识搞好学习实践活动的意义。二是深入调研、吃透情况、摸准本单位本部门存在“不符合”“不适应”的主要问题。三是开展讨论查找问题存在的主客观原因。第二阶段分析检查中的三个环节，一是抓好领导班子的民主生活会、民主生活会一定要联系个人的思想实际绝不能开成工作总结会。二是形成领导班子分析检查报告。三是组织群众评议。第三阶段整改落实中的三个环节，一是制定整改落实方案。二是集中解决突出问题。三是建立长效机制。最后一个环节是进行群众满意度测评。这十一个环节，环环紧扣都是规定动作、一点都不能少。开展学习实践科学发展观活动是全党政治生活中的一件大事，我们各级党的组织都要加强政治责任感、引起高度重视、精心组织、扎实推进，在这一问题上要敢于动真格、善于出实招，从事关民生的具体问题入手、多办群众看得见摸得着的实事，使学习实践科学发展观的过程成为推动科学发展的过程、成为不断为民造福的过程、成为创新体制建立科学合理长效机制的过程。\n（三）、方法。\n在这次学习实践科学发展观活动中一定要把握好中央提出的四条原则，坚持解放思想、突出实践特色、贯彻群众路线、正面教育为主。要紧密联系本单位的实际，具体做到“四个结合”。\n1、要与贯彻落实党的十七大和十七届三中全会精神结合起来。党的十七大报告中把中国特色社会主义一面旗帜、一条道路、一个理论体系、“三个一”与“四个坚定不移”即：坚定不移地继续解放思想，坚定不移地坚持改革开放，坚定不移地推动科学发展，坚定不移地全面建设小康社会。并认真的进行了阐述和相互贯通、构成了鲜明突出的主题：高举中国特色社会主义伟大旗帜，以邓小平理论和“三个代表”重要思想为指导，深入贯彻落实科学发展观，继续解放思想，坚持改革开放，推动科学发展，促进社会和谐，为夺取全面建设小康社会新胜利而奋斗。确定这样的主题，就是要向党内外、国内外宣示，我们党将举什么旗、走什么路、以什么样的精神状态、朝着什么样的发展目标继续前进。\n2、要与贯彻落实中央和省上的经济工作会议精神结合起来。中央经济工作会议主要有五个方面的内容：（1）、加强和改善宏观调控，实施积极的财政政策和适度宽松的货币政策。（今年扩大财政赤字8000亿元其中地方2000亿元，2008年的赤字仅1100多亿元）（2）、巩固和发展农业和农村经济好形势，保障农产品有效供给、促进农民持续增收。（3）、加快发展方式转变，推进经济结构战略性调整。（4）、深化改革开放、完善有利于科学发展的体制机制。（5）、着力解决涉及群众利益的难点热点问题、切实维护社会稳定。这次第十一届全国人大二次会议上又提出：“扩内需、保增长，调结构、上水平，抓改革、增活力，重民生、促和谐。”二十四字方针，进一步明确了今年的发展大计。\n做好今年的经济工作、首先要把开展深入学习实践科学发展观活动与保持经济平稳较快发展紧密结合起来，着力把握发展规律、创新发展理念、转变发展方式、破解发展难题，着力转变影响和制约科学发展的思想观念和体制机制，着力解决经济社会发展中的突出问题。要深入实际、深入基层、深入群众，开展调查研究，做到问政于民、问需于民、问计于民，使提出的发展思路、工作部署、政策措施更加符合实际。最关键的是要进一步加强党风廉政建设、加强和改进党对经济工作的领导，统一思想、协调行动、加强学习、增长本领、转变作风、狠抓落实。要加强督促检查、严格执行纪律，只有把思想和行动统一到科学发展观的要求上来，统一到中央对国内外经济形势的分析判断上来，统一到中央决策部署上来，以思想认识的高度一致保证行动和工作的高度协调，才能确保中央关于进一步扩大内需、促进经济增长的政策措施不折不扣的落实到位，党和国家大政方针得到贯彻执行。（今年国家投资4万亿元人民币用于刺激经济发展的计划己基本安排到位，4万亿的投资构成大体是这样的、城市民生工程主要是保障性住房约4000亿元；农村民生工程，包括水、电、路、气、房约3700亿元；基础设施建设，包括铁路、公路、机场、水利等约15000亿元；教育、卫生、文化、计划生育等社会事业方面约1500亿元；节能减排、生态工程约2100亿元；调整结构和技术改造约3700亿元；以上各项总和大约30000亿元，另外10000亿元主要用于灾后重建。）\n3、要与学习胡锦涛总书记在《纪念党的十一届三中全会召开三十周年大会上的讲话》精神结合起来。胡锦涛总书记的重要讲话，从近一个世纪以来中华民族为实现伟大复兴进行的伟大革命的历史高度，从中国共产党带领人民发展中国特色社会主义、建设富强民主文明和谐的社会主义现代化国家的高度、从党和国家事业发展全局的高度，全面回顾和总结了改革开放30年的伟大历程和辉煌成就，高度评价了党的十一届三中全会的重要意义和历史功绩，系统阐述了改革开放“十个结合”的宝贵经验。\n1、必须把坚持马克思主义基本原理同推进马克思主义中国化结合起来，解放思想、实事求是、与时俱进，以实践基础上的理论创新为改革开放提供理论指导。2、必须把坚持四项基本原则同坚持改革开放结合起来，牢牢扭住经济建设这个中心，始终保持改革开放的正确方向。3、必须把尊重人民首创精神同加强和改善党的领导结合起来，坚持执政为民、紧紧依靠人民、切实造福人民，在充分发挥人民创造历史作用中体现党的领导核心作用。4、必须把坚持社会主义基本制度同发展市场经济结合起来，发挥社会主义制度的优越性和市场配置资源的有效性，使全社会充满改革发展的创造活力。5、必须把推动经济基础变革同推动上层建筑改革结合起来，不断推进政治体制改革，为改革开放和社会主义现代化建设提供制度保证和法制保障。6、必须把发展社会生产力同提高全民族文明素质结合起来，推动物质文明和精神文明协调发展，更加自觉、更加主动推动文化大发展大繁荣。7、必须把提高效率同促进社会公平结合起来，实现在经济发展的基础上由广大人民共享改革发展成果，推动社会主义和谐社会建设。8、必须把坚持独立自主同参与经济全球化结合起来，统筹好国内国际两个大局，为促进人类和平与发展的崇高事业作出贡献。9、必须把促进改革发展同保持社会稳定结合起来，坚持改革力度、发展速度和社会可承受的程度的统一，确保社会安定团结、和谐稳定。10、必须把推进中国特色社会主义伟大事业同推进党的建设新的伟大工程结合起来，加强党的执政能力建设和先进性建设，提高党的领导水平和执政水平、拒腐防变和抵御风险能力。\n胡锦涛总书记在讲话中强调，到我们党成立100周年时建成惠及十几亿人口的更高水平的小康社会，到新中国成立100周年时基本实现现代化，建成富强民主文明和谐的社会主义现代化国家。只要我们不动摇、不懈怠、不折腾，坚定不移的推进改革开放，坚定不移地走中国特色社会主义道路，就一定能够实现这一宏伟蓝图和奋斗目标。\n胡锦涛总书记强调不动摇、不懈怠、不折腾是十分重要的、因为改革开放以来，我们党鼓励在坚持四项基本原则下可以言论自由、思想多元化，但在现实的中国、在理论界仍存在新左派思想和新自由主义思潮，（例：新左派思想的代表认为“物权法”是保护私有制、夸大两极分化、仇官、仇富等观念，新自由主义代表的观念要全面私有化要把国有资产分到每个人、人均6万元。）他们的主张说到底都是反对党的纲领和基本路线的。去年我们国家是喜事难事都比较多的一年，全国人民在党中央、国务院的坚强领导下完成得都很好，受到了全世界的瞩目。今年我国所面临的国际国内政治经济形势既有喜事也有大事难事：新中国成立六十周年大庆，国际金融危机、平息西藏叛乱五十周年等等。尤其是国际金融危机带来世界范围内的经济形势进一步恶化、这次危机己远远超出上个世纪三十年代的世界经济危机，是近百年来发生的最大的一次经济危机。首先是美国的金融危机越演越烈，己有流动性黑洞走向流动性陷阱。所谓流动性黑洞是现有的流动性一下消失，流动性陷阱则是诱导政府注资，但所注资金对市场没有作用。现在美国有数以百万亿美元计的五花八门的证券和债券需要在市场抛售，没有几年时间、美国是难以从流动性陷阱里爬出来的。美国现在的情况比日本上世纪80年代末90年代的情况要严重得多，工业生产连续下滑、失业率也从2007年底的4.4%上升到2008年9月的6.1%，为2004年10月底以来的最高点。对于欧洲经济、目前是货币紧缩和通货膨胀问题同时存在，两者很难平衡，加之长期在体制和机制上严重缺乏活力，整个欧元区各国自顾不暇、在今年3月1日欧洲特别峰会上匈亚利等中东欧国家提议2400亿美元“救命”基金，遭到了德国为首的西欧国家拒绝，法国总统萨科齐因建议本国汽车工业撤出捷克和斯洛伐克在东欧信誉扫地，德国总理默克尔今年9月面临议会选举不愿因为东欧慷慨解囊而得罪选民，经济危机袭来、以邻为壑的保护主义苗头日渐显露，以为同在“欧元区”大船上的中东欧国家才意识到同舟未必共济、失望溢于言表。\n最近，世界银行调低了对2009年世界经济增长的预测，分别有6月份的3%下调为1%。其中，日美欧等“高收入国家”由6月份的2%下调为0.1%的负增长，新兴国家在内的发展中国家增长率由6月份的6.4%下调为4.5%。此外，世界性的通货膨胀压力短期内难以根本缓解，美元贬值、黄金上扬、石油掉价、股市暴跌、多米诺效应下全球经济下滑并步入萧条阶段、经济实体重新洗牌。世界金融危机对中国的直接影响一是国内几大银行共购买了美国价值约200亿美元的证券产品面临着巨额贬值甚至破产清算的噩运。二是今年的外贸出口业务一定会随着世界性的经济危机受到冲击。据有关统计资料显示今年元月份上海、江苏、浙江、广东四省市外贸进出口总额己出现大幅下降，外贸出口额上海市下降了26%，其它三省下降了16%---19%，外贸进口额平均下降了45%---48%左右。同时国内外的一藏独分子、东突分子、动乱分子等敌对势力，妄图分裂祖国的贼心仍然不死。所以，我们每个党员时刻都要保持清醒的政治头脑和政治敏锐性。时刻都要与党中央站在一起。\n4、要与落实工商行政管理的职能和完成2009年的具体任务结合起来。如何在工商行政管理工作中贯彻落实好科学发展观，一是要提高认识，统一思想，进一步增强贯彻落实科学发展观的自觉性和坚定性。思想是行动的先导，贯彻落实科学发展观是一场深刻的观念、体制革命，只有认识到位才能行动积极。这就要求我们广大工商干部要通过深入学习，进一步解放思想、认真剖析和解决不适应、不符合科学发展观的观念和体制，真正把思想认识和行动统一到科学发展观的要求上来。二是要强化监管，依法行政，努力营造有利于科学发展的市场环境，作为市场监管和行政执法的工商行政管理机关，肩负着维护市场秩序的重任，必须紧紧围绕履行管理职能，强化监管、依法行政，努力营造公平公正的准入环境，竞争有序的市场环境，安全健康的消费环境。三是要立足本职、服务大局，当好积极推动科学发展的促进派。发展是硬道理、发展是科学发展的第一要义、是我们党执政兴国的第一要务、也是工商行政管理的根本目的。要综合运用工商行政管理的各项职能、立足本职、服务大局，改进管理、优化服务，要把省委、省政府“四抓”“三支撑”、“工业强省”的战略落到实处，还要结合当地实际、服务地方经济，促进经济社会又好又快的发展。四是要发挥工商行政管理的职能，坚持我国的基本经济制度，积极支持各类市场经济主体的发展。落实中央一号文件精神、积极支持新农村建设，服务好“三农”、大力促进农村改革发展。落实国家实施的各项就业再就业优惠政策，积极引导就业、积极参与社会治安综合管理，努力维护社会和谐稳定。（今年的就业形势不容乐观、需要安排进城务工的农民工约2000万人、今年应届毕业生约600万人、往届未就业的毕业生累积约150万人，在国家鼓励就业的各种优惠政策支持下据专家估计仍有1200万人难于就业。）五是要锐意改革，开拓创新，通过大力加强法制建设、着力构建长效机制，深化监管制度改革，努力构建适应科学发展的工商行政管理体制机制。六是要固本强基、加强队伍建设，要以停征“两费”和落实新“三定”方案为契机、抓好“基层建设年”、推进“四化”建设、落实“四个统一”、建立“四高目标”队伍。省局张绪胜局长在今年全省工商行政管理工作会议上已经紧密联系全省工商行政管理工作的实际把这些新要求与贯彻落实党的十七大、十七届三中全会精神，落实中央、国务院、省委、省政府的经济工作会议及全国工商行政管理工作会议精神紧密结合起来做了详尽的安排部署。最近，省局又以甘工商发［2009］29号文将今年的主要工作任务细划到十一个大的方面（1、学习实践科学发展观2、优化发展环境3、服务“三农”4、监管执法5、消保维权6、非公经济党的建7、信息化建设8、基层建设9、领导班子建设10、党风廉政建设11、精神文明建设。）共计五十五个小项，这些工作都是实打实的硬任务。所以，我们不仅要按照中央、省委的要求，确保学习实践科学发展观活动达到预期的目标、更要紧密联系工商行政管理工作的实际、把学习实践科学发展活动的收获转化为推动各项工作的不竭动力，努力在继续解放思想上迈出新步伐，在改革开放上实现新突破，在推动科学发展上取得新进展，在社会和谐上见到新成效，在工商事业发展上做出新贡献。做好今年的各项工作，不辜负省局领导的希望。\n各市（州）、县（区）局的领导都要借助这次学习实践科学发展观的东风，进一步认清今年的形势和任务、摸清辖区内的社情、民情和局情、分析完成各项任务的有利条件和不利因素，把今年的各项任务分解到单位、落实到人员、靠实责任、扎实工作、精细管理、突出亮点，确保全面完成好，用实际行动向国庆六十周年献一份厚礼。\n谢谢大家！\n省工商局副地巡视员程康年\n年月"},{"id":255,"title":"战友情深","category":"散文","date":"二零一六年三月三十日补记","body":"四十余年前，有一批有志青年响应祖国的号召，为保家卫国舍亲弃家，从五湖四海来到了解放军这座大学校，相聚于二十军五十九师一七六团特务连，经过几年的同吃、同住、同训练、结下了深厚情谊。\n有聚就有散，几年后同样一颗红心两种准备，服从组织的安排，有的留队、有的转业复员、各谋前程。经过几十年的打拼奋斗，大都事业有成、儿孙满堂、可乐享天伦。\n宋君永高人如其名、看人看事不同常人，四十余年后仍不忘旧情相有挂牵，于二零一六年三月二十八日相约部分战友会面于南京，畅叙别后衷情，余因由未能亲赴、只在电话中与几位战友略聊了几句、特感遗憾，因情所感，遂以《扬州慢》词牌填词一首以示纪念。\n有幸的是去年三月三十一日至四月二日，由原特务连侦察排长王道林和司务长朱时兴二人（后均提升）又续前缘发起，在部队从江浙换防后的驻地商丘相聚，我再以《扬州慢》词牌填词一首为《战友情深之二》奉献给大家，以表庆贺。\n今年战友们又定于四月十三日至十六日在泰州相聚，可以见到几十年未见面的一些战友，确为人生之幸事之喜事，因我略算为半个主人，所以仍以《扬州慢》词牌填词《战友情深之三》。送给大家，祝福战友们身体康健，幸福美滿、相聚常有时，连绵不断。\n《杨州慢》\n战友情深之一\n少年励志，相聚军营，五湖四海同心。\n岁月快如梭，情谊与日添。\n屈指服役期已滿，铁打营盘，流水的兵。\n无奈何，转业复员，各谋前程。\n宋君厚意，四十余载仍相念。\n邀聚石头城，把酒叙情，倍感温馨。\n奋斗之路漫漫，已是白发滿两鬓。\n人生虽苦短，别忘执手相牵。\n战友情深之二\n握手拥抱，不识旧貌，四十年情未了。\n帅气虽已去，思念从未消。\n忆往昔同一战壕，互帮互学，胜似同胞。\n今相邀，商丘叙旧，离绪滔滔。\n综观社会，部队乃是大学校。\n一代又一代，投军从戎，大浪湧潮。\n别说壮志未酬，天若有情天亦老。\n余生多珍惜，心静方得寿高。\n战友情深之三\n光阴荏苒，世事移转，战友四十年前。\n商丘曾相约，泰州再见面。\n一年一度来聚会，传递消息，续叙衷情。\n细端详，绉纹增多，白发又添。\n天道公允，人生有苦就有甜。\n吾辈无怨悔，相逢春天，美在人心。\n放下功名利禄，随命运顺其自然。\n世间无常好，盼相聚有来年。\n《扬州慢》曲牌名，又名《朗州慢》，上下两片共九十八字，上片五十字，十句。下片四十八字，九句。上下片各四平韵。上片第四、五句和下片第三、第八句均为一字逗式句。\n我原籍为扬州市人，因一九九六年辖区变动后划入泰州市。《扬州慢》曲牌声情悲凉，后人多用于怀旧之幽情。我也钟爱此曲牌情深悠远的意境。喜用之，不当之处请指正。\n三省轩主程康年。\n二零一六年三月三十日补记。\n二零一八年四月二日重补记。"},{"id":256,"title":"新年随想","category":"散文","date":"新年感怀","body":"怱怱又走过去一年，在人生道路上也画了一个句号，是圆是扁还是像一个曲折拐弯的问号，当由他人评判。不管怎么说人是要活到老学到老的，过去的一年得到了什么？失去了什么？总结点经验教训似乎很有必要。否则，今后的路怎样走就会失去目标。\n新年昭示着送走了又一个轮回，岁月走远时总会留下抹不去的痕迹、人的面额上会刻上深浅不等的皱纹、人的心灵中也会种下或是“心怀凌云志”或是“只是近黄昏”的感动和问叹。自然界的木本植物是用年轮来记录自己的生命，草本植物是以一岁一枯黄的法则彰显顽强不屈的力量，人们则是用生活的脚印来丈量岁月、记录人生轨迹。不积踛步无以千里，走好人生每一步才显得生命有意义。\n人的生命在历史长河中仅为一瞬间、它却时刻担当着在苦难与快乐编织的诺亚方舟上品尝着酸辣苦甜。每个人不论何时何地回忆起往昔的岁月一定都会有很多感慨，成功者欣欣然、失败者惶惶然，但成功与失败证明的仅是昨天，不能说明今天，更不能表达明天。只要胜不骄、败不馁，始终拼博奋斗明天总是会更美好。\n新年张扬的是一个崭新的开始、谁都渴望春天的温暖、谁都会在心田里播下希望的种子，收获季节一定是种瓜得瓜种豆得豆。在新的一年里想创造出新的业绩吗？要记住磨刀不误砍柴功，不断学习充电，做好充分准备，冲破束缚观念的茧、磨亮上阵能力的剑。人生旅途就是攀爬上坡的车、逆水而进的舟，创造成功是要付出辛勤劳动的、不劳而获坐享其成只是懦者的空想、天道酬勤才是一条亘古不变的真理。\n聆听新年的钟声、感知岁月的脚步、回味过去的艰辛、放飞美好的心愿，那就让我们一起展望未来、展望明天，乘风破浪、勇往直前，坚定地相信有好梦就一定会实现。\n三省轩主程康年"},{"id":257,"title":"无锡纪事","category":"散文","date":"二零一三年国庆期间","body":"我的出生地是江苏泰兴市曲霞镇，自上世纪六十年代末当兵离家一直在外闯荡，转眼四十多年过去了，以前在“好儿男志在四方”励志格言的鼓动下，对退休后如何安排养老问题从未作认真考虑，直到前年迫在眉睫才去准备，退休后定居最少有四地可以选择，一是我长期工作的第二故乡嘉峪关、二是我最后四年工作单位省城兰州，三是女儿女婿生活的城市无锡，四是曾在“游子思归”小诗“离家飘泊时日长，别梦依稀常惆怅。老将随至念桑梓，叶落归根返故乡”中写到的裔胞之地——故乡曲霞镇。经权衡再三先选两地、嘉峪关和无锡，嘉峪关毕竟是我工作了三十多年的地方、我的生活圈在这里，故乡与无锡仅一江之隔车程不足一小时，另外、中国的养老现状还是要靠自已、靠子女，因此无锡是最后养老送终的地方。趁这人生60—70岁难有的黄金时代，我和老伴的身体还好，就像侯鸟一样两边飞吧。由此我对无锡的情况情不自禁的关注了起来，更多地了解是为了将来更好的融合进去。所以将我一点所见所闻所感所受记录下来，才有这篇《无锡纪事》\n一、无锡的历史与今天。\n江南水乡无锡坐拥锡惠山脉之光、以独享太湖、古运河、梁溪河以及众多河浜湖湾港汊交织的水网之灵性、闻名遐迩。它位于江苏省南部，长江三角洲平原腹地、北扼长江、南控太湖、东连苏州、西接常州，京杭大运河穿城而过，自古就是太湖流域的交通枢纽、东距我国的第一大都市上海约120公里、西距省会南京约170公里，无锡物产丰富是我国的鱼米之乡，商业发达自古就有钱码头、布码头、米码头之说，有“小上海”之称。这里风景秀丽“上有天堂、下有苏杭”实际上是对整个长三角的赞誉，无锡当然也在其中。\n无锡建城历史悠久、己有3500多年，自商末（公元前十二世纪）周太王长子泰伯偕弟仲雍，三让天下、东奔江南、定居梅里、筑城立国自号“勾吴”，开创了吴国历史。然后历经周、秦、两汉、三国、魏晋南北朝、隋、唐、宋、元、明、清、民国上下几千年的历史变迁、沿革至今。现在的行政区划是2000年国务院批准的，设2市6区、共32个乡镇51个街道。全市总面织4606.75平方公里，其中陆上面积3966.66平方公里，太湖水域面积640.09平方公里。无锡市有总人口639.024万人，其中市区人口354.23万人。2011年全市生产总值达6880.15亿元，人均GDP1.7万美元、按现行汇率计算达到10.47万元、突破10万大关、跃居江苏省第一，相当于世界同期平均水平9227美元的1.8倍。2004年1月无锡当选《CCTV》全国十大最具有经济活力的城市，所辖的江阴市在中国百强县中名列第一、宜兴市位居第七，江阴市的华西村有“天下第一村”的美誉。2010年12月获选为最具幸福感的城市，其颁奖词是：“传承千年的鱼米之乡，历久弥新的工业摇篮，这里风光秀美、陶冶了人们的文化素质，这里的教育发达、培养了无数杰出人才，濛濛烟雨、秀美江南、祥和文明、宜居之城。”\n无锡给我的印象是，人文积淀厚重、经济社会发达、旅游资源丰富、文明和谐普及、创新求进给力。我曾以《临江仙》曲牌填词三首，题为《无锡吟》对其夸赞。可见得无锡是：\n历史悠久、风光秀丽，可耐人无穷回味。\n人杰地灵、物产丰裕，享安乐幸福之乡。\n二、赐福有福的南禅寺\n南禅寺是无锡的一个重要地标，是旧时的八景之\n一，南朝梁武帝萧衍崇尚佛教、在全国大兴寺庙建设，时有寺庙四百八十之说，晚唐诗人杜牧的“千里莺啼绿映红，水村山廓酒旗风。南朝四百八十寺，多少楼台烟雨中。”诗句就佐证了这一点，当时无锡也建了不少寺庙、旧称梁溪有十大宝刹、其中有一座护国寺规模宏大，历数第二，建于梁武帝太清初年（公元547年）。唐高宗咸亨年间（公元670—674年）将护国寺改名为“灵山寺”，（现在灵山大佛所居的寺院应为祥符禅寺）北宋仁宗皇帝又赐名为“福圣禅院”老百姓因该寺庙地处南门随呼之为“南禅寺”，八年后宋仁宗又给与南禅寺相恃的北禅寺赐名“寿圣禅院”。北禅寺现己毁。\n南禅寺有一座七级八面、高43.3米的古塔，名“妙光塔”是宋徽宗赵佶所赐的八景之一，把妙光塔立在羊腰湾与运河的交汇处传说是为了制服水患。妙光塔历经元、明、清多次劫难，现存建筑多为明正统年间所建，1925年做了修复，1980年做了全面整修。南禅寺内天王殿、殿身辉煌、香火鼎盛；妙光塔、塔尖矗天、气势不凡；五戒堂、堂内庄严、净化人心；放生池、池水碧蓝、清澈照人。大雄宝殿中如来端坐中央、安祥庄重、慈眉善目，口欲启齿而又止、状似演法且为尽。两边护法罗汉、人人精神抖擞、个个神情专注。除了无锡的“南禅寺”外，福建的福州市、龙岩市，山西的忻州市、青海的西宁市还有日本的京都府都分别建有南禅寺。\n广义上的“南禅寺”也从20世纪八十年代起建设成无锡的文化商城、面积有12万平方米，成为人们游玩购物的好去处，妙光街被定为旅游一条街。\n南禅寺、赐福有福，福如东海长流水。\n无锡人、得福知福，福满金匮延千代。\n三、皇帝崇尚的惠山镇。\n惠山古镇位于京杭大运河无锡北塘段南岸，东西长1.7公里，以黄埠墩和惠山寺为界，南北宽0.8公里处于锡山大桥和通惠路之间，总面积约103公顷，其中惠山寺至宝善桥之间为核心区面积约为25公顷。大运河支流惠山浜直达腹地，古镇与惠山公园浑然一起是休闲探幽的极好去处。古镇文化底蕴丰厚，两岸历史文物林立、人文荟萃。惠山古镇以惠山寺、惠山直街、横街的祠堂群为依托连接二泉、寄畅园。这里晨钟暮鼓、经声佛号、淙淙流泉、阵阵松涛、诗书礼乐、文化精妙。\n惠山寺建于南朝景平元年（公元423年）有1580余年历史，规模位列无锡十大丛林之首，也是无锡的标志性建筑。从唐会昌（公元841年）至清同治年间惠山寺五次遭劫、五次重建、2002年进行了全面维修、2004年4月26日恢复宗教活动，香火旺盛。清乾隆皇帝六次南巡、六次驾临并亲题“江南第一山”匾额以示挚爱。唐代茶圣陆羽在此品茗后称“惠泉第二”天下第二泉因此得名。姚雪垠先生在他的散文《惠泉吃茶记》中对此另有高见。惠山寺门口的对联：“大哉王言，山为第一泉为二；巍然庙貌，祠为教孝寺为忠。”其教化子民功不可没。惠山寺石经幢耸立古镇中心。街口立一石碑横额正面刻有“五里香塍”四字，是晚清窦承焯所书，反面篆书“九峰翠嶂”是邵宝八世族孙邵涵初所书，碑立于清咸丰六年。有一千多年历史的唐代“听松石”长20米、宽0.87米、高0.56米呈褐色、表面平坦、一头微翘若帎、宛如卧榻、供游人坐卧，静听松涛。唐代书法家李阳冰用篆体写了“听松”立于此，阿炳的二胡曲《听松》也是在此有感而发后所创。建于北宋的金莲桥至今仍在背负近千年历史的重托、建于明万历年间的龙光塔是古镇一景、明代所建的寄畅园、愚公谷面貌依旧。唐.皮日休有诗赞曰：“千叶莲花旧有香，半山金刹照方塘。殿前日暮高风起，松子声声打石床。”600余年的古银杏树、400余年的古香樟树、古玉兰花至今根深叶茂。\n直街祠堂群、横街祠堂群、上下河塘祠堂群是古镇的另一景观，这些祠堂始建于唐、盛于明淸，先后有120处祠堂建筑物。其中有宰相祠九处，楚相有春申君黄歇，唐相有李绅、陆贽、张柬之，宋相有司马光、王旦、范仲淹、李纲，清相有李鸿章。祠堂群按规制可划分为尚书祠、侍郎祠、御史祠、巡视祠、忠节祠、贞节祠等，名目繁多。明代“千人报德坊”“华氏四面牌坊”是古镇牌坊群中的佼佼者。整个祠堂群中涉及80余姓、180余人，是除山西洪洞大槐树外的又一处追根溯源、寻根问祖、探索姓氏文化可去的地方。\n古镇上的泥人博物馆也值得一看，泥人是无锡著名特产之一，（紫砂壶、泥人、茶叶）无锡泥人始创于南北朝距今已有一千多年历史，取惠山东北坡山脚下离地面约1米深处的黑土，其土质细腻柔软、搓而不纹、弯而不断、干而不裂、可塑性极佳，制作工艺分为揑胚、彩绘、开相几部分，手揑的产品价格远高于印模产品，阿福阿喜是最讨人喜欢的代表作。\n听松石、石坚如磐，卧古镇千年无损。\n祠堂群、文化瑰宝，扬功德万世不朽。\n四、养育无锡的梁溪河。\n和长江、黄河是中国的母亲河一样，梁溪河是无\n锡的母亲河，梁溪河又名梁清溪，是沟通城区水系、京杭大运河、五里湖、太湖的重要枢纽。《无锡志》卷二《山川.总水》“梁溪”条目记载：“梁溪，即梁清溪距州城西四十丈、阔十丈、深五丈，源发于惠山之泉，入溪为南北流，其南绕惠山西南三十里，自小渲西流，出浦岭、独山二门入太湖。”\n由于城市建设的不断扩大，梁溪河现在在城中的地理位置已发生了很大变化。得益于梁溪河的水网枢纽作用，因此从未听说无锡发生过水患涝灾。明代著名学者《永乐大典》编纂人之一的王达曾写诗赞曰：“微波皱绿回轻风，溪流直与南湖通。人家两岸几废兴，鸥影萧萧夕照中。”明代大戏剧家汤显祖来锡游玩后也留诗夸赞：“横山断尾若龙蹲，烟雨平芜势独尊。日暮花溪泛桃水，太湖西去有双门。”古人这两首赞美梁溪河的诗宜景宜物、缠绵悱恻，令人回味无穷。对今天的无锡我也放胆留藏头直白拙诗一首：“山在江南称锡惠，城依太湖碧波水。人居画中宜长寿，文化道德传后辈。名扬四海风景美，胜迹遍布游人醉。无缘识得此地好？锡城欢迎来相会。”\n改革开放后无锡市政府十分重视梁溪河的整治，整治工作以改善水体生态环境、保护和恢复沿河岸的古建筑及自然景观为主要任务，同时以历史文脉为主线、将整个景观带分为“序景”“源起”“承传”“融合”，四个部分，共整治河道岸体14公里，重建驳岸10公里。\n整治后的梁溪河两岸林木葱郁、四季花开不断、绿化面积有116公顷。河水清澈如镜、宛若一条丝带把梁韵苑、仙蠡墩、鱼趣园、梁湖生态公园等多个开放式景点连串到一起，组成了一道亮丽的风景线，约有五公里长，并以蠡溪桥为界分为东西两苑。\n蠡溪东苑以江南水乡的田园风光为主、运用桑田情浓、小桥流水、水车草庐、梁溪古渡、杏花楼、牌坊、码头来体现浓郁的江南风情，唐代诗人李绅的诗句镶嵌在松子亭中，元代大画家倪瓒的雕像端坐在河边、手捋长髯、凝望流淌的河水、似乎在构思什么佳作。其《与百雨登溪山胜概楼》诗中句“若士振衣千仞表，何人泛宅五湖间。”也刻在牌坊的反面。横批是“四海无闲”。\n“梁溪古渡”有一个眉清目秀的青年肩背布搭、手拿雨伞正准备上船进京赶考、年迈的母亲躬着腰、拄着拐棍向儿子挥手，怀着无限的期盼、依依不舍之情、让人动容。\n蠡溪西苑以江南水乡帎河古街及无锡的抗金名将李纲的梁溪居和明代谏臣顾可久的清溪庄为主景，文会堂、九峰阁、烟雨墩、芙蓉池、乌头门、山阴亭及许多拱桥点缀其中，一进两苑、秀丽挺拔的牌坊屹立眼前，上联：“北屏九龙绣嶂、延数千年锡惠文脉，”下联：“南带五湖烟波、阅三万顷吴越风光。”横批是：“蠡溪水苑”，苑内楼堂馆亭皆是仿古建筑、雕梁画柱琉璃飞檐、错落有致、古色古香。晚上华灯齐放、五颜六色的建筑群倒映水中，胜似仙境。\n梁溪河、勾通水网，遏水患造福百姓。\n大太湖、鱼米之乡，利运输惠泽黎民。\n金色江南二期的“颐景园”小区、沿梁溪河精品路段而筑，小女居家东西两边被隐秀路和鸿桥路所包、小区北门前是横贯东西的梁淸路，南距梁溪河边曲径通幽的健身道仅有五十步之遥，每天早晚煅炼身体、漫步其中，美不胜收，早春和深秋的早晨与傍晚、河面上还经常会泛起轻纱般的薄雾、更让人有如痴如醉、飘飘欲仙的感觉。\n无锡是一个人杰地灵的地方、这里人才辈出；无锡是一个风景秀丽的地方、这里景点诱人；无锡是一个人文荟萃的地方，这里民风淳朴；无锡是一个充满活力的地方，这里前途无量。无锡永远是一幅画不完的画、一首写不完的诗、一卷读不完的书。大哉无锡、美哉无锡。同时也有感于灵山大佛和鼋头渚景区。\n灵山佛、佛法无边，念南无阿弥陀佛。\n鼋头渚、渚孕吴越，蕴千年历史玄机。\n当然只要虚心学习、认真探索、就有可能做一个真正的无锡人。努力去适应吧！\n三省轩主程康年\n二零一三年国庆期间\n三省轩主程康年\n二零一三年国庆期间"},{"id":258,"title":"自得其乐颂","category":"诗","date":"二零二一年初冬","body":"岁月流逝未轻耗，\n人生磨砺见端梢。\n别悔少壮不努力，\n无憾老大福寿高。\n饴孙娱心伺花草，\n舞文弄墨初捉刀。\n文字游戏诗当酒，\n自愉自乐常小酌。\n三省轩主程康年\n二零二一年初冬"},{"id":259,"title":"西藏印象","category":"散文","date":"西藏纪行","body":"享有“世界屋脊”盛誉的西藏，是一个美丽而神奇的地方，它位于中国的西南边疆、青藏高原的西南部，面积122万平方公里，辖拉萨、日喀则、林芝、昌都、那曲、山南、阿里七个地区，人口277万，去年实现生产总值250、4亿元、人均GDP首次突破1000美元。西藏边境线全长4000公里，与缅甸、印度、不丹、尼泊尔接壤，喜马拉雅山脉平均海拔都在6000米以上，海拔8848、13米的珠穆拉玛峰是地球之颠、又有世界第三极之称。长久以来，西藏一直是旅行家心目中一片令人向往的神秘之地和梦寐以求的探险乐园，独具特色的西藏风俗人情、价值观念、宗教信仰、文化艺术等领域、对世人有一股阻挡不住的诱惑。今年7月1日青藏铁路——世界上最高的一条高原“天路”通车了，它就像一条五彩的哈达把拉萨和祖国的内地紧紧的联系到了一起，备受国内外游客关注的西藏一下出现了旅游热潮，从四面八方奔赴西藏的人潮滚滚而来，车票真是一票难求呀，随着时间的推移我想信此情一定会得到好转的。\n8月中旬有幸参加了国家工商总局组织在拉萨召开的中国西部省市商标行政保护协作会议，又一次跨进西藏。\n第一次进藏是2000年的7月底、8月初，随我市原纪委书记常江同志和市委常委、常务副市长路志龙同志带队的党政代表团应邀到青海省格尔木市、签订缔结友好城市协议的机会去了一次拉萨，当时青藏公路有很多路段都在修路，路很难行，汽车一路颠簸。早晨七点出发，中午在长江源头沱沱河上第一桥旁打尖、晚餐是那曲行署招待的，因为有一辆武警交通部队的车带路才敢于饭后继续前行，320多公里的路程走了八个小时、第二天凌晨四点才到拉萨。由于党政代表团的成员都着急赶回兰州参加省政府组织的“兰洽会”，此次到拉萨只是浮光掠影、走马观花的看了看布达拉宫、罗布林卡、哲蚌寺、大昭寺、八廓街，而当时八廓街、江苏路等主要街道和好多景点都正在改造建设中，并没有留下多少好的、深刻的记忆，这次有机会正好补此遗憾。\n这次进藏是8月15日从兰州乘917次列车由省工商局张汉文副局长带队、酒泉阎耀成局长、陇南马曦局长、省局商广处郭进胜副处长和我五人同行。列车使用的车体目前在国内铁路线上是一流的、最现代化的、具有全封闭空调系统、卫星定位系统、垃圾粪便自动收集系统、软卧车厢内给每人都备有吸氧和声像系统。硬卧车厢也是按组分隔，有公共吸氧点、餐厅、条件很好。铁路基本与青藏公路并行、途经西宁、格尔木、那曲、当雄四个停靠站，其余是无人值守站，沿途可以看到青海省玉树地区的可可西里无人区、昆仑山、念青唐古拉山、羌塘草原等原始风光。可以毫不夸张的说在无人区你如果任意踩上一脚、迈出一步，就有可能踩出开天辟地以来的第一脚，迈出前无古人的第一步。羌塘草原上拿出你的相机随意摄几个镜头都是风景如画的风光照，蓝天上飘荡着变幻莫测的云彩、大地上点缀着簇簇藏式的帐篷，牧场上流淌着悠闲肥壮的牛羊、美景溢于言表真是美不胜收。16日晚十点半准点到达拉萨，火车站是一座具有藏民族特色的建筑位于拉萨西南的堆龙德庆县柳梧乡境内、海拔3600米。在车站受到西藏自治区工商局同志们的热情接待，按照藏民族的风俗给每位代表都献了哈达。在回宾馆的路上自治区工商局的同志介绍，刚到西藏要少喝酒、少洗澡、少做激烈运动、要多休息，就好比出国的倒时差、要有一个适应过程，并给每人发了一盒黑褐色的胶囊“高原安”说是服后可增加血氧量、抗击高原反应，在西藏的几天我除了晚上睡觉有点不实的感觉外，其它几乎没有感到任何不适。是夜，下榻在西藏自治区政府宾馆“西藏大厦”。\n西藏所辖七个地区除昌都、阿里未去外、其余五个地区的风光都乘机去领略了一下，每个地方都各有特点。17日会议报到的当天下午，因为无事在拉萨两位朋友的帮助下我们代表团五人、去纳木错观光，纳本错是列青海湖后的我国第二咸水湖、也是世界上海拔最高的大湖，位于拉萨市当雄县和那曲地区的班戈县之间，距拉萨市区约260公里，从拉萨市区出发途经当雄县城和羊八井地热温泉带，到了纳根山口、向西就可以遥望到闪闪发亮的纳木错了，纳木错的湖面海拔4718米，东西方向最长处70公里、南北方向最宽处30公里、面积约1920平方公里，当你走到湖边时，首先映入你眼帘的是蓝天连接着的蓝色圣湖，烟波浩淼，水天一色，湖边的神山传说是佛的手印、满悬彩色经幡，十分迷人，尤其是在那神圣、宁静、祥和面前，你的灵魂一定会受到震撼、净化和洗礼。纳木错与阿里的玛旁雍错、浪卡子县的羊卓雍错并称为西藏三大圣湖，也是藏胞所称的“天湖”。藏语称湖为“错”，在西藏辽阔的大地上总共有大小湖泊1500多个。\n拉萨，亦称“日光城”、平均海拔3700米，拉萨河穿城而过、海拔虽高但气候比较湿润，拉萨虽有1300多年的历史。但1951年和平解放时仅是一个2万多人的聚居地、面积不足3平方公里，即是2000年到拉萨、给我的印象也是城区面积基本上和当时的嘉峪关市差不多，市区内的原始生态面貌还比较多。18日会务组组织会议代表参观拉萨市内的景点，如今看到的拉萨发展速度与原来一首老歌《逛新城》里提到的情景相比简直是天壤之别确实让人吃惊、城市真正有了一片新面貌、城区面积是50年前的18倍、城市常住人口是50年前的10倍，市内高楼林立、街道宽阔、商业繁荣、交通发达、民族团结、人民安康幸福，据西藏自治区工商局的同志介绍，西藏发展如此之快主要得益于中央财政的支持、得益于国家西部大开发和全国各地对口帮扶政策的支持，有很多项目都是自带资金、自带建设队伍的交钥匙工程，拉萨城市的迅猛发展、还得益于为庆祝西藏自治区和平解放五十周年而建成的很多公益项目。布达拉宫广场的夜景、拉萨的商业步行街与国内任何一个城市相比都毫不逊色，拉萨的现代化气息已经很浓、很浓。\n藏北重镇那曲意为“黑河”，处于唐古拉山、念青唐古拉山、冈底斯的山脉怀抱之中，西边有达尔果雪山、东边有布古雪山，总面积40多万平方公里，平均海拔4000米以上那曲地区下辖九个县，但人口都很少，10平方公里平均不到一户人家。去纳木错的途中、车外不时会碰到磕长头去拉萨朝拜的藏胞，藏传佛教的经义是写在天空中、写在大地上、写在人们心灵里的至高无尚的圣经，据说这些藏胞大都是从青海的玉树、果洛和甘肃的甘南和西藏各地出发、没有汽车、没有帐蓬，甚至缺食少水，仅靠一位家人拉一辆架子车陪伴，一路上，他们将双手沿鼻尖举至额头，身体前仆，磕三步一等身长头。一次结束，下一次仍重复这一固定动作。行程千余里、耗时一年甚至一年多才能到拉萨，宗教真是可以让人忍耐现实的痛苦。很多人都认为这种顶礼膜拜是迷信和愚昧无知的行为。对此我另有所见，这种对洗赎原罪的信念、对苦行礼佛的虔诚、对信仰崇拜的忠贞，没有坚强的意志是做不到的，我相信当他们额头触地之时他们的灵魂一定会与洁净无瑕的天空越来越近。相比之下，生活在嘈杂闹市里的人们，人心浮躁、物欲横流，人的精神己被撕成碎片，人们除了相信看得见、摸得着的物质以外似乎不再相信什么，那些易逝的疯狂的物质正在使人们忘记“日食三餐、夜躺八尺”的古训、正在吞噬人们的灵魂和良知、正在瓜分善良人们的生命。太多的“东西”也因此生出了太多的事情。脂肪代替了灵魂，物质挤占了精神的空间，逐渐使人成为没有灵魂没有精神的物质驱壳。如果世界上没有了精神追求那么世界将会成为什么样子？很难设想！如果我们每个人对自己的信仰都持有藏胞朝圣这样的韧性、政治家们再善于把政治信仰和宗教信仰（正道的宗教都是规劝人从善）有机的结合起来，将一种精神在“天时、地利、人和”的环境下传承得恰到好处，人的生命才会升华、民族才有凝聚力、社会才会发展得更加繁荣、更加和谐、更加进步。\n自认为有三十几年党龄的我、对发展着的马列主义、毛泽东思想、邓小平理论和“三个代表”重要思想、还算是一名忠实执着的追随者、崇拜者，还在守护着这片精神家园。\n山南地区是吐蕃祖地也就是说是整个藏民族古代文化的发祥地，它位于雅鲁藏布江的中部流域，这里土地肥沃，吐蕃王朝前身的雅隆部落就活跃在这一带，山南地区的首府在泽当镇、城市虽然不大，基本没有高楼大厦，但建筑物都蛮新潮，现代化的商品琳琅满目，穿过泽当镇向南八公里有个凸起的城堡孤零零地矗立在扎西日次山头上，那就是西藏的第一座宫殿雍布拉康，扎西日次是一座小山、相对海拔也就是100多米，山形酷似母鹿的后腿，“雍布”的意思即母鹿。据考证，雍布拉康是雅隆部落第一代赞普（藏王）聂赤赞普修建的宫殿，距今约有2100多年的历史、西藏民间普遍相传“地方莫古于雅隆、房屋莫古于雍布、赞普莫古于聂赤。”是说这座最古老的建筑物是西藏最古老的国王在最古老的土地上建起来的。直到三十三世藏王、第一世法王松赞干布，于公元七世纪征服了其它诸小部落，建立了统一的吐蕃王朝后，大本营才迁移到北面的拉萨并建起布达拉宫。从山南返回时发现曲水县的对口支援单位是我的原籍江苏省泰州市。\n20日我们去林芝观光，出拉萨顺浩浩荡荡的尼洋河峡谷一路向东途经达孜、泽当、墨竹工卡、工布江达几个县，过海拔5100米的米拉山口后海拔逐渐降低，途中参观了巴松错以及湖心岛，“巴松错”、其实就是一个水库、利用水的自然落差正在修建水力发电站。这是一个既节省资源又十分环保的好项目，一定会给藏胞带来好的福音和效益，去林芝的一路、风光旖旎、路两边尽是茂密的原始森林，自然植皮保护很好、葱郁滴翠、不愧为有西藏江南的美称。\n林芝的首府设在八一镇，八一镇的城市规模虽然比不上拉萨、但城市面貌很新、所有的建筑物都很现代化、藏民族传铳特色的建筑物很少，其现代化水平用我的眼光看、某种程度上己超过拉萨，我们投宿的福建大酒店是福建省援建的、其水平在国内评一个四星级宾馆完全够标准。林芝地区辖七个县、平均海拔3100米、八一镇2900米，总人口16、5万，2005年的经济总量是24、2亿元。行署专员周金边同志是我们江苏老乡，他是南通人在林芝地区工作己经36年了，一个从东海之滨鱼米之乡来的人在雪域高原坚持了这么多年、我感到很了不起，他是真正把西藏当作第二故乡了。不！应该是把西藏当作第一故乡了。在返回拉萨的途中到巴结村参观了堪称世界第一的巨柏，围粗18米、树高50米，据考证己有2500年的树龄，是真正的活化石。站在巨型古柏面前、打量短暂的人生、才领会到弹指一挥间的真正含义。\n22日去日喀则，日喀则距离拉萨约270公里、是西藏的第二大城市己有500年的历史，全区共有18个县市总人口66万人、2005年的经济总量约40亿元，著名的喜马拉雅山就在其境内。日喀则平均海拔4100米、市区3850米，在日喀则参观了黄教六大名寺之一的扎什布伦寺，十世班禅大师的灵塔就安放在寺内的西陵，藏传佛教的派系比较多有红教、黄教、花教、白教、如白教又划为四大系八小系，其它派系下也分有不同的派别，黄教是西藏目前最大的教派、绝大多数藏胞都是信仰的黄教。黄教的六大寺院还有拉萨的哲蚌寺、甘丹寺、色拉寺、青海西宁的塔尔寺、甘南夏河的拉卜愣寺。在日喀则的宗山上还有一座小布达拉宫不知是何时毁掉的，今年正在重建，关于小布达拉宫还有好多美丽的传说，但愿以后有机会再去拜谒。\n拉萨机场位于山南地区的贡嘎县境内、那里是雅鲁藏布江河谷上最为宽阔的地带，建机场比较适宜，机场原来距离拉萨市区约90余公里，据说是国内离城市最远的一个机场，现在打穿了四公里的隧道，行程缩短了五分之二，不到一小时的车程就可以到达拉萨市中心。\n这次西藏之行除昌都和阿里地区未去外，涉足了五个地区给我印象最深的还是新农村建设，无论走到那里都很少再看到原来那些低矮的藏居石屋，代之而起的都是宽敞明亮的藏式小楼，屋面的材料很现代化、大都采用色彩新艳的彩钢板，仅此我看西藏的新农村基础建设有可能会走到全国的前面。到过西藏的人对西藏的印象会各不相同，每一个人每次去西藏的印象也肯定不一样，这就是我的感受，衷心祝愿西藏在改革开放中、经济快速发展、与全国各兄弟民族一样共享现代文明，衷心祝愿西藏同胞能坚守住具有民族传统的风俗人情，能保住人类最后一片原生态的净土，衷心祝愿西藏在今后的日子里走得更快、更好、更红。\n这次在西藏会议期间学到了很多兄弟单位在商标行政保护方面的经验，使我增长了不少见识，今后在商标监管保护方面的执法能力、肯定会得到相应的提高，这次会议期间的另一大收获是使我结识了很多新朋友。\n深深的感谢这次会议的组织者。\n嘉峪关市工商局三省轩主程康年\n年月日"},{"id":260,"title":"走在春天里","category":"散文","date":"二零一三年元宵节后","body":"一年四季、春夏秋冬的变迁，春华秋实、严寒酷暑的更替，是无法改变的自然规律。对于春华秋实的春天与秋天会有人厌烦吗？可严寒酷暑在有些人们的心中总像避之不及的魔。因此，“老天爷”只合一半的人缘，其实老天爷是十分公平的，让人们有得就有失、有失就有得。这就是“天命”。\n春节一过、新一年的春天就又悄然来到了人间，来到了人们心上，平原山川、河流溪边、乡间路旁、花草树木、禽鸟蜂蝶，世间万物都在报告春的消息。太阳也早出晚归无私的加班给大地送来温暖。转眼间冰雪风霜的寒意就会步履蹣跚地远去，那种“随风潜入夜、润物细无声”的细雨缠绵、鸟语花香的日子也会迤逦而来。\n走在春天的绿色里。走在绿荫之下、走在绿草之上、走在花的海洋中，心在春光里荡漾、品嚼着春的味道，风在和煦的阳光下轻柔地吹着、垂柳曝出油嫩的秀眉叶像一丛丛绿色的羽毛，千朵柳絮伴着万般柔情在微风中轻歌曼舞，刚冒尖的小草在春风和阳光的鼓动下、一个劲地挤进了田园、漫上了道路、爬上了门前的台阶，绿苔、车前子和野草莓沿着房前屋后的墙角绣出了一道道美丽的花环。草地上到处都可看到生机盎然代表生命的绿色。没有花香没有树高的小草同样会在春天里恣情率性的生长着、碧绿着展示自己旺盛的生命力。\n在漫山遍野的绿色草地上竞相开满了姹紫嫣红的小花：有红，冲击着人们的视觉和嗅觉神经，令人十分亢奋、甚至勾起了大声放歌的欲望。一簇簇的鲜花间还有层层花蕾，争先恐后的等待开放。（这里是西北草原的春色）抬头看远处、桃花、杏花、梨花、茶花、杜鹃、玫瑰、玉兰、石榴等和一些不知名的花儿也是“你方唱罢我登场”争奇斗艳，红红火火、五彩缤纷，点缀在青山绿水、道路阡陌、河堤湖岸、庭院房舍之间，春天简直就是花的世界。（这里是秀美江南的春光）\n走在春天的河溪旁。轻轻地听到了溪水淙淙的低声吟唱，冰雪消融了、小溪涌动、河水也随着丰满起来，水面上经常有小鱼儿跳出来、想品尝挡不住的春色。抬头看到的还有艳阳、蓝天、白云，水天交接处白云映照在清澈的河水里，不知道是流水推着白云涌动、还是白云带着河水流淌。靠河堤岸的芦苇、蒲草丛里己冒出细细的嫩芽，小荷也露出了尖尖角，鹅和鸭们时而扎个猛子乐此不彼的水下淘食，时而漂浮在水面上尽情地扑楞着翅膀追逐嬉戏、不时还伸长脖子“呱、呱、呱”的高歌一曲，“春江水暖鸭先知”的诗情画意就呈现在你的眼前。\n走在春天的细雨里。春雨是春天的使者，是春姑娘俏丽的倩影，“好雨知时节，当春乃发生。”，霏霏细雨幻，像一名婉约少女的柔姿紧贴您的脸颊，又像一缕薄纱裹着你的全身，站在暮色的雨幕中在华灯初放的映衬下你会感觉到她的轻盈妩媚、她的可人风韵、此时此刻她更像一幅大写意的水墨风景画、把你带到了《人间仙境》。春雨给了世间万物生命的营养，生命也因此更显得无比滋润、显得生机勃勃。\n轻细如丝的春雨让我的思绪与之产生了和谐的共鸣，春雨可以荡涤万劫尘世的喧嚣和鼓噪，同样可以净化人们心灵的烦闷和浮躁。亲和春雨可以抛弃胸中所有的积郁、敞开胸怀拥抱自然，用宁静致远的心境去洞察人间世事，宽容一切。春夜丝雨的无边爱抚、浸润的是心底那份与“谁知风雨夜，花落知多少？”失落和感伤情结不相容的浓浓纯情。春雨又像一场大戏开了幕却忘记了结尾，潇潇洒洒、纷纷扬扬要待梅雨季节过后才算结束，虽如此我也愿意接受春雨的洗礼。\n走在暖暖的阳光里。春天是万物复苏、拔节生长的美好季节。艳阳高照的日子里，鸟儿也忙了起来，屋檐下的燕子呢喃，树梢上的麻雀啾啾、翠柳间的黄鹂叽叽；杜鹃啼血、布谷催播、牧笛悠扬、山歌激荡。农夫们在田野上也适时翻地挖垄，施肥播种为春耕而忙碌着，“种瓜得瓜、种豆得豆”，这种生生不息就是春天赐予人们最好的礼物。春天不仅创造了美艳的色彩、带来了芳香与甘甜，也给人们带来了收获的希望。只要有春天，在人生的道路上即使遇到一些挫折也没有理由悲观和失望。\n一日之计在于晨，一年之计在于春。春天赋于大自然的是生机勃发、朝气向上的气息，给予人们的是无限的关切、温暖的体贴、青春的活力、幸福的慰籍。春天把美好的一切都奉献给了大地、奉献给了人们。只要我们善于把握春天，把握自己的命运，就会有光明的前途和美好的明天。\n让我们感谢春天。\n流连在春天里，我总感觉我是最幸福的人。\n三省轩主程康年\n二零一三年元宵节后"},{"id":261,"title":"走进大自然的怀抱","category":"散文","date":"二零一七年四月五日清明节后","body":"月日离开嘉峪关，日又回到阔别百日的无锡，回来后不几天的月日便是清明节，清明节除了扫墓祭祖、在江南还有踏青游春的传统习俗。此节又在农历的阳春三月，正好春光明媚\n踏青就是走进大自然，去欣赏春天的美色。清明那天风和日丽，我们一家去了位于无锡阳山镇新河口路与桃园东路交叉口的“田园东方”。它是集现代农业、休闲旅游、田园社区等产业的田园综合体。在这里我们置身于风景如画的万亩桃海之间，尽情享受春天带给的温暖、享受艳阳送来的爱意，可谓是美不胜收。\n“田园东方”应理解为人和自然和谐“美”的杰作，它除了留有城郊农村原有的韵味外、还增添了人们对“美”的新含义的认识。因此，在自然环境中加入了不少人为新作，可惜的是它融合了太重太浓的商业气氛。给我的直觉是“美”失去了天然，失去了纯真，“美”中自有不足。\n春天在无锡值得游览的地方太多太多……。那就让我们走进大自然的怀抱吧。\n宋．无门和尚所作禅诗《颂》“春有百花秋有月，夏有凉风冬有雪。若无闲事挂心头，便是人间好时节。”奉劝世人抛开内心烦恼、不要整天为琐事牵挂，世间万事万物都是美好的，情随景生、释放心怀，随时随地都可以欣赏到人间美景。\n无论是春天的百花、夏天的凉风、秋天的明月、冬天的洁雪，还是大自然的原野山川、江河湖海，都是活生生的，只要你用心去欣赏、用情去发现，都有其妙不可言的独特美。\n那么，你观赏过大自然的美景吗？那天的湛蓝、云的飘逸、山的巍峨、水的清澈、花的烂漫、草的嫩柔……，我看这一切的美仑美奐都来自天然。\n那么，你聆听过大自然的声音吗？那雷电狂风、溪流淙淙、小鸟啾啾、春燕呢喃、蟋蟀弹唱、蜜蜂嗡嗡……，我想这所有的天音合唱皆源自永恒。\n大自然以她瑰丽神奇的美景、深邃神秘的声音在召喚我们，迎接我们。\n流连在贡湖湾湿地蜂蝶飞舞的阡陌上、花丛间；荡漾在沐浴无限春光的蠡湖边、太湖旁；闲逛在花香溢十里的梅园、金匮公园里……；任摇曳的柳丝轻拂，随风中的樱花洒落，乘小草的清香飘远……。远眺一汪湖水的轻波，聆听百鸟齐鸣的欢歌。大自然毫无保留的将美好与温暖送到人间，给人们带来最良好的祝愿。\n百花争报春意暖，万众莫失好时节。此时此刻应该让我们携一腕清新、握一袭优雅漫步在江南小桥流水旁、沉浸在古镇老街小巷里、寻寻觅觅，寻觅历史和现实、自然与人文的经典故事。我们会发现原来天地和人生的和谐、都是那么美好；我们会感悟原来生活可以这样简单、简单才是快乐。\n走出去，走进大自然的怀抱，在湖光山色中享受人在画中、景在心中、天人合一的美。\n走出去，走进大自然的怀抱，在旖旎风光中体会博爱无垠、返朴归真、无私无欲的爽。\n微笑着，把昨天轻轻放下；微笑着，把烦恼远远拋却；微笑着，把心灵缓缓释放；微笑着，把今天紧紧拥抱。\n让我们快乐在大自然的怀抱里每一天，一定都会是阳光明媚、百花盛开的春天。\n三省轩主程康年\n二零一七年四月五日清明节后"},{"id":262,"title":"一封迟发的家书","category":"散文","date":"二零一四年十二月十二日","body":"这是一封迟发的家书，七年前在女儿结婚典礼上，我们不仅送给她一些最美好的祝愿、还有让她如何面对复杂社会\n生活环境，老实做人踏实做事的殷切期望。\n女儿结婚成家，就要离开我们身边去独立生活，所以我把这封家书题名为《放飞》。今年我们添了外孙，女儿已为人母，肩上也会扛上教育孩子的义务，慢慢地会体会到当父母的艰辛，现在补录这封家书，谨为全家记之、勉之、检之、行之。\n女儿出生在一九八零年二月六日九时三十六分，（农历庚申年）是独生女。我和她母亲都是兄弟姊妹众多，又都经过三年自然灾害的困难时期，吃了很多苦。现在细想起来、在物质特别匮乏的那个年代，父母养育我们是多么不容易啊。孩子多、生活负担虽重、但“多子多福”的“幸福”感，父辈们也是有的。我父亲在我成人后、经常讲我儿时在麦地里扛麦捆的故事，很可笑。我们培养女儿长大成人，当然也有一定的成就感，今后发展得怎么样只好由她自已再努力了。\n朱自清先生有一篇散文《儿女》他将五个小孩吃饭、游戏的情景写得活龙活现。文章中特别提到了对子女的教育问题，“职业、人生观等，还是由他们自已去定的好；自已顶可贵，只要指导，帮助他们自己去发展，便是极贤明的办法”。“目前所能做的，只是培养他们基本的力量——胸襟与眼光，孩子们还是孩子们，自然说不上高远的，慢慢从近处小处下手便了。这自然也只能先按照我自已的样子：‘神而明之，存乎其人。’光辉也罢，倒楣也罢，平凡也罢，让他们各尽各的力去。”我写《放飞》的原意也是如此。\n女儿出生正赶上我国实行计划生育、又适逢改革开放，日子越过越好，一个孩子犹如掌上明珠，总怕孩子跟我们小时候一样吃苦，从生活的各个方面、都尽量满足她的要求，哪怕倾其所有。给孩子的爱、基本上达到了娇惯的程度。这可能不是我们一家，应该是这一代家长教育孩子的通病。\n在蜜糖罐里长大的独生子女，很多都不理解父母的良苦用心，很多都会患有孤独、自私、任性、懒惰、依赖症。为了确保女儿能健康成长，高中毕业后就帮她选择了到解放军这座大学校、大熔炉里去锻炼、去吃苦、去学会独立生活。几年的军旅、军校生活，很多缺点都得到了克服，正常的生活习惯也有所养成，铸就了良好的人格品质、树立了人生目标、奠定了人生基础。虽如此、父母仍希望你在今后的生活中要对“世事洞明皆学问，人情练达即文章”这句话的深刻含义不断加深理解，对今后如何为人处世父母叮嘱再三。\n附记\n亲爱的女儿：\n按照中国人的传统观念，结婚成家，就要离开父母独立的去过日子，虽然你可以自主选择人生道路、决定生活方式，创造你的幸福人生，毕竞你还年轻、还幼稚、在父母面前你仍然是一个小孩。结婚成家尤如一只放飞的风筝、你可以在蓝天中自由翱翔。但今后你所有的一切，仍会有一根线牵挂在父母的心上。在离开父母的日子里，父母有言相赠，人来到这个世间，都会在世俗的泥淖里扑腾，都会在困难中前行，机遇应该靠自已把握，前途无论如何、都应该坦然面对，不要有任何抱怨。人一生必须懂得“一命、二运、三读书”的深刻含义。“命”是规律不可突破，“运”是机遇可以争取，“读书”是积累才干的基础，无人能替代。美好的人生只有自已去努力、去创造。人一生中必须学会“自尊、自爱、自强、自立”，诸事不要依靠别人、要敢于自已担当，具体为学会做好三件事，一是学会做人，二是学会做事，三是学会理家。\n一、学会做人。就是要学会融洽社会、人群、自然等各个方面的关系。学会老实做人必须具有“诚实之心”、“博爱之心”、“善良之心”、“感恩之心”。\n“诚实之心”是做人的根本。只有用诚实之心对人、才会获得别人的欣赏与信任、帮助与支持；只有用诚实之心对人、才会对神灵、对天地、对自然、对一切有敬畏之感；只有用诚实之心对人，才不会逾越“道德”这堵墙的底线。失信于人等于加害自已，从小讲的《狼来了》的故事就是这个意思，诚实之心对人并不排除善意的谎言和与对手的戒备，俗话说，“害人之心不可有、防人之心不可无”。切记之。\n“博爱之心”是安身立命之前提。只有用大爱之心去看世间的一切，才会觉得世间一切都是光鲜的、灿烂的、美好的。没有爱心必生戾气，看人不顺眼、看事不顺心，怨天尤人、疲惫身心，于人、于事、于已，毫无盖处。快乐面对一切、才能享受幸福一生。顺境得势戒骄气，逆袭背时莫失意。古人说：“福兮祸所倚，祸兮福所伏”，“祸福无门、惟人自召”，这些都是哲理。\n“善良之心”是人之本性。“人之初、性本善”。一生要把持好。有善良之心才能悲悯弱势群体；有善良之心才能宽容他人之过；有善良之心才能施人不图有报。人生的价值在于付出，不在于索取。付出证明你的富有，索取证明你的贫穷，人一生中应该多想自已“有什么”、少想自已“没什么”，只有这样才会多些“满足”、少些“欲望”，知足常乐，贪欲与恶念定会损人终生，千万不可有侥幸心理。\n守善念、结善缘、处安泰、树尊严。人生“日食三餐、夜躺八尺。”足矣，多余皆可帮助别人。“上善若水、厚德载物”，凭善良之心做人，定会平安一生。\n“感恩之心”。懂得感恩就是学会理性做人。一个人从呱呱落地到一生的成长过程都离不开家人、师长、亲朋及社会所有人的关心帮助、离不开天地、自然无私的给予，一生中的点滴进步和成功，也绝不完全是个人努力的结果。没有天、哪有地？没有父母哪有你？理性地思考是不是成长比成功更重要？学会感恩，才会有人帮你搭超越自已的平台，才会有人给你建不断登高的天梯。\n二、学会做事。积累知识，增长才干是学会做事的有效途径。踏实做事也必须具有三心，“恒心”、“热心”、“信心”\n“书山有路勤为径，学海无崖苦作舟”说学习本是一件苦差事，只有持以“恒心”，坚持不懈的去努力、去认真探索，才有可能获得成功，如果没有恒心就有可能蜻蜓点水、半途而废，或成“半桶水”。其实，知识不在多少、能用就好，“学以致用”才是目的，专业知识、专业技能、是获得进入文明社会的通行证，有它才能更好地为社会、为人民服务。“读万卷书、行万里路”，一定记住要把自已的一生置于不断的学习之中，只有这样才能不会被前进的社会所抛弃。\n对自已的工作、事业要有“热心”，热心激发热情，才能做一行爱一行，三百六十行，行行出状元。切莫把工作当作一种累赘和负担，站在这山看到那山高。最重要的是能在工作中释放人格、释放能量、释放快乐。\n“信心”是做一切事情的原动力，信心是恒心和热心的催化剂，信心是克服一切惰性的良方妙药、“胜不骄，败不馁”，要相信自已的能力和水平，坚信不移才能一丝不苟、探求不止。\n三、学会理家。学会理家必须具有“真心”、“责任心”“孝心”。家庭是社会的细胞，是社会的最小单位。爱情是婚姻的基础、婚姻是家庭的基础。打理爱情要有“真心”，爱情应是相互赠予、相互包容，要把当好‘贤内助’作为家庭的重要责任。夫妻之间要互相关心对方的思想、工作和生活，切莫追求激情、追求完美，也不能对什么都漠不关心，只要双方都肯不计回报的付出，才能体会“爱”的真缔，才会把家庭建成一个幸福的港湾。\n家庭也不单纯就是一个二人世界，有老有小，有兄弟、姊妹、妯娌、还有血姻亲方面的亲戚，有不少的人情世故，打理好家庭就要有“责任心”，要正确认识自己在家庭中的位置，不骄横、不娇气，遇事公平讲民主、尊老爱小尽责任，就会建成一个和谐家庭。如果一个人对家庭、对至亲都缺乏“责任心”，那么，对工作、对社会就不可能是一个真正有责任感的人。\n中国己进入老年社会，尤其空巢老人己成为一个特殊的社会群体。更多的需要社会、子女的关注。“积谷防饥、养儿防老”、“幼吾幼及人之幼，老吾老及人之老”。和“百善孝为先”这都是中国传统的养老观。“二十四孝”的故事是弘扬中华民族优良传统的“孝文化”，每则故事都很感人，在新的历史条件下虽大可不必仿效，但作为子女不可无“孝心”，随着社会的进步“孝”必然有新的内容，“孝顺”一词，意在顺从。物质帮助尽力而为，老人更注重精神抚慰。\n人的一生与广袤宇宙的永恒时间和无限空间相比较是十分短暂的，根本无法抗衡。人的一生就如轻风一缕、不会留下许多痕迹。对“名利地位”不能不去博弈，更应视如草芥、不必过份的去追求。做任何事情都讲究有“度”，“大智若愚、难得糊塗”，切勿钻“牛角尖”。爱护身体、敬重生命、荡涤心灵、乐观自在，享受美好人生，才是最重要的。\n所提“十心”句句皆肺腑之言，可以说是“老程家”一脉相传的“家规家风”，也是我们对你实心实意的期盼与祝愿，望切记于心，更应重视在日常生活中从点点滴滴开始亲修亲为，“路漫漫兮、其修远矣、吾将上下而求索”，父母愿意与你们一路同行。\n外孙百日、这封迟发的家书就算是送给你母子的礼物。\n二零一四年十二月十二日——父亲书于灯下。\n三省轩主程康年。"},{"id":263,"title":"追忆非洲见闻（之三）·文明古国——埃及","category":"散文","date":"二零〇七年三月一日完稿","body":"11月30日凌晨5：10分从内罗毕的恩克贝西机场乘MS850航班飞埃及首都开罗8：55分到达。埃及地跨亚非两大洲、大部份位于非洲东北部、一小部份（西奈半岛）位于亚洲西南角、国土面积100.2万平方公里，西与利比亚为邻、南与苏丹交界、东临红海并与巴勒斯坦接壤、北临地中海、海岸线长2700公里，全境96%为沙漠，境内最高峰沙伊卜巴纳特山海拔2187米。尼罗河是非洲第一大河、也是世界第二条长河，发源于埃塞俄比亚高原，流经布隆迪、卢旺达、坦桑尼亚、乌干达、肯尼亚、扎伊尔、苏丹，埃及等九个国家后入地中海全长6700公里，在埃及境内贯穿南北长1350公里，两岸形成3----16公里宽的河谷，入海处形成2.4万平方公里的三角洲，尼罗河谷和三角洲是埃及文化的摇篮、也是世界文化发祥地之一。\n开罗就坐落在三角洲的顶端，开罗是埃及和阿拉伯世界最大最古老的城市，阿拉伯人把开罗称作“卡海勒”即“胜利者”。全国总人口6521万、有99%的人口聚居在仅为国土面积4%的河谷和三角洲地带，农业人口占总人口的56%，开罗有1577万人是世界上十个人口最多的城市之一。开罗给我的直观印象是城市并不美丽、绿化率低，城市建设与管理都比较差，城市的建筑物跟欧洲比缺少古典、跟亚洲比缺少新颖，都比较陈旧，从市内往金字塔的途中所见建筑物有五分之一到四分之一的屋面都是未完工程梁柱裸露，据导游介绍竣工的工程要向国家纳税而且赋税很重，在建工程可以暂不纳税所以大家都钻政策的空子。街道上跑的汽车很破旧、除我去过的越南河内交通工具以摩托为主、数量比不上开罗以外，与我到过的欧洲、亚洲、非洲等国家城市看到的汽车都无法相比，流经市区的一条叫不出名字的小河污染很严重，污水横流、看到的几条街道卫生也很差，这些虽说与经济发展有关，经济发展滞后城市建设肯定受影响，但这也是与城市管理者的水平分不开的。以上是我的一管之见吧。\n埃及与中国、印度、巴比伦并列为四大文明古国，具有悠久的历史和人类早期文明、公元前3200年出现奴隶制的统一国家，当时国王称法老。这时的埃及文化己日渐趋于成熟、开始使用象形文字。用纸莎草生产草纸的技术发明推进了人类社会的进步，我们在草纸画博物馆看到这项技术至今仍在使用，我在此购了一些草纸画、内容都是埃及的古老故事、准备回国送朋友、其价格还真不菲、要比汉哈力大巴扎（旅游购物市场）上高5—10倍，当然质量也不一样、真应了一句俗话“一分钱一分货”。汉哈力大巴扎是开罗最大的小商品市场、以出售纸草画、香水、香料、手饰等旅游纪念品为主，吃饭购物应有尽有、是一个“宰老外”的地方。大大小小店铺的老板都会用英语接待顾客、通常用“你从哪里来？”作为开场白，一听是从中国来的马上一脸灿烂笑着说：“我喜欢中国、喜欢中国人。”在异国他乡受到如此不菲的尊重和热情的欢迎真感到高兴，这全得益于我国的和平外交政策。\n接机的导游是一位埃及姑娘二十一、二岁，热情大方、她的中国名字叫阿美拉，她告诉我们她们家是一个和美幸福的家庭、家中有五口人父母亲和一个妹妹一个弟弟，父亲开了一个汽车修理铺、妹妹大学毕业后注册了自己的公司、母亲是家庭妇女、弟弟还在上学，经济收入在开罗是中等水平。她自己是开罗大学中文系毕业的。埃及实行义务教育，她在大学每学期的学杂费用折合人民币还不足200元，埃及实行公费医疗，市民有病到公立医院医治可以免费，但医疗服务质量并不让人满意，私立医院的服务质量好但费用昂贵是一般人承受不了的。通过交流我们对阿美拉所掌握的中文词汇和理解能力来判断她的中文最高也就是国内初中一年级的水平。阿美拉没有来过中国但她很向往中国，她说争取一两年内凑足经费要到中国旅游，她说在埃及干导游这一行挺不错收入比较高，因为埃及是不允许其它国家移民当导游的。\n在开罗我们首先游览了久赋盛名的金字塔和狮身人面像。埃及目前已发现的金字塔有96座，金字塔是古埃及法老给自己修的陵墓，不同于我国历代帝王的寝陵都是地下工程而金字塔是从地面向上修建的，我想这是否与崇拜有关，中国文化传统是相信有十八层地狱和阴曹地府的、埃及文化传统是崇拜太阳神的。\n最大的金字塔是吉萨的三座、大金字塔是第四王朝第二个国王胡夫的陵墓，建于公元前2690年左右，原高146.5米，因年久风化顶端剥落10米、现高136.5米，底边每边长230多米，三角面斜度为51度，塔底面积为5.29万平方米，塔身用230万块石头砌成，每块石头平均重2.5吨，据说用了10万人花了20年的时间才建成。该金字塔的内部通道和放置石棺的石室工程浩大，设计也十分精巧、现在全部对游客开放、在里面往返一次大约需半个多小时。在胡夫金字塔南侧建有纪念当年将胡夫木乃伊运到金字塔安葬的运输工具“太阳船”博物馆，太阳船是纯木结构用绳索捆绑而成。第二座金字塔是胡夫的儿子哈夫拉国王的陵墓，建于公元前2650年、比胡夫金字塔低3米、但建筑形式更加完美壮观，塔前建有庙宇和形似哈夫拉面部的狮身人面像、高22米、长57米、雕像的一个耳朵就有2米高，除狮爪外全部由一块天然岩石雕刻而成。由于石质疏松且经过4000多年漫长岁月的侵蚀整个雕像风化严重、亟待进行抢救性保护。第三座金字塔属胡夫的孙子门卡乌拉国王、建于公元前2600年左右、当时正是第四王朝衰落时期其规模结构都无法与前两座金字塔相比。晚上下榻0asis—H0tel（宾馆），次日早餐后安排去参观埃及历史博物馆。\n埃及历史博物馆建在开罗市中心的解放广场一侧，1902年建成开馆，馆藏文物据说有10万至25万件。到底有多少没有翔实资料参考，博物馆的规模很大、我的感觉不亚于英国伦敦的大英博物馆，博物馆分两层、收藏的展品按年代顺序陈列在几十间展室中、其展品大都是有五、六千年历史的法老、古希腊——罗马时期的石人、石棺、石碑、石柱、我觉得是把埃及整个历史写在石头上的一部“石头记”。该馆中收藏的大量木乃伊、纯金制作的宫廷御用珍品其做工精细令人赞叹，镇馆之宝242磅重的图坦卡蒙金面具和纯金棺椁更是无与伦比。埃及的酒文化历史堪于我国相媲美、馆藏中有出土5000多年前的宫廷美酒。在这里可以窥探到人类五、六千年前时空的文明真是大开眼界。\n与这个博物馆相距不远、位于尼罗河中一个岛上的开罗塔高187米、登塔远眺全城景色尽收眼底，开罗的另一大景观是遍布全城的清真寺、宣礼塔使开罗获有“千塔之城”的雅号，艾资哈尔清真寺规模宏大一次可容纳一、两万人做礼拜。在埃及信奉伊斯兰教的阿拉伯人占87%、信奉基督教的科莫特人约占11.8%，还有少数人信奉东正教、天主教、犹太教。伊斯兰教为国教，信徒很虔诚每天要做四次礼拜、早晨日出前一次、上午九点至十点期间一次、下午四点至五点期间一次、晚上日落后一次。每次礼拜的时间是十到十五分钟，星期六和星期天的礼拜时间略长每次要半小时。\n开罗位于连接非、亚、欧三洲苏伊士运河的要冲、是世界十大都市之一，到这里观光旅游的人很多、所以漫步开罗街头、可以看到各种肤色的人。本地的阿拉伯人身着宽袍大袖、头上盘一圈汗巾，街头还常看到骑毛驴踽踽而行的村姑乡民、头顶盛馕竹筛和肩挑水果担沿街叫卖的游商小贩，俨然一派阿拉伯风情。\n12月2日早餐后去亚历山大城参观，沿途看到的景色与我们甘肃、新疆差不多尽是戈壁荒漠、可耕地种植的大都是香蕉、埃及的土地是国有的、香蕉园个人也可以承包经营。从开罗往亚历山大的公路路况还算可以、基本上能达到国内二级公路标准、埃及人的市场观念也比较浓、沿公路两侧设置有很多商业广告。\n亚历山大位于尼罗河三角洲西缘、面临地中海、面积1000平方公里、人口305万、是埃及第二大城市、东地中海的最大港口、该城始建于公元前332年、因希腊马其顿国王亚历山大占领埃及而得名，这里三面环水、风景优美、气候宜人，是埃及的避暑胜地、滨海大道更是风景独特毫不逊色于上海的外滩。这里集中了埃及三分之一的工业企业，棉纺、汽配、石油、造船业较发达。亚历山大城市建设与管理和开罗相比给我的印象是美丽多了。\n亚历山大蒙扎塔花园是一个具有特色的景点、蒙扎塔花园实际上就是埃及皇室避暑的夏宫、座落城市东部、占地155.4公顷、与海相接、密林环绕、园内仅将海滨向游人和垂钓者开放，法鲁克国王的行宫（现为埃及国宾馆）至今对外未开放。在这里还可以看到始建于公元前280年的亚历山大灯塔、塔高135米、经数次地震于1435年完全毁坏，1480年用其石块在原址上修筑城堡、用国王卡特巴的名字命名，1966年改为埃及航海博物馆、介绍自一万年前从草船开始的埃及造船和航海史，该城堡与开罗古城堡并称为埃及两大中世纪城堡。\n驱车离开蒙扎塔花园途经滨海大道向城市西南方向驶去、进入老城区首先映入眼帘的是轰隆隆行驶在石砌马路上的有轨电车、这道风景线在其它地方己难得一见了。不一会儿来到了一个一片荒凉的高地上、一根巨大的擎天大柱直插云霄这就是闻名遐尔的“萨瓦里”（桅杆的意思）千百年来萨瓦里石柱留下了很多趣闻轶事，十字军将士认为古罗马大将庞贝（公元前106年——前48年）被恺撒击败、逃到埃及后死于埃及、其骨灰就存放在柱顶骨灰罐里所以至今仍将萨瓦里石柱称为庞贝柱。石柱建于公元297年、由柱基、柱身、柱顶三部份组成、总高度为26.85米、重约500吨、柱身呈园柱形下部直径2.8米、上部直径2.3米、由一整块采自上埃及阿斯旺的、粉红色亚斯文花岗石雕凿而成、柱顶为古罗马科斯林式、饰有爵床花图案。仰望柱顶有欲将倾倒之感、颇为吓人。1000多年来、亚历山大经历了沧海桑田、许多著名的古迹或成废墟或销声匿迹、唯有庞贝石柱巍然挺立、如今成了亚历山大城的标志。在亚历山大还参观了一个地下古墓室群看到了埃及的古代葬俗，随后就结束了此旅程返回开罗。\n12月3日上午考察团参观了埃及古都孟菲斯、拉米西斯神像和撒拉卡的阶梯金字塔、下午到汉哈力大巴扎购物、晚上乘游船在尼罗河上游览开罗的夜景。\n开罗的形成可追溯到公元前3000年古王国时期，作为首都亦有千年的历史、在它西南约30公里开阔的平地上有一个小院落掩映在一片绿荫之中这就是古都孟菲斯遗址博物馆，内有法老拉姆希斯的巨型石像。\n萨卡拉阶梯金字塔位于开罗城南郊30公里、尼罗河西河谷绿洲边缘外的沙漠戈壁上、由多座金字塔组成，阶梯金字塔是古埃及第三王朝法老左塞尔的陵墓建于公元前2700年、塔呈阶梯状、塔高60米、是埃及现存金字塔中年代最早的。\n在汉哈力大巴扎购物、商铺老板很热情，讨价还价必不可少否则肯定挨宰当“冤大头”。有团友一心想购埃及的风光碟片、老板开价很高怎么谈也降不下来，团友呼我帮忙、我将平时管市场的砍价经验和混身解数拿出来与老板谈判、最后不仅以较低的价格买到了想要的碟片、老板还从柜台内走出来与我拥抱夸赞中国人很精明、临告别时还给每个团友赠送一瓶果汁饮料。晚上乘游船游览开罗的夜景、沿河两岸灯光开放漂亮至极，大大冲淡了我对开罗白天的不良印象，在游船上还观看了具有阿拉伯特色的肚皮舞等舞蹈。\n这次在埃及旅游使我印象较深的还有无论在那个旅游景点都会碰到很多荷枪实弹的警察、甚至把重机枪都架到旅游景点的大门口、警察很多但他们的衣着大都不太整洁、精神也是懒洋洋的、与游客聊天照相很随便，这种警容风纪实在不敢恭维。这么多警察在旅游景点值勤让人首先想到的是安全感？还是危险感？确实茫然、捉摸不透。\n12月4日凌晨3点45分乘TK1143次航班飞土耳其的伊斯坦布尔两小时后约6点钟到达。\n嘉峪关市工商局三省轩主程康年\n二七年三月一日完稿"},{"id":264,"title":"追忆非洲见闻（之四）·东西文明交汇点土耳其","category":"散文","date":"非洲纪行","body":"12月4日早晨6点钟飞机徐徐降落在伊斯坦布尔的耶希尔科伊机场，导游接机后将我们安排到Seasons-----HoteL（宾馆）休息。这次考察途中历经四个国家十几个城市安排的宾馆都称是四星级标准，其硬件与国内宾馆相比我认为也就达到两星级，但其服务大都是一流的。自中国加入世贸组织以后国人都在讲要与世界接轨，毫无疑义中国要融于世界就必须与世界接轨，善于学习借鉴别人先进的管理理念和经验。可是，有很多国人（部门、行业）对“接轨”的理解是否片面了点儿？有的不顾国情机械的照抄照搬，有的专拣对自己有利的就用、损害他人利益可以全然不顾。就我国的宾馆饭店与我所到过的国家和城市相比较而言总体印象是国外硬件配置上注重的是节能、环保、舒适，尤其注重服务质量，确实让你感到有宾至如归的感觉，而国内的硬件配置更多的考虑是如何豪华如何满足奢侈享受、服务方面更是有不少差距。其它行业的“接轨”在媒体上屡有曝光，让歪嘴和尚念所谓的“接轨”经是不是令人担忧？我想，国人（部门、行业）应该到细细思量的时候了，取得“真经”才更有利于经济的发展、社会的进步，否则只会祸国殃民、遗害无穷。\n真是管窥之见、杞人忧天。\n土耳其地跨亚欧两洲、位于地中海和黑海之间、东边界伊朗，东北邻格鲁吉亚、亚美尼亚、阿塞拜疆，东南与叙利亚、伊拉克接壤，西北和保加利亚、希腊毗连，北滨黑海，西及西南隔地中海与塞浦路斯遥遥相望。博斯普鲁斯和达达尼尔两海峡之间的马尔马拉海是沟通黑海和地中海的唯一道，海岸线长3518公里。全国地形东高西低、正好与我国相反，这种地形的分界线应该是帕米尔高原，其境内大部分为高原和山地、沿海有少量狭长平原。沿海地区为亚热带地中海气候、其余的内陆高原属热带草原和沙漠型气候。全国总面积约78.06万平方公里，位于小亚细亚半岛的亚洲部分占国土总面积的96.9%，位于巴尔干半岛东南的欧洲部分占3.1%，全国总人口约6550万，其中80%是土耳其族、15%是库尔德族、此外还有亚美尼亚、阿拉伯和希腊等少数民族、全国99%的居民奉伊斯兰教。首都安卡拉是1923年从伊斯坦布尔迁移至此。\n伊斯坦布尔是土耳其全国最大的城市、最大的港口、近1700年的都城历史留下了丰富多彩的文物古迹使伊斯坦布尔成为世界著名的旅游胜地。伊斯坦布尔始建于公元前668年，当时称拜占庭，公元324年罗马帝国君士坦丁大帝从罗马迁都于此改名君士坦丁堡。公元395年罗马帝国分裂后君士坦丁堡成为东罗马帝国（亦称拜占庭帝国）的首都。公元1453年土耳其苏丹穆罕默德二世攻占此城灭亡了东罗马，这里又成了奥斯曼帝国的都城并改名为伊斯坦布尔，直至1923年土耳其共和国成立迁都安卡拉。伊斯坦布尔现有人口548万、城市面积254平方公里。\n下午乘游轮观光博斯普鲁斯海峡、欣赏马尔马拉海两岸迷人风光，建于1973年的博斯普鲁斯海峡大桥是世界上唯一飞跨亚欧两洲造型独特的跨海吊桥，它不仅将被海峡分割的城市联在了一起，也把亚欧两大洲联结在一起。桥身全长1650米、跨越海峡水面1074米、高64米、桥下没有桥墩、可通行各种类型的船只，在吊桥兄弟的行列中目前就坐欧洲第一把、世界第四把交椅。海峡两岸红屋顶的哥特式建筑与古色古香的伊斯兰式屋宇交相映辉漂亮至极，当夕阳西下看见对岸的窗户被落日余辉映照成点点桔红时，就像羞涩少女向你投来频频笑靥、一定会让你流连忘返，入夜、又是别一番景象、桥上华灯齐明、远远望去宛如一条流光溢彩跃跃腾飞的巨龙，煞是壮观。此刻你才会深刻理解多少世纪以前的人们为何选择伊斯坦布尔这一块非凡土地休生养息的理由和伊斯坦布尔享有现代“世界最美丽城市之一”美誉的理由。\n12月5日的行程安排是参观圣索菲亚大教堂和蓝色清真寺以及旅游途中不可缺少的购物环节。圣索菲亚大教堂又名阿亚索菲亚博物馆是一座长方形的古罗马时代遗留下来的天主教教堂。由康斯坦丁大帝于公元6世纪建成，其宽大的圆形穹顶直径达31米，离地高55米，它的墙面用关于圣母、基督、使徒构成的华丽壁画和马赛克装饰，底部四周有四座雄伟的拱门和40个大玻璃窗，据说这座典型的拜占庭建筑里的装饰对欧洲的文艺复兴运动都产生过影响。1453年拜占庭帝国灭亡后信仰伊斯兰教的土耳其人在教堂外修了4座宣礼塔，将这座千年历史的大教堂改为清真寺，细品起来真还有点不伦不类，1935年土耳其国家将它改为博物馆，永远供人们参观。\n伊斯坦布尔市内与埃及的开罗市一样遍布大小清真寺共有3000余座，高耸的宣礼塔有1000多座。最负盛名的是建于1616年的苏丹艾哈迈德清真寺，它是世界上唯一现存的六塔清真寺。那庄严肃穆的圆顶和耸入云天的宣礼塔特别引人注目，寺内四壁镶嵌着两万多块蓝色瓷砖并配以典型的伊斯兰特色的图案花纹，礼拜厅里的光线柔和明亮、显得十分静谧，遂有了“蓝色清真寺”的美名。清真寺大都是四塔、六塔有什么含义至今我也没有搞懂。\n土耳其是传统的农牧国家、牧业相对发达因此生产的皮革制品无论是款式还是质量都相当不错，在一家著名的皮革加工厂团友们观看服装模特的表演后在展销大厅纷纷解囊为家人和朋友选购礼品、我受团友的感动也掏兜为夫人选购了一件可双面穿着的皮衣，虽使出砍价的混身解数商家下浮幅度依然很小，最终还是价格不菲以3000多元人民币成交。在土耳其为团友马国昌购旅行箱砍价过程还是比较成功的。\n12月6日应该是出行考察的最后一天，酒店早餐后去游览道尔玛巴赫切新皇宫。旧城区的托普卡珀博物馆是土耳其苏丹的宫殿，占地70万平方米建于1478年，土耳其共和国成立后辟为博物馆，馆内收藏有土耳其历史上许多珍贵文物外还收藏着上至唐宋、下至明清的中国古瓷器1.7万件，据说仅次于北京故宫博物院和德国德累斯顿艺术博物馆为世界第三位。道尔玛巴赫切新皇宫是19世纪苏丹的王宫，其地理位置十分优越，后院面临大海有皇家专用码头。据说在土耳其革命时最后一位国王就是从这里出逃的。皇宫的大门、大理石墙面和屋顶无数精湛的浮雕、壁画、吊灯无处不体现建筑的精湛，宫内珍藏的皇家用品、东西方品味都很浓，弥足珍贵的是宫内珍藏的一盏重达4.5吨的巨型吊灯可算是举世闻名的稀世珍宝。参观完皇宫在赴机场的沿途我们还看到了另一处古遗迹，那就是1453年奥斯曼帝国穆罕默德二世进攻时的破城之地，古城墙有两重、多为石料构筑、内墙筑于公元413年、外墙筑于447年、外有城濠围护，内墙较高约9米、厚4.8米，城墙上每间隔54米布一座了望塔、塔高18米。外墙上设有92座炮塔至今犹存56座。伊斯坦布尔市分为三个区，位于欧洲部分的有旧城区和贝依奥卢商业区，位于亚洲部分的是于斯屈达尔区，在旧城区有7座小山这里的文物古迹和旅游景点很多因时间关系都没有参观到，留下了不少遗憾。\n伊斯坦布尔不仅地理位置上横跨亚欧两大洲，而且还兼收并蓄亚、欧、非三大洲各民族思想。文化、艺术之精粹。阿亚索菲亚博物馆、苏丹艾哈迈德清真寺、托普卡珀博物馆在这些名胜古迹里处处都渗透着东西方思想、文化、艺术交汇的痕迹，见证着东西方思想、文化、艺术融合的历史。土耳其大部分国土虽在亚洲、但他们一贯奉行的是亲西方政策、赞同推进西方民主化进程、目前己于欧盟实现关税同盟，人们的生活方式也大都西方化。\n中午12点45分乘SQ491航班离境，导游送团友每人一颗天眼祝我们一路平安。飞机途经阿联酋首都迪拜时在机场暂停了几个小时、给飞机补足油料等待上客。12月7日凌晨7时左右才到达新加坡再换乘上午10点15分的SQ804次航班飞赴广州回国、约4小时后安全降落在广州新机场。半月有余的国外生活虽然很愉快，但因语言不通、生活方式不同终究是感到不方便，这种恋家情结真应了一句俗语“在家千日好、出门一时难”，踏进国门一股说不出的亲切感扑面而来，一颗悬着的心也终于放了下来。\n嘉峪关市工商局三省轩主程康年\n二七年四月完稿\n附记一：经贸考察团团友名单：\n石建民嘉峪关市人民政府副市长、考察团团长\n马国昌嘉峪关市人事局局长、考察团秘书长\n赵方勇嘉峪关河西家俱城总经理、考察团成员\n王东方嘉峪关东方商贸公司总经理、考察团成员\n何伍嘉峪关市长城公司总经理、考察团成员\n王汝让兰州市市政公司总经理、考察团成员\n附记二：经贸考察团考察日程表："},{"id":265,"title":"追忆非洲见闻（之一）·天崖海角——南非","category":"散文","date":"非洲纪行","body":"让世界瞩目的第三届中非合作论坛北京峰会于11月3日举行，距我去年随市政府考察团赴非洲几个国家进行经贸考察将近一年的时间。这次53个独立的非洲国家有48个国家的政府首脑齐聚北京共商中非友谊、和平、合作、发展大计，开启中华文明与非洲文明、携手共进、开拓创新的新时代，其深远的历史意义和现实意义举世瞩目。说到非洲，难免会引发我对所去过的几个非洲国家的回忆，现将我所经历及所见所闻的奇闻趣事追录如下。\n去年的经贸考察团是由省商务厅赞助、嘉峪关市人民政府组织的，副市长石建民同志带队、考察团成员一行七人中有政府部门工作人员也有出口经营权的企业经理，考察团共去了四个国家，南非、肯尼亚、埃及、和横跨欧和亚两大洲的土耳其。考察团是11月22日15时20分，从广州出关乘SQ803航班飞往新加坡约3小时后到达，凌晨1时30分从新加坡转乘SQ480班机飞往有南非“母亲城”之称的开普敦、约12小时后到达。\n南非位于非洲大陆最南端，三面濒临印度洋和大西洋，好望角正是两洋交汇之处。南非有人口4690万人，南非也是世界上唯一有三个首都的国家，行政首都比勒陀利亚是南非中央政府所在地，立法首都开普敦是南非国会所在地、全国第二大城市、也是国际海运航道的重要港口，司法首都布隆方丹是全国司法机构所在地。南非的第一大城市约翰内斯堡是全国的经济中心。\n南非是非洲大陆上经济最发达的国家，但在世界范围内只能属中等收入发展中国家，人均国民收入2600美元左右，且贫富悬殊、种族收入差距明显、有2/3的国民收入掌握在20%的富人手中。据资料反映南非2005年的失业率是26·7%，从机场出来沿路两边连绵不断的都是设施十分简陋的棚户区——“铁皮房”，这里是黑人集中居住的地方。（据说现在也有不到1%的破落户白人住在这里）进入开普敦市区看到在大街上行走的只有两种人——黑人和游客，路边的黑人都是等待找工作的，谁家需要园丁和清洁工都可以开车来随便拉一个。在这里白人显得很尊贵、他们不是坐在车上就会蜗居在房子里，他们驾乘的汽车都是美国、欧洲、日本进口的高档车，非洲产的中低档车他们是不会买的。由于过去种族隔离政策的影响他们都居住在白人别墅区，房子有英式的、德式的、西班牙式的就是没有非洲式的。南非的主要经济支柱是采矿业、制造业和农业，南非是世界上五大矿产国之一，钻石和黄金举世闻名。\n到机场接机的导游夏小姐是中国西安人，因要节约时间争取多看几个景点、接机后就直接到西海岸的驼鸟园参观，驼鸟园山实际上是一名华人经营的养殖加工场，驼鸟皮和驼鸟蛋制成的各种工艺品别具特色，听介绍驼鸟全身都是宝有很高的经济价值。\n午饭后参观最具开普敦市特色标志的桌山，到开普敦不去桌山就如同到北京没去长城一般，据导游讲我们去的季节开普敦天气变化莫测，风雨天桌山景点是不开放的，所以留下遗憾的游客很多。我们很幸运，这天风和日丽、阳光明媚。桌山海拔1087米，长约3000米、宽不到300米，因岩石构成的山顶像被神斧拦腰砍了一刀，远远望去如桌面一样平坦。上山没有汽车道、要么徒步攀登、要么乘缆车，徒步登顶大约要3个小时左右，乘缆车很方便只需五分钟，所乘的缆车与我过去所登乘过的缆车都不一样，硕大的园形缆车一次可载客四、五十人，缆车在缓缓向上运行的同时呈顺时针方向移动，从山底到山顶整整绕一周360度，让每一位乘客都有机会饱览周围的景色，据说此缆车是1929建成运营的、这种人性化的设计可充分体现当年设计者的良苦用心。\n站在桌山顶上可以看到桌山脚下维多利亚港的美丽景色；可以看到孤立在海上的罗宾岛、那是以前南非政府关押黑人政治犯的地方，南非前总统曼德拉曾在那里度过了十八个春秋，曼德拉是一位受世人尊敬的国家领导人，他在就职典礼上说：“我希望建立的南非是黑人可以安心生活的，也是白人可以安心生活的；是穷人可以安心生活的，也是富人可以安心生活的。”他把“和解与爱”确立为一个国家的精神和信念。看一看世界区域性动乱的国家如能用“和解与爱”精神治国，世界哪能会不太平呢？在桌山顶上可以看到开普敦市的全貌、开普敦确实不愧为世界最美丽城市之一的称号，爱德华式、维多利亚式、开普荷式建筑溶为一体、相得益彰、漂亮至极。站在山顶上向南远眺还可以看到离市区48公里的好望角（G00D—H0PE），远远望去在深蓝色的洋面上缓缓飘动着几片碎纸片、那是经过此海区的海轮，这里是苏伊士运河开通之前由欧洲往亚洲的海上必经之地。好望角原称“风暴角，1487年7月葡萄牙探险家巴塞少缪·迪亚士奉国王之命率探险队从里斯本出发沿非洲西海岸向南航行去寻找一条通往“黄金之国”——印度的航道，当船队驶到大西洋与印度洋交汇水域之时海面上狂风大作、风雨交加，船队被推到一个无名的岬角上才免遭灭顶之灾，迪亚士就把此地命名为“风暴角”。1497年11月葡萄牙另一名探险家达迦马率远航船队成功地绕过此角于次年5月到达印度洋西海岸然后满载黄金、丝绸、香料回到里斯本，葡萄牙国王约翰二世因为其美好的愿望己经实现、就将“风暴角”改称为“好望角”。虽如此这里的海难还是不断，1968年6月一艘满载49000吨原油的“世界荣誉”号油轮途经好望角时遭到20米高巨浪的袭击，油轮就像一根小木棍一样一折两段永远沉入洋底，据不完全统计自上世纪70年代以来，在此海区失事的万吨级以上巨轮就有11艘之多，由于两洋交汇海域气象恶劣，现在国际气象组织在角山上建有现代化的气象塔替代了矗立在角山顶上为船只引航的古灯塔、随时分析研究预报此地气象情况，供来往船只参考以避不测，灯塔己成为历史遗迹。\n回宾馆的途中听导游介绍，开普敦的失业率虽高社会治安状况总体还是好的，但有必要做好预防，在开普敦有这样一句顺口溜“黑人没有不偷的、印巴人没有不骗的、华人没有不赌的、欧洲人没有不嫖的”。华人好赌风糜世界，在事业上的赌是一种拚博精神无可非议，在赌场上的豪赌并非是一种好习惯，有好多企业家、高官因赌落马教训深刻值得吸取。\n更有意思的是在开普敦还看到了一个“断桥”的故事，“断桥”本出自中国美丽的神话“白蛇传”，故事发生在风景如画的杭州西湖是主人翁许仙和白娘子相遇相识的地方，至今“断桥雪景”还与“平湖秋月”、“花港观鱼”、“柳浪闻莺”、“苏堤春晓”“曲塘夏荷”……并列为西湖十大景点之一。开普敦的“断桥”是建城市立交中碰到的一个难题，有一私宅正好影响建桥用地，市政府征地给了很丰厚的补偿但户主就是不同意搬迁，因为南非的“物权法”对私有财产的保护十分有力，市政府花了很大代价建立交桥就此搁浅造成浪费实属无奈，如要能将此地征用就必须修改法律。此事如若发生在我国早就以“钉子户”被拔掉了，我想法律应该是神圣的，党中央提出依法治国的方略社会各部门都应该认认真真、实实在在的贯彻执行、依法办事才有氛围，依法治国的方略才能落实。\n晚餐有代表团成员建议要去品尝一下真正的南非鲍鱼，大家都涌跃响应，鲜鲍和干发鲍鱼我曾经都吃过，实在不知道味道好在哪里？因为是集体行动不好扫团友的兴只好勉强附随。饭后结账一只鲍鱼就是80美元，加工制作及口味没有一点特殊，另加其它几碟小菜主食，那天晚餐大约每人一百美元，约合人民币800多元，这也是我有生以来吃得最简单又最奢侈、最昂贵的一餐，第二天又有人说开普敦小龙虾每年的11月到次年的4月是最肥美的季节鼓动要去品尝被我婉言谢绝，中国人虽然慢慢富起来了，但还达不到这样的消费水平，国内达不到温饱的百姓、饥饿的非洲人民他们想的是什么？晚宿StGeorgeHotel。\n第二天早餐后乘车前往大西洋沿岸的豪特湾，豪特湾是开普半岛上一个风景如画的小镇，在豪特湾佛罗湾码头乘Calypso号豪华游艇去德克岛观赏开普软毛海豹，这是一种皮毛光滑，看似小型鱼雷一样的哺乳动物，海豹的寿命20年至40年，公豹体型比母豹略大、体重约300公斤，软毛海豹的怀孕期约8至12个月，通常一胎只产一仔，海豹的游泳速度很快每小时约17公里，小海豹六周时就会游泳，海豹的主食是鱼类、贝类。在德克岛看到有几千只海豹在4至7米深的海水中上下窜动实为壮观。塘鹅也是德克岛上特有的珍稀动物。\n企鹅滩坐落在漂亮的Si鄄Mon小镇，这里的企鹅没有南极的大、但那种摇头晃脑的姿势同样十分可爱。参观完企鹅滩驱车到好望角景区大约有一小时的车程，好望角周围40公里长的海岸线和1500多种动植物全部列入原始自然保护区，所以沿途都是低矮的灌木丛，羚羊、驼鸟、狒狒这些野生动物可能会与你不期而遇。\n好望角是一个小山岬、所有来过的人都会关注角山上立的一块简易木牌上面写着：“好望角非洲大陆最西南端18?˙29＇51\"——E，34˙21＇25\"S，指向中国北京的直线距离是12933公里，除了经纬度和地标指向外很少有人工修饰的痕迹，千百年来海水的冲刷使山崖鬼斧神工般的突兀在海边上，它的左边是平缓而温暖的印度洋、右边是湍急而寒冷的大西洋，由于两洋的温度和流向不同、看起来一个如窈窕淑女、一个似刚劲猛男。站在好望角山上的近处观海完全不同于桌山上的远处观海，别有一种韵味、在这里向南远望，两大洋交汇处浩浩荡荡的海风裹挟着滔天巨浪一览无余好像一把银色的利剑直插天际。在好望角山下的近处可以看到汹涌的波涛蓄积着无比的力量、后浪推前浪顺势澎湃而来，碰到岸边嶙峋的乱石、迸溅出巨大的浪花就像崩溃坍塌的雪山一下涌到你的面前、随后又会化成白色的碎玉悄悄远去，随着时间的推移、石头都被海浪无形的力量修饰得圆润浑厚。此刻，你不得不被大自然那种神圣的震撼力所折服、所感染。角山上一草一木、一石一贝都不允许捡拾、当然也不允许留下任何垃圾。无论这里曾是异族入侵南非的大门、是历史人文的一个重要基点，也无论这里曾接纳过多少来自世界各地的游客、好望角依然能做到淡化人文矫饰、只容大自然的蚀刻、始终保持着原汁原味。在好望角看到的是风景不是文化，而这样的风景里面谁知道又包含了多少文化？落日的余辉渐渐染透了远处的天空、白色的好望角灯塔被抹上了金黄色、沿岸的冬青花像燃烧的火焰一样红、归巢的海鸟在山顶上不停的盘旋，蓝色的大海依然呼啸着奔向前方，多好的景色哦！虽然恋恋不舍但时间告诉我们这一天的旅程快结束了、团友们最终都是心不甘愿的离开了这里。\n25日早餐后去机场09：40乘SA322航班离开美丽迷人的开普敦去约翰内斯堡，两小时后到达。接站的导游是一个中国上海的汤姓少妇，夫妇双方都在约堡。\n约堡面积约269平方公里、海拔1800米、人口600万，是南非最大的商业、金融、交通、经济中心，约堡四季如春、气候宜人完全可以与我国春城昆明媲美、夏天平均气温摄氏21度左右、冬季平均气温11度左右。约堡老城区的市中心（DownTown）己日渐萧条、到晚上冷冷静静基本上成了一座“死城”，以山顿（Sandston）为首的一批新开发的城区己成为文化、金融、购物中心。在约堡参观了非洲土著民俗文化村落，观看了豪放的非洲原始歌舞表演，品尝了原汁原味的非洲饮食文化。玉米面和烤肉是他们的主食但很多穷人是吃不起烤肉的，非洲特色的丰盛大餐与中国餐相比给我的印象是终身难忘、确实又是不能恭维。\n下午参观了钻石中心了解了钻石的切割制作过程及识别钻石等级质量的基本方法，确定一颗钻石的价格要将钻石的颜色、光洁度、切割面、重量等四大要素结合起来判断，所以说世界上没有任何一颗钻石完全相同。在这里选购的钻石讨价还价后要比珠宝商场低10%—20%。在这里我为我太太购了一只钻石吊坠、记不清花了多少兰特、折合人民币约两万元、这是我们结婚后我送给她最昂贵的一份礼物，也可能就是一生中最值钱的纪念品。之后是必不可少的一个旅游项目由导游带到市商业中心购物。商品虽然很丰富但也没有多少特色所以也就没有再掏腰包购买，我感到也很值得既饱了眼福又省了钱。\n太阳城并非一座城市，它只是在非洲荒原上一个三面环山的山坳中、花100多亿兰特（兰特是南非货币、每一个兰特大约相当于1·5元人民币，在南非我收集了一套不完整的流通币做纪念。）建成的一个度假村，酒店、赌场、游乐园应有尽有，每年大约有120万人到这里旅游度假、四个五星级以上标准的酒店共有1320个房间，皇宫大酒店最负盛名、超豪华程度己达七星级标准，每天的房价是320美元，旅游旺季天天爆满，即使淡季所有宾馆客房平均利用率也达到了87%以上，值得称道的是度假村里设有创意独特的人造海滩浴场、九秒钟发生一次冲浪，后浪推前浪真有海的感觉，特别是一小时发生一次“地震”的地震桥让游客满足了好奇心理，它让世界注目的原因是先后有三届世界小姐评选在这里进行总决赛。\n南非4690万总人口中有474万人是艾滋病患者或病毒潜伏者，总人口中四分之一的失业率和十分之一的患病率是南非政府和联合国组织都要认真面对的社会问题。\n嘉峪关市工商局三省轩主程康年\n二00六年十一月完稿\n嘉峪关市工商局三省轩主程康年\n二六年十一月完稿"},{"id":266,"title":"雄关工商赋","category":"文","date":"二零零二年·办公楼落成乔迁之时","body":"上下五千年、纵横逾万里，雄伟壮观的万里长城，是各族人民智慧的结晶、是中华民族的象征、是中华巨龙的脊梁。\n嘉峪关“天下第一雄关”，她屹立在古丝绸之路、万里长城的最西端，其深邃、其神奇、其博大，令人惊叹、引人遐想。\n深邃的昔日之嘉峪关，在华夏文明的历史长河中，她抵御了熊熊战火狼烟、历经了漫漫沧桑巨变、见证了河西走廊的兴衰。至今，依然是长城上的一座丰碑、一堵铁壁、一驻铜墙。\n神奇的今日之嘉峪关，厚重的历史积淀与更多的现代文明交相辉映，经过雄关儿女的精雕细琢、精心打扮“天工开物”一座被誉为：戈壁明珠、玲珑剔透、绮丽秀美的新型城市神话般的洒落在祖国西部的大漠上，向世人展现她那迷人的风采和豪爽。\n博大的明日之嘉峪关，迎来新世纪的曙光、憧憬小康社会的希望，鼓舞雄关儿女为之奋斗、创造美好未来繁荣、昌盛、幸福和富强。\n雄关工商人在嘉峪关的发展中，辛勤耕耘、悉心点缀“锦上添花”同样付出了拚搏和艰辛：实施西部开发战略、营造“三个环境”的窗口，有他们不倦的身影；制定市场规则、清除市场障碍、维护市场秩序、有他们执法的形象；嘉峪关社会、经济进步的琴弦上有他们谱写的乐章。\n“雄关漫道真如铁，而今迈步从头越”。朋友们，让我们携起手来、踏上新的征程、贡献智慧和力量，创造新的辉煌。雄关伸出了双手，在欢迎远方的宾朋贵客，我们热衷的期望在长城脚下欢聚一堂。\n三省轩主程康年\n写于二零零二年办公楼落成乔迁之时"},{"id":267,"title":"乙巳立秋前后管社山庄赏荷有感","category":"诗","date":"乙巳立秋后六日","body":"微风无意送幽香\n细雨未敢卸艳妆。\n千顷绿波轻跃动，\n一池倩影红粉黄。\n\n飓风无情暴雨狂，\n枝斜叶残毁荷塘。\n坚贞不屈藕传世，\n荣枯相成济流芳。\n\n三省轩主程康年\n乙已立秋后六日\n写于无锡四为斋，\n\n注：二零二六年第十三号台风\"白海豚\"八月九日至十三日侵袭无锡，阵风十二至十四级，每秒三十三至四十五米，暴雨成灾，破坏力极大。去管社山庄赏荷，立秋前挑一个小雨天去了一次，因雨中赏荷别有韵味，台风过后又去一次相隔不足半月、可两次看到的情景截然不同，遂有感而发，成其诗，备念。"},{"id":268,"title":"悼念亲家公","category":"诗","date":"乙巳年八月初一","body":"八旬亲家公，\n突患病危重。\n九八撒手去，\n墓地添新冢。\n\n报国曾建功，\n立业为民众。\n举案齐眉和，\n楷模合族颂。\n\n孝悌继祖训，\n忠厚传家风。\n人生苦旅短，\n从此无影踪。\n\n追念思无穷，\n常忆音与容。\n一声道别远，\n鞠躬再鞠躬。\n\n三省轩主程康年，\n乙巳年八月初一\n写于无锡四为斋"},{"id":269,"title":"镇江北固山怀稼轩","category":"诗","date":"丙午槐月廿五日","body":"        镇江北固山怀稼轩\n           （满江红）\n\n       浩荡长江，东流去，浪花如雪。\n       登临处，北固山巅，吴地人杰。\n       腥风血雨钩旧梦，金戈铁马照残月。\n       问神州。英雄何处寻？空悲切。\n       靖康耻，志未灭。\n       陈九议，十论辟。\n       看稼轩豪语，字字泣血。 \n       善政清廉治京口，神鸦社鼓千秋绝。\n       看今朝，盛世慰忠魂，山河悦。\n\n      三省轩主程康年\n      丙午槐月廿五日\n      写于无锡四为斋\n\n注释：\n\n       浩淼的长江之水，滾滾东流逐浪而去。此时我们登临上镇江北固山顶，极目远眺远处是一座高楼大厦鳞次栉比、车水马龙川流不息的繁华城市，近处是山清水秀林木葱翠、生机盎然的风景区，下边是奔流不息大浪淘沙的万里长江，岸边掀起的朵朵浪花美若白雪瞬息而逝，这里自古以来英才辈出人杰地灵，站在山顶上脑海里突然浮现出北宋词人抗金勇士辛弃疾（号稼轩）身先士卒奋勇杀敌的身影。腥风血雨勾走了早已远去的旧梦，那金戈铁马浴血奋战的场面还在眼前若隐若现。问神州大地这样为国为民的英雄人物到哪里去追寻？不必为他颠沛跌宕的一生发出空无的悲叹。而是要为他那坚韧不拔终生不移的报国之志点赞。翻开历史可以看到中华民族无论哪个朝代从来都不缺像他这样精忠报国的仁人志士。\n       在金人入侵的那个时期朝内主战派和主和派极力相争胶着不定。主战的辛弃疾也因此几经罢绌和起用，他的报国之志虽未得到充分的实现。但他从未放弃仍坚持上陈《九议》《美芹十论》于朝庭、字字陈实情、句句泣心血。一二零四年重获任用镇江知府，此时已六十五岁，正当他要施展报国为民抱负时又遭谗臣弹劾降职使用，六十八岁时因心情抑郁积愤引病而逝。他一生遗存的六百多首诗词歌赋，题材广泛写政治、写哲理、写恋惰、写朋友之情、写风俗民情、写田园风光、写平常生活、写读书感想等等，涉及面如此之广犹如一座丰厚的文学宝库很值得珍惜。他的思想与才干至今还得到人们的追念，可见中华民族的文化自信力植根之深甚是可贵。纵观历史祖国的大好河山发生了巨大的变化，如今国泰民安、盛世太平、完全可以高兴的告慰历朝历代像稼轩翁这样拥有家国情怀的民族英雄仁人志士。\n\n       巅：山顶。\n       吴地：三国时镇江属吴国\n       靖康：北宗（1126—1127）宋钦宗靖康年间的一次历史事件，金军攻破东京（今开封）俘虏了宋徽宗、宋钦宗及嫔妃朝臣三千余人押解北上。\n       耻：耻辱。\n       灭：丢失。\n       陈：向上级递送有证据的论逑。\n       辟：精辟。\n       辛弃疾（1140年5月28日—1207年10月3日）山东历城人。字幼安、号稼轩\n       善政：好制度。\n       治：管理。\n       京口：镇江古称京口。\n       社鼓：三种（锣、鼓、鑔）以上组合的打击乐器，神鸦社鼓泛指庆典、祭祀、纪念活动。\n       绝：从未停止。\n       悅：高兴。\n       \n       辛弃疾曾在北固山上填写了一首直抒心胸的（永遇乐）《京口北固亭怀古》词，以寄托自己报国无门的情思，现敬录于下：\n       （永     遇     乐）\n     《京口北固亭怀古》\n               辛  弃  疾\n\n       千古江山，英雄无觅孙仲谋处。舞榭歌台，风流总被雨打风吹去。斜阳草树，寻常巷陌，人道守奴常住。想当年，金戈铁马，气吞万里如虎。\n       元嘉草草，封狼居胥，赢得仓惶北顾。四十三年，望中犹记，烽火扬州路。可堪回首，佛狸祠下，一片神鸦社鼓。凭谁问:廉颇老矣，尚能饭否。\n\n（满江红）词牌名，又名（烟波玉）（伤春曲）等，双调九十三字，上阙八句四十七字四仄韵，下阙十句四十六字五仄韵为正体。也有九十三字上阙八句四十七字四平韵，下阙十句四十六字五平韵。和九十三字上阙八句四十七字五仄韵，下阙十句四十六字六仄韵及八十九字和九十七字等多种变体"}]};
